// esbuild entry of services/modbuilder/designer-spec.js: the build service's copy of the gameplay designer validator and
// compiler, GENERATED from these TypeScript files (one source of truth; test/cyrus-designer.test.ts checks the file is
// current and gives the same results as the TypeScript).
export { validateDesign, validateDesigns, designFeatures, canonicalJson, DESIGN_LIMITS, DESIGN_SPEC_VERSION, CAPS, BUDGET, DESIGN_CHECKS } from "./spec";
export { compileDesigns, COMPILER_VERSION, designParams } from "./compile";
export { planDesignEdit, applyParameterEdits } from "./params";
export { libraryHash, COMPONENT_LIBRARY_VERSION } from "./components";
// R3 menus + quests (the same `design` files with a kind discriminator)
export { validateGameplay, designKind, GAMEPLAY_LIMITS, GAMEPLAY_CAPS, GAMEPLAY_SPEC_VERSION } from "./gameplay/spec";
export { compileMod, GAMEPLAY_COMPILER_VERSION } from "./gameplay/compile";
export { applyGameplayEdits } from "./gameplay/params";
export { gameplayLibraryHash, GAMEPLAY_LIBRARY_VERSION } from "./gameplay/components";
// Cyrus R3 gameplay designers, PORTAL side of a succeeded build: the service's designs are never trusted. Every returned
// design is validated and the whole mod is compiled AGAIN here with the TypeScript compiler for the build's exact
// version; the generated-source hash is compared with the one the service compiled into the jar (serviceAgreed). A design
// that fails is dropped with a reason. The sources are deterministic, so the portal stores only the designs.
import type { CompileOk } from "./compile";
import { canonicalJson, type ItemDesign } from "./spec";
import { compileMod } from "./gameplay/compile";
import { GAMEPLAY_LIMITS, designKind, validateGameplay, type DesignKind, type MenuDesign, type QuestDesign } from "./gameplay/spec";
import { createHash } from "node:crypto";

export const DESIGN_SPEC_MIME = "application/vnd.nxeon.item-design+json";
/** R3 menus / quests: the same `design` asset kind, one mime per design kind. */
export const DESIGN_KIND_MIME: Record<DesignKind, string> = { item: DESIGN_SPEC_MIME, menu: "application/vnd.nxeon.menu-design+json", quest: "application/vnd.nxeon.quest-design+json" };
export type SvcDesign = { name: string; path: string; sha256: string; spec: unknown };
export type SvcDesignCompile = { hash?: string; pluginName?: string; configVersion?: number; customHooks?: boolean; modelsApplied?: string[]; /** item model states the service compiled the flag indexes from */ itemModels?: Record<string, { modes: string[]; flags: string[]; use: boolean }> } | null | undefined;
export type CheckedDesign = { name: string; kind: DesignKind; design: ItemDesign | MenuDesign | QuestDesign; canonical: string; specSha256: string };
export type CheckedDesigns = { ok: CheckedDesign[]; dropped: { name: string; reason: string }[]; notices: string[]; compiled: CompileOk | null; serviceAgreed: boolean | null };

const sha = (s: string) => createHash("sha256").update(s).digest("hex");

export function checkReturnedDesigns(list: SvcDesign[] | undefined, ctx: { namespace: string; mcVersion: string; pluginName: string | null; compile?: SvcDesignCompile }): CheckedDesigns {
  const out: CheckedDesigns = { ok: [], dropped: [], notices: [], compiled: null, serviceAgreed: null };
  const all = (list ?? []).slice(0, GAMEPLAY_LIMITS.maxDesignFiles);
  const what = (k: DesignKind | null) => (k === "menu" ? "Menu design" : k === "quest" ? "Quest design" : "Item design");
  // every kind at once: items keep the item validator's results; menus/quests get the cross-file checks
  const v = validateGameplay(all.map((d) => d?.spec), { version: ctx.mcVersion, namespace: ctx.namespace });
  const valid = new Map<string, ItemDesign | MenuDesign | QuestDesign>([...v.items, ...v.menus, ...v.quests].map((d) => [d.id, d]));
  all.forEach((d, i) => {
    const name = typeof d?.name === "string" ? d.name.slice(0, 40) : "?";
    const f = v.files[i];
    const kind = designKind(d?.spec);
    const design = f?.ok ? valid.get(f.id) : undefined;
    if (!f || !f.ok || !design) { out.dropped.push({ name, reason: f?.errors[0] ? `${f.errors[0].path}: ${f.errors[0].message}` : "failed the design checks" }); out.notices.push(`${what(kind)} "${name}" was left out: it did not pass Nxeon's design checks for Minecraft ${ctx.mcVersion}.`); return; }
    if (design.id !== name || out.ok.some((x) => x.name === name)) { out.dropped.push({ name, reason: "name mismatch or duplicate" }); return; }
    const canonical = canonicalJson(design);
    out.ok.push({ name, kind: kind ?? "item", design, canonical, specSha256: sha(canonical) });
  });
  const pluginName = ctx.compile?.pluginName ?? ctx.pluginName;
  if (out.ok.length && pluginName) {
    const r = compileMod(out.ok.map((x) => x.design), { version: ctx.mcVersion, namespace: ctx.namespace, pluginName, configVersion: ctx.compile?.configVersion, customHooks: ctx.compile?.customHooks === true, ...(ctx.compile?.modelsApplied ? { assets: { models: ctx.compile.modelsApplied, ...(ctx.compile.itemModels ? { itemModels: ctx.compile.itemModels } : {}) } } : {}) });
    if (r.ok) { out.compiled = r; out.serviceAgreed = ctx.compile?.hash ? ctx.compile.hash === r.hash : null; }
    else out.notices.push(`The designs could not be compiled again on the portal (${r.errors[0]?.message ?? "error"}).`);
  }
  return out;
}
// Cyrus R3 gameplay designers: does a BUILD get the designer route? Pure + deterministic (no AI call; server side).
// Item-with-abilities requests (a weapon/staff/tonic/... plus an ability word: cooldown, right-click, charge, mark,
// pull, projectile, buff...) are built from a typed ItemDesign instead of free-form Java; menu / quest requests (a shop,
// a GUI, a dialogue, quests, missions, daily tasks; not auctions, player trading, banks, claims or minigames) are built
// from typed MenuDesign / QuestDesign files (./gameplay). OFF unless CYRUS_DESIGNER=1
// (fail closed): off, nothing is decided, nothing is recorded and the build request stays byte-identical. Designers are
// NOT plan-gated (owner decision); any texture / sound / model the design references still goes through the asset gates
// (the texture and sound routes decide those, not this one).
import { designFeatures } from "./spec";

export const DESIGNER_FLAG = "CYRUS_DESIGNER";
export const designerOn = (env: Record<string, string | undefined> = process.env) => env[DESIGNER_FLAG] === "1";

/** The thing the request is about (an item). */
export const ITEM_WORDS = /\b(swords?|blades?|katanas?|staffs?|staves|wands?|scythes?|daggers?|axes?|hammers?|maces?|spears?|halberds?|weapons?|relics?|amulets?|talismans?|tonics?|potions?|elixirs?|rods?|orbs?|gauntlets?|tridents?|bows?|crossbows?|shields?|charms?|custom items?|magic items?|artifacts?|gun|rifle|pistol|launcher)\b/i;
/** What it does (an ability the graph can express). */
export const ABILITY_WORDS = /\b(abilit(?:y|ies)|cooldowns?|right[- ]?clicks?|left[- ]?clicks?|sneak(?:ing)?|shift[- ]?(?:right[- ]?)?click|charges?|charged|charging|marks?|marked|pulls?|pulled|dash(?:es)?|blinks?|teleports?|launch(?:es)?|shoots?|fires?|projectiles?|bolts?|buffs?|heals?|healing|on hit|on kill|when (?:you )?(?:hit|kill|eat|drink|join|die)|passive|knockback|lifesteal|special attack|slows?|stuns?)\b/i;

/** R3 menus: an inventory GUI the menu designer can build (shops, selectors, kit menus, dialogues). */
export const MENU_WORDS = /\b(gui|guis|menus?|inventory (?:menu|gui|screen)|chest (?:menu|gui)|shops?|shop keepers?|shopkeepers?|selectors?|kit menu|warp menu|npc dialogues?|dialogues?|dialogs?)\b/i;
/** R3 quests: quest chains, objectives, daily tasks. */
export const QUEST_WORDS = /\b(quest ?chains?|quest givers?|quest objectives?|questlines?|quests?|missions?|daily (?:tasks?|challenges?|quests?)|weekly (?:tasks?|challenges?|quests?)|bounty|bounties)\b/i;
/** Requests the menu/quest IR cannot express honestly (player-to-player trading, auctions, banks, claims, minigames): no gameplay route. */
export const GAMEPLAY_EXCLUDE = /\b(auction(?: house)?s?|player[- ]to[- ]player|trade with (?:other )?players|player shops?|chest shops?|sign shops?|bank(?:s|ing)?|loans?|land claims?|claims?|minigames?|bed ?wars|sky ?wars|parkour|leaderboards?|databases?|mysql|web ?hooks?|discord)\b/i;

export type DesignerRouteInput = { text: string; explicit?: unknown; existing?: boolean; /** R3: the base build already ships menu / quest designs (keeps the MENUS AND QUESTS prompt part on change builds). */ existingGameplay?: boolean; mcVersion: string; on: boolean };
export type DesignerRouteDecision = { route: boolean; matched: string[]; notices: string[]; limits: string[]; /** R3: menu / quest words matched (present only then): the prompt gets the MENUS AND QUESTS part. */ gameplay?: { menus: boolean; quests: boolean } };

/** Menu / quest words (and no excluded feature): the gameplay part of the designer route. */
export function matchGameplayWords(text: string): { menus: boolean; quests: boolean; matched: string[] } {
  const t = text ?? "";
  if (GAMEPLAY_EXCLUDE.test(t)) return { menus: false, quests: false, matched: [] };
  const m = MENU_WORDS.exec(t), q = QUEST_WORDS.exec(t);
  return { menus: !!m, quests: !!q, matched: [...(m ? [`menu:${m[0].toLowerCase()}`] : []), ...(q ? [`quest:${q[0].toLowerCase()}`] : [])] };
}

const explicitDesign = (raw: unknown) => (Array.isArray(raw) ? raw.includes("design") : !!raw && typeof raw === "object" && (raw as Record<string, unknown>).design === true);

export function matchDesignerWords(text: string): string[] {
  const i = ITEM_WORDS.exec(text ?? ""), a = ABILITY_WORDS.exec(text ?? "");
  return i && a ? [`item:${i[0].toLowerCase()}`, `ability:${a[0].toLowerCase()}`] : [];
}

export function decideDesignerRoute(i: DesignerRouteInput): DesignerRouteDecision {
  const none: DesignerRouteDecision = { route: false, matched: [], notices: [], limits: [] };
  if (!i.on) return none;
  const itemWords = matchDesignerWords(i.text);
  const gp = matchGameplayWords(i.text);
  const matched = [...itemWords, ...gp.matched];
  if (!matched.length && !explicitDesign(i.explicit) && !i.existing && !i.existingGameplay) return none;
  const gameplay = gp.menus || gp.quests || i.existingGameplay ? { gameplay: { menus: gp.menus || !!i.existingGameplay, quests: gp.quests || !!i.existingGameplay } } : {};
  const fe = designFeatures(i.mcVersion);
  if (!fe.ok) return { route: false, matched, notices: [`The item designer isn't available for Minecraft ${i.mcVersion} yet (${fe.error}), so Cyrus writes this mod as plain code.`], limits: [] };
  const limits = [
    "Custom items with abilities are built from a typed design: cooldowns, ranges, strengths, sounds and messages stay editable in config.yml without rebuilding.",
    ...(fe.features.itemModel ? [] : [`Custom item models need Minecraft 1.21.4 or newer; on ${i.mcVersion} the items keep their base look.`]),
    ...(gp.menus || i.existingGameplay ? ["Menus are built from a typed design: buttons, paginated shop lists, item / XP / Vault money prices, permissions and dialogues; prices and texts stay editable in config.yml. No player-to-player trading or auctions."] : []),
    ...(gp.quests || i.existingGameplay ? ["Quests are built from a typed design: steps with kill / collect / craft / visit / break / talk / survive objectives, branches, chains, daily or weekly repeats and rewards; progress is stored on each player."] : []),
  ];
  return { route: true, matched, notices: [], limits, ...gameplay };
}

/** Does a stored build result carry designs (ModBuild.result.assets.designs, written by the asset sync)? */
export function hasDesigns(result: unknown): boolean {
  const a = (result as { assets?: { designs?: unknown[] } } | null)?.assets;
  return Array.isArray(a?.designs) && a!.designs!.length > 0;
}

/** Does a stored build result carry menu or quest designs (rows with kind menu / quest)? */
export function hasGameplayDesigns(result: unknown): boolean {
  const a = (result as { assets?: { designs?: { kind?: unknown }[] } } | null)?.assets;
  return Array.isArray(a?.designs) && a!.designs!.some((d) => d && (d.kind === "menu" || d.kind === "quest"));
}
// Cyrus R3 gameplay designers, part 2: metadata of the MENU / QUEST components (purpose, supported families, limits, how
// they are tested) + the library hash. The Java is in ./java.ts. A component is "verified" exactly like the item
// components (../components/index.ts): javac against the real Paper classpaths of 1.21.11 (JDK 21) and 26.2 (JDK 25)
// with zero warnings, the strict safety scan on its bytecode + source, and a Test Flight boot with no ERROR line
// (test/cyrus-gameplay-real.ts). Other registry versions use the same sources (no per-version code here; the item
// library's Compat is the only per-version file): compiled per the API sheets, NOT by javac (`javacVerified: false`).
import { createHash } from "node:crypto";
import { COMPONENTS as ITEM_COMPONENTS, COMPONENT_LIBRARY_VERSION, compatSource, type ComponentMeta } from "../components";
import { GAMEPLAY_LIMITS } from "./spec";
import * as J from "./java";

