  { id: "gameplay-rewards", file: "designer/RewardDistributor.java", purpose: "RewardDistributor: items (overflow dropped at the feet), XP, potion, own data pack advancement, item ability, message", families: ALL, limits: ["at most 2304 items per give", "advancements of this project's namespace only"], tests: [UNIT, REAL], source: J.REWARDS_JAVA },
  { id: "gameplay-command", file: "designer/GameplayCommand.java", purpose: "the mod command with menu / quests / params / reload (items' give/list stay with DesignCommand)", families: ALL, limits: ["menus/quests for everyone by default; list/costs/check/params ops"], tests: [UNIT, REAL, "Test Flight: RCON menu list/costs, quests list/check, console usage"], source: J.GPCOMMAND_JAVA },
