/** Only in mods with money costs (compile-only Vault API 1.7 from the import allowlist; never shaded). */
export const VAULT_COMPONENT: ComponentMeta = { id: "gameplay-vault", file: "designer/VaultMoney.java", purpose: "money costs through the allowlisted Vault API (created only when the Vault plugin is installed)", families: ALL, limits: ["needs Vault + an economy plugin on the server", "compile-only dependency vault-api"], tests: [UNIT, REAL, "javac with VaultAPI-1.7 on the classpath; NOT run with a real Vault + economy on a server"], source: J.VAULT_JAVA };
export const VAULT_DEP = "vault-api";

/** Hash of the whole library a menu/quest mod is built from (item components + gameplay components). */
export function gameplayLibraryHash(): string {
  const h = createHash("sha256");
  h.update(COMPONENT_LIBRARY_VERSION);
  h.update(GAMEPLAY_LIBRARY_VERSION);
  for (const c of [...ITEM_COMPONENTS, ...GAMEPLAY_COMPONENTS, VAULT_COMPONENT]) { h.update(c.id); h.update(c.source); }
  h.update(compatSource({ version: "x", itemModel: true, attributeNames: "plain", javaRelease: 21, scheduling: "paper" }));
  return h.digest("hex");
}
// Cyrus R3 verified component library: metadata (what each component is for, which versions it supports, its limits
// and how it is tested) + rendering into a mod's package. The Java lives in ./java.ts. A component is "verified" when
// (1) it compiles with javac against the real Paper classpaths of the registry's lanes (1.21.11 on JDK 21, 26.2 on
// JDK 25; recorded by test/cyrus-designer-real.ts), (2) the strict safety scan passes on its bytecode, (3) a Test Flight
// boots a mod built from it with no ERROR lines. Versions without a resolved classpath on the build host (1.21.1,
// 1.21.4, 1.21.8, 26.1.2) use the same sources plus their Compat variant: compiled per the javap-verified API sheets,
// NOT by javac (stated in the docs and in compile results as `javacVerified: false`).
import { createHash } from "node:crypto";
import type { DesignFeatures } from "../spec";
import { BUDGET, RUNTIME_CAPS } from "../spec";
import * as J from "./java";

export const COMPONENT_LIBRARY_VERSION = "cyrus-components-1";

export type ComponentMeta = {
  id: string;
  file: string; // relative to the mod's package dir
  purpose: string;
  /** Registry families it supports ("1.21", "26"); every component supports both. */
  families: ("1.21" | "26")[];
  limits: string[];
  tests: string[];
  source: string;
};

const ALL: ("1.21" | "26")[] = ["1.21", "26"];
const UNIT = "test/cyrus-designer.test.ts (pure: present in every compile, strict-scan text rules, golden hashes)";
const REAL = "test/cyrus-designer-real.ts (javac 1.21.11/JDK 21 + 26.2/JDK 25, strict scan, Test Flight boot)";

export const COMPONENTS: ComponentMeta[] = [
  { id: "designer-trigger", file: "designer/Trigger.java", purpose: "the ten trigger kinds", families: ALL, limits: [], tests: [UNIT, REAL], source: J.TRIGGER_JAVA },
  { id: "designer-budget", file: "designer/Budget.java", purpose: "per-activation resource budget (runtime twin of the static check)", families: ALL, limits: [`actions ${BUDGET.actions}`, `entities ${BUDGET.entities}`, `tasks ${BUDGET.tasks}`, `particles ${BUDGET.particles}`, `projectiles ${BUDGET.projectiles}`], tests: [UNIT, REAL, "simulator budget tests"], source: J.BUDGET_JAVA },
