  { id: "designer-config", file: "designer/DesignConfig.java", purpose: "config loader: jar defaults, validation, clamping to the caps, migration hook (config_version)", families: ALL, limits: ["only values under items.* are migrated", "backup config.yml.bak-v<N>"], tests: [UNIT, REAL, "Test Flight: out-of-range value clamped after /<mod> reload; old config_version migrated"], source: J.CONFIG_JAVA },
