303	export function progressEntryChars(q: QuestDesign): number {
304	  const steps = questSteps(q);
305	  const stepLen = Math.max(...steps.map((s) => s.step.id.length));
306	  const branchLen = Math.max(0, ...(q.branches?.options ?? []).map((b) => b.id.length));
307	  const counts = Math.max(...steps.map((s) => s.step.objectives.map((o) => String(objectiveTarget(o)).length).reduce((a, b) => a + b + 1, -1)));
