318	type Sink = { errors: GpIssue[]; warnings: GpIssue[]; file: string };
319	const failF = (s: Sink, path: string, code: string, message: string) => s.errors.push({ path, code, message, file: s.file });
320	const warnF = (s: Sink, path: string, code: string, message: string) => s.warnings.push({ path, code, message, file: s.file });
321	
322	function checkItemRef(s: Sink, at: string, ref: string, ctx: GpContext, idx: Index, what: string, display = false) {
323	  if (ref.startsWith("minecraft:")) {
324	    if (!isVanilla("item", ref, ctx.version)) failF(s, at, "unknown_vanilla_id", missingIdReason("item", ref, ctx.version));
325	    else if (ref === "minecraft:air" || (!display && BANNED_BASES.test(ref.slice(10)))) failF(s, at, "banned_item", `${ref} cannot be ${what} (operator item, spawn egg or a drastic right-click)`);
326	  } else if (!idx.items.has(ref)) failF(s, at, "unresolved_ref", `no design item "${ref}" in this mod`);
327	}
328	function checkIcon(s: Sink, at: string, ic: Icon, ctx: GpContext, idx: Index, fe: DesignFeatures) {
329	  if ((ic.material === undefined) === (ic.item === undefined)) { failF(s, at, "icon_source", "an icon needs exactly one of material (a vanilla item) or item (a design item of this mod)"); return; }
330	  if (ic.material) checkItemRef(s, `${at}.material`, ic.material, ctx, idx, "an icon", true);
331	  if (ic.item && !idx.items.has(ic.item)) failF(s, `${at}.item`, "unresolved_ref", `no design item "${ic.item}" in this mod`);
332	  if (ic.model) {
333	    if (!ic.model.startsWith(`${ctx.namespace}:`)) failF(s, `${at}.model`, "foreign_namespace", `the item model must be in this mod's namespace ${ctx.namespace}`);
334	    else if (ctx.assets?.models && !ctx.assets.models.includes(ic.model)) warnF(s, `${at}.model`, "asset_unresolved", `${ic.model}: this mod has no such item model, so the icon keeps its base look`);
335	    if (!fe.itemModel) warnF(s, `${at}.model`, "item_model_unsupported", `custom item models need Minecraft 1.21.4 or newer; on ${ctx.version} the icon keeps its base look`);
336	  }
337	}
338	function checkSound(s: Sink, at: string, key: string, ctx: GpContext) {
339	  const kns = key.split(":")[0];
340	  if (kns === "minecraft") warnF(s, at, "vanilla_sound_unchecked", `${key}: vanilla sound keys are not checked against the game (a wrong key plays nothing)`);
341	  else if (kns !== ctx.namespace) failF(s, at, "foreign_namespace", `${key} uses the namespace ${kns}; sounds must be minecraft: or this mod's ${ctx.namespace}`);
342	  else if (ctx.assets?.sounds && !ctx.assets.sounds.includes(key)) warnF(s, at, "asset_unresolved", `${key}: this mod has no such custom sound, so it plays nothing`);
343	}
344	function checkCost(s: Sink, at: string, c: Cost | undefined, ctx: GpContext, idx: Index) {
345	  if (!c) return;
346	  if (c.type === "item") checkItemRef(s, `${at}.item`, c.item, ctx, idx, "a cost");
347	  if (c.type === "economy") warnF(s, at, "economy_needs_vault", "money costs work only when the server runs Vault and an economy plugin; without them this is refused with a message");
348	}
349	function checkAbilityRef(s: Sink, at: string, item: string, ability: string, idx: Index) {
350	  const it = idx.items.get(item);
351	  if (!it) { failF(s, at, "unresolved_ref", `no design item "${item}" in this mod`); return; }
352	  const ab = it.abilities.find((a) => a.id === ability);
353	  if (!ab) { failF(s, at, "unresolved_ref", `item ${item} has no ability "${ability}"`); return; }
354	  if (TRIGGER_HAS_TARGET[ab.trigger.type] === "always") warnF(s, at, "run_ability_no_target", `${item}.${ability} normally has a target (${ab.trigger.type}); run from a menu or reward it has none, so target effects are skipped`);
355	}
356	function permsOf(s: Sink, perms: { node: string }[] | undefined): Set<string> {
357	  const out = new Set<string>();
358	  (perms ?? []).forEach((p, i) => {
359	    if (out.has(p.node)) failF(s, `permissions[${i}].node`, "duplicate_id", `permission ${p.node} is declared twice`);
360	    if (RESERVED_NODES.test(p.node)) failF(s, `permissions[${i}].node`, "reserved_node", `${p.node} is reserved for the mod's own command`);
361	    out.add(p.node);
362	  });
363	  return out;
364	}
365	
366	function checkActions(s: Sink, at: string, list: MenuAction[] | undefined, ctx: GpContext, idx: Index, here: MenuDesign | null) {
367	  (list ?? []).forEach((a, i) => {
368	    const ap = `${at}.actions[${i}]`;
369	    switch (a.type) {
370	      case "open_menu": if (!idx.menus.has(a.menu)) failF(s, `${ap}.menu`, "unresolved_ref", `no menu "${a.menu}" in this mod`); else if (here && a.menu === here.id) warnF(s, ap, "reopen_self", "opening the same menu only refreshes it"); break;
371	      case "next_page": case "prev_page": if (!here || here.style !== "chest" || !here.list) failF(s, ap, "no_list", `${a.type} needs a menu with a paginated list`); break;
372	      case "back": break;
373	      case "give_item": checkItemRef(s, `${ap}.item`, a.item, ctx, idx, "given by a menu"); break;
374	      case "play_sound": checkSound(s, `${ap}.sound`, a.sound, ctx); break;
375	      case "run_ability": checkAbilityRef(s, ap, a.item, a.ability, idx); break;
376	      case "start_quest": case "abandon_quest": if (!idx.quests.has(a.quest)) failF(s, `${ap}.quest`, "unresolved_ref", `no quest "${a.quest}" in this mod`); break;
377	      case "choose_branch": {
378	        const q = idx.quests.get(a.quest);
379	        if (!q) failF(s, `${ap}.quest`, "unresolved_ref", `no quest "${a.quest}" in this mod`);
380	        else if (!q.branches?.options.some((b) => b.id === a.branch)) failF(s, `${ap}.branch`, "unresolved_ref", `quest ${a.quest} has no branch "${a.branch}"`);
381	        break;
382	      }
383	      case "open_quest_log": if (!idx.quests.size) failF(s, ap, "no_quests", "open_quest_log needs at least one quest in this mod"); break;
384	      default: break;
385	    }
386	  });
387	  const gives = (list ?? []).filter((a) => a.type === "give_item").length;
388	  if (gives > 4) failF(s, `${at}.actions`, "too_many_gives", `${gives} give_item actions in one click; the limit is 4`);
389	}
