391	/** Validate one menu (references resolved against the mod index). */
392	export function validateMenu(input: unknown, ctx: GpContext, idx: Index, fe: DesignFeatures): GpValidation<MenuDesign> {
393	  const id = (input as { id?: string })?.id ?? "?";
394	  const s: Sink = { errors: [], warnings: [], file: id };
395	  if (sizeOf(input) > GAMEPLAY_LIMITS.maxSpecBytes) { failF(s, "(root)", "spec_size", `the menu is larger than ${GAMEPLAY_LIMITS.maxSpecBytes} bytes`); return { ok: false, ...s }; }
396	  const p = MenuDesignSchema.safeParse(input);
397	  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) failF(s, issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors: s.errors, warnings: s.warnings }; }
398	  const m = p.data;
399	  const perms = permsOf(s, m.permissions);
400	  const needPerm = (at: string, node?: string) => { if (node && !perms.has(node)) failF(s, at, "undeclared_permission", `permission ${ctx.namespace}.${node} is not declared in "permissions"`); };
401	  needPerm("permission", m.permission);
402	  if (m.openWith?.item) {
403	    const it = idx.items.get(m.openWith.item);
404	    if (!it) failF(s, "openWith.item", "unresolved_ref", `no design item "${m.openWith.item}" in this mod`);
405	    else if (it.abilities.some((a) => ["right_click", "sneak_right_click", "charge_release"].includes(a.trigger.type))) failF(s, "openWith.item", "opener_conflict", `${m.openWith.item} has right-click abilities; a menu opener item must not (both would fire on one click)`);
406	  }
407	  const clicks = menuClickables(m);
408	  for (const { path, c } of clicks) {
409	    checkIcon(s, `${path}.icon`, c.icon, ctx, idx, fe);
410	    checkCost(s, `${path}.cost`, c.cost, ctx, idx);
411	    needPerm(`${path}.permission`, c.permission);
412	    checkActions(s, path, c.actions, ctx, idx, m);
413	    // dupe at the IR level: a click that gives more of its own cost item than it takes is an infinite source
414	    if (c.cost?.type === "item") {
415	      const give = (c.actions ?? []).filter((a) => a.type === "give_item" && a.item === (c.cost as { item: string }).item).reduce((n, a) => n + ((a as { count?: number }).count ?? 1), 0);
416	      if (give > c.cost.count) failF(s, path, "cost_loop", `gives ${give} x ${c.cost.item} for ${c.cost.count} x ${c.cost.item}: an endless source of that item`);
417	      else if (give && give === c.cost.count) warnF(s, path, "cost_noop", "gives back exactly what it costs");
418	    }
419	    if (c.hideWithoutPermission && !c.permission) warnF(s, path, "hide_without_permission", "hideWithoutPermission does nothing without a permission");
420	    if (!c.actions?.length && c.cost) failF(s, path, "cost_without_action", "a cost with no actions takes the player's items for nothing");
421	  }
422	  if (m.style === "chest") {
423	    const size = m.rows * 9;
424	    const used = new Map<number, string>();
425	    const claim = (slot: number, at: string) => {
426	      if (slot >= size) { failF(s, at, "slot_outside", `slot ${slot} is outside a ${m.rows}-row menu (0-${size - 1})`); return; }
427	      if (used.has(slot)) failF(s, at, "slot_overlap", `slot ${slot} is also used by ${used.get(slot)}`);
428	      else used.set(slot, at);
429	    };
430	    (m.buttons ?? []).forEach((b, i) => claim(b.slot, `buttons[${i}].slot`));
431	    if (m.filler) checkItemRef(s, "filler", m.filler, ctx, idx, "a filler", true);
432	    if (m.list) {
433	      const L = m.list;
434	      L.slots.forEach((x, i) => claim(x, `list.slots[${i}]`));
435	      claim(L.prev.slot, "list.prev.slot"); claim(L.next.slot, "list.next.slot");
436	      checkIcon(s, "list.prev.icon", L.prev.icon, ctx, idx, fe); checkIcon(s, "list.next.icon", L.next.icon, ctx, idx, fe);
437	      if (L.source.type === "fixed") {
438	        const pages = Math.ceil(L.source.entries.length / L.slots.length);
439	        if (pages > GAMEPLAY_LIMITS.maxPages) failF(s, "list.source.entries", "too_many_pages", `${L.source.entries.length} entries in ${L.slots.length} slots is ${pages} pages; the limit is ${GAMEPLAY_LIMITS.maxPages}`);
440	      } else {
441	        const cur = L.source.currency;
442	        if (cur.type === "item") checkItemRef(s, "list.source.currency.item", cur.item, ctx, idx, "a currency");
443	        if (cur.type === "economy") warnF(s, "list.source.currency", "economy_needs_vault", "money prices work only when the server runs Vault and an economy plugin; without them purchases are refused with a message");
444	        const [lo, hi] = cur.type === "item" ? GAMEPLAY_CAPS.itemCost : cur.type === "xp_levels" ? GAMEPLAY_CAPS.xpLevelCost : cur.type === "economy" ? GAMEPLAY_CAPS.economyCost : [0, 0];
445	        L.source.entries.forEach((e, i) => {
446	          const at = `list.source.entries[${i}]`;
447	          checkItemRef(s, `${at}.material`, e.material, ctx, idx, "sold");
448	          if (cur.type === "item" && e.material === cur.item) failF(s, `${at}.material`, "cost_loop", "a config list cannot sell its own currency");
449	          if (cur.type !== "free" && (e.price < lo || e.price > hi)) failF(s, `${at}.price`, "price_range", `price ${e.price} is outside ${lo}-${hi} for a ${cur.type} currency`);
450	          if (cur.type !== "economy" && !Number.isInteger(e.price)) failF(s, `${at}.price`, "price_integer", "item and XP prices are whole numbers");
451	        });
452	        const cap = Math.min(GAMEPLAY_LIMITS.maxConfigEntries, L.slots.length * GAMEPLAY_LIMITS.maxPages);
453	        if (L.source.entries.length > cap) failF(s, "list.source.entries", "too_many_pages", `more than ${cap} entries do not fit ${GAMEPLAY_LIMITS.maxPages} pages`);
454	        if (cur.type === "free") warnF(s, "list.source.currency", "free_list", "every entry of this list is free");
455	      }
456	      if (L.prev.slot === L.next.slot) failF(s, "list.next.slot", "slot_overlap", "prev and next use the same slot");
457	    } else if (!(m.buttons ?? []).length) failF(s, "buttons", "empty_menu", "a chest menu needs buttons or a list");
458	  }
459	  if (m.style === "dialogue" && m.speakerIcon) checkIcon(s, "speakerIcon", m.speakerIcon, ctx, idx, fe);
460	  if (m.openWith?.npc && m.style !== "dialogue") warnF(s, "openWith.npc", "npc_chest", "NPC menus are usually dialogues; this opens a chest menu from an NPC");
461	  return s.errors.length ? { ok: false, errors: s.errors, warnings: s.warnings } : { ok: true, design: m, errors: [], warnings: s.warnings };
462	}
