464	/** Validate one quest (references resolved against the mod index). */
465	export function validateQuest(input: unknown, ctx: GpContext, idx: Index): GpValidation<QuestDesign> {
466	  const id = (input as { id?: string })?.id ?? "?";
467	  const s: Sink = { errors: [], warnings: [], file: id };
468	  if (sizeOf(input) > GAMEPLAY_LIMITS.maxSpecBytes) { failF(s, "(root)", "spec_size", `the quest is larger than ${GAMEPLAY_LIMITS.maxSpecBytes} bytes`); return { ok: false, ...s }; }
469	  const p = QuestDesignSchema.safeParse(input);
470	  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) failF(s, issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors: s.errors, warnings: s.warnings }; }
471	  const q = p.data;
472	  const v = ctx.version;
473	  const perms = permsOf(s, q.permissions);
474	  if (q.permission && !perms.has(q.permission)) failF(s, "permission", "undeclared_permission", `permission ${ctx.namespace}.${q.permission} is not declared in "permissions"`);
475	  (q.requires ?? []).forEach((r, i) => {
476	    if (r === q.id) failF(s, `requires[${i}]`, "circular_prerequisites", "a quest cannot require itself");
477	    else if (!idx.quests.has(r)) failF(s, `requires[${i}]`, "unresolved_ref", `no quest "${r}" in this mod`);
478	  });
479	  if (new Set(q.requires ?? []).size !== (q.requires ?? []).length) failF(s, "requires", "duplicate_id", "a prerequisite is listed twice");
480	  const stepIds = new Set<string>();
481	  for (const { step, path } of questSteps(q)) {
482	    if (stepIds.has(step.id)) failF(s, `${path}.id`, "duplicate_id", `step ${step.id} is defined twice in this quest (main and branch steps share one id space)`);
483	    stepIds.add(step.id);
484	    step.objectives.forEach((o, j) => {
485	      const at = `${path}.objectives[${j}]`;
486	      switch (o.type) {
487	        case "kill_entity":
488	          if (!o.entity && !o.kinds?.length) failF(s, at, "empty_filter", "kill_entity needs an entity or kinds");
489	          if (o.entity && !isVanilla("entity_type", o.entity, v)) failF(s, `${at}.entity`, "unknown_vanilla_id", missingIdReason("entity_type", o.entity, v));
490	          break;
491	        case "collect_item": case "craft_item":
492	          checkItemRef(s, `${at}.item`, o.item, ctx, idx, o.type === "collect_item" ? "collected" : "crafted");
493	          if (o.type === "craft_item" && !o.item.startsWith("minecraft:") && idx.items.get(o.item) && !idx.items.get(o.item)!.recipe) failF(s, `${at}.item`, "not_craftable", `design item ${o.item} has no recipe, so it can never be crafted`);
494	          if (o.type === "collect_item" && o.take && o.mode === "pickup") warnF(s, at, "take_pickup", "take with pickup mode removes the items only if the player still has them when the step completes");
495	          break;
496	        case "break_block": if (!isVanilla("block", o.block, v)) failF(s, `${at}.block`, "unknown_vanilla_id", missingIdReason("block", o.block, v)); break;
497	        case "talk": {
498	          const m = idx.menus.get(o.menu);
499	          if (!m) failF(s, `${at}.menu`, "unresolved_ref", `no menu "${o.menu}" in this mod`);
500	          else if (m.style !== "dialogue") failF(s, `${at}.menu`, "not_dialogue", `talk needs a dialogue menu; ${o.menu} is a chest menu`);
501	          break;
502	        }
503	        default: break;
504	      }
505	    });
506	    const kinds = step.objectives.map((o) => o.type === "talk" ? `talk:${o.menu}` : o.type === "visit_location" ? `visit:${o.world}:${o.x}:${o.y}:${o.z}` : "");
507	    if (kinds.some((k, i) => k && kinds.indexOf(k) !== i)) warnF(s, `${path}.objectives`, "duplicate_objective", "two identical objectives in one step complete together");
508	  }
509	  if (q.branches) {
510	    const ids = new Set<string>();
511	    q.branches.options.forEach((b, i) => { if (ids.has(b.id)) failF(s, `branches.options[${i}].id`, "duplicate_id", `branch ${b.id} is defined twice`); ids.add(b.id); if (b.icon) checkIcon(s, `branches.options[${i}].icon`, b.icon, ctx, idx, designFeatures(v).ok ? (designFeatures(v) as { features: DesignFeatures }).features : ({ itemModel: true } as DesignFeatures)); });
512	  }
513	  const rewardCheck = (list: Reward[] | undefined, at: string) => (list ?? []).forEach((r, i) => {
514	    const rp = `${at}[${i}]`;
515	    switch (r.type) {
516	      case "give_item": checkItemRef(s, `${rp}.item`, r.item, ctx, idx, "a reward"); break;
517	      case "xp": if ((r.points === undefined) === (r.levels === undefined)) failF(s, rp, "xp_amount", "xp needs exactly one of points or levels"); break;
518	      case "advancement": {
519	        const ns = r.advancement.split(":")[0];
520	        if (ns !== ctx.namespace) failF(s, `${rp}.advancement`, "foreign_namespace", `${r.advancement}: only this project's own data pack advancements (${ctx.namespace}:...) can be granted`);
521	        else if (ctx.assets?.advancements === undefined) warnF(s, `${rp}.advancement`, "advancement_unchecked", `${r.advancement} is not checked against the project's data pack here; if it is missing the reward logs a note and grants nothing`);
522	        else if (!ctx.assets.advancements.includes(r.advancement)) failF(s, `${rp}.advancement`, "advancement_not_in_project", `${r.advancement} is not an advancement of this project's data pack (make it with the data pack studio first)`);
523	        break;
524	      }
525	      case "run_ability": checkAbilityRef(s, rp, r.item, r.ability, idx); break;
526	      default: break;
527	    }
528	  });
529	  rewardCheck(q.rewards, "rewards");
530	  q.branches?.options.forEach((b, i) => rewardCheck(b.rewards, `branches.options[${i}].rewards`));
531	  if (q.icon) { const fe = designFeatures(v); if (fe.ok) checkIcon(s, "icon", q.icon, ctx, idx, fe.features); }
532	  const mode = q.repeat?.mode ?? "once";
533	  if (mode === "once" && q.repeat?.cooldownSeconds !== undefined) warnF(s, "repeat.cooldownSeconds", "no_repeat", "a once-only quest has no cooldown");
534	  const surviveTotal = (steps: Step[]) => steps.reduce((n, st) => n + Math.max(0, ...st.objectives.map((o) => (o.type === "survive" ? o.seconds : 0))), 0);
535	  const limit = q.failure?.timeLimitSeconds;
536	  if (limit !== undefined) {
537	    const worst = surviveTotal(q.steps) + Math.max(0, ...(q.branches?.options ?? []).map((b) => surviveTotal(b.steps)));
538	    if (worst > limit) failF(s, "failure.timeLimitSeconds", "time_limit_too_short", `the survive objectives need ${worst} s but the time limit is ${limit} s: the quest can never be completed`);
539	  }
540	  // reward farm: a repeatable quest that completes instantly (only talk / visit) with a short cooldown must not give items or XP
541	  const instant = questSteps(q).every(({ step }) => step.objectives.every((o) => o.type === "talk" || o.type === "visit_location"));
542	  const valuable = [...(q.rewards ?? []), ...(q.branches?.options ?? []).flatMap((b) => b.rewards ?? [])].some((r) => r.type === "give_item" || r.type === "xp");
543	  if (mode !== "once" && repeatCooldown(q) < FARM_COOLDOWN_SECONDS && instant && valuable) failF(s, "repeat", "reward_farm", `this quest completes instantly (talk/visit only) and repeats after ${repeatCooldown(q)} s: its item/XP rewards could be farmed. Use a cooldown of at least ${FARM_COOLDOWN_SECONDS} s or a real objective`);
544	  if (mode !== "once" && repeatCooldown(q) < FARM_COOLDOWN_SECONDS) {
545	    // collecting X (kept) and getting X back as a reward is an endless source
546	    const kept = new Set(questSteps(q).flatMap(({ step }) => step.objectives.filter((o) => o.type === "collect_item" && !o.take).map((o) => (o as { item: string }).item)));
547	    const back = [...(q.rewards ?? []), ...(q.branches?.options ?? []).flatMap((b) => b.rewards ?? [])].filter((r) => r.type === "give_item" && kept.has(r.item));
548	    if (back.length) failF(s, "rewards", "reward_farm", `the reward gives ${(back[0] as { item: string }).item}, which the quest only asks the player to have (not take), and it repeats quickly: an endless source`);
549	  }
550	  if (q.failure?.abandon === false && mode === "once" && !limit) warnF(s, "failure.abandon", "no_abandon", "players can never drop this quest");
551	  return s.errors.length ? { ok: false, errors: s.errors, warnings: s.warnings } : { ok: true, design: q, errors: [], warnings: s.warnings };
552	}
