554	export type GameplayValidation = {
555	  ok: boolean;
556	  /** Per file, in input order. */
557	  files: { id: string; kind: DesignKind | null; ok: boolean; errors: GpIssue[]; warnings: GpIssue[] }[];
558	  items: ItemDesign[]; menus: MenuDesign[]; quests: QuestDesign[];
559	  /** Mod-level errors (also listed in each affected file's errors when one is affected). */
560	  errors: GpIssue[];
561	  itemResults: DesignValidation[];
562	  features?: DesignFeatures;
563	  /** Worst-case progress characters per player (QuestStore v1). */
564	  progressChars: number;
