567	/** Exchange graph of every priced click (cost item -> given item): a cycle that multiplies the start amount is an arbitrage dupe. */
568	export function arbitrageLoops(menus: MenuDesign[], quests: QuestDesign[] = []): { cycle: string[]; gain: number; where: string }[] {
569	  type Edge = { from: string; to: string; rate: number; where: string };
570	  const edges: Edge[] = [];
571	  for (const m of menus) {
572	    for (const { path, c } of menuClickables(m)) {
573	      if (c.cost?.type !== "item") continue;
574	      for (const a of c.actions ?? []) if (a.type === "give_item") edges.push({ from: c.cost.item, to: a.item, rate: (a.count ?? 1) / c.cost.count, where: `${m.id}: ${path}` });
575	    }
576	    if (m.style === "chest" && m.list?.source.type === "config" && m.list.source.currency.type === "item") {
577	      const cur = m.list.source.currency.item;
578	      m.list.source.entries.forEach((e, i) => { if (e.price > 0) edges.push({ from: cur, to: e.material, rate: e.amount / e.price, where: `${m.id}: list.source.entries[${i}]` }); });
579	    }
580	  }
581	  for (const q of quests) {
582	    if ((q.repeat?.mode ?? "once") === "once" || repeatCooldown(q) >= FARM_COOLDOWN_SECONDS) continue;
583	    for (const { step, path } of questSteps(q)) for (const o of step.objectives) if (o.type === "collect_item" && o.take)
584	      for (const r of q.rewards ?? []) if (r.type === "give_item") edges.push({ from: o.item, to: r.item, rate: (r.count ?? 1) / o.count, where: `${q.id}: ${path}` });
585	  }
586	  // Bellman-Ford on -log(rate) from every node; bounded: at most ~600 edges
587	  const nodes = [...new Set(edges.flatMap((e) => [e.from, e.to]))];
588	  const out: { cycle: string[]; gain: number; where: string }[] = [];
589	  const seen = new Set<string>();
590	  for (const start of nodes) {
591	    const dist = new Map<string, number>(nodes.map((n) => [n, Infinity]));
592	    const pred = new Map<string, Edge>();
593	    dist.set(start, 0);
594	    for (let i = 0; i < nodes.length; i++) for (const e of edges) { const w = -Math.log(e.rate); if (dist.get(e.from)! + w < dist.get(e.to)! - 1e-12) { dist.set(e.to, dist.get(e.from)! + w); pred.set(e.to, e); } }
595	    for (const e of edges) {
596	      if (dist.get(e.from)! - Math.log(e.rate) < dist.get(e.to)! - 1e-12) {
597	        // walk back to find the cycle
598	        let x = e.to;
599	        for (let i = 0; i < nodes.length; i++) x = pred.get(x)?.from ?? x;
600	        const cyc: string[] = []; let y = x; let gain = 1; let where = "";
601	        for (let i = 0; i <= nodes.length; i++) { const pe = pred.get(y); if (!pe) break; cyc.unshift(y); gain *= pe.rate; where = pe.where; y = pe.from; if (y === x) break; }
602	        const key = [...cyc].sort().join(">");
603	        if (cyc.length && !seen.has(key)) { seen.add(key); out.push({ cycle: [...cyc, cyc[0]], gain: +gain.toFixed(4), where }); }
604	      }
605	    }
606	  }
607	  return out;
608	}
