610	/** Validate a whole mod: every design file (any kind) + the cross-file checks. */
611	export function validateGameplay(inputs: unknown[], ctx: GpContext): GameplayValidation {
612	  const errors: GpIssue[] = [];
613	  const res: GameplayValidation = { ok: false, files: [], items: [], menus: [], quests: [], errors, itemResults: [], progressChars: 0 };
614	  const fail = (file: string | undefined, path: string, code: string, message: string) => { const e = { path, code, message, ...(file ? { file } : {}) }; errors.push(e); const f = res.files.find((x) => x.id === file); if (f) { f.errors.push(e); f.ok = false; } };
615	  if (!NAMESPACE_RE.test(ctx.namespace)) { fail(undefined, "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); return res; }
616	  const fe = designFeatures(ctx.version);
617	  if (!fe.ok) { fail(undefined, "version", "unsupported_version", fe.error); return res; }
618	  res.features = fe.features;
619	  const kinds = inputs.map(designKind);
620	  const ids = inputs.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : ""));
621	  inputs.forEach((_, i) => res.files.push({ id: ids[i] || `#${i}`, kind: kinds[i], ok: true, errors: [], warnings: [] }));
622	  if (inputs.length > GAMEPLAY_LIMITS.maxDesignFiles) fail(undefined, "(mod)", "too_many_files", `${inputs.length} design files; the limit is ${GAMEPLAY_LIMITS.maxDesignFiles}`);
623	  kinds.forEach((k, i) => { if (!k) fail(res.files[i].id, "kind", "unknown_kind", `"kind" must be absent/"item", "menu" or "quest"`); });
624	  const dup = ids.find((k, i) => k && ids.indexOf(k) !== i);
625	  if (dup) fail(dup, "(mod)", "duplicate_item", `design ${dup} is defined twice (items, menus and quests share one id space)`);
626	  const count = (k: DesignKind) => kinds.filter((x) => x === k).length;
627	  if (count("menu") > GAMEPLAY_LIMITS.maxMenus) fail(undefined, "(mod)", "too_many_menus", `${count("menu")} menus; the limit is ${GAMEPLAY_LIMITS.maxMenus}`);
628	  if (count("quest") > GAMEPLAY_LIMITS.maxQuests) fail(undefined, "(mod)", "too_many_quests", `${count("quest")} quests; the limit is ${GAMEPLAY_LIMITS.maxQuests}`);
629	  // items first (the item validator, unchanged)
630	  const itemIdx = inputs.map((x, i) => (kinds[i] === "item" ? i : -1)).filter((i) => i >= 0);
631	  const iv = validateDesigns(itemIdx.map((i) => inputs[i]), { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets });
632	  res.itemResults = iv.results;
633	  for (const e of iv.errors) fail(undefined, e.path, e.code, e.message);
634	  iv.results.forEach((r, j) => {
635	    const f = res.files[itemIdx[j]];
636	    for (const w of r.warnings) f.warnings.push({ ...w, file: f.id });
637	    if (!r.ok) { for (const e of r.errors) { const x = { ...e, file: f.id }; f.errors.push(x); errors.push(x); } f.ok = false; } else res.items.push(r.design);
638	  });
639	  // the index: every parseable menu/quest (so references between them resolve even when another check fails)
640	  const idx: Index = { items: new Map(res.items.map((d) => [d.id, d])), menus: new Map(), quests: new Map() };
641	  inputs.forEach((x, i) => {
642	    if (kinds[i] === "menu") { const p = MenuDesignSchema.safeParse(x); if (p.success) idx.menus.set(p.data.id, p.data); }
643	    if (kinds[i] === "quest") { const p = QuestDesignSchema.safeParse(x); if (p.success) idx.quests.set(p.data.id, p.data); }
644	  });
645	  inputs.forEach((x, i) => {
646	    const k = kinds[i];
647	    if (k !== "menu" && k !== "quest") return;
648	    const r = k === "menu" ? validateMenu(x, ctx, idx, fe.features) : validateQuest(x, ctx, idx);
649	    const f = res.files[i];
650	    f.warnings.push(...r.warnings);
651	    if (!r.ok) { for (const e of r.errors) { const y = { ...e, file: f.id }; f.errors.push(y); errors.push(y); } f.ok = false; }
652	    else if (k === "menu") res.menus.push(r.design as MenuDesign); else res.quests.push(r.design as QuestDesign);
653	  });
654	  // ---- cross-file: prerequisite cycles
655	  const qmap = new Map(res.quests.map((q) => [q.id, q]));
656	  const state = new Map<string, number>();
657	  const stack: string[] = [];
658	  const inCycle = new Set<string>();
659	  const dfs = (id: string) => {
660	    state.set(id, 1); stack.push(id);
661	    for (const r of qmap.get(id)?.requires ?? []) {
662	      if (!qmap.has(r)) continue;
663	      if (state.get(r) === 1) stack.slice(stack.indexOf(r)).forEach((x) => inCycle.add(x));
664	      else if (!state.get(r)) dfs(r);
665	    }
666	    stack.pop(); state.set(id, 2);
667	  };
668	  for (const q of res.quests) if (!state.get(q.id)) dfs(q.id);
669	  for (const id of [...inCycle].sort()) fail(id, "requires", "circular_prerequisites", `quest ${id} is part of a prerequisite cycle (${[...inCycle].sort().join(" -> ")}), so it can never start`);
670	  // ---- reachability: menus that can be opened, quests that can be started
671	  const openable = new Set<string>();
672	  for (const m of res.menus) if (m.openWith?.command !== false || m.openWith?.item || m.openWith?.npc) openable.add(m.id);
673	  const mmap = new Map(res.menus.map((m) => [m.id, m]));
674	  const queue = [...openable];
675	  while (queue.length) {
676	    const m = mmap.get(queue.shift()!);
677	    if (!m) continue;
678	    for (const { c } of menuClickables(m)) for (const a of c.actions ?? []) if (a.type === "open_menu" && mmap.has(a.menu) && !openable.has(a.menu)) { openable.add(a.menu); queue.push(a.menu); }
679	  }
680	  for (const m of res.menus) if (!openable.has(m.id)) fail(m.id, "openWith", "unreachable_menu", `menu ${m.id} can never be opened (no command, item, NPC or open_menu from an openable menu)`);
681	  const startedFromMenu = new Set<string>();
682	  for (const m of res.menus) if (openable.has(m.id)) for (const { c } of menuClickables(m)) for (const a of c.actions ?? []) if (a.type === "start_quest") startedFromMenu.add(a.quest);
683	  const startable = new Map<string, boolean>();
684	  const canStart = (id: string, seen = new Set<string>()): boolean => {
685	    if (startable.has(id)) return startable.get(id)!;
686	    const q = qmap.get(id);
687	    if (!q || seen.has(id) || inCycle.has(id)) return false;
688	    seen.add(id);
689	    const ok = ((q.start ?? "command") === "command" || startedFromMenu.has(id)) && (q.requires ?? []).every((r) => canStart(r, seen));
690	    startable.set(id, ok);
691	    return ok;
692	  };
693	  for (const q of res.quests) {
694	    if (inCycle.has(q.id)) continue;
695	    if (!canStart(q.id)) fail(q.id, q.start === "menu" && !startedFromMenu.has(q.id) ? "start" : "requires", "unreachable_quest", q.start === "menu" && !startedFromMenu.has(q.id) ? `quest ${q.id} starts only from a menu, but no openable menu has a start_quest for it` : `quest ${q.id} needs a quest that can never be started`);
696	    for (const { step, path } of questSteps(q)) step.objectives.forEach((o, j) => { if (o.type === "talk" && mmap.has(o.menu) && !openable.has(o.menu)) fail(q.id, `${path}.objectives[${j}]`, "unreachable_dialogue", `dialogue ${o.menu} can never be opened, so this objective can never be met`); });
697	  }
698	  // ---- arbitrage (dupe) loops across every shop and fast-repeat quest
699	  for (const loop of arbitrageLoops(res.menus, res.quests)) fail(loop.where.split(":")[0], loop.where.split(": ")[1] ?? "(mod)", "arbitrage_loop", `trading ${loop.cycle.join(" -> ")} multiplies the items by ${loop.gain}: an endless source (lower the given counts or raise the costs)`);
700	  // ---- stored progress worst case (bounded PDC string per player)
701	  res.progressChars = 3 + res.quests.reduce((n, q) => n + progressEntryChars(q) + 1, 0);
702	  if (res.progressChars > GAMEPLAY_LIMITS.maxProgressChars) fail(res.quests.at(-1)?.id, "(mod)", "progress_oversize", `a player's stored quest progress could reach ${res.progressChars} characters; the limit is ${GAMEPLAY_LIMITS.maxProgressChars} (use shorter quest/step ids or fewer quests)`);
703	  // drop invalid designs from the lists (a cross-file failure makes that file invalid)
704	  const bad = new Set(res.files.filter((f) => !f.ok).map((f) => f.id));
705	  res.menus = res.menus.filter((m) => !bad.has(m.id)).sort((a, b) => (a.id < b.id ? -1 : 1));
706	  res.quests = res.quests.filter((q) => !bad.has(q.id)).sort((a, b) => (a.id < b.id ? -1 : 1));
707	  res.items = res.items.filter((d) => !bad.has(d.id));
708	  res.ok = !errors.length && res.files.every((f) => f.ok);
709	  return res;
710	}
