341	/** Static worst case of one action list (multiplicity = how many times the list runs per activation). */
342	export function budgetOf(list: Action[], mult = 1, depth = 1): { actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number } {
343	  const t = { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0, nodes: 0, depth };
344	  for (const a of list) {
345	    t.actions += mult; t.nodes += 1;
346	    const add = (b: ReturnType<typeof budgetOf>) => { t.actions += b.actions; t.entities += b.entities; t.tasks += b.tasks; t.particles += b.particles; t.projectiles += b.projectiles; t.nodes += b.nodes; t.depth = Math.max(t.depth, b.depth); };
347	    switch (a.type) {
348	      case "damage": case "heal": case "potion_effect": case "knockback": case "pull_to": case "push_from": case "apply_mark": t.entities += mult; break;
349	      case "spawn_particles": t.particles += a.count * mult; break;
350	      case "launch_projectile": t.projectiles += mult; t.tasks += mult; break; // the lifetime task
351	      case "query_marked": case "query_nearby": add(budgetOf(a.actions, mult * a.max, depth + 1)); break;
352	      case "delayed": t.tasks += mult; add(budgetOf(a.actions, mult, depth + 1)); break;
353	      case "branch": { const th = budgetOf(a.then, mult, depth + 1), el = a.else ? budgetOf(a.else, mult, depth + 1) : null; t.nodes += th.nodes + (el?.nodes ?? 0) + a.if.length;
354	        // worst case = the heavier branch for each counter
355	        for (const k of ["actions", "entities", "tasks", "particles", "projectiles"] as const) t[k] += Math.max(th[k], el?.[k] ?? 0);
356	        t.depth = Math.max(t.depth, th.depth, el?.depth ?? 0); break; }
357	      default: break;
358	    }
359	  }
360	  return t;
361	}
