363	/** Walk every action (pre-order) with its path ("a0", "a1.n0", "a2.then0", "a2.else1"). */
364	export function walkActions(list: Action[], fn: (a: Action, path: string, inLoop: boolean) => void, prefix = "", inLoop = false): void {
365	  list.forEach((a, i) => {
366	    const here = prefix ? `${prefix}${i}` : `a${i}`;
367	    fn(a, here, inLoop);
368	    if (a.type === "query_marked" || a.type === "query_nearby") walkActions(a.actions, fn, `${here}.n`, true);
369	    else if (a.type === "delayed") walkActions(a.actions, fn, `${here}.n`, inLoop);
370	    else if (a.type === "branch") { walkActions(a.then, fn, `${here}.then`, inLoop); if (a.else) walkActions(a.else, fn, `${here}.else`, inLoop); }
371	  });
372	}
373	/** Every condition of an ability with its path ("c0", "a2.if0"). */
374	export function walkConditions(ab: Ability, fn: (c: Condition, path: string, inLoop: boolean) => void): void {
375	  (ab.conditions ?? []).forEach((c, i) => fn(c, `c${i}`, false));
376	  walkActions(ab.actions, (a, p, inLoop) => { if (a.type === "branch") a.if.forEach((c, i) => fn(c, `${p}.if${i}`, inLoop)); });
377	}
