379	export function validateDesign(input: unknown, ctx: DesignContext): DesignValidation {
380	  const errors: DzIssue[] = [];
381	  const warnings: DzIssue[] = [];
382	  const bucket = new Map<string, string[]>(DESIGN_CHECKS.map((c) => [c, []]));
383	  const failed = new Set<string>();
384	  const ran = new Set<string>(["schema"]);
385	  const fail = (check: string, path: string, code: string, message: string) => { errors.push({ path, code, message }); failed.add(check); bucket.get(check)!.push(`${path}: ${message}`); };
386	  const warn = (check: string, path: string, code: string, message: string) => { warnings.push({ path, code, message }); bucket.get(check)!.push(`warn ${path}: ${message}`); };
387	  const budgets: AbilityBudget[] = [];
388	  const checksOf = (): DzCheck[] => DESIGN_CHECKS.map((id) => {
389	    const items = bucket.get(id)!;
390	    return { id, status: !ran.has(id) ? "not_run" : failed.has(id) ? "fail" : items.length ? "warn" : "pass", items: items.slice(0, 20) };
391	  });
392	  const bad = (): DesignValidation => ({ ok: false, errors, warnings, checks: checksOf(), budgets });
393	
394	  ran.add("namespace");
395	  if (!NAMESPACE_RE.test(ctx.namespace)) { fail("namespace", "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); return bad(); }
396	  ran.add("version_features");
397	  const fe = designFeatures(ctx.version);
398	  if (!fe.ok) { fail("version_features", "version", "unsupported_version", fe.error); return bad(); }
399	  const v = ctx.version;
400	  if (input && typeof input === "object" && !Array.isArray(input) && (input as { schemaVersion?: unknown }).schemaVersion !== undefined && (input as { schemaVersion?: unknown }).schemaVersion !== DESIGN_SPEC_VERSION) {
401	    fail("schema", "schemaVersion", "schema_version", `schemaVersion must be ${DESIGN_SPEC_VERSION}`); return bad();
402	  }
403	  const bytes = (() => { try { return new TextEncoder().encode(JSON.stringify(input)).length; } catch { return Infinity; } })();
404	  ran.add("limits");
405	  if (bytes > DESIGN_LIMITS.maxSpecBytes) { fail("limits", "(root)", "spec_size", `the design is ${bytes} bytes; the limit is ${DESIGN_LIMITS.maxSpecBytes}`); return bad(); }
406	  const parsed = ItemDesignSchema.safeParse(input);
407	  if (!parsed.success) {
408	    for (const i of parsed.error.issues.slice(0, 30)) fail("schema", issuePath(i.path) || "(root)", "schema", i.message);
409	    return bad();
410	  }
411	  const d = parsed.data;
412	  for (const c of ["vanilla_ids", "references", "context", "budget"]) ran.add(c);
413	  const ns = ctx.namespace;
414	  const id = buildIdentifier(ns, "item", d.id);
415	  if (!id.ok) fail("namespace", "id", "bad_id", id.error);
416	
417	  // base item
