604	/** Validate a whole mod (all its design files): each file + cross-file duplicates. */
605	export function validateDesigns(inputs: unknown[], ctx: Omit<DesignContext, "items">): { ok: boolean; results: DesignValidation[]; errors: DzIssue[] } {
606	  const keys = inputs.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : "")).filter(Boolean);
607	  const errors: DzIssue[] = [];
608	  if (inputs.length > DESIGN_LIMITS.maxItems) errors.push({ path: "(mod)", code: "too_many_items", message: `${inputs.length} design items; the limit is ${DESIGN_LIMITS.maxItems}` });
609	  const dup = keys.find((k, i) => keys.indexOf(k) !== i);
610	  if (dup) errors.push({ path: "(mod)", code: "duplicate_item", message: `design item ${dup} is defined twice` });
611	  const results = inputs.slice(0, DESIGN_LIMITS.maxItems).map((x) => validateDesign(x, { ...ctx, items: keys }));
612	  return { ok: !errors.length && results.every((r) => r.ok), results, errors };
613	}
