44	function iconParams(s: ParamSink, rel: string, ic: Icon, what: string) {
45	  if (ic.name) addParam(s, `${rel}.name`, "text", [0, 60], ic.name.text, `${what} name`, "text");
46	  (ic.lore ?? []).forEach((l, j) => addParam(s, `${rel}.lore${j}`, "text", [0, 60], l.text, `${what} lore line ${j + 1}`, "text"));
47	  if (ic.amount !== undefined) addParam(s, `${rel}.amount`, "int", cap("iconAmount"), ic.amount, `${what} stack size shown`, "count");
48	}
49	function costParams(s: ParamSink, rel: string, c: Cost | undefined, what: string) {
50	  if (!c) return;
51	  if (c.type === "item") addParam(s, `${rel}.cost.count`, "int", cap("itemCost"), c.count, `${what} price (${c.item.replace(/^minecraft:/, "")})`, "price");
52	  if (c.type === "xp_levels") addParam(s, `${rel}.cost.levels`, "int", cap("xpLevelCost"), c.levels, `${what} price (XP levels)`, "price");
53	  if (c.type === "economy") addParam(s, `${rel}.cost.amount`, "num", cap("economyCost"), c.amount, `${what} price (money, Vault)`, "price");
54	}
55	function actionParams(s: ParamSink, rel: string, list: MenuAction[] | undefined, what: string) {
56	  (list ?? []).forEach((a, k) => {
57	    const r = `${rel}.a${k}`;
58	    switch (a.type) {
59	      case "give_item": addParam(s, `${r}.count`, "int", cap("giveCount"), a.count ?? DEFAULTS.giveCount, `${what} gives ${a.item.replace(/^minecraft:/, "")} (count)`, "count"); break;
60	      case "send_message": case "actionbar": addParam(s, `${r}.text`, "text", [0, 120], a.text, `${what} ${a.type === "actionbar" ? "actionbar" : "message"} text`, "text"); break;
61	      case "play_sound": addParam(s, `${r}.sound`, "sound", [0, 100], a.sound, `${what} sound key`, "sound"); addParam(s, `${r}.volume`, "num", cap("volume"), a.volume ?? DEFAULTS.volume, `${what} sound volume`, "other"); addParam(s, `${r}.pitch`, "num", cap("pitch"), a.pitch ?? DEFAULTS.pitch, `${what} sound pitch`, "other"); break;
62	      case "potion_effect": addParam(s, `${r}.duration_ticks`, "ticks", cap("potionTicks"), a.durationTicks, `${what} ${a.effect} duration (ticks)`, "duration"); addParam(s, `${r}.amplifier`, "int", cap("amplifier"), a.amplifier ?? DEFAULTS.amplifier, `${what} ${a.effect} level - 1`, "level"); break;
63	      case "heal": addParam(s, `${r}.amount`, "num", cap("heal"), a.amount, `${what} heal (health points)`, "heal"); break;
64	      default: break;
65	    }
66	  });
67	}
68	/** Node id of each clickable: buttons by slot (b<slot>), fixed list entries e<i>, dialogue choices c<i>. */
69	export function clickNode(path: string, slot?: number): string {
70	  if (slot !== undefined) return `b${slot}`;
71	  const m = /\[(\d+)\]$/.exec(path);
72	  return path.startsWith("choices") ? `c${m![1]}` : `e${m![1]}`;
73	}
