75	export function menuParams(m: MenuDesign): Param[] {
76	  const s = sinkFor(`menus.${m.id}.`, m.id);
77	  addParam(s, "title", "text", [0, 32], m.title, "menu title", "text");
78	  if (m.style === "dialogue") {
79	    addParam(s, "speaker", "text", [0, 60], m.speaker.text, "speaker name", "text");
80	    m.lines.forEach((l, i) => addParam(s, `line${i}`, "text", [0, 80], l, `dialogue line ${i + 1}`, "text"));
81	    if (m.speakerIcon) iconParams(s, "speaker_icon", m.speakerIcon, "speaker icon");
82	  }
83	  for (const { path, c, slot } of menuClickables(m)) {
84	    const node = clickNode(path, slot);
85	    const what = slot !== undefined ? `slot ${slot}` : path.startsWith("choices") ? `choice ${node.slice(1)}` : `entry ${node.slice(1)}`;
86	    iconParams(s, node, c.icon, what);
87	    costParams(s, node, c.cost, what);
88	    actionParams(s, node, c.actions, what);
89	  }
90	  if (m.style === "chest" && m.list) { iconParams(s, "prev", m.list.prev.icon, "previous page button"); iconParams(s, "next", m.list.next.icon, "next page button"); }
91	  return own(s, "menu");
92	}
