103	      addParam(s, `${rel}.x`, "num", cap("coord"), o.x, `${what}: x`, "other"); addParam(s, `${rel}.y`, "num", cap("coordY"), o.y, `${what}: y`, "other"); addParam(s, `${rel}.z`, "num", cap("coord"), o.z, `${what}: z`, "other");
