121	export function questParams(q: QuestDesign): Param[] {
122	  const s = sinkFor(`quests.${q.id}.`, q.id);
123	  addParam(s, "title", "text", [0, 40], q.title, "quest title", "text");
124	  if (q.description) addParam(s, "description", "text", [0, 120], q.description, "quest description", "text");
125	  if (q.icon) iconParams(s, "icon", q.icon, "quest icon");
126	  if ((q.repeat?.mode ?? "once") !== "once") addParam(s, "repeat.cooldown_seconds", "int", cap("repeatCooldownSeconds"), repeatCooldown(q), `${q.repeat!.mode} cooldown (seconds)`, "cooldown");
127	  if (q.failure?.timeLimitSeconds !== undefined) addParam(s, "failure.time_limit_seconds", "int", cap("timeLimitSeconds"), q.failure.timeLimitSeconds, "time limit (seconds)", "duration");
128	  if (q.branches?.prompt) addParam(s, "branches.prompt", "text", [0, 60], q.branches.prompt, "branch choice prompt", "text");
129	  for (const { step } of questSteps(q)) {
130	    addParam(s, `steps.${step.id}.text`, "text", [0, 80], step.text, `step ${step.id} text`, "text");
131	    step.objectives.forEach((o, j) => objectiveParams(s, `steps.${step.id}.o${j}`, o, `step ${step.id}`));
132	  }
133	  for (const b of q.branches?.options ?? []) {
134	    addParam(s, `branches.${b.id}.label`, "text", [0, 60], b.label.text, `branch ${b.id} label`, "text");
135	    rewardParams(s, `branches.${b.id}.rewards`, b.rewards, `branch ${b.id}`);
136	  }
137	  rewardParams(s, "rewards", q.rewards, "quest");
138	  return own(s, "quest");
139	}
