141	/** Every parameter of a mod, in config order: items, then menus, then quests (each sorted by id). */
142	export function modParams(items: ItemDesign[], menus: MenuDesign[], quests: QuestDesign[]): Param[] {
143	  const byId = <T extends { id: string }>(x: T[]) => [...x].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
144	  return [...designParams(items), ...byId(menus).flatMap(menuParams), ...byId(quests).flatMap(questParams)];
