148	type Gen = { params: Map<string, Param>; statics: string[]; ns: string; models: string[] | undefined };
149	const P = (g: Gen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
150	const has = (g: Gen, rel: string) => g.params.has(rel);
151	const nameColor = (c?: string) => (c ? colorExpr(c) : "null");
152	
153	function iconExpr(g: Gen, rel: string, ic: Icon, fallbackName?: string): string {
154	  const name = has(g, `${rel}.name`) ? P(g, `${rel}.name`) : fallbackName ?? "null";
155	  const lore = (ic.lore ?? []).map((_, j) => P(g, `${rel}.lore${j}`));
156	  const loreExpr = lore.length ? `List.of(${lore.join(", ")})` : "List.of()";
157	  const amount = has(g, `${rel}.amount`) ? P(g, `${rel}.amount`) : "1";
158	  if (ic.item) return `designIcon(${jstr(ic.item)}, ${name}, ${nameColor(ic.name?.color)}, ${loreExpr}, ${amount}, ${!!ic.glint})`;
159	  const modelOk = !!ic.model && (!g.models || g.models.includes(ic.model));
160	  const [mns, mkey] = modelOk ? ic.model!.split(":") : [null, null];
161	  return `icon(${MATERIAL(ic.material!)}, ${name}, ${nameColor(ic.name?.color)}, ${loreExpr}, ${amount}, ${!!ic.glint}, ${mns ? jstr(mns) : "null"}, ${mkey ? jstr(mkey) : "null"})`;
162	}
163	function costExpr(g: Gen, rel: string, c: Cost | undefined): string {
164	  if (!c) return "CostCharger.Cost.NONE";
165	  if (c.type === "item") return c.item.startsWith("minecraft:") ? `CostCharger.Cost.items(${MATERIAL(c.item)}, ${P(g, `${rel}.cost.count`)})` : `CostCharger.Cost.design(${jstr(c.item)}, ${P(g, `${rel}.cost.count`)})`;
166	  if (c.type === "xp_levels") return `CostCharger.Cost.levels(${P(g, `${rel}.cost.levels`)})`;
167	  return `CostCharger.Cost.money(${P(g, `${rel}.cost.amount`)})`;
168	}
169	function givesExpr(g: Gen, rel: string, list: MenuAction[] | undefined): string {
170	  const s = (list ?? []).map((a, k) => (a.type !== "give_item" ? null : a.item.startsWith("minecraft:") ? `stack(${MATERIAL(a.item)}, ${P(g, `${rel}.a${k}.count`)})` : `designStack(${jstr(a.item)}, ${P(g, `${rel}.a${k}.count`)})`)).filter(Boolean);
171	  return `gives(${s.join(", ")})`;
172	}
173	function clickBody(g: Gen, rel: string, list: MenuAction[] | undefined): string[] {
174	  const out: string[] = [];
175	  (list ?? []).forEach((a, k) => {
176	    const r = `${rel}.a${k}`;
177	    switch (a.type) {
178	      case "open_menu": out.push(`ctx.open(${jstr(a.menu)});`); break;
179	      case "close": out.push("ctx.close();"); break;
180	      case "back": out.push("ctx.back();"); break;
181	      case "next_page": out.push("ctx.nextPage();"); break;
182	      case "prev_page": out.push("ctx.prevPage();"); break;
183	      case "give_item": out.push(a.item.startsWith("minecraft:") ? `ctx.give(stack(${MATERIAL(a.item)}, 1), ${P(g, `${r}.count`)});` : `ctx.giveDesign(${jstr(a.item)}, ${P(g, `${r}.count`)});`); break;
184	      case "send_message": out.push(`ctx.message(${P(g, `${r}.text`)}, ${a.color ? colorExpr(a.color) : "NamedTextColor.WHITE"});`); break;
185	      case "actionbar": out.push(`ctx.actionbar(${P(g, `${r}.text`)}, ${a.color ? colorExpr(a.color) : "NamedTextColor.WHITE"});`); break;
186	      case "play_sound": out.push(`ctx.sound(${P(g, `${r}.sound`)}, (float) ${P(g, `${r}.volume`)}, (float) ${P(g, `${r}.pitch`)});`); break;
187	      case "potion_effect": out.push(`ctx.potion(PotionEffectType.${a.effect.toUpperCase()}, (int) ${P(g, `${r}.duration_ticks`)}, ${P(g, `${r}.amplifier`)});`); break;
188	      case "heal": out.push(`ctx.heal(${P(g, `${r}.amount`)});`); break;
189	      case "run_ability": out.push(`ctx.ability(${jstr(a.item)}, ${jstr(a.ability)});`); break;
190	      case "start_quest": out.push(`ctx.startQuest(${jstr(a.quest)});`); break;
191	      case "abandon_quest": out.push(`ctx.abandonQuest(${jstr(a.quest)});`); break;
192	      case "choose_branch": out.push(`ctx.chooseBranch(${jstr(a.quest)}, ${jstr(a.branch)});`); break;
193	      case "open_quest_log": out.push("ctx.questLog();"); break;
194	    }
195	  });
196	  return out;
197	}
198	function lambda(body: string[], ind: string): string {
199	  if (!body.length) return "ctx -> {}";
200	  return `ctx -> {\n${body.map((l) => `${ind}    ${l}`).join("\n")}\n${ind}}`;
201	}
