213	function menuClass(pkg: string, m: MenuDesign, cls: string, ns: string, models: string[] | undefined): { source: string; params: Param[] } {
214	  const params = menuParams(m);
215	  const base = `menus.${m.id}.`;
216	  const g: Gen = { params: new Map(params.map((p) => [p.path.slice(base.length), p])), statics: [], ns, models };
217	  const body: string[] = ["reset();"];
218	  if (m.style === "chest") {
219	    if (m.filler) body.push(`filler(${MATERIAL(m.filler)});`);
220	    for (const { path, c, slot } of menuClickables(m)) {
221	      const node = clickNode(path, slot);
222	      const head = slot !== undefined ? `button(${slot}, ` : "entry(";
223	      body.push(`${head}${iconExpr(g, node, c.icon)}, ${costExpr(g, node, c.cost)}, ${c.permission ? jstr(c.permission) : "null"}, ${!!c.hideWithoutPermission}, ${givesExpr(g, node, c.actions)}, ${lambda(clickBody(g, node, c.actions), "        ")});`);
224	    }
225	    if (m.list) {
226	      body.push(`list(new int[] {${m.list.slots.join(", ")}}, ${m.list.prev.slot}, ${iconExpr(g, "prev", m.list.prev.icon, jstr("Previous page"))}, ${m.list.next.slot}, ${iconExpr(g, "next", m.list.next.icon, jstr("Next page"))});`);
227	      const src = m.list.source;
228	      if (src.type === "config") {
229	        const cur = src.currency;
230	        const kind = cur.type === "item" ? "ITEM" : cur.type === "xp_levels" ? "XP_LEVELS" : cur.type === "economy" ? "ECONOMY" : "FREE";
231	        const mat = cur.type === "item" && cur.item.startsWith("minecraft:") ? MATERIAL(cur.item) : "null";
232	        const des = cur.type === "item" && !cur.item.startsWith("minecraft:") ? jstr(cur.item) : "null";
233	        body.push(`configList(CostCharger.Kind.${kind}, ${mat}, ${des});`);
234	      }
235	    }
236	  } else {
237	    const icon = m.speakerIcon ? iconExpr(g, "speaker_icon", m.speakerIcon, P(g, "speaker")) : "null";
238	    body.push(`dialogue(${P(g, "speaker")}, ${nameColor(m.speaker.color)}, ${icon}, List.of(${m.lines.map((_, i) => P(g, `line${i}`)).join(", ")}));`);
239	    for (const { path, c } of menuClickables(m)) {
240	      const node = clickNode(path);
241	      body.push(`entry(${iconExpr(g, node, c.icon)}, ${costExpr(g, node, c.cost)}, ${c.permission ? jstr(c.permission) : "null"}, ${!!c.hideWithoutPermission}, ${givesExpr(g, node, c.actions)}, ${lambda(clickBody(g, node, c.actions), "        ")});`);
242	    }
243	  }
244	  const load = params.map((p) => loadLine(p, p.path.slice(base.length)));
245	  const ow = m.openWith ?? {};
246	  const src = [
247	    ...classHeader(pkg, "menus", ["CostCharger", "DesignConfig", "Gameplay", "MenuDef"]),
248	    `/** Menu "${m.title.replace(/\*\//g, "")}" (${ns}:${m.id}, ${m.style}${m.style === "chest" ? `, ${m.rows} rows` : ""}). Generated by Cyrus from assets/designs/${m.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
249	    `public final class ${cls} extends MenuDef {`,
250	    `    private static final String B = ${jstr(base)};`,
251	    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
252	    ``,
253	    `    public ${cls}(Gameplay g) {`,
254	    `        super(g, ${jstr(m.id)}, Style.${m.style === "chest" ? "CHEST" : "DIALOGUE"}, ${m.style === "chest" ? m.rows : 3}, ${m.permission ? jstr(m.permission) : "null"}, ${ow.command !== false}, ${ow.item ? jstr(ow.item) : "null"}, ${!!ow.npc});`,
255	    `    }`,
256	    ``,
257	    `    @Override`,
258	    `    public String title() { return p_title; }`,
259	    ``,
260	    `    @Override`,
261	    `    public void load(DesignConfig c) {`,
262	    ...load.map((l) => `        ${l}`),
263	    ...body.map((l) => `        ${l}`),
264	    `    }`,
265	    ``,
266	    `    @Override`,
267	    `    public void describe(List<String> out) {`,
268	    ...params.map((p) => `        out.add(B + ${jstr(p.path.slice(base.length))} + "=" + ${p.field});`),
269	    `    }`,
270	    `}`,
271	    ``,
272	  ];
273	  return { source: src.join("\n"), params };
274	}
