276	const KIND_BITS: Record<string, number> = { player: 1, hostile: 2, animal: 4, living: 8 };
277	function objectiveExpr(g: Gen, rel: string, o: Objective): string {
278	  const mat = (ref: string) => (ref.startsWith("minecraft:") ? `${MATERIAL(ref)}, null` : `null, ${jstr(ref)}`);
279	  switch (o.type) {
280	    case "kill_entity": {
281	      const set = o.entity ? `T_${rel.replace(/\./g, "_")}` : "Set.of()";
282	      if (o.entity) g.statics.push(`private static final Set<String> ${set} = Set.of(${jstr(bare(o.entity))});`);
283	      return `QuestDef.Objective.kill(${set}, ${(o.kinds ?? []).reduce((m, k) => m | KIND_BITS[k], 0)}, ${P(g, `${rel}.count`)})`;
284	    }
285	    case "collect_item": return `QuestDef.Objective.collect(${mat(o.item)}, ${P(g, `${rel}.count`)}, ${o.mode === "pickup"}, ${!!o.take})`;
286	    case "craft_item": return `QuestDef.Objective.craft(${mat(o.item)}, ${P(g, `${rel}.count`)})`;
287	    case "visit_location": return `QuestDef.Objective.visit(${P(g, `${rel}.world`)}, ${P(g, `${rel}.x`)}, ${P(g, `${rel}.y`)}, ${P(g, `${rel}.z`)}, ${P(g, `${rel}.radius`)})`;
288	    case "break_block": return `QuestDef.Objective.breaks(${MATERIAL(o.block)}, ${P(g, `${rel}.count`)})`;
289	    case "talk": return `QuestDef.Objective.talk(${jstr(o.menu)})`;
290	    case "survive": return `QuestDef.Objective.survive(${P(g, `${rel}.seconds`)})`;
291	  }
292	}
293	function rewardLines(g: Gen, rel: string, list: Reward[] | undefined): string[] {
294	  return (list ?? []).map((r, i) => {
295	    const p = `${rel}.r${i}`;
296	    switch (r.type) {
297	      case "give_item": return r.item.startsWith("minecraft:") ? `r.give(p, new ItemStack(${MATERIAL(r.item)}), ${P(g, `${p}.count`)});` : `r.design(p, ${jstr(r.item)}, ${P(g, `${p}.count`)});`;
298	      case "xp": return r.points !== undefined ? `r.points(p, ${P(g, `${p}.points`)});` : `r.levels(p, ${P(g, `${p}.levels`)});`;
299	      case "potion_effect": return `r.potion(p, PotionEffectType.${r.effect.toUpperCase()}, (int) ${P(g, `${p}.duration_ticks`)}, ${P(g, `${p}.amplifier`)});`;
300	      case "advancement": return `r.advancement(p, ${jstr(r.advancement.split(":").slice(1).join(":"))});`;
301	      case "run_ability": return `r.ability(p, ${jstr(r.item)}, ${jstr(r.ability)});`;
302	      case "send_message": return `r.message(p, ${P(g, `${p}.text`)}, ${r.color ? colorExpr(r.color) : "NamedTextColor.GREEN"});`;
