318	  for (const st of q.steps) body.push(`step(${stepArgs(st)});`);
319	  for (const b of q.branches?.options ?? []) {
320	    const ic = b.icon ? iconExpr(g, `branches.${b.id}.icon`, b.icon, P(g, `branches.${b.id}.label`)) : `icon(Material.PAPER, ${P(g, `branches.${b.id}.label`)}, ${nameColor(b.label.color)}, List.of(), 1, false, null, null)`;
