332	    ...classHeader(pkg, "quests", ["DesignConfig", "Gameplay", "QuestDef", "RewardDistributor"]),
333	    `/** Quest "${q.title.replace(/\*\//g, "")}" (${ns}:${q.id}). Generated by Cyrus from assets/designs/${q.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
334	    `public final class ${cls} extends QuestDef {`,
335	    `    private static final String B = ${jstr(base)};`,
336	    ...[...new Set(g.statics)].map((s) => `    ${s}`),
337	    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
338	    ``,
339	    `    public ${cls}(Gameplay g) {`,
340	    `        super(g, ${jstr(q.id)}, Start.${start}, Repeat.${mode.toUpperCase()}, OnDeath.${death}, ${q.failure?.abandon !== false}, ${q.progressBar !== false}, ${q.permission ? jstr(q.permission) : "null"}, List.of(${(q.requires ?? []).map(jstr).join(", ")}));`,
341	    `    }`,
342	    ``,
343	    `    @Override`,
344	    `    public void load(DesignConfig c) {`,
345	    ...load.map((l) => `        ${l}`),
346	    ...body.map((l) => `        ${l}`),
347	    `    }`,
348	    ``,
349	    `    @Override`,
