414	function listYaml(menus: MenuDesign[]): string[] {
415	  const lists = menus.filter((m): m is Extract<MenuDesign, { style: "chest" }> => m.style === "chest" && m.list?.source.type === "config");
416	  if (!lists.length) return [];
417	  const out = [`# Config lists (shop lines) belong to you: edit, add or remove lines and run reload. They are never reset by an update.`, `# Each line: material (a vanilla item id), amount (1-64), price (in the list's currency), name (optional).`, `lists:`];
418	  for (const m of lists) {
419	    const src = m.list!.source as Extract<NonNullable<typeof m.list>["source"], { type: "config" }>;
420	    const cur = src.currency.type === "item" ? src.currency.item : src.currency.type;
421	    out.push(`  # ${m.id}: currency ${cur}`);
422	    if (!src.entries.length) { out.push(`  ${m.id}: []`); continue; }
423	    out.push(`  ${m.id}:`);
424	    for (const e of src.entries) {
425	      out.push(`  - material: ${JSON.stringify(e.material)}`, `    amount: ${e.amount}`, `    price: ${Number.isInteger(e.price) ? e.price : e.price}`);
426	      if (e.name) out.push(`    name: ${JSON.stringify(e.name)}`);
427	    }
428	  }
429	  return out;
430	}
