484	const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`;
485	const secs = (t: number) => (t >= 86400 ? plural(+(t / 86400).toFixed(2), "day") : t >= 3600 ? plural(+(t / 3600).toFixed(2), "hour") : plural(t, "second"));
486	const costText = (c?: Cost) => (!c ? "" : c.type === "item" ? ` for ${c.count} x ${bare(c.item).replace(/_/g, " ")}` : c.type === "xp_levels" ? ` for ${c.levels} XP levels` : ` for ${c.amount} money (needs Vault)`);
487	const OBJ_WORDS = (o: Objective): string => {
488	  switch (o.type) {
489	    case "kill_entity": return `kill ${o.count} ${o.entity ? bare(o.entity).replace(/_/g, " ") : (o.kinds ?? []).join("/")}`;
490	    case "collect_item": return `${o.mode === "pickup" ? "pick up" : "have"} ${o.count} ${bare(o.item).replace(/_/g, " ")}${o.take ? " (handed in)" : ""}`;
491	    case "craft_item": return `craft ${o.count} ${bare(o.item).replace(/_/g, " ")}`;
492	    case "visit_location": return `go to ${o.x} ${o.y} ${o.z} in ${o.world}`;
493	    case "break_block": return `break ${o.count} ${bare(o.block).replace(/_/g, " ")}`;
494	    case "talk": return `talk (${o.menu})`;
495	    case "survive": return `survive ${o.seconds} s`;
496	  }
497	};
