520	    q.steps.forEach((s, i) => lines.push(`  ${i + 1}. ${s.text} (${s.objectives.map(OBJ_WORDS).join(", ")})`));
521	    for (const b of q.branches?.options ?? []) lines.push(`  - Path "${b.label.text}": ${b.steps.map((s) => `${s.text} (${s.objectives.map(OBJ_WORDS).join(", ")})`).join("; ")}`);
522	  }
