525	  lines.push(``, `## Commands and permissions`, ``,
526	    `- \`/${command} menu <id> [player]\` (${ns}.menu: everyone; other players ${ns}.menu.others), \`/${command} menu list\`, \`/${command} menu costs <id>\` (${ns}.command)`,
527	    `- \`/${command} quests\`, \`quests log\`, \`quests start|abandon|info|choose <id>\` (${ns}.quests: everyone); \`quests list\`, \`quests check\` (${ns}.command); \`quests reset <player>\` (${ns}.quests.admin)`,
528	    `- \`/${command} give <item> [player] [count]\` (${ns}.give), \`/${command} list\`, \`/${command} params [id]\` (${ns}.command), \`/${command} reload\` (${ns}.reload); operators by default`);
529	  for (const p of [...menus.flatMap((m) => m.permissions ?? []), ...quests.flatMap((q) => q.permissions ?? [])]) lines.push(`- ${ns}.${p.node}: ${p.description} (default ${p.default})`);
530	  if (notes.length) lines.push(``, `## Good to know`, ``, ...notes.map((n) => `- ${n}`));
531	  lines.push(``);
