536	/** Compile a whole mod (any mix of item, menu and quest design files). Item-only mods: the item compiler, unchanged. */
537	export function compileMod(inputs: unknown[], ctx: CompileContext & { assets?: CompileContext["assets"] & { advancements?: string[] } }): ModCompileResult {
538	  const kinds = inputs.map(designKind);
539	  if (kinds.every((k) => k === "item")) {
540	    const r = compileDesigns(inputs, ctx);
541	    if (!r.ok) return { ok: false, errors: r.errors, warnings: r.warnings };
542	    return { ...r, menus: [], quests: [], deps: [], counts: { items: r.designs.length, menus: 0, quests: 0 }, gameplay: false };
543	  }
544	  const warnings: GpIssue[] = [];
545	  if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(ctx.pluginName)) return { ok: false, errors: [{ path: "pluginName", code: "bad_name", message: "the plugin name must be 2-40 letters, digits or _ starting with a letter" }], warnings };
546	  const v = validateGameplay(inputs, { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets });
547	  for (const f of v.files) for (const w of f.warnings) warnings.push({ ...w, path: `${f.id}: ${w.path}` });
548	  if (!v.ok) return { ok: false, errors: [...v.errors.map((e) => ({ ...e, path: e.file ? `${e.file}: ${e.path}` : e.path }))], warnings };
549	  const fe = v.features as DesignFeatures;
550	  const items = [...v.items].sort((a, b) => (a.id < b.id ? -1 : 1));
551	  const { menus, quests } = v;
552	  const lower = ctx.pluginName.toLowerCase().replace(/_/g, "");
553	  const pkg = `dev.nxeon.plugins.${/^[a-z]/.test(lower) ? lower : `p${lower}`}`;
554	  const main = camel(ctx.pluginName.replace(/^[a-z]/, (c) => c.toUpperCase())) || "DesignerMod";
555	  const mainCls = /^[A-Z]/.test(main) ? main : `M${main}`;
556	  const command = ctx.pluginName.toLowerCase().slice(0, 32);
557	  if (vanillaIds("command", ctx.version).has(command)) return { ok: false, errors: [{ path: "pluginName", code: "command_clash", message: `/${command} is a vanilla command in Minecraft ${ctx.version}; pick another plugin name` }], warnings };
558	  const money = menus.some((m) => menuClickables(m).some(({ c }) => c.cost?.type === "economy") || (m.style === "chest" && m.list?.source.type === "config" && m.list.source.currency.type === "economy"));
559	  const files: CompiledFile[] = [];
560	  const dir = `src/main/java/${pkg.replace(/\./g, "/")}`;
561	  const add = (path: string, content: string, role: CompiledFile["role"]) => files.push({ path, content, sha256: sha256(content), role });
562	  for (const c of [...COMPONENTS, ...GAMEPLAY_COMPONENTS, ...(money ? [VAULT_COMPONENT] : [])]) add(`${dir}/${c.file}`, renderComponent(c.source, pkg), "component");
563	  add(`${dir}/${COMPAT_META.file}`, renderComponent(compatSource(fe), pkg), "compat");
564	  const classes = new Map<string, string>();
565	  const claim = (cls: string, what: string): DzIssue | null => { if (classes.has(cls)) return { path: what, code: "class_clash", message: `${classes.get(cls)} and ${what} map to the same Java class ${cls}; rename one` }; classes.set(cls, what); return null; };
566	  const itemClasses: string[] = [], menuClasses: string[] = [], questClasses: string[] = [];
567	  const modelsApplied: string[] = [];
568	  for (const d of items) {
569	    const icls = `${camel(d.id)}Item`;
570	    const e1 = claim(`items.${icls}`, d.id); if (e1) return { ok: false, errors: [e1], warnings };
571	    const abCls: string[] = [];
572	    for (const ab of d.abilities) {
573	      const acls = `${camel(d.id)}${camel(ab.id)}`;
574	      const e2 = claim(`abilities.${acls}`, `${d.id}.${ab.id}`); if (e2) return { ok: false, errors: [e2], warnings };
575	      add(`${dir}/abilities/${acls}.java`, abilityClass(pkg, d, ab, acls, ctx.namespace).source, "generated");
576	      abCls.push(acls);
577	    }
578	    const modelOk = !!d.assets?.model && (!ctx.assets?.models || ctx.assets.models.includes(d.assets.model));
579	    if (modelOk) modelsApplied.push(d.assets!.model!);
580	    add(`${dir}/items/${icls}.java`, itemClass(pkg, d, icls, abCls, ctx.namespace, fe, modelOk).source, "generated");
581	    itemClasses.push(icls);
582	  }
583	  for (const m of menus) {
584	    const cls = `${camel(m.id)}Menu`;
585	    const e = claim(`menus.${cls}`, m.id); if (e) return { ok: false, errors: [e], warnings };
586	    add(`${dir}/menus/${cls}.java`, menuClass(pkg, m, cls, ctx.namespace, ctx.assets?.models).source, "generated");
587	    menuClasses.push(cls);
588	  }
589	  for (const q of quests) {
590	    const cls = `${camel(q.id)}Quest`;
591	    const e = claim(`quests.${cls}`, q.id); if (e) return { ok: false, errors: [e], warnings };
592	    add(`${dir}/quests/${cls}.java`, questClass(pkg, q, cls, ctx.namespace, ctx.assets?.models).source, "generated");
593	    questClasses.push(cls);
594	  }
595	  const ids = { items: items.map((d) => d.id), menus: menus.map((m) => m.id), quests: quests.map((q) => q.id) };
596	  // R3 item model states (feature/cyrus-r2): the same ModelStates wiring as an item-only mod
597	  const ms = modelStatesOf(items, fe, ctx);
598	  if (ms) add(`${dir}/designer/ModelStates.java`, renderComponent(MODEL_STATES_JAVA, pkg), "component");
599	  add(`${dir}/${mainCls}.java`, mainClassGp(pkg, mainCls, ctx.namespace, command, itemClasses, menuClasses, questClasses, ids, !!ctx.customHooks, money, ms), "generated");
600	  const ordered = modParams(items, menus, quests);
601	  const valuesHash = designerValuesHash(ordered);
602	  const configVersion = ctx.configVersion !== undefined ? Math.max(1, Math.min(1_000_000, Math.round(ctx.configVersion))) : nextConfigVersion(ctx.previousConfig, valuesHash);
603	  add(`src/main/resources/config.yml`, configYmlGp(ctx.pluginName, command, ordered, configVersion, valuesHash, randomSeedFor(ctx.namespace), menus), "resource");
604	  const perms = [...items.flatMap((d) => d.permissions ?? []), ...menus.flatMap((m) => m.permissions ?? []), ...quests.flatMap((q) => q.permissions ?? [])];
605	  const desc = (ctx.description ?? [items.length ? `Items: ${items.map((d) => d.name.text).join(", ")}` : "", menus.length ? `Menus: ${menus.map((m) => m.title).join(", ")}` : "", quests.length ? `Quests: ${quests.map((q) => q.title).join(", ")}` : ""].filter(Boolean).join(". ")).slice(0, 200);
606	  add(`src/main/resources/plugin.yml`, pluginYmlGp(ctx.pluginName, `${pkg}.${mainCls}`, ctx.pluginVersion ?? "1.0.0", ctx.version, desc, command, ctx.namespace, perms, money), "resource");
607	  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
608	  // README: the item part from the item compiler's README text when there are items, then menus, quests, settings
609	  const notes: string[] = [];
610	  for (const d of items) if (d.assets?.model && fe.itemModel && !modelsApplied.includes(d.assets.model)) notes.push(`${d.name.text} keeps the ${bare(d.base).replace(/_/g, " ")} look: this mod has no custom model "${d.assets.model}".`);
611	  if (!fe.itemModel && (items.some((d) => d.assets?.model) || menus.some((m) => menuClickables(m).some(({ c }) => c.icon.model)))) notes.push(`Custom item models need Minecraft 1.21.4 or newer: on ${fe.version} items and icons keep their base look.`);
612	  notes.push(...stateNotes(items, fe));
613	  if (money) notes.push("Money prices need the Vault plugin and an economy plugin on the server; without them those buttons say so and take nothing.");
614	  if (menus.some((m) => m.openWith?.npc)) notes.push(`NPC menus open when a player right-clicks an entity tagged ${ctx.namespace}.npc.<menu id> (an operator adds the tag with /tag <entity> add ${ctx.namespace}.npc.<menu id>).`);
615	  if (quests.length) notes.push("Quest progress is stored on each player (no database) and survives restarts; when a quest's steps change in an update, players on a changed step restart that quest.");
616	  if (quests.some((q) => (q.repeat?.mode ?? "once") === "daily" || q.repeat?.mode === "weekly")) notes.push("Daily and weekly quests use a rolling cooldown from the last completion (24 h / 7 days), not a calendar reset.");
617	  if (menus.length) notes.push("Menu clicks are server-side only: shift-clicks, number keys, drags and drops in a menu do nothing; prices are taken before anything is given.");
618	  notes.push("Gameplay effects run on the server: protection plugins and PvP settings can block damage and teleports.");
619	  // the item part of the README = the item compiler's item sections (everything before its settings)
620	  const itemPart = (() => {
621	    if (!items.length) return "";
622	    const r = compileDesigns(items, { ...ctx, configVersion: 1 });
623	    if (!r.ok) return "";
624	    return r.readme.split("\n## Settings (config.yml)")[0].split("\n").slice(4).join("\n");
625	  })();
626	  const rd = readmeGp(itemPart, ordered, ctx.pluginName, command, ctx.namespace, ctx.version, menus, quests, notes);
627	  const hash = sha256(files.map((f) => `${f.path}\n${f.sha256}`).join("\n") + `\nREADME\n${sha256(rd)}`);
628	  return {
629	    ok: true, files, readme: rd, readmeSha256: sha256(rd), hash, params: ordered, warnings, notes, pkg, modelsApplied, mainClass: `${pkg}.${mainCls}`, command, configVersion, designerValuesHash: valuesHash,
630	    features: fe, javacVerified: (JAVAC_VERIFIED_VERSIONS as readonly string[]).includes(ctx.version), compiler: `${COMPILER_VERSION}+${GAMEPLAY_COMPILER_VERSION}`, library: GAMEPLAY_LIBRARY_VERSION, libraryHash: gameplayLibraryHash(),
631	    designs: items, menus, quests, deps: money ? [VAULT_DEP] : [], counts: { items: items.length, menus: menus.length, quests: quests.length }, gameplay: true,
632	  };
633	}
