1	// Cyrus R3 gameplay designers: the COMPILER. Validated item designs -> a complete Paper plugin source tree (Java,
2	// plugin.yml, config.yml) + README text for the mod page, deterministically (same designs + context = same bytes;
3	// golden-hash tested). The ability graph is compiled to straight Java that calls the verified component library
4	// (./components): no interpreter, no reflection, no free-form code. Every number, text and sound key of the graph is a
5	// config.yml PARAMETER (Java reads it through the clamping config loader), so editing a parameter changes config.yml
6	// (+ the README) and never a Java file (./params.ts proves it with a diff). Structure (kinds, effects, particles,
7	// targets, stats, recipe) is Java.
8	import { createHash } from "node:crypto";
9	import { vanillaIds } from "../datapack/versions";
10	import { COMPAT_META, COMPONENTS, COMPONENT_LIBRARY_VERSION, compatSource, libraryHash, renderComponent } from "./components";
11	import { MODEL_STATES_JAVA } from "./components/states";
12	import {
13	  CAPS, CONSUMABLE_BASES, DESIGN_SPEC_VERSION, RUNTIME_CAPS, validateDesigns, walkActions,
14	  type Ability, type Action, type CapName, type Condition, type DesignContext, type DesignFeatures, type DzIssue, type ItemDesign,
15	} from "./spec";
