17	export const COMPILER_VERSION = "cyrus-designer-compile-1";
18	/** Lanes where the generated sources were compiled with javac against the real Paper classpath (test/cyrus-designer-real.ts). */
19	export const JAVAC_VERIFIED_VERSIONS = ["1.21.11", "26.2"] as const;
