21	export type ParamKind = "num" | "ticks" | "int" | "text" | "sound";
22	export type Param = {
23	  /** Full config.yml path. */
24	  path: string;
25	  /** Java field (in the ability or item class). */
26	  field: string;
27	  kind: ParamKind;
28	  min: number;
29	  max: number;
30	  value: number | string;
31	  label: string;
32	  item: string;
33	  ability?: string;
34	  /** What the parameter is, for edit matching: cooldown / range / strength / sound / damage / heal / duration / chance / count / radius / text / other. */
35	  role: string;
36	  /** R3 menus/quests: the parameter belongs to a menu or a quest (`item` then holds its id); absent = an item parameter. */
37	  owner?: "menu" | "quest";
38	};
