40	export type CompileContext = {
41	  version: string;
42	  namespace: string;
43	  pluginName: string;
44	  pluginVersion?: string;
45	  description?: string;
46	  /** Free-form extension code exists at src/main/java/<pkg>/custom/CustomHooks.java (enable(JavaPlugin) / disable()). */
47	  customHooks?: boolean;
48	  /** The previous build's config.yml text: config_version is kept when the designer values did not change, else bumped. */
49	  previousConfig?: string;
50	  /** Exact config_version to emit (the portal re-compile reproduces the service's); wins over previousConfig. */
51	  configVersion?: number;
52	  assets?: DesignContext["assets"];
53	};
