55	export type CompiledFile = { path: string; content: string; sha256: string; role: "component" | "compat" | "generated" | "resource" };
56	export type CompileOk = {
57	  ok: true; files: CompiledFile[]; readme: string; readmeSha256: string; hash: string; params: Param[]; warnings: DzIssue[]; notes: string[];
58	  pkg: string; mainClass: string; command: string; modelsApplied: string[]; configVersion: number; designerValuesHash: string; features: DesignFeatures;
59	  javacVerified: boolean; compiler: string; library: string; libraryHash: string; designs: ItemDesign[];
60	};
