62	
63	export const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");
64	export const camel = (s: string) => s.split("_").filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("");
65	export const jstr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
66	export const ystr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
67	export const fmtNum = (v: number, kind: ParamKind) => (kind === "num" ? (Number.isInteger(v) ? v.toFixed(1) : String(v)) : String(Math.round(v)));
68	export const jnum = (v: number) => (Number.isInteger(v) ? `${v}.0` : String(v));
69	const fieldOf = (rel: string) => "p_" + rel.replace(/[.]/g, "_");
70	const COLOR_NAMES: Record<string, string> = { black: "BLACK", dark_blue: "DARK_BLUE", dark_green: "DARK_GREEN", dark_aqua: "DARK_AQUA", dark_red: "DARK_RED", dark_purple: "DARK_PURPLE", gold: "GOLD", gray: "GRAY", dark_gray: "DARK_GRAY", blue: "BLUE", green: "GREEN", aqua: "AQUA", red: "RED", light_purple: "LIGHT_PURPLE", yellow: "YELLOW", white: "WHITE" };
71	export const colorExpr = (c?: string) => (!c ? "null" : c.startsWith("#") ? `TextColor.color(0x${c.slice(1).toUpperCase()})` : `NamedTextColor.${COLOR_NAMES[c]}`);
72	const KIND_BITS: Record<string, number> = { player: 1, hostile: 2, animal: 4, living: 8 };
73	export const maskOf = (k?: string[]) => (k ?? []).reduce((m, x) => m | (KIND_BITS[x] ?? 0), 0);
74	export const bare = (id: string) => id.replace(/^minecraft:/, "");
75	export const MATERIAL = (id: string) => `Material.${bare(id).toUpperCase()}`;
76	
77	/** Optional-field defaults (documented in docs "Cyrus gameplay designers (R3)"). */
78	export const DEFAULTS = {
79	  knockbackVertical: 0.35, pullVertical: 0.25, pushVertical: 0.35, amplifier: 0, lifetimeTicks: 100, spread: 0.3, particleSpeed: 0.02,
80	  volume: 1, pitch: 1, fadeInTicks: 10, stayTicks: 40, fadeOutTicks: 10, giveCount: 1, chargeCost: 1, passiveAmplifier: 0,
81	} as const;
