92	/** The parameters of one ability, in config order (also the Java field order). */
93	export function abilityParams(item: ItemDesign, ab: Ability): Param[] {
94	  const s: ParamSink = { params: [], base: `items.${item.id}.abilities.${ab.id}.`, item: item.id, ability: ab.id, abilityName: ab.name };
95	  if (ab.cooldownTicks !== undefined) addParam(s, "cooldown_ticks", "ticks", "cooldownTicks", ab.cooldownTicks, "cooldown (ticks, 20 = 1 s)", "cooldown");
96	  if (ab.charges) { addParam(s, "charges.max", "int", "chargesMax", ab.charges.max, "charges", "charges"); addParam(s, "charges.regen_ticks", "ticks", "chargeRegenTicks", ab.charges.regenTicks, "ticks per charge regained", "cooldown"); }
97	  const t = ab.trigger;
98	  if ("targetRange" in t && t.targetRange !== undefined) addParam(s, "trigger.target_range", "num", "targetRange", t.targetRange, "target range (blocks)", "range");
99	  if (t.type === "held_interval") addParam(s, "trigger.period_ticks", "ticks", "periodTicks", t.periodTicks, "interval (ticks)", "cooldown");
100	  if (t.type === "charge_release") { addParam(s, "trigger.min_charge_ticks", "ticks", "minChargeTicks", t.minChargeTicks, "minimum charge (ticks)", "duration"); addParam(s, "trigger.max_charge_ticks", "ticks", "maxChargeTicks", t.maxChargeTicks, "full charge (ticks)", "duration"); }
101	  const cond = (c: Condition, rel: string) => {
102	    switch (c.type) {
103	      case "health_below": case "health_above": addParam(s, `${rel}.fraction`, "num", "healthFraction", c.fraction, `${c.type.replace("_", " ")} (fraction of max health)`, "other"); break;
104	      case "random_chance": addParam(s, `${rel}.chance`, "num", "chance", c.chance, "chance (0-1)", "chance"); break;
105	      case "time_of_day": addParam(s, `${rel}.from`, "int", "timeOfDay", c.from, "time window start (ticks)", "other"); addParam(s, `${rel}.to`, "int", "timeOfDay", c.to, "time window end (ticks)", "other"); break;
106	      case "charges_available": addParam(s, `${rel}.amount`, "int", "chargeCost", c.amount, "charges needed", "count"); break;
107	      default: break;
108	    }
109	  };
110	  (ab.conditions ?? []).forEach((c, i) => cond(c, `c${i}`));
111	  walkActions(ab.actions, (a, p) => {
112	    switch (a.type) {
113	      case "damage": addParam(s, `${p}.amount`, "num", "damage", a.amount, "damage (health points)", "damage"); break;
114	      case "heal": addParam(s, `${p}.amount`, "num", "heal", a.amount, "heal (health points)", "heal"); break;
115	      case "potion_effect": addParam(s, `${p}.duration_ticks`, "ticks", "potionTicks", a.durationTicks, `${a.effect} duration (ticks)`, "duration"); addParam(s, `${p}.amplifier`, "int", "amplifier", a.amplifier ?? DEFAULTS.amplifier, `${a.effect} level - 1`, "level"); break;
116	      case "knockback": case "pull_to": case "push_from": {
117	        const dv = a.type === "knockback" ? DEFAULTS.knockbackVertical : a.type === "pull_to" ? DEFAULTS.pullVertical : DEFAULTS.pushVertical;
118	        addParam(s, `${p}.strength`, "num", "strength", a.strength, `${a.type.replace("_", " ")} strength`, "strength"); addParam(s, `${p}.vertical`, "num", "vertical", a.vertical ?? dv, `${a.type.replace("_", " ")} lift`, "lift"); break;
119	      }
120	      case "teleport_short": addParam(s, `${p}.range`, "num", "teleportRange", a.range, "teleport range (blocks)", "range"); break;
121	      case "launch_projectile": addParam(s, `${p}.speed`, "num", "projectileSpeed", a.speed, `${a.kind} speed`, "speed"); addParam(s, `${p}.lifetime_ticks`, "ticks", "projectileLifetime", a.lifetimeTicks ?? DEFAULTS.lifetimeTicks, `${a.kind} lifetime (ticks)`, "duration"); break;
122	      case "spawn_particles": addParam(s, `${p}.count`, "int", "particleCount", a.count, `${a.particle} particles`, "count"); addParam(s, `${p}.spread`, "num", "particleSpread", a.spread ?? DEFAULTS.spread, `${a.particle} spread`, "other"); addParam(s, `${p}.speed`, "num", "particleSpeed", a.speed ?? DEFAULTS.particleSpeed, `${a.particle} speed`, "other"); break;
123	      case "play_sound": addParam(s, `${p}.sound`, "sound", [0, 100], a.sound, "sound key", "sound"); addParam(s, `${p}.volume`, "num", "volume", a.volume ?? DEFAULTS.volume, "sound volume", "other"); addParam(s, `${p}.pitch`, "num", "pitch", a.pitch ?? DEFAULTS.pitch, "sound pitch", "other"); break;
124	      case "send_message": case "actionbar": addParam(s, `${p}.text`, "text", [0, RUNTIME_CAPS.textChars], a.text, a.type === "actionbar" ? "actionbar text" : "message text", "text"); break;
125	      case "title":
126	        addParam(s, `${p}.title`, "text", [0, RUNTIME_CAPS.titleChars], a.title, "title text", "text");
127	        if (a.subtitle !== undefined) addParam(s, `${p}.subtitle`, "text", [0, RUNTIME_CAPS.subtitleChars], a.subtitle, "subtitle text", "text");
128	        addParam(s, `${p}.fade_in_ticks`, "ticks", "titleFadeTicks", a.fadeInTicks ?? DEFAULTS.fadeInTicks, "title fade in", "duration");
129	        addParam(s, `${p}.stay_ticks`, "ticks", "titleStayTicks", a.stayTicks ?? DEFAULTS.stayTicks, "title stay", "duration");
130	        addParam(s, `${p}.fade_out_ticks`, "ticks", "titleFadeTicks", a.fadeOutTicks ?? DEFAULTS.fadeOutTicks, "title fade out", "duration");
131	        break;
132	      case "give_item": addParam(s, `${p}.count`, "int", "giveCount", a.count ?? DEFAULTS.giveCount, `${a.item} count`, "count"); break;
133	      case "set_cooldown": {
134	        const ref = item.abilities.find((x) => x.id === (a.ability ?? ab.id));
135	        addParam(s, `${p}.ticks`, "ticks", "cooldownTicks", a.ticks ?? ref?.cooldownTicks ?? 0, `cooldown set on ${a.ability ?? ab.id} (ticks)`, "cooldown"); break;
136	      }
137	      case "consume_charge": addParam(s, `${p}.amount`, "int", "chargeCost", a.amount ?? DEFAULTS.chargeCost, "charges spent", "count"); break;
138	      case "query_marked": addParam(s, `${p}.radius`, "num", "queryMarkedRadius", a.radius, `marked "${a.mark}" search radius`, "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
139	      case "query_nearby": addParam(s, `${p}.radius`, "num", "queryNearbyRadius", a.radius, "nearby search radius", "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
140	      case "delayed": addParam(s, `${p}.delay_ticks`, "ticks", "delayTicks", a.delayTicks, "delay (ticks)", "duration"); break;
141	      case "branch": a.if.forEach((c, i) => cond(c, `${p}.if${i}`)); break;
142	      default: break;
143	    }
144	  });
145	  return s.params;
146	}
