148	export function itemParams(item: ItemDesign): Param[] {
149	  const s: ParamSink = { params: [], base: `items.${item.id}.`, item: item.id };
150	  for (const m of item.marks ?? []) { addParam(s, `marks.${m.name}.duration_ticks`, "ticks", "markTicks", m.durationTicks, `mark "${m.name}" duration (ticks)`, "duration"); addParam(s, `marks.${m.name}.max_per_owner`, "int", "marksPerOwner", m.maxPerOwner, `mark "${m.name}" max per player`, "count"); }
151	  (item.passives ?? []).forEach((p, i) => addParam(s, `passives.p${i}.amplifier`, "int", "passiveAmplifier", p.amplifier ?? DEFAULTS.passiveAmplifier, `passive ${p.effect} level - 1`, "level"));
152	  (item.acquisition?.loot ?? []).forEach((l, i) => addParam(s, `loot.l${i}.chance`, "num", "lootChance", l.chance, `chance in ${l.table}`, "chance"));
153	  (item.acquisition?.drops ?? []).forEach((l, i) => addParam(s, `drops.d${i}.chance`, "num", "lootChance", l.chance, `drop chance from ${l.entity}`, "chance"));
154	  return s.params;
155	}
