161	// ---------------------------------------------------------------------------------------------------- Java codegen
162	class Out {
163	  lines: string[] = [];
164	  push(ind: number, s: string) { this.lines.push("    ".repeat(ind) + s); }
165	}
166	export const JTYPE: Record<ParamKind, string> = { num: "double", ticks: "long", int: "int", text: "String", sound: "String" };
167	export function loadLine(p: Param, rel: string): string {
168	  switch (p.kind) {
169	    case "num": return `${p.field} = c.num(B + ${jstr(rel)}, ${jnum(p.min)}, ${jnum(p.max)});`;
170	    case "ticks": return `${p.field} = c.ticks(B + ${jstr(rel)}, ${p.min}L, ${p.max}L);`;
171	    case "int": return `${p.field} = c.integer(B + ${jstr(rel)}, ${p.min}, ${p.max});`;
172	    case "text": return `${p.field} = c.text(B + ${jstr(rel)}, ${p.max});`;
173	    case "sound": return `${p.field} = c.soundKey(B + ${jstr(rel)});`;
174	  }
175	}
176	
177	type AbGen = { item: ItemDesign; ab: Ability; params: Map<string, Param>; statics: string[]; ns: string; loopN: number };
178	const P = (g: AbGen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
179	
180	function condExpr(g: AbGen, c: Condition, rel: string, A: string): string {
181	  const neg = (e: string) => (c.negate ? `!(${e})` : e);
182	  const own = (ref?: string) => !ref || ref === g.ab.id;
183	  const other = (ref: string) => `d.ability(${jstr(g.item.id)}, ${jstr(ref)})`;
184	  switch (c.type) {
185	    case "cooldown_ready": return neg(own(c.ability) ? `cooldownReady(${A}.player())` : `(${other(c.ability!)} == null || ${other(c.ability!)}.cooldownReady(${A}.player()))`);
186	    case "has_permission": return neg(`${A}.player().hasPermission(${jstr(`${g.ns}.${c.node}`)})`);
187	    case "target_is": {
188	      const set = c.types?.length ? `T_${rel.replace(/\./g, "_")}` : "null";
189	      if (c.types?.length) g.statics.push(`private static final Set<String> ${set} = Set.of(${c.types.map((t) => jstr(bare(t))).join(", ")});`);
190	      const e = `Checks.targetIs(${A}.target(), ${maskOf(c.kinds)}, ${set})`;
191	      return c.negate ? `(${A}.target() != null && ${A}.target().isValid() && !${e})` : e;
192	    }
193	    case "world_in": {
194	      const set = `W_${rel.replace(/\./g, "_")}`;
195	      g.statics.push(`private static final Set<String> ${set} = Set.of(${c.worlds.map(jstr).join(", ")});`);
196	      return neg(`${set}.contains(${A}.player().getWorld().getName())`);
197	    }
198	    case "health_below": case "health_above":
199	      return `Checks.health(${c.subject === "self" ? `${A}.player()` : `${A}.livingTarget()`}, ${P(g, `${rel}.fraction`)}, ${c.type === "health_below"}, ${!!c.negate})`;
200	    case "item_identity": return neg(`d.identity().is(${A}.player().getInventory().${c.slot === "main_hand" ? "getItemInMainHand" : "getItemInOffHand"}(), ${jstr(c.item)})`);
201	    case "sneaking": return neg(`${A}.player().isSneaking()`);
202	    case "charges_available": return neg(own(c.ability) ? `chargesLeft(${A}.player()) >= ${P(g, `${rel}.amount`)}` : `(${other(c.ability!)} != null && ${other(c.ability!)}.chargesLeft(${A}.player()) >= ${P(g, `${rel}.amount`)})`);
203	    case "random_chance": return neg(`d.random().nextDouble() < ${P(g, `${rel}.chance`)}`);
204	    case "time_of_day": return neg(`Checks.timeIn(${A}.player().getWorld(), ${P(g, `${rel}.from`)}, ${P(g, `${rel}.to`)})`);
205	  }
206	}
