208	function actions(g: AbGen, o: Out, list: Action[], prefix: string, A: string, ind: number): void {
209	  list.forEach((a, i) => {
210	    const rel = prefix ? `${prefix}${i}` : `a${i}`;
211	    o.push(ind, `// ${rel}: ${a.type}`);
212	    o.push(ind, `if (!${A}.budget().action()) return;`);
213	    const subj = (t: string | undefined, dflt: "self" | "target") => ((t ?? dflt) === "self" ? `${A}.player()` : `${A}.livingTarget()`);
214	    const ent = (t: string | undefined) => ((t ?? "self") === "self" ? `${A}.player()` : `${A}.target()`);
215	    const at = (w: string | undefined) => (w === "target" ? `d.effects().target(${A})` : w === "point" ? `d.effects().point(${A})` : `d.effects().self(${A})`);
216	    const scale = (b?: boolean) => (b ? ` * ${A}.charge()` : "");
217	    switch (a.type) {
218	      case "damage": o.push(ind, `d.effects().damage(${A}, ${subj(a.target, "target")}, ${P(g, `${rel}.amount`)}${scale(a.scaleWithCharge)});`); break;
219	      case "heal": o.push(ind, `d.effects().heal(${A}, ${subj(a.target, "self")}, ${P(g, `${rel}.amount`)}${scale(a.scaleWithCharge)});`); break;
220	      case "potion_effect": o.push(ind, `d.effects().potion(${A}, ${subj(a.target, "self")}, PotionEffectType.${a.effect.toUpperCase()}, (int) ${P(g, `${rel}.duration_ticks`)}, ${P(g, `${rel}.amplifier`)});`); break;
221	      case "knockback": o.push(ind, `d.effects().knockback(${A}, ${subj(a.target, "target")}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
222	      case "pull_to": o.push(ind, `d.effects().pullTo(${A}, ${subj(a.target, "target")}, ${a.to === "self" ? `${A}.player().getLocation()` : `${A}.point()`}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
223	      case "push_from": o.push(ind, `d.effects().pushFrom(${A}, ${subj(a.target, "target")}, ${a.from === "self" ? `${A}.player().getLocation()` : `${A}.point()`}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
224	      case "teleport_short": o.push(ind, `d.effects().teleportShort(${A}, ${P(g, `${rel}.range`)});`); break;
225	      case "launch_projectile": o.push(ind, `d.effects().launch(${A}, ${jstr(a.kind)}, ${P(g, `${rel}.speed`)}, ${a.tag ? jstr(a.tag) : "null"}, ${P(g, `${rel}.lifetime_ticks`)});`); break;
226	      case "spawn_particles": o.push(ind, `d.effects().particles(${A}, ${at(a.at)}, Particle.${a.particle.toUpperCase()}, ${P(g, `${rel}.count`)}, ${P(g, `${rel}.spread`)}, ${P(g, `${rel}.speed`)});`); break;
227	      case "play_sound": o.push(ind, `d.effects().sound(${A}, ${at(a.at)}, ${P(g, `${rel}.sound`)}, (float) ${P(g, `${rel}.volume`)}, (float) ${P(g, `${rel}.pitch`)});`); break;
228	      case "send_message": o.push(ind, `d.effects().message(${A}, ${ent(a.to)}, ${P(g, `${rel}.text`)}, ${colorExpr(a.color)});`); break;
229	      case "actionbar": o.push(ind, `d.effects().actionbar(${A}, ${ent(a.to)}, ${P(g, `${rel}.text`)}, ${colorExpr(a.color)});`); break;
230	      case "title": o.push(ind, `d.effects().title(${A}, ${ent(a.to)}, ${P(g, `${rel}.title`)}, ${a.subtitle !== undefined ? P(g, `${rel}.subtitle`) : "null"}, ${colorExpr(a.color)}, ${P(g, `${rel}.fade_in_ticks`)}, ${P(g, `${rel}.stay_ticks`)}, ${P(g, `${rel}.fade_out_ticks`)});`); break;
231	      case "give_item":
232	        if (a.item.startsWith("minecraft:")) o.push(ind, `d.effects().give(${A}, new ItemStack(${MATERIAL(a.item)}), ${P(g, `${rel}.count`)});`);
233	        else { o.push(ind, `{`); o.push(ind + 1, `DesignItem gi = d.item(${jstr(a.item)});`); o.push(ind + 1, `d.effects().give(${A}, gi == null ? null : gi.create(), ${P(g, `${rel}.count`)});`); o.push(ind, `}`); }
234	        break;
235	      case "set_cooldown":
236	        if (!a.ability || a.ability === g.ab.id) o.push(ind, `startCooldown(${A}.player(), ${P(g, `${rel}.ticks`)});`);
237	        else { o.push(ind, `{`); o.push(ind + 1, `Ability o = d.ability(${jstr(g.item.id)}, ${jstr(a.ability)});`); o.push(ind + 1, `if (o != null) o.startCooldown(${A}.player(), ${P(g, `${rel}.ticks`)});`); o.push(ind, `}`); }
238	        break;
239	      case "consume_charge":
240	        if (!a.ability || a.ability === g.ab.id) o.push(ind, `spendCharges(${A}.player(), ${P(g, `${rel}.amount`)});`);
241	        else { o.push(ind, `{`); o.push(ind + 1, `Ability o = d.ability(${jstr(g.item.id)}, ${jstr(a.ability)});`); o.push(ind + 1, `if (o != null) o.spendCharges(${A}.player(), ${P(g, `${rel}.amount`)});`); o.push(ind, `}`); }
242	        break;
243	      case "apply_mark":
244	        o.push(ind, `{`);
245	        o.push(ind + 1, `LivingEntity mt = ${A}.livingTarget();`);
246	        o.push(ind + 1, `DesignItem.Mark m = d.item(${jstr(g.item.id)}).mark(${jstr(a.mark)});`);
247	        o.push(ind + 1, `if (mt != null && mt != ${A}.player() && ${A}.budget().entity() && d.marks().apply(${A}.player().getUniqueId(), mt.getUniqueId(), ${jstr(`${g.item.id}.${a.mark}`)}, d.now(), m.ticks(), m.max()) && m.glow()) mt.addPotionEffect(new PotionEffect(PotionEffectType.GLOWING, (int) m.ticks(), 0, false, false));`);
248	        o.push(ind, `}`);
249	        break;
250	      case "query_marked": case "query_nearby": {
251	        const n = ++g.loopN;
252	        const around = a.around === "point" ? `${A}.point()` : `${A}.player().getLocation()`;
253	        if (a.type === "query_marked") o.push(ind, `for (LivingEntity t${n} : d.marks().marked(${A}.player().getUniqueId(), ${jstr(`${g.item.id}.${a.mark}`)}, ${around}, ${P(g, `${rel}.radius`)}, ${P(g, `${rel}.max`)}, d.now())) {`);
254	        else {
255	          const set = a.types?.length ? `T_${rel.replace(/\./g, "_")}` : "null";
256	          if (a.types?.length) g.statics.push(`private static final Set<String> ${set} = Set.of(${a.types.map((t) => jstr(bare(t))).join(", ")});`);
257	          o.push(ind, `for (LivingEntity t${n} : Targets.nearby(${A}.player(), ${around}, ${P(g, `${rel}.radius`)}, ${P(g, `${rel}.max`)}, ${maskOf(a.kinds)}, ${set}, ${!!a.includePlayers})) {`);
258	        }
259	        o.push(ind + 1, `Activation a${n} = ${A}.withTarget(t${n});`);
260	        actions(g, o, a.actions, `${rel}.n`, `a${n}`, ind + 1);
261	        o.push(ind, `}`);
262	        break;
263	      }
264	      case "delayed":
265	        o.push(ind, `d.later(${A}, ${P(g, `${rel}.delay_ticks`)}, () -> {`);
266	        actions(g, o, a.actions, `${rel}.n`, A, ind + 1);
267	        o.push(ind, `});`);
268	        break;
269	      case "branch":
270	        o.push(ind, `if (${a.if.map((c, j) => condExpr(g, c, `${rel}.if${j}`, A)).join(" && ")}) {`);
271	        actions(g, o, a.then, `${rel}.then`, A, ind + 1);
272	        if (a.else) { o.push(ind, `} else {`); actions(g, o, a.else, `${rel}.else`, A, ind + 1); }
273	        o.push(ind, `}`);
274	        break;
275	    }
276	  });
277	}
