306	  if (t.type === "charge_release") { load.push("minChargeTicks = p_trigger_min_charge_ticks;"); load.push("maxChargeTicks = Math.max(p_trigger_min_charge_ticks, p_trigger_max_charge_ticks);"); }
307	  const src = [
