366	function ingredientExpr(x: unknown, items: Map<string, string>): string {
367	  if (Array.isArray(x)) return `new RecipeChoice.MaterialChoice(${(x as string[]).map(MATERIAL).join(", ")})`;
368	  const s = x as string;
369	  if (/^[a-z][a-z0-9_]{1,31}$/.test(s)) return `designChoice(${jstr(s)})`;
370	  if (s.startsWith("#")) return `tagChoice(${jstr(bare(s.slice(1)))})`;
371	  void items;
372	  return `new RecipeChoice.MaterialChoice(${MATERIAL(s)})`;
373	}
