551	export function yamlTree(params: Param[]): string[] {
552	  type Node = { children: Map<string, Node>; param?: Param };
553	  const root: Node = { children: new Map() };
554	  for (const p of params) {
555	    let n = root;
556	    for (const seg of p.path.split(".")) { if (!n.children.has(seg)) n.children.set(seg, { children: new Map() }); n = n.children.get(seg)!; }
557	    n.param = p;
558	  }
559	  const out: string[] = [];
560	  const walk = (n: Node, ind: number) => {
561	    for (const [k, c] of n.children) {
562	      const pad = "  ".repeat(ind);
563	      if (c.param) {
564	        const p = c.param;
565	        const range = p.kind === "text" ? `text, max ${p.max} characters` : p.kind === "sound" ? "namespaced sound key" : `${fmtNum(p.min, p.kind)} to ${fmtNum(p.max, p.kind)}`;
566	        out.push(`${pad}# ${p.label} (${range})`);
567	        out.push(`${pad}${k}: ${p.kind === "text" || p.kind === "sound" ? ystr(String(p.value)) : fmtNum(Number(p.value), p.kind)}`);
568	      } else { out.push(`${pad}${k}:`); walk(c, ind + 1); }
569	    }
570	  };
571	  walk(root, 0);
572	  return out;
573	}
