653	      const tr = ab.trigger.type === "charge_release" ? `${TRIGGER_WORDS.charge_release} (${ab.trigger.release === "right_click" ? "right-click while sneaking" : "stop sneaking"})` : TRIGGER_WORDS[ab.trigger.type];
