666	  lines.push(`## Settings (config.yml)`, ``, `Change any of these in plugins/${name}/config.yml and run \`/${command} reload\` (values are clamped to the range shown):`, ``);
667	  for (const p of params) lines.push(`- \`${p.path}\` = ${p.kind === "text" || p.kind === "sound" ? `"${p.value}"` : fmtNum(Number(p.value), p.kind)}: ${p.label}${p.kind === "text" || p.kind === "sound" ? "" : ` (${fmtNum(p.min, p.kind)}-${fmtNum(p.max, p.kind)})`}`);
668	  lines.push(``, `## Commands and permissions`, ``, `- \`/${command} give <item> [player] [count]\` (${ns}.give, operators)`, `- \`/${command} list\`, \`/${command} params [item]\` (${ns}.command, operators)`, `- \`/${command} reload\` (${ns}.reload, operators)`);
