676	export function compileDesigns(inputs: unknown[], ctx: CompileContext): CompileResult {
677	  const warnings: DzIssue[] = [];
678	  if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(ctx.pluginName)) return { ok: false, errors: [{ path: "pluginName", code: "bad_name", message: "the plugin name must be 2-40 letters, digits or _ starting with a letter" }], warnings };
679	  if (!inputs.length) return { ok: false, errors: [{ path: "(mod)", code: "no_designs", message: "no design items" }], warnings };
680	  const v = validateDesigns(inputs, { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets });
681	  const errors: DzIssue[] = [...v.errors];
682	  v.results.forEach((r, i) => {
683	    const id = (inputs[i] as { id?: string })?.id ?? `#${i}`;
684	    for (const e of r.errors) errors.push({ ...e, path: `${id}: ${e.path}` });
685	    for (const w of r.warnings) warnings.push({ ...w, path: `${id}: ${w.path}` });
686	  });
687	  if (!v.ok || errors.length) return { ok: false, errors, warnings };
688	  const designs = v.results.map((r) => (r as Extract<typeof r, { ok: true }>).design).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
689	  const fe = (v.results[0] as Extract<(typeof v.results)[number], { ok: true }>).features;
690	  const lower = ctx.pluginName.toLowerCase().replace(/_/g, "");
691	  const pkg = `dev.nxeon.plugins.${/^[a-z]/.test(lower) ? lower : `p${lower}`}`;
692	  const main = camel(ctx.pluginName.replace(/^[a-z]/, (c) => c.toUpperCase())) || "DesignerMod";
693	  const mainCls = /^[A-Z]/.test(main) ? main : `M${main}`;
694	  const command = ctx.pluginName.toLowerCase().slice(0, 32);
695	  // a vanilla command root would be shadowed (or shadow vanilla): refuse (the exact version's command tree)
696	  if (vanillaIds("command", ctx.version).has(command)) return { ok: false, errors: [{ path: "pluginName", code: "command_clash", message: `/${command} is a vanilla command in Minecraft ${ctx.version}; pick another plugin name` }], warnings };
697	  const classes = new Map<string, string>();
698	  const claim = (cls: string, what: string): string | null => { if (classes.has(cls)) return classes.get(cls)!; classes.set(cls, what); return null; };
699	  const files: CompiledFile[] = [];
700	  const dir = `src/main/java/${pkg.replace(/\./g, "/")}`;
701	  const add = (path: string, content: string, role: CompiledFile["role"]) => files.push({ path, content, sha256: sha256(content), role });
702	  for (const c of COMPONENTS) add(`${dir}/${c.file}`, renderComponent(c.source, pkg), "component");
703	  add(`${dir}/${COMPAT_META.file}`, renderComponent(compatSource(fe), pkg), "compat");
704	  const itemClasses: string[] = [];
705	  const params: Param[] = [];
706	  const modelsApplied: string[] = [];
707	  for (const d of designs) {
708	    const icls = `${camel(d.id)}Item`;
709	    const clash = claim(icls, d.id);
710	    if (clash) return { ok: false, errors: [{ path: d.id, code: "class_clash", message: `items ${clash} and ${d.id} map to the same Java class ${icls}; rename one` }], warnings };
711	    const abCls: string[] = [];
712	    for (const ab of d.abilities) {
713	      const acls = `${camel(d.id)}${camel(ab.id)}`;
714	      const c2 = claim(acls, `${d.id}.${ab.id}`);
715	      if (c2) return { ok: false, errors: [{ path: `${d.id}.${ab.id}`, code: "class_clash", message: `${c2} and ${d.id}.${ab.id} map to the same Java class ${acls}; rename one` }], warnings };
716	      const g = abilityClass(pkg, d, ab, acls, ctx.namespace);
717	      add(`${dir}/abilities/${acls}.java`, g.source, "generated");
718	      abCls.push(acls);
719	      params.push(...g.params);
720	    }
721	    const modelOk = !!d.assets?.model && (!ctx.assets?.models || ctx.assets.models.includes(d.assets.model));
722	    if (modelOk) modelsApplied.push(d.assets!.model!);
723	    const it = itemClass(pkg, d, icls, abCls, ctx.namespace, fe, modelOk);
724	    add(`${dir}/items/${icls}.java`, it.source, "generated");
725	    itemClasses.push(icls);
726	    params.push(...it.params);
727	  }
728	  // config order = designParams order (item params first, then abilities), independent of the class emission order
729	  const ordered = designParams(designs);
730	  const ms = modelStatesOf(designs, fe, ctx);
731	  if (ms) add(`${dir}/designer/ModelStates.java`, renderComponent(MODEL_STATES_JAVA, pkg), "component");
732	  add(`${dir}/${mainCls}.java`, mainClass(pkg, mainCls, ctx.namespace, command, itemClasses, designs.map((d) => d.id), !!ctx.customHooks, ms), "generated");
733	  const notes: string[] = [];
734	  for (const d of designs) if (d.assets?.model && fe.itemModel && !modelsApplied.includes(d.assets.model)) notes.push(`${d.name.text} keeps the ${bare(d.base).replace(/_/g, " ")} look: this mod has no custom model "${d.assets.model}".`);
735	  if (!fe.itemModel && designs.some((d) => d.assets?.model)) notes.push(`Custom item models need Minecraft 1.21.4 or newer: on ${fe.version} the items keep their base look.`);
736	  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "charge_release")) notes.push(`${d.name.text}: charge by holding sneak with it in your main hand, then ${d.abilities.find((a) => a.trigger.type === "charge_release" && a.trigger.release === "unsneak") ? "let go of sneak" : "right-click while still sneaking"}.`);
737	  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "item_consume") && !(CONSUMABLE_BASES as readonly string[]).includes(bare(d.base))) notes.push(`${d.name.text} must be eaten to work.`);
738	  notes.push(...stateNotes(designs, fe));
739	  notes.push("Gameplay effects run on the server: protection plugins and PvP settings can block damage and teleports.");
740	  const valuesHash = designerValuesHash(ordered);
741	  const configVersion = ctx.configVersion !== undefined ? Math.max(1, Math.min(1_000_000, Math.round(ctx.configVersion))) : nextConfigVersion(ctx.previousConfig, valuesHash);
742	  const seed = randomSeedFor(ctx.namespace);
743	  add(`src/main/resources/config.yml`, configYml(ctx.pluginName, command, ordered, configVersion, valuesHash, seed), "resource");
744	  add(`src/main/resources/plugin.yml`, pluginYml(ctx.pluginName, `${pkg}.${mainCls}`, ctx.pluginVersion ?? "1.0.0", ctx.version, (ctx.description ?? `Custom items: ${designs.map((d) => d.name.text).join(", ")}`).slice(0, 200), command, ctx.namespace, designs), "resource");
745	  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
746	  const rd = readme(ctx.pluginName, command, ctx.namespace, designs, ordered, fe, notes);
747	  const hash = sha256(files.map((f) => `${f.path}\n${f.sha256}`).join("\n") + `\nREADME\n${sha256(rd)}`);
748	  return {
749	    ok: true, files, readme: rd, readmeSha256: sha256(rd), hash, params: ordered, warnings, notes, pkg, modelsApplied, mainClass: `${pkg}.${mainCls}`, command, configVersion, designerValuesHash: valuesHash,
750	    features: fe, javacVerified: (JAVAC_VERIFIED_VERSIONS as readonly string[]).includes(ctx.version), compiler: COMPILER_VERSION, library: COMPONENT_LIBRARY_VERSION, libraryHash: libraryHash(), designs,
751	  };
752	}
