755	const DURING_JAVA: Record<string, string> = { cooldown: "COOLDOWN", no_charges: "NO_CHARGES", charging: "CHARGING" };
756	const duringText = (d: string) => (d === "cooldown" ? "cools down" : d === "no_charges" ? "has no charges" : "is charging");
757	/** The ModelStates wiring of a mod, or null when no design has states (or the version has no item models). */
758	export function modelStatesOf(designs: ItemDesign[], fe: DesignFeatures, ctx: Pick<CompileContext, "assets">): MainStates | null {
759	  if (!fe.itemModel) return null;
760	  const rules: string[] = [], flagCounts: [string, number][] = [], aims: string[] = [];
761	  for (const d of designs) {
762	    const st = d.states;
763	    if (!st) continue;
764	    const im = d.assets?.model ? ctx.assets?.itemModels?.[d.assets.model] : undefined;
765	    for (const m of st.modes ?? []) rules.push(`new ModelStates.Rule(${jstr(d.id)}, ${jstr(m.ability)}, ModelStates.During.${DURING_JAVA[m.during]}, ${jstr(m.value)}, -1)`);
766	    let n = im ? im.flags.length : 0;
767	    (st.flags ?? []).forEach((f, i) => { const k = im ? im.flags.indexOf(f.name) : i; if (k < 0) return; n = Math.max(n, k + 1); rules.push(`new ModelStates.Rule(${jstr(d.id)}, ${jstr(f.ability)}, ModelStates.During.${DURING_JAVA[f.during]}, null, ${k})`); });
768	    if (st.modes?.length || st.flags?.length) flagCounts.push([d.id, n]);
769	    if (st.aim) aims.push(d.id);
770	  }
771	  return rules.length || aims.length ? { rules, flagCounts, aims } : null;
772	}
