774	export function stateNotes(designs: ItemDesign[], fe: DesignFeatures): string[] {
775	  const out: string[] = [];
776	  for (const d of designs) {
777	    const st = d.states;
778	    if (!st) continue;
779	    if (!fe.itemModel) { out.push(`${d.name.text}: item model states need Minecraft 1.21.4 or newer, so on ${fe.version} its look does not change.`); continue; }
780	    const what = [...(st.modes ?? []).map((m) => `"${m.value}" while ${m.ability.replace(/_/g, " ")} ${duringText(m.during)}`), ...(st.flags ?? []).map((f) => `"${f.name}" while ${f.ability.replace(/_/g, " ")} ${duringText(f.during)}`)];
781	    if (what.length) out.push(`${d.name.text} changes its look in hand: ${what.join(", ")} (players see it with the resource pack).`);
782	    if (st.aim) out.push(`${d.name.text}: hold right-click to aim (like drawing a bow, you walk slower while aiming).`);
783	  }
784	  return out;
785	}
