export const BUDGET_JAVA = String.raw`package __PKG__.designer;

/**
 * Component designer-budget v1: the per-activation resource budget. The design validator proves the static worst case
 * fits these numbers; this class enforces them again at runtime (a hand-edited config can raise counts only up to the
 * caps, and nested delayed steps share the activation's budget). When a counter is exhausted the activation stops.
 */
public final class Budget {
    public static final int ACTIONS = 64;
    public static final int ENTITIES = 32;
    public static final int TASKS = 8;
    public static final int PARTICLES = 512;
    public static final int PROJECTILES = 3;
    private int actions;
    private int entities;
    private int tasks;
    private int particles;
    private int projectiles;
    private boolean exhausted;

    public boolean action() { if (actions >= ACTIONS) { exhausted = true; return false; } actions++; return true; }
    public boolean entity() { if (entities >= ENTITIES) { exhausted = true; return false; } entities++; return true; }
    public boolean task() { if (tasks >= TASKS) { exhausted = true; return false; } tasks++; return true; }
    public boolean projectile() { if (projectiles >= PROJECTILES) { exhausted = true; return false; } projectiles++; return true; }
    /** How many of n particles may still be spawned (0 when the budget is used up). */
    public int particles(int n) {
        int use = Math.max(0, Math.min(n, PARTICLES - particles));
        particles += use;
        if (use < n) exhausted = true;
        return use;
    }
    public boolean exhausted() { return exhausted; }
}
`;

