import org.bukkit.NamespacedKey;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;

/**
 * Component designer-identity v1: an item IS a design item only when its PersistentDataContainer carries
 * <namespace>:item = <item key>. Never by name, lore, material or model (renaming in an anvil or another plugin's lore
 * cannot fake or break it). The namespace is the project's reserved nx_ namespace, so two mods never collide.
 */
public final class ItemIdentity {
    private final NamespacedKey key;

    public ItemIdentity(String namespace) { this.key = new NamespacedKey(namespace, "item"); }

    public NamespacedKey key() { return key; }

    public void tag(ItemMeta meta, String id) { meta.getPersistentDataContainer().set(key, PersistentDataType.STRING, id); }

    public String idOf(ItemStack stack) {
        if (stack == null || stack.getType().isAir() || !stack.hasItemMeta()) return null;
        ItemMeta meta = stack.getItemMeta();
        return meta == null ? null : meta.getPersistentDataContainer().get(key, PersistentDataType.STRING);
    }

    public boolean is(ItemStack stack, String id) { return id.equals(idOf(stack)); }

    public boolean carries(Player player, String id) {
        for (ItemStack s : player.getInventory().getContents()) if (is(s, id)) return true;
        return false;
    }
}
