import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.UUID;
import org.bukkit.Bukkit;
import org.bukkit.Keyed;
import org.bukkit.NamespacedKey;
import org.bukkit.command.PluginCommand;
import org.bukkit.entity.Player;
import org.bukkit.inventory.Recipe;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Component designer-runtime v1: the hub of a designer mod. Owns every piece of state (cooldowns, charges, marks,
 * charge timers, tasks, recipes) and drops all of it on disable; drops a player's state on quit and on death.
 */
public final class Designer {
    private final JavaPlugin plugin;
    private final String namespace;
    private final ItemIdentity identity;
    private final NamespacedKey projectileKey;
    private final Cooldowns cooldowns = new Cooldowns();
    private final Charges charges = new Charges();
    private final Marks marks = new Marks();
    private final Tasks tasks;
    private final DesignConfig config;
    private final Effects effects;
    private final Map<String, DesignItem> items = new LinkedHashMap<>();
    private final List<NamespacedKey> recipeKeys = new ArrayList<>();
    private final Set<UUID> active = new HashSet<>();
    private final Map<UUID, Long> chargeStart = new HashMap<>();
    private final Map<UUID, Long> lastClick = new HashMap<>();
    private Random random = new Random(0L);

    public Designer(JavaPlugin plugin, String namespace) {
        this.plugin = plugin;
        this.namespace = namespace;
        this.identity = new ItemIdentity(namespace);
        this.projectileKey = new NamespacedKey(namespace, "projectile");
        this.tasks = new Tasks(plugin);
        this.config = new DesignConfig(plugin);
        this.effects = new Effects(this);
    }

    public void enable(PluginCommand command, List<DesignItem> list) {
        for (DesignItem i : list) items.put(i.id(), i);
        reload();
        plugin.getServer().getPluginManager().registerEvents(new DesignListener(this), plugin);
        if (command != null) {
            DesignCommand c = new DesignCommand(this, command.getName());
            command.setExecutor(c);
            command.setTabCompleter(c);
        }
        for (DesignItem i : items.values()) {
            for (Recipe r : i.recipes()) {
                if (!(r instanceof Keyed k)) continue;
                if (Bukkit.addRecipe(r)) recipeKeys.add(k.getKey());
                else plugin.getLogger().warning("recipe " + k.getKey() + " was not added (a recipe with that key exists)");
            }
        }
    }

    /** Reload config.yml (with migration + clamping) into every ability; restarts the interval timers. Returns notes. */
    public List<String> reload() {
        config.load();
        random = new Random(config.seed());
        for (DesignItem i : items.values()) i.load(config);
        tasks.cancelTimers();
        boolean passives = false;
        for (DesignItem i : items.values()) {
            for (Ability a : i.abilities(Trigger.HELD_INTERVAL)) tasks.timer(a.periodTicks(), () -> heldTick(i, a));
            passives |= i.hasPassives();
        }
        if (passives) tasks.timer(40L, this::passiveTick);
        List<String> notes = new ArrayList<>();
        if (config.migrated() != null) notes.add(config.migrated());
        for (String n : config.notes()) { notes.add(n); plugin.getLogger().warning("config: " + n); }
        return notes;
    }

    private void heldTick(DesignItem item, Ability a) {
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (p.isDead()) continue;
            boolean has = a.inventorySlot() ? identity.carries(p, item.id()) : identity.is(p.getInventory().getItemInMainHand(), item.id());
            if (has) a.fire(Activation.of(a, p, null, null, 0));
        }
    }

    private void passiveTick() {
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (p.isDead()) continue;
            String main = identity.idOf(p.getInventory().getItemInMainHand());
            String off = identity.idOf(p.getInventory().getItemInOffHand());
            for (DesignItem i : items.values()) if (i.hasPassives()) i.passives(p, i.id().equals(main), i.id().equals(off));
        }
    }

    public void disable() {
        tasks.close();
        for (NamespacedKey k : recipeKeys) Bukkit.removeRecipe(k);
        recipeKeys.clear();
        cooldowns.clearAll();
        charges.clearAll();
        marks.clear();
        active.clear();
        chargeStart.clear();
        lastClick.clear();
    }

    /** Drop everything a player had (quit, death). */
    public void forget(UUID id) {
        cooldowns.clear(id);
        charges.clear(id);
        marks.removeOwner(id);
        chargeStart.remove(id);
        lastClick.remove(id);
        active.remove(id);
    }

    /** Server tick (Paper Bukkit.getCurrentTick): cooldowns, charges, marks and charge timers count ticks. */
    public long now() { return Bukkit.getCurrentTick(); }

    /** Re-entry guard: while a player's activation runs, events it causes do not trigger abilities. */
    boolean enter(Player p) { return active.add(p.getUniqueId()); }
    void exit(Player p) { active.remove(p.getUniqueId()); }
    public boolean busy(Player p) { return active.contains(p.getUniqueId()); }

    /** At most one click activation per player per tick (the client can send two interact packets for one click). */
    boolean firstClickThisTick(Player p) { long t = now(); Long last = lastClick.put(p.getUniqueId(), t); return last == null || last != t; }

    void startCharge(UUID id) { chargeStart.put(id, now()); }
    Long chargeStart(UUID id) { return chargeStart.get(id); }
    void clearCharge(UUID id) { chargeStart.remove(id); }

    /** Run a step later for this activation (counts against its task budget; skipped if the player left). */
    public boolean later(Activation a, long delay, Runnable step) {
        if (!a.budget().task()) return false;
        return tasks.later(delay, () -> {
            if (!a.valid() || !enter(a.player())) return;
            try { step.run(); } finally { exit(a.player()); }
        });
    }

    public DesignItem held(Player p) { String id = identity.idOf(p.getInventory().getItemInMainHand()); return id == null ? null : items.get(id); }
    public DesignItem item(String id) { return items.get(id); }
    public Ability ability(String itemId, String abilityId) { DesignItem i = items.get(itemId); return i == null ? null : i.ability(abilityId); }
    public Collection<DesignItem> items() { return items.values(); }
    public List<NamespacedKey> recipeKeys() { return recipeKeys; }
    public JavaPlugin plugin() { return plugin; }
    public String namespace() { return namespace; }
    public ItemIdentity identity() { return identity; }
    public NamespacedKey projectileKey() { return projectileKey; }
    public Cooldowns cooldowns() { return cooldowns; }
    public Charges charges() { return charges; }
    public Marks marks() { return marks; }
    public Tasks tasks() { return tasks; }
    public Effects effects() { return effects; }
    public Random random() { return random; }
}
`;

export const TASKS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.bukkit.Bukkit;
import org.bukkit.plugin.Plugin;
import org.bukkit.scheduler.BukkitTask;

/**
 * Component designer-tasks v1: the only scheduler use in a designer mod. Paper main-thread scheduler (BukkitScheduler)
 * only: no async tasks, no threads, no Folia region schedulers (the registry's scheduling lane is "paper"; plugin.yml
 * does not claim folia-supported). One-shot tasks are tracked and capped (LIVE plugin-wide); timers are tracked; every
 * task is cancelled on disable and timers on /reload.
 */
public final class Tasks {
    public static final int LIVE = 128;
    private final Plugin plugin;
    private final Set<BukkitTask> live = new HashSet<>();
    private final List<BukkitTask> timers = new ArrayList<>();
    private boolean closed;

    public Tasks(Plugin plugin) { this.plugin = plugin; }

    public boolean later(long delay, Runnable step) {
        if (closed || live.size() >= LIVE) return false;
        final BukkitTask[] self = new BukkitTask[1];
        self[0] = Bukkit.getScheduler().runTaskLater(plugin, () -> { live.remove(self[0]); step.run(); }, Math.max(1L, delay));
        live.add(self[0]);
        return true;
    }

    public void timer(long period, Runnable step) {
        if (closed) return;
        long p = Math.max(10L, period);
        timers.add(Bukkit.getScheduler().runTaskTimer(plugin, step, p, p));
    }

    public void cancelTimers() { for (BukkitTask t : timers) t.cancel(); timers.clear(); }

    public void close() {
        closed = true;
        cancelTimers();
        for (BukkitTask t : new ArrayList<>(live)) t.cancel();
        live.clear();
    }

    public int live() { return live.size(); }
    public int timers() { return timers.size(); }
}
`;

export const CONFIG_JAVA = String.raw`package __PKG__.designer;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import org.bukkit.configuration.Configuration;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Component designer-config v1: config.yml with defaults from the jar, validation and CLAMPING to the design caps (a
 * hand-edited value can never exceed what the validator allows), and a migration hook: when the jar's config_version is
 * newer than the server's file (the design's parameters were edited in Cyrus), every value under "items" is reset to the
 * jar's new default (Cyrus is the source of truth for designer values), the old file is kept as config.yml.bak-v<N>,
 * other sections are kept. A missing or non-numeric value falls back to the jar default.
 */
public final class DesignConfig {
    private final JavaPlugin plugin;
    private FileConfiguration cfg;
    private Configuration defaults;
    private final List<String> notes = new ArrayList<>();
    private String migrated;

    public DesignConfig(JavaPlugin plugin) { this.plugin = plugin; }

    public void load() {
        plugin.saveDefaultConfig();
        plugin.reloadConfig();
        cfg = plugin.getConfig();
        defaults = cfg.getDefaults();
        notes.clear();
        migrated = null;
        if (defaults == null) return;
        int jarVersion = defaults.getInt("config_version", 1);
        Object raw = cfg.get("config_version", null);
        int fileVersion = raw instanceof Number n ? n.intValue() : 0;
        if (fileVersion < jarVersion) migrate(fileVersion, jarVersion);
    }

    private void migrate(int from, int to) {
        File folder = plugin.getDataFolder();
        File file = new File(folder, "config.yml");
        try {
            if (file.isFile()) Files.copy(file.toPath(), new File(folder, "config.yml.bak-v" + from).toPath(), StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            plugin.getLogger().warning("could not back up config.yml before the update: " + e.getMessage());
        }
        int n = 0;
        for (String key : defaults.getKeys(true)) {
            if (!key.startsWith("items.") || defaults.isConfigurationSection(key)) continue;
            cfg.set(key, defaults.get(key));
            n++;
        }
        cfg.set("config_version", to);
        plugin.saveConfig();
        migrated = "config.yml migrated from version " + from + " to " + to + " (" + n + " designer values updated, backup config.yml.bak-v" + from + ")";
        plugin.getLogger().info(migrated);
    }

    private double fallback(String path, double min) { return defaults == null ? min : defaults.getDouble(path, min); }

    /** A number clamped to [min, max]; out-of-range values are clamped and noted. */
    public double num(String path, double min, double max) {
        double v;
        if (cfg.isDouble(path) || cfg.isInt(path) || cfg.isLong(path)) v = cfg.getDouble(path);
        else { v = fallback(path, min); if (cfg.contains(path, true)) notes.add(path + " is not a number, using " + v); }
        if (Double.isNaN(v) || Double.isInfinite(v)) v = fallback(path, min);
        if (v < min || v > max) {
