    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }

    private boolean allowed(CommandSender s, String node) {
        if (s.hasPermission(g.designer().namespace() + "." + node)) return true;
        say(s, "You don't have permission for that.", NamedTextColor.RED);
        return false;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String used, String[] args) {
        if (args.length == 0) {
            List<String> it = new ArrayList<>();
            for (DesignItem i : g.designer().items()) it.add(i.id());
            say(sender, g.plugin().getName() + ": items " + (it.isEmpty() ? "-" : String.join(", ", it)) + "; menus " + (g.menus().menus().isEmpty() ? "-" : String.join(", ", g.menus().menus().keySet())) + "; quests " + (g.quests().defs().isEmpty() ? "-" : String.join(", ", g.quests().defs().keySet())) + ". Use /" + label + " menu <id>, /" + label + " quests, /" + label + " params, /" + label + " reload", NamedTextColor.GOLD);
            return true;
        }
        String sub = args[0].toLowerCase(Locale.ROOT);
        switch (sub) {
            case "menu" -> menu(sender, args);
            case "quests", "quest" -> quests(sender, args);
            case "params" -> params(sender, args);
            case "reload" -> {
                if (!allowed(sender, "reload")) return true;
                List<String> notes = g.reload();
                say(sender, g.plugin().getName() + " config reloaded" + (notes.isEmpty() ? "" : " (" + notes.size() + " note" + (notes.size() == 1 ? "" : "s") + ")"), NamedTextColor.GREEN);
                for (String n : notes) say(sender, "- " + n, NamedTextColor.YELLOW);
            }
            default -> items.onCommand(sender, command, used, args);
        }
        return true;
    }

    private void menu(CommandSender sender, String[] args) {
        if (args.length < 2) { say(sender, "Usage: /" + label + " menu <id> [player], /" + label + " menu list, /" + label + " menu costs <id>", NamedTextColor.RED); return; }
        String a = args[1].toLowerCase(Locale.ROOT);
        if (a.equals("list")) {
            if (!allowed(sender, "command")) return;
            for (MenuDef m : g.menus().menus().values()) say(sender, describe(m), NamedTextColor.AQUA);
            if (g.menus().menus().isEmpty()) say(sender, "No menus.", NamedTextColor.GRAY);
            return;
        }
        if (a.equals("costs")) {
            if (!allowed(sender, "command")) return;
            MenuDef m = args.length >= 3 ? g.menus().menu(args[2].toLowerCase(Locale.ROOT)) : null;
            if (m == null) { say(sender, "Usage: /" + label + " menu costs <id>", NamedTextColor.RED); return; }
            int n = 0;
            for (MenuDef.Button b : m.buttons()) if (!b.cost().free()) { say(sender, "slot " + b.slot + ": " + cost(b), NamedTextColor.AQUA); n++; }
            int i = 0;
            for (MenuDef.Button b : m.entries()) { if (!b.cost().free()) { say(sender, "entry " + i + ": " + cost(b), NamedTextColor.AQUA); n++; } i++; }
            if (n == 0) say(sender, m.id() + " has no costs.", NamedTextColor.GRAY);
            return;
        }
        MenuDef m = g.menus().menu(a);
        if (m == null) { say(sender, "Unknown menu " + args[1] + ".", NamedTextColor.RED); return; }
        Player target;
        if (args.length >= 3) {
            if (!allowed(sender, "menu.others")) return;
            target = Bukkit.getPlayerExact(args[2]);
            if (target == null) { say(sender, "Player " + args[2] + " is not online.", NamedTextColor.RED); return; }
        } else if (sender instanceof Player p) {
            if (!allowed(sender, "menu")) return;
            if (!m.command()) { say(sender, "That menu is not opened by command.", NamedTextColor.RED); return; }
            target = p;
        } else { say(sender, "Usage from the console: /" + label + " menu <id> <player>", NamedTextColor.RED); return; }
        final Player t = target;
        g.menus().later(t, () -> g.menus().open(t, m.id(), 0, false));
        if (t != sender) say(sender, "Opened " + m.id() + " for " + t.getName() + ".", NamedTextColor.GREEN);
    }

    private String cost(MenuDef.Button b) {
        String s = g.costs().describe(b.cost());
        if (b.cost().kind() == CostCharger.Kind.ECONOMY && !g.costs().moneyReady()) s += " (needs Vault and an economy plugin: not set up on this server, so it is refused)";
        if (b.permission() != null) s += " (needs " + g.designer().namespace() + "." + b.permission() + ")";
        return s;
    }

    private String describe(MenuDef m) {
        StringBuilder b = new StringBuilder(m.id()).append(": ");
        if (m.style() == MenuDef.Style.DIALOGUE) b.append("dialogue choices=").append(m.entries().size());
        else {
            b.append("chest rows=").append(m.rows()).append(" buttons=").append(m.buttons().size());
            if (m.pageSize() > 0) b.append(" list=").append(m.pageSize()).append(" slots entries=").append(m.entries().size()).append(m.configList() != null ? " (config " + m.configList() + ")" : " (fixed)").append(" pages=").append(Pagination.pages(m.entries().size(), m.pageSize()));
        }
        List<String> opens = new ArrayList<>();
        if (m.command()) opens.add("command");
        if (m.opener() != null) opens.add("item:" + m.opener());
        if (m.npc()) opens.add("npc:" + g.designer().namespace() + ".npc." + m.id());
        b.append(" opens=").append(opens.isEmpty() ? "menus-only" : String.join(",", opens));
        b.append(" permission=").append(m.permission() == null ? "-" : g.designer().namespace() + "." + m.permission());
        return b.toString();
    }

    private void quests(CommandSender sender, String[] args) {
        String a = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "";
        if (a.equals("list") || (a.isEmpty() && !(sender instanceof Player))) {
            if (!allowed(sender, "command")) return;
            for (QuestDef q : g.quests().defs().values()) say(sender, define(q), NamedTextColor.AQUA);
            if (g.quests().defs().isEmpty()) say(sender, "No quests.", NamedTextColor.GRAY);
            return;
        }
        if (a.equals("check")) { if (allowed(sender, "command")) for (String line : check()) say(sender, line, line.contains("FAIL") ? NamedTextColor.RED : NamedTextColor.AQUA); return; }
        if (a.equals("reset")) {
            if (!allowed(sender, "quests.admin")) return;
            Player t = args.length >= 3 ? Bukkit.getPlayerExact(args[2]) : null;
            if (t == null) { say(sender, args.length >= 3 ? "Player " + args[2] + " is not online." : "Usage: /" + label + " quests reset <player>", NamedTextColor.RED); return; }
            g.quests().reset(t);
            say(sender, "Reset the quest progress of " + t.getName() + ".", NamedTextColor.GREEN);
            return;
        }
        if (!(sender instanceof Player p)) { say(sender, "Only players can do quests. Console: /" + label + " quests list | check | reset <player>", NamedTextColor.RED); return; }
        if (!allowed(sender, "quests")) return;
        String id = args.length >= 3 ? args[2].toLowerCase(Locale.ROOT) : null;
        switch (a) {
            case "" -> { for (QuestDef q : g.quests().defs().values()) say(p, q.id() + " - " + q.title() + ": " + g.quests().state(p, q), NamedTextColor.AQUA); }
            case "log" -> g.menus().later(p, () -> g.menus().open(p, MenuManager.LOG, 0, false));
            case "start" -> { if (id == null) say(p, "Usage: /" + label + " quests start <id>", NamedTextColor.RED); else g.quests().start(p, id, true); }
            case "abandon" -> { if (id == null) say(p, "Usage: /" + label + " quests abandon <id>", NamedTextColor.RED); else g.quests().abandon(p, id); }
            case "info" -> { if (id == null) say(p, "Usage: /" + label + " quests info <id>", NamedTextColor.RED); else g.quests().info(p, id); }
            case "choose" -> {
                QuestDef q = g.quests().def(id);
                if (q == null || !q.hasBranches()) say(p, "Usage: /" + label + " quests choose <quest with a choice>", NamedTextColor.RED);
                else { final String qid = q.id(); g.menus().later(p, () -> g.menus().open(p, MenuManager.BRANCH + qid, 0, false)); }
            }
            default -> say(p, "Unknown subcommand. Use /" + label + " quests [log|start|abandon|info|choose] <id>", NamedTextColor.RED);
        }
    }

    private String define(QuestDef q) {
        List<String> kinds = new ArrayList<>();
        int steps = q.steps().size();
        List<QuestDef.Step> all = new ArrayList<>(q.steps());
        for (QuestDef.Branch b : q.branches()) all.addAll(b.steps());
        for (QuestDef.Step s : all) for (QuestDef.Objective o : s.objectives()) { String k = o.kind().name().toLowerCase(Locale.ROOT); if (!kinds.contains(k)) kinds.add(k); }
        return q.id() + ": steps=" + steps + " branches=" + q.branches().size() + " objectives=" + String.join(",", kinds) + " repeat=" + q.repeat().name().toLowerCase(Locale.ROOT) + (q.cooldownSeconds() > 0 ? "/" + q.cooldownSeconds() + "s" : "") + " start=" + q.start().name().toLowerCase(Locale.ROOT) + " requires=" + (q.requires().isEmpty() ? "-" : String.join(",", q.requires())) + " title=" + q.title();
    }

    /** Definitions + the progress codec, run on this server's JVM (the TS twin prints the same sample). */
    private List<String> check() {
        List<String> out = new ArrayList<>();
        StringBuilder idx = new StringBuilder("quest index:");
        for (Map.Entry<QuestDef.Kind, Integer> e : g.quests().index().entrySet()) idx.append(' ').append(e.getKey().name().toLowerCase(Locale.ROOT)).append('=').append(e.getValue());
        out.add(idx.append(" handlers=").append(ObjectiveTracker.HANDLERS).append(" (one listener, one handler per event kind) timer=1 max_active=").append(g.quests().maxActive()).toString());
        Map<String, QuestStore.Entry> sample = new HashMap<>();
        Map<String, QuestStore.Entry> worst = new HashMap<>();
        for (QuestDef q : g.quests().defs().values()) {
            QuestStore.Entry e = new QuestStore.Entry(q.id());
            e.state = 'A';
            e.step = q.first().id();
            for (int j = 0; j < 3; j++) e.counts[j] = j < q.first().objectives().size() ? Math.min(j + 1, q.first().objectives().get(j).count()) : 0;
            e.started = 1700000000L;
            e.completions = 2;
            e.last = 1700000100L;
            sample.put(q.id(), e);
            QuestStore.Entry w = new QuestStore.Entry(q.id());
            w.state = 'A';
            int sl = 0, bl = 0, cl = 0;
            List<QuestDef.Step> all = new ArrayList<>(q.steps());
            for (QuestDef.Branch b : q.branches()) { all.addAll(b.steps()); bl = Math.max(bl, b.id().length()); }
            for (QuestDef.Step s : all) {
                sl = Math.max(sl, s.id().length());
                int c = -1;
                for (QuestDef.Objective o : s.objectives()) c += String.valueOf(o.count()).length() + 1;
                cl = Math.max(cl, c);
            }
            w.step = "s".repeat(sl);
            w.branch = "b".repeat(bl);
            out.add("size " + q.id() + ": " + (q.id().length() + 3 + sl + 1 + bl + 1 + cl + 1 + 10 + 1 + 7 + 1 + 10));
            worst.put(q.id(), w);
        }
        String enc = QuestStore.encode(sample);
        List<String> notes = new ArrayList<>();
        Map<String, QuestStore.Entry> back = QuestStore.decode(enc, g.quests().defs(), notes);
        out.add("store roundtrip: " + (QuestStore.encode(back).equals(enc) && notes.isEmpty() ? "ok" : "FAIL"));
        out.add("store sample: " + enc);
        if (!g.quests().defs().isEmpty()) {
            QuestDef q = g.quests().defs().values().iterator().next();
            String legacy = QuestStore.VERSION + "|" + q.id() + ",A,no_such_step,,5.5.5,1,0,0|zz_removed,A,s1,,1.0.0,1,0,0";
            List<String> n2 = new ArrayList<>();
            Map<String, QuestStore.Entry> m2 = QuestStore.decode(legacy, g.quests().defs(), n2);
            QuestStore.Entry e2 = m2.get(q.id());
            boolean ok = m2.size() == 1 && e2 != null && e2.step.equals(q.first().id()) && e2.counts[0] == 0 && n2.size() == 2;
            out.add("store migration (removed quest dropped, changed step restarted): " + (ok ? "ok" : "FAIL") + " notes=" + n2.size());
            List<String> n3 = new ArrayList<>();
            boolean reset = QuestStore.decode("v9|whatever", g.quests().defs(), n3).isEmpty() && n3.size() == 1;
            out.add("store unknown format reset: " + (reset ? "ok" : "FAIL"));
            String big = QuestStore.VERSION + "|" + q.id() + ",A," + q.first().id() + ",,999999.999999.999999,1,0,0";
            QuestStore.Entry e4 = QuestStore.decode(big, g.quests().defs(), new ArrayList<>()).get(q.id());
            boolean clamp = e4 != null && e4.counts[0] == q.first().objectives().get(0).count();
            out.add("store count clamp: " + (clamp ? "ok" : "FAIL"));
        }
        out.add("store limit: " + QuestStore.MAX_CHARS + " characters per player");
        return out;
    }

    private void params(CommandSender sender, String[] args) {
        if (!allowed(sender, "command")) return;
        String want = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : null;
        List<String> out = new ArrayList<>();
        for (DesignItem i : g.designer().items()) if (want == null || i.id().equals(want)) i.describe(out);
        for (MenuDef m : g.menus().menus().values()) if (want == null || m.id().equals(want)) m.describe(out);
        for (QuestDef q : g.quests().defs().values()) if (want == null || q.id().equals(want)) q.describe(out);
        if (out.isEmpty()) say(sender, "No parameters.", NamedTextColor.GRAY);
        for (String line : out) say(sender, line, NamedTextColor.AQUA);
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String used, String[] args) {
        List<String> out = new ArrayList<>();
        String last = args.length == 0 ? "" : args[args.length - 1].toLowerCase(Locale.ROOT);
        if (args.length <= 1) { for (String s : SUBS) if (s.startsWith(last)) out.add(s); return out; }
        String sub = args[0].toLowerCase(Locale.ROOT);
        if (sub.equals("menu") && args.length == 2) { for (String s : g.menus().menus().keySet()) if (s.startsWith(last)) out.add(s); if ("list".startsWith(last)) out.add("list"); if ("costs".startsWith(last)) out.add("costs"); return out; }
        if (sub.startsWith("quest") && args.length == 2) { for (String s : QSUBS) if (s.startsWith(last)) out.add(s); return out; }
        if (sub.startsWith("quest") && args.length == 3) { for (String s : g.quests().defs().keySet()) if (s.startsWith(last)) out.add(s); return out; }
        return items.onTabComplete(sender, command, used, args);
    }
}
`;

/** Only in mods with money costs: the Vault bridge (compile-only Vault API 1.7, never shaded; plugin.yml softdepend). */
export const VAULT_JAVA = String.raw`package __PKG__.designer;

import java.util.Locale;
import net.milkbowl.vault.economy.Economy;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.plugin.RegisteredServiceProvider;

/**
 * Component gameplay-vault v1: money costs through the allowlisted Vault API (net.milkbowl.vault, compile-only, not in
 * the jar). Created by the main class ONLY when the Vault plugin is on the server (so this class never loads without
 * it); the economy provider is looked up on every call (economy plugins may register after enable).
 */
public final class VaultMoney implements CostCharger.Money {
    private static Economy eco() {
        RegisteredServiceProvider<Economy> r = Bukkit.getServicesManager().getRegistration(Economy.class);
        return r == null ? null : r.getProvider();
    }

    @Override public boolean ready() { return eco() != null; }
    @Override public boolean has(Player p, double amount) { Economy e = eco(); return e != null && e.has(p, amount); }
    @Override public boolean withdraw(Player p, double amount) { Economy e = eco(); return e != null && e.has(p, amount) && e.withdrawPlayer(p, amount).transactionSuccess(); }
    @Override public String format(double amount) { Economy e = eco(); return e == null ? String.format(Locale.ROOT, "%.2f", amount) : e.format(amount); }
}
`;

// REAL menu/quest designer runs ON node-2 (not part of the unit suite: real javac, real strict scan, real Paper boots).
//   scripts/devhost run --lock -- npx tsx test/cyrus-gameplay-real.ts --out /tank/nxeon-build/tmp/cyrus-r11-gameplay/results.json [--javac-only] [--lane 1.21.11]
// No real Minecraft client, no bot and no AI model: clicking menu slots, buying, quest progress from real play and the
// NPC / item openers are NOT exercised here; what runs is the compile lane, the safety scan and the server-side surface
// reachable from the console (commands registered, menu list / costs, quest list / check: the progress codec on the
// real JVM, params, config generated, clamping, config lists checked, config_version migration, the edit jar).
// Steps per lane (1.21.11 on JDK 21, 26.2 on JDK 25; classpath = resolved Paper API + the allowlisted Vault API 1.7):
//   1. compile the showcase (TS compiler) -> javac --release N -proc:none -Xlint:deprecation,removal (0 warnings expected)
//   2. reproducible jar twice -> same sha256; strict scan (bytecode + source) -> no findings
//   3. Test Flight with RCON checks; 4. parameter edit (price, kill count, daily cooldown) -> only config.yml differs in
//      the jar (every .class identical); the edited jar over the OLD config.yml -> migrated, new values live
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { recompileModWithEdits } from "../lib/cyrus/designer/gameplay/params";
import { progressSample } from "../lib/cyrus/designer/gameplay/simulate";
import { progressEntryChars } from "../lib/cyrus/designer/gameplay/spec";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck } from "../lib/cyrus/testflight/types";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";
import { GP_NS as NS, GP_PLUGIN as PLUGIN, loadGameplayFixtures } from "../scripts/cyrus/gameplay-golden";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r11-gameplay/run-${Date.now().toString(36)}`;
const VAULT = `${T}/cyrus-import-deps/VaultAPI-1.7.jar`;
const ALL_LANES = [
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const LANES = ALL_LANES.filter((l) => !arg("--lane") || l.version === arg("--lane"));
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const CMD = PLUGIN.toLowerCase();

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

function build(r: ModCompileOk, lane: (typeof ALL_LANES)[number], tag: string) {
  const dir = path.join(RUN, `${lane.version}-${tag}`);
  rmSync(dir, { recursive: true, force: true });
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = [readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim(), ...(r.deps.includes("vault-api") ? [VAULT] : [])].join(":");
  const t0 = Date.now();
  let javacOut = "";
  try { javacOut = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed on ${lane.version}:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 12000)); }
  const javacMs = Date.now() - t0;
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jar = (out: string) => { execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", out, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]); return sha(readFileSync(out)); };
  const jarPath = path.join(dir, `${PLUGIN}-${lane.version}-${tag}.jar`);
  const h1 = jar(jarPath), h2 = jar(path.join(dir, "again.jar"));
  return { dir, classes, sources: sources.length, classFiles: entries.filter((e) => e.endsWith(".class")).length, javacMs, javacWarnings: (javacOut.match(/warning:/g) ?? []).length, javacOut: javacOut.slice(0, 3000), jarPath, jarSha256: h1, reproducible: h1 === h2, jarBytes: readFileSync(jarPath).length };
}

function scan(b: ReturnType<typeof build>, lane: (typeof ALL_LANES)[number]) {
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  try {
    const bytecode = S.scanBytecode(b.classes, { profile: "strict" });
    const src = walk(path.join(b.dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(path.join(b.dir, "ws"), abs) }));
    const source = S.scanSource(src, { profile: "strict" });
    const all = [...bytecode, ...source];
    return { profile: "strict", blocks: all.filter((f: { severity: string }) => f.severity === "block").length, warnings: all.filter((f: { severity: string }) => f.severity === "warn").length, findings: all.map((f: { severity: string; rule: string; where: string }) => `${f.severity}:${f.rule}@${f.where}`) };
  } finally { process.env.PATH = oldPath; }
}

function harvest(runId: string | null) {
  const out: Record<string, unknown> = {};
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF, "runs", runId);
  const pd = path.join(dir, `plugins/${PLUGIN}`);
  out.configOnDisk = existsSync(path.join(pd, "config.yml"));
  if (out.configOnDisk) { const t = readFileSync(path.join(pd, "config.yml"), "utf8"); out.configVersionOnDisk = Number(/^config_version:\s*(\d+)/m.exec(t)?.[1] ?? NaN); out.listsOnDisk = /^lists:/m.test(t); }
  out.backups = existsSync(pd) ? readdirSync(pd).filter((n) => n.startsWith("config.yml.bak")) : [];
  const log = path.join(dir, "logs/latest.log");
  const lines = existsSync(log) ? readFileSync(log, "utf8").split("\n") : [];
  out.pluginLog = lines.filter((l) => new RegExp(PLUGIN, "i").test(l) && !/Preparing/.test(l)).map((l) => l.slice(0, 300)).slice(0, 40);
  out.pluginErrorLines = lines.filter((l) => /\/(ERROR|FATAL)\]|Exception/.test(l) && new RegExp(PLUGIN, "i").test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.sandboxNoiseLines = lines.filter((l) => /\/(ERROR|FATAL)\]/.test(l) && !new RegExp(PLUGIN, "i").test(l)).length;
  rmSync(dir, { recursive: true, force: true });
  return out;
}

