// Cyrus R3 gameplay designers, part 2: EDIT WITHOUT REGENERATING for menus and quests. Every number and text of a menu
// or quest is a config.yml parameter (./compile.ts menuParams / questParams), so a value edit (a price, a kill count, a
// cooldown, a title, a coordinate) changes the design, and the recompile changes config.yml (values + designer-values
// hash + config_version) and the README, never a Java file. Item parameters go through the item edit path (../params.ts).
// Pure: no I/O, no model call.
import { applyParameterEdits, diffCompiled, type AppliedEdit, type CompiledDiff, type ParamEdit } from "../params";
import type { CompileContext } from "../compile";
import type { ItemDesign } from "../spec";
import { compileMod, modParams, type ModCompileOk } from "./compile";
import { MenuDesignSchema, QuestDesignSchema, type MenuDesign, type QuestDesign } from "./spec";

export type GameplayMod = { items: ItemDesign[]; menus: MenuDesign[]; quests: QuestDesign[] };
export type GameplayEditResult = { ok: true; mod: GameplayMod; applied: AppliedEdit[] } | { ok: false; errors: string[] };

const camelKey = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());
type Obj = Record<string, unknown>;

function iconSet(icon: Obj | undefined, field: string, value: number | string): string | null {
  if (!icon) return "no icon";
  if (field === "name") { (icon.name as Obj).text = value; return null; }
  if (field === "amount") { icon.amount = value; return null; }
  const l = /^lore(\d+)$/.exec(field);
  if (l) { const line = (icon.lore as Obj[] | undefined)?.[Number(l[1])]; if (!line) return "no lore line"; line.text = value; return null; }
  return `unknown icon field ${field}`;
}
function clickSet(c: Obj, rest: string[], value: number | string): string | null {
  if (rest.length === 1) return iconSet(c.icon as Obj, rest[0], value);
  if (rest[0] === "cost" && rest.length === 2) { const cost = c.cost as Obj | undefined; if (!cost) return "no cost"; cost[rest[1]] = value; return null; }
  const a = /^a(\d+)$/.exec(rest[0]);
  if (a && rest.length === 2) { const act = (c.actions as Obj[] | undefined)?.[Number(a[1])]; if (!act) return `no action ${rest[0]}`; act[camelKey(rest[1])] = value; return null; }
  return `unknown path ${rest.join(".")}`;
}

function setInMenu(m: Obj, rest: string[], value: number | string): string | null {
  const [head, ...tail] = rest;
  if (head === "title" && !tail.length) { m.title = value; return null; }
  if (head === "speaker" && !tail.length) { (m.speaker as Obj).text = value; return null; }
  const line = /^line(\d+)$/.exec(head);
  if (line && !tail.length) { const lines = m.lines as string[]; if (Number(line[1]) >= lines.length) return "no line"; lines[Number(line[1])] = String(value); return null; }
  if (head === "speaker_icon") return iconSet(m.speakerIcon as Obj, tail[0], value);
  if (head === "prev" || head === "next") return iconSet(((m.list as Obj | undefined)?.[head] as Obj | undefined)?.icon as Obj, tail[0], value);
  const b = /^b(\d+)$/.exec(head), e = /^e(\d+)$/.exec(head), c = /^c(\d+)$/.exec(head);
  const node = b ? (m.buttons as Obj[] | undefined)?.find((x) => x.slot === Number(b[1])) : e ? (((m.list as Obj | undefined)?.source as Obj | undefined)?.entries as Obj[] | undefined)?.[Number(e[1])] : c ? (m.choices as Obj[] | undefined)?.[Number(c[1])] : undefined;
  if (!node) return `no clickable ${head}`;
  return clickSet(node, tail, value);
}

function setInQuest(q: Obj, rest: string[], value: number | string): string | null {
  const [head, ...tail] = rest;
  if ((head === "title" || head === "description") && !tail.length) { q[head] = value; return null; }
  if (head === "icon") return iconSet(q.icon as Obj, tail[0], value);
  if (head === "repeat" && tail[0] === "cooldown_seconds") { (q.repeat as Obj).cooldownSeconds = value; return null; }
  if (head === "failure" && tail[0] === "time_limit_seconds") { (q.failure as Obj).timeLimitSeconds = value; return null; }
  const steps = () => [...(q.steps as Obj[]), ...(((q.branches as Obj | undefined)?.options as Obj[] | undefined) ?? []).flatMap((b) => b.steps as Obj[])];
  const rewardSet = (list: Obj[] | undefined, r: string, field: string) => { const m = /^r(\d+)$/.exec(r); const x = m ? list?.[Number(m[1])] : undefined; if (!x) return `no reward ${r}`; x[camelKey(field)] = value; return null; };
  if (head === "steps") {
    const st = steps().find((s) => s.id === tail[0]);
    if (!st) return `no step ${tail[0]}`;
    if (tail[1] === "text" && tail.length === 2) { st.text = value; return null; }
    const o = /^o(\d+)$/.exec(tail[1] ?? "");
    const obj = o ? (st.objectives as Obj[])[Number(o[1])] : undefined;
    if (!obj || tail.length !== 3) return `no objective ${tail.slice(1).join(".")}`;
    obj[tail[2]] = value;
    return null;
  }
  if (head === "branches") {
    const br = q.branches as Obj | undefined;
    if (!br) return "no branches";
    if (tail[0] === "prompt" && tail.length === 1) { br.prompt = value; return null; }
    const b = (br.options as Obj[]).find((x) => x.id === tail[0]);
    if (!b) return `no branch ${tail[0]}`;
    if (tail[1] === "label" && tail.length === 2) { (b.label as Obj).text = value; return null; }
    if (tail[1] === "rewards" && tail.length === 4) return rewardSet(b.rewards as Obj[] | undefined, tail[2], tail[3]);
    return `unknown branch path ${tail.join(".")}`;
  }
  if (head === "rewards" && tail.length === 2) return rewardSet(q.rewards as Obj[] | undefined, tail[0], tail[1]);
  return `unknown quest path ${rest.join(".")}`;
}

/** Apply parameter edits (exact config paths) to a whole mod; every value is checked against its parameter's caps. */
export function applyGameplayEdits(mod: GameplayMod, edits: ParamEdit[]): GameplayEditResult {
  const params = new Map(modParams(mod.items, mod.menus, mod.quests).map((p) => [p.path, p]));
  const out: GameplayMod = { items: mod.items.map((d) => structuredClone(d)), menus: mod.menus.map((m) => structuredClone(m)), quests: mod.quests.map((q) => structuredClone(q)) };
  const errors: string[] = [];
  const applied: AppliedEdit[] = [];
  const itemEdits: ParamEdit[] = [];
  for (const e of edits.slice(0, 32)) {
    const p = params.get(e.path);
    if (!p) { errors.push(`${e.path} is not a parameter of this mod (structural changes need a normal build)`); continue; }
    if (!p.owner) { itemEdits.push(e); continue; }
    let v: number | string = e.value;
    if (p.kind === "text" || p.kind === "sound") {
      if (typeof v !== "string") { errors.push(`${e.path} needs text`); continue; }
      if (p.kind === "sound" && !/^[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*$/.test(v)) { errors.push(`${e.path}: "${v}" is not a namespaced sound key`); continue; }
      if (v.length < 1 || v.length > p.max) { errors.push(`${e.path}: text must be 1-${p.max} characters`); continue; }
    } else {
      if (typeof v !== "number" || !Number.isFinite(v)) { errors.push(`${e.path} needs a number`); continue; }
      if (p.kind !== "num") v = Math.round(v);
      if (v < p.min || v > p.max) { errors.push(`${e.path}: ${v} is outside ${p.min}-${p.max}`); continue; }
    }
    const parts = e.path.split(".");
    const target = p.owner === "menu" ? out.menus.find((m) => m.id === parts[1]) : out.quests.find((q) => q.id === parts[1]);
    const err = !target ? `no ${p.owner} ${parts[1]}` : p.owner === "menu" ? setInMenu(target as unknown as Obj, parts.slice(2), v) : setInQuest(target as unknown as Obj, parts.slice(2), v);
    if (err) { errors.push(`${e.path}: ${err}`); continue; }
    applied.push({ path: e.path, label: p.label, from: p.value, to: v });
  }
  if (itemEdits.length) {
    const r = applyParameterEdits(out.items, itemEdits);
    if (!r.ok) errors.push(...r.errors); else { out.items = r.designs; applied.push(...r.applied); }
  }
  if (errors.length) return { ok: false, errors };
  for (const m of out.menus) { const r = MenuDesignSchema.safeParse(m); if (!r.success) return { ok: false, errors: r.error.issues.slice(0, 5).map((i) => `${m.id}: ${i.path.join(".")}: ${i.message}`) }; }
  for (const q of out.quests) { const r = QuestDesignSchema.safeParse(q); if (!r.success) return { ok: false, errors: r.error.issues.slice(0, 5).map((i) => `${q.id}: ${i.path.join(".")}: ${i.message}`) }; }
  return { ok: true, mod: out, applied };
}

/** Edit + recompile against the previous compile (its config.yml drives config_version). Only config.yml + README differ. */
export function recompileModWithEdits(previous: ModCompileOk, edits: ParamEdit[], ctx: Omit<CompileContext, "previousConfig">): { ok: true; result: ModCompileOk; diff: CompiledDiff; applied: AppliedEdit[] } | { ok: false; errors: string[] } {
  const e = applyGameplayEdits({ items: previous.designs, menus: previous.menus, quests: previous.quests }, edits);
  if (!e.ok) return e;
  const prevCfg = previous.files.find((f) => f.path === "src/main/resources/config.yml")?.content;
  const r = compileMod([...e.mod.items, ...e.mod.menus, ...e.mod.quests], { ...ctx, previousConfig: prevCfg });
  if (!r.ok) return { ok: false, errors: r.errors.map((x) => `${x.path}: ${x.message}`) };
  return { ok: true, result: r, diff: diffCompiled(previous, r), applied: e.applied };
