const camelKey = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());

/** Navigate a relative ability path ("a0.n1", "a2.then0", "c1", "a3.if0") to its node. */
function nodeAt(ab: Record<string, unknown>, rel: string[]): Record<string, unknown> | null {
  let cur: Record<string, unknown> | null = null;
  for (let i = 0; i < rel.length; i++) {
    const seg = rel[i];
    const m = /^(a|n|then|else|c|if)(\d+)$/.exec(seg);
    if (!m) return null;
    const idx = Number(m[2]);
    const list = (m[1] === "a" ? ab.actions : m[1] === "c" ? ab.conditions : m[1] === "n" ? cur?.actions : m[1] === "then" ? cur?.then : m[1] === "else" ? cur?.else : cur?.if) as unknown[] | undefined;
    if ((m[1] === "a" || m[1] === "c") && i !== 0) return null;
    if (!Array.isArray(list) || !list[idx] || typeof list[idx] !== "object") return null;
    cur = list[idx] as Record<string, unknown>;
  }
  return cur;
}

/** Set one parameter in a (cloned) design. Returns an error string or null. */
function setInDesign(d: ItemDesign, path: string, value: number | string): string | null {
  const parts = path.split(".");
  if (parts[0] !== "items" || parts[1] !== d.id) return `${path} is not in ${d.id}`;
  const rest = parts.slice(2);
  const obj = d as unknown as Record<string, unknown>;
  if (rest[0] === "abilities") {
    const ab = (d.abilities as unknown as Record<string, unknown>[]).find((a) => a.id === rest[1]);
    if (!ab) return `no ability ${rest[1]}`;
    const tail = rest.slice(2);
    if (tail.length === 1 && tail[0] === "cooldown_ticks") { ab.cooldownTicks = value; return null; }
    if (tail[0] === "charges" && tail.length === 2) { const c = ab.charges as Record<string, unknown> | undefined; if (!c) return "no charges"; c[camelKey(tail[1])] = value; return null; }
    if (tail[0] === "trigger" && tail.length === 2) { (ab.trigger as Record<string, unknown>)[camelKey(tail[1])] = value; return null; }
    const node = nodeAt(ab, tail.slice(0, -1).flatMap((s) => s.split("."))) ;
    if (!node) return `no node at ${tail.slice(0, -1).join(".")}`;
    node[camelKey(tail[tail.length - 1])] = value;
    return null;
  }
  if (rest[0] === "marks" && rest.length === 3) { const m = (d.marks as unknown as Record<string, unknown>[] | undefined)?.find((x) => x.name === rest[1]); if (!m) return `no mark ${rest[1]}`; m[camelKey(rest[2])] = value; return null; }
  if (rest[0] === "passives" && rest.length === 3) { const i = Number(rest[1].slice(1)); const p = (d.passives as unknown as Record<string, unknown>[] | undefined)?.[i]; if (!p) return `no passive ${rest[1]}`; p[camelKey(rest[2])] = value; return null; }
  if ((rest[0] === "loot" || rest[0] === "drops") && rest.length === 3) { const i = Number(rest[1].slice(1)); const acq = obj.acquisition as Record<string, unknown[]> | undefined; const l = acq?.[rest[0]]?.[i] as Record<string, unknown> | undefined; if (!l) return `no ${rest[0]} ${rest[1]}`; l[camelKey(rest[2])] = value; return null; }
  return `${path} is not a designer parameter`;
}

/** Apply parameter edits (exact config paths) to designs. Every value is checked against the parameter's caps. */
export function applyParameterEdits(designs: ItemDesign[], edits: ParamEdit[]): EditResult {
  const params = new Map(designParams(designs).map((p) => [p.path, p]));
  const out = designs.map((d) => structuredClone(d));
  const errors: string[] = [];
  const applied: AppliedEdit[] = [];
  for (const e of edits.slice(0, 32)) {
    const p = params.get(e.path);
    if (!p) { errors.push(`${e.path} is not a parameter of this mod (structural changes need a normal build)`); continue; }
    let v: number | string = e.value;
    if (p.kind === "text" || p.kind === "sound") {
      if (typeof v !== "string") { errors.push(`${e.path} needs text`); continue; }
      if (p.kind === "sound" && !/^[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*$/.test(v)) { errors.push(`${e.path}: "${v}" is not a namespaced sound key`); continue; }
      if (v.length < (p.kind === "text" ? 1 : 3) || v.length > p.max) { errors.push(`${e.path}: text must be 1-${p.max} characters`); continue; }
    } else {
      if (typeof v !== "number" || !Number.isFinite(v)) { errors.push(`${e.path} needs a number`); continue; }
      if (p.kind !== "num") v = Math.round(v);
      if (v < p.min || v > p.max) { errors.push(`${e.path}: ${v} is outside ${p.min}-${p.max}`); continue; }
    }
    const d = out.find((x) => x.id === p.item)!;
    const err = setInDesign(d, e.path, v);
    if (err) { errors.push(err); continue; }
    applied.push({ path: e.path, label: p.label, from: p.value, to: v });

