// Cyrus engine core: reserved namespaces + the identifier registry rules (MASTER-PLAN 4.2).
// Every project reserves a namespace `nx_<hash>` when it is created (lib/cyrus/engine-core/store.ts), and every
// identifier a mod defines (item, model, sound, permission, command, recipe, glyph, config key) is built from it,
// so two Nxeon mods cannot collide by construction. Glyphs get codepoints from a per-namespace home block in the
// supplementary Private Use Areas. Pure, deterministic and client-safe (no crypto module, no DB).
// GAME-AGNOSTIC: the formats are generic `ns:key` / `ns.key` strings; an adapter maps them to a game's own syntax.

export const NAMESPACE_RE = /^nx_[a-z0-9]{8}$/;

/** `resource` = a data pack resource path (loot table, advancement, function, tag, enchantment): `nx_x:a/b/c`. */
export const IDENTIFIER_KINDS = ["item", "model", "sound", "permission", "command", "recipe", "glyph", "config", "resource"] as const;
export type IdentifierKind = (typeof IDENTIFIER_KINDS)[number];
export const isIdentifierKind = (v: unknown): v is IdentifierKind => typeof v === "string" && (IDENTIFIER_KINDS as readonly string[]).includes(v);

const SEG = "[a-z0-9_]+";
const KEY_RULES: Record<IdentifierKind, { re: RegExp; sep: ":" | "."; hint: string }> = {
  item: { re: /^[a-z0-9_]{1,48}$/, sep: ":", hint: "lowercase letters, digits, underscores" },
  recipe: { re: /^[a-z0-9_]{1,48}$/, sep: ":", hint: "lowercase letters, digits, underscores" },
  command: { re: /^[a-z0-9_]{1,32}$/, sep: ":", hint: "lowercase letters, digits, underscores (max 32)" },
  glyph: { re: /^[a-z0-9_]{1,48}$/, sep: ":", hint: "lowercase letters, digits, underscores" },
  model: { re: new RegExp(`^${SEG}(/${SEG}){0,3}$`), sep: ":", hint: "path segments of lowercase letters, digits, underscores joined by /" },
  resource: { re: new RegExp(`^${SEG}(/${SEG}){0,5}$`), sep: ":", hint: "path segments of lowercase letters, digits, underscores joined by / (max 6)" },
  sound: { re: new RegExp(`^${SEG}(\\.${SEG}){0,5}$`), sep: ":", hint: "segments of lowercase letters, digits, underscores joined by ." },
  permission: { re: /^[a-z0-9_-]+(\.[a-z0-9_-]+){0,5}$/, sep: ".", hint: "segments of lowercase letters, digits, - or _ joined by ." },
  config: { re: /^[a-z0-9_-]+(\.[a-z0-9_-]+){0,5}$/, sep: ".", hint: "segments of lowercase letters, digits, - or _ joined by ." },
};
const MAX_KEY = 64;

/** FNV-1a 64-bit (BigInt). Not a security hash: only spreads namespaces and glyph blocks evenly. */
export function fnv1a64(s: string): bigint {
  let h = 0xcbf29ce484222325n;
  const bytes = new TextEncoder().encode(s);
  for (const b of bytes) {
    h ^= BigInt(b);
    h = (h * 0x100000001b3n) & 0xffffffffffffffffn;
  }
  return h;
}

/** Deterministic namespace for a seed (the store seeds it with the project id, plus an attempt counter on a clash). */
export function namespaceFromSeed(seed: string): string {
  return "nx_" + fnv1a64(seed).toString(36).padStart(13, "0").slice(-8);
}
export const isNamespace = (v: unknown): v is string => typeof v === "string" && NAMESPACE_RE.test(v);

export type IdResult = { ok: true; id: string } | { ok: false; error: string };

export function buildIdentifier(namespace: string, kind: IdentifierKind, key: string): IdResult {
  if (!isNamespace(namespace)) return { ok: false, error: `"${namespace}" is not a reserved nx_ namespace` };
  const rule = KEY_RULES[kind];
  if (!rule) return { ok: false, error: `unknown identifier kind ${String(kind)}` };
  if (typeof key !== "string" || key.length === 0 || key.length > MAX_KEY || !rule.re.test(key)) return { ok: false, error: `${kind} key "${key}" must be ${rule.hint} (max ${MAX_KEY})` };
  return { ok: true, id: `${namespace}${rule.sep}${key}` };
}

export function parseIdentifier(kind: IdentifierKind, full: string): { namespace: string; key: string } | null {
  const rule = KEY_RULES[kind];
  if (!rule || typeof full !== "string") return null;
  const at = full.indexOf(rule.sep);
  if (at < 0) return null;
  const namespace = full.slice(0, at);
  const key = full.slice(at + 1);
  return buildIdentifier(namespace, kind, key).ok ? { namespace, key } : null;
}

/** Validate a full identifier, optionally requiring it to live in the project's own namespace. */
export function validateIdentifier(kind: IdentifierKind, full: string, ownNamespace?: string): { ok: true } | { ok: false; error: string } {
  const p = parseIdentifier(kind, full);
  if (!p) return { ok: false, error: `"${full}" is not a valid namespaced ${kind} identifier` };
  if (ownNamespace && p.namespace !== ownNamespace) return { ok: false, error: `"${full}" is outside this project's namespace ${ownNamespace}` };
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Glyph codepoints: 256-codepoint blocks in Supplementary PUA-A (U+F0000) and PUA-B (U+100000).
// The BMP PUA (U+E000-F8FF) is left alone: third-party packs crowd it.
// ---------------------------------------------------------------------------
export const GLYPH_BLOCK = 256;
const BLOCKS_PER_PLANE = 255; // 0x?0000 .. 0x?FEFF; the last partial block (FFF00-FFFFD) is never used
export const GLYPH_BLOCKS = BLOCKS_PER_PLANE * 2;

export function glyphBlockStart(index: number): number {
  const i = ((index % GLYPH_BLOCKS) + GLYPH_BLOCKS) % GLYPH_BLOCKS;
  return i < BLOCKS_PER_PLANE ? 0xf0000 + i * GLYPH_BLOCK : 0x100000 + (i - BLOCKS_PER_PLANE) * GLYPH_BLOCK;
}
export const glyphHomeBlock = (namespace: string): number => Number(fnv1a64(`glyph:${namespace}`) % BigInt(GLYPH_BLOCKS));
export function isGlyphCodepoint(cp: number): boolean {
  if (!Number.isInteger(cp)) return false;
  const inPlane = (base: number) => cp >= base && cp < base + BLOCKS_PER_PLANE * GLYPH_BLOCK;
  return inPlane(0xf0000) || inPlane(0x100000);
}

/** First free codepoint for a namespace: its home block first, then the following blocks (wrapping). null = all full. */
export function nextGlyph(namespace: string, taken: Iterable<number>): number | null {
  const used = new Set(taken);
  const home = glyphHomeBlock(namespace);
  for (let b = 0; b < GLYPH_BLOCKS; b++) {
    const start = glyphBlockStart(home + b);
    for (let cp = start; cp < start + GLYPH_BLOCK; cp++) if (!used.has(cp)) return cp;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Collision detection across any set of identifiers (one project, a Mod Pack, a server's installed mods).
// ---------------------------------------------------------------------------
export type IdentRecord = { kind: IdentifierKind; id: string; codepoint?: number | null; owner?: string };
export type Collision =
  | { type: "duplicate_id"; kind: IdentifierKind; id: string; owners: string[] }
  | { type: "duplicate_codepoint"; codepoint: number; ids: string[]; owners: string[] }
  | { type: "invalid_id"; kind: string; id: string; owner: string; error: string };

/**
 * Pure. Two records collide when they define the same identifier of the same kind, or two glyphs share a codepoint.
 * Identifiers are compared case-insensitively (several games lower-case them on load).
 */
export function detectCollisions(records: readonly IdentRecord[]): Collision[] {
  const out: Collision[] = [];
  const byId = new Map<string, IdentRecord[]>();
  const byCp = new Map<number, IdentRecord[]>();
  for (const r of records) {
    const owner = r.owner ?? "";
    if (!isIdentifierKind(r.kind) || !parseIdentifier(r.kind, r.id.toLowerCase())) {
      out.push({ type: "invalid_id", kind: String(r.kind), id: r.id, owner, error: "not a valid namespaced identifier" });
      continue;
    }
    const k = `${r.kind}|${r.id.toLowerCase()}`;
    byId.set(k, [...(byId.get(k) ?? []), r]);
    if (r.kind === "glyph" && typeof r.codepoint === "number") byCp.set(r.codepoint, [...(byCp.get(r.codepoint) ?? []), r]);
  }
  for (const [k, list] of byId) if (list.length > 1) {
    const [kind, id] = k.split("|") as [IdentifierKind, string];
    out.push({ type: "duplicate_id", kind, id, owners: list.map((x) => x.owner ?? "") });
  }
  for (const [cp, list] of byCp) if (list.length > 1) {
    out.push({ type: "duplicate_codepoint", codepoint: cp, ids: list.map((x) => x.id), owners: list.map((x) => x.owner ?? "") });
  }
  return out;
}
