const SET_RE = /^[a-z][a-z0-9_]{1,31}$/;
const EVENT_RE = /^[a-z][a-z0-9_]{0,23}$/;

/**
 * `itemModels` (Cyrus item model states, optional): ItemModelSpec v1 objects. Each spec's idle texture and state
