 */
export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; sounds?: PackSoundEvent[]; allowPreview?: boolean; itemModels?: unknown[] }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
