  attackDamage: [0, 40],
  speed: [0.1, 0.5],
  knockbackResistance: [0, 1],
  followRange: [16, 64],
  arenaRadius: [8, 64],
  emptyDespawnSeconds: [10, 600],
  maxDurationSeconds: [60, 3600],
  spawnCooldownSeconds: [0, 86400],
  maxAlive: [1, 3],
  below: [0.01, 1], // phase threshold: health fraction
  intervalTicks: [20, 400],
  weight: [1, 10],
  cooldownTicks: [0, 1200],
  telegraphTicks: [0, 60],
  targetMax: [1, 8],
  targetRange: [1, 48],
  damage: [0, 40],
  heal: [0, 200],
  strength: [0, 3],
  vertical: [0, 1.5],
  potionTicks: [1, 600],
  amplifier: [0, 4],
  selfAmplifier: [0, 2],
  projectileSpeed: [0.2, 3],
  projectileDamage: [0, 20],
  particleCount: [1, 64],
  particleSpread: [0, 4],
  particleSpeed: [0, 1],
  volume: [0, 2],
  pitch: [0.5, 2],
  summonCount: [1, 4],
  minionHealth: [1, 100],
  minionsMax: [1, 16],
  delayTicks: [1, 100],
  healthPerPlayer: [0, 1],
  damagePerPlayer: [0, 0.5],
  maxPlayers: [1, 20],
