export const WaveSchema = z.strictObject({
  delaySeconds: capInt("waveDelaySeconds").optional(),
  spawns: z.array(WaveSpawnSchema).min(1).max(BOSS_LIMITS.maxWaveSpawns),
  /** "cleared": the next wave starts when every mob of this wave is dead (seconds = optional time limit: the encounter fails);
   * "timer": the next wave starts after seconds. */
  advance: z.enum(["cleared", "timer"]),
  seconds: capInt("waveSeconds").optional(),
  message: Text(120).optional(),
});
export type Wave = z.infer<typeof WaveSchema>;
export const EncounterDesignSchema = z.strictObject({
  schemaVersion: z.literal(BOSS_SPEC_VERSION),
  kind: z.literal("encounter"),
  id: Key,
  title: Text(40),
  arena: z.strictObject({ radius: capNum("arenaRadius") }),
  start: z.strictObject({ command: z.boolean().optional(), item: Key.optional(), cooldownSeconds: capInt("spawnCooldownSeconds").optional() }).optional(),
  waves: z.array(WaveSchema).min(1).max(BOSS_LIMITS.maxWaves),
  /** Mobs of this encounter alive at once (every wave's total must fit). */
  maxAlive: capInt("encounterMaxAlive"),
  failure: z.strictObject({ emptySeconds: capInt("emptyDespawnSeconds"), timeLimitSeconds: capInt("encounterTimeLimit").optional() }),
  rewards: DropsSchema.optional(),
  bossBar: BarSchema.optional(),
  messages: z.strictObject({ start: Text(120).optional(), complete: Text(120).optional(), fail: Text(120).optional() }).optional(),
