// --------------------------------------------------------------------------------------------------------- helpers
export type BossContext = {
  version: string;
  namespace: string;
  features: DesignFeatures;
  items: Map<string, ItemDesign>;
  /** Asset keys: sounds `<ns>:set.event`; lootTables `<ns>:path` of the project's data pack (undefined = not checked). */
  assets?: { sounds?: string[]; lootTables?: string[] };
};
export type BossIssue = DzIssue & { file?: string };
export type BossValidation<T> = { ok: true; design: T; errors: []; warnings: BossIssue[]; budgets: AttackBudget[] } | { ok: false; errors: BossIssue[]; warnings: BossIssue[]; budgets: AttackBudget[] };
export type AttackBudget = { attack: string; actions: number; entities: number; tasks: number; particles: number; projectiles: number; summons: number; depth: number };

const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");
const sizeOf = (x: unknown) => { try { return new TextEncoder().encode(JSON.stringify(x)).length; } catch { return Infinity; } };
type Sink = { errors: BossIssue[]; warnings: BossIssue[]; file: string };
const failF = (s: Sink, path: string, code: string, message: string) => s.errors.push({ path, code, message, file: s.file });
const warnF = (s: Sink, path: string, code: string, message: string) => s.warnings.push({ path, code, message, file: s.file });

/** Walk every action (pre-order) with its path ("a0", "a1.n0") and delay depth. */
export function walkBossActions(list: BossAction[], fn: (a: BossAction, path: string, depth: number) => void, prefix = "a", depth = 0): void {
  list.forEach((a, i) => {
    const here = `${prefix}${i}`;
    fn(a, here, depth);
    if (a.type === "delayed") walkBossActions(a.actions, fn, `${here}.n`, depth + 1);
  });
}

/** Static worst case of one attack's actions with `targets` targets (per-target actions run once per target). */
export function bossBudgetOf(list: BossAction[], targets: number, depth = 0): Omit<AttackBudget, "attack"> {
  const t = { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0, summons: 0, depth };
  for (const a of list) {
    const m = isPerTarget(a) ? targets : 1;
    t.actions += m;
    switch (a.type) {
      case "damage": case "knockback": case "pull": case "potion_effect": t.entities += m; break;
      case "launch_projectile": t.projectiles += m; t.tasks += m; break; // + the lifetime task
      case "spawn_particles": t.particles += a.count * m; break;
      case "leap": case "heal_self": case "self_effect": t.entities += 1; break;
      case "summon": t.summons += a.count; t.entities += a.count; break;
      case "delayed": { t.tasks += 1; const b = bossBudgetOf(a.actions, targets, depth + 1); for (const k of ["actions", "entities", "tasks", "particles", "projectiles", "summons"] as const) t[k] += b[k]; t.depth = Math.max(t.depth, b.depth); break; }
      default: break;
    }
  }
  return t;
}
export const SUMMON_BUDGET = BOSS_LIMITS.summonsPerAttack;
export const DROP_LOOP_MESSAGE = "drops its own summon item: an endless source";

const DEFAULT_TARGET_RANGE_SLACK = 0;
function checkItemRef(s: Sink, at: string, ref: string, ctx: BossContext, what: string, display = false) {
  if (ref.startsWith("minecraft:")) {
    if (!isVanilla("item", ref, ctx.version)) failF(s, at, "unknown_vanilla_id", missingIdReason("item", ref, ctx.version));
    else if (ref === "minecraft:air" || (!display && BANNED_BASES.test(ref.slice(10)))) failF(s, at, "banned_item", `${ref} cannot be ${what} (operator item, spawn egg or a drastic right-click)`);
  } else if (!ctx.items.has(ref)) failF(s, at, "unresolved_ref", `no design item "${ref}" in this mod`);
}
function checkSound(s: Sink, at: string, key: string, ctx: BossContext) {
  const kns = key.split(":")[0];
  if (kns === "minecraft") warnF(s, at, "vanilla_sound_unchecked", `${key}: vanilla sound keys are not checked against the game (a wrong key plays nothing)`);
  else if (kns !== ctx.namespace) failF(s, at, "foreign_namespace", `${key} uses the namespace ${kns}; sounds must be minecraft: or this mod's ${ctx.namespace}`);
  else if (ctx.assets?.sounds && !ctx.assets.sounds.includes(key)) warnF(s, at, "asset_unresolved", `${key}: this mod has no such custom sound, so it plays nothing`);
}
function checkMob(s: Sink, at: string, ref: string, ctx: BossContext, list: readonly string[], what: string) {
  const bare = ref.replace(/^minecraft:/, "");
  if (!isVanilla("entity_type", ref, ctx.version)) { failF(s, at, "unknown_vanilla_id", missingIdReason("entity_type", ref, ctx.version)); return; }
  if (!list.includes(bare)) failF(s, at, "base_not_allowed", `${ref} cannot be ${what} (allowed: ${list.join(", ")}): it breaks blocks, explodes, teleports, splits, flies or has its own boss fight`);
}
function checkSpawnItem(s: Sink, at: string, key: string, ctx: BossContext) {
  const it = ctx.items.get(key);
  if (!it) { failF(s, at, "unresolved_ref", `no design item "${key}" in this mod`); return; }
  if (it.abilities.some((a) => ["right_click", "sneak_right_click", "charge_release"].includes(a.trigger.type))) failF(s, at, "opener_conflict", `${key} has right-click abilities; a summon item must not (both would fire on one click)`);
  if (it.abilities.some((a) => a.trigger.type === "item_consume")) failF(s, at, "opener_conflict", `${key} is eaten / drunk; a summon item must not be`);
}
function checkDrops(s: Sink, at: string, d: Drops | undefined, ctx: BossContext, summonItem: string | undefined) {
  if (!d) return;
  (d.items ?? []).forEach((x, i) => {
    checkItemRef(s, `${at}.items[${i}].item`, x.item, ctx, "dropped");
    if (summonItem && x.item === summonItem && x.chance > 0) failF(s, `${at}.items[${i}]`, "drop_loop", `${summonItem} ${DROP_LOOP_MESSAGE}`);
    if (x.chance === 0) warnF(s, `${at}.items[${i}].chance`, "never_drops", "chance 0: this never drops");
  });
  if (d.lootTable) {
    const ns = d.lootTable.split(":")[0];
    if (ns !== ctx.namespace) failF(s, `${at}.lootTable`, "foreign_namespace", `${d.lootTable}: only this project's own data pack loot tables (${ctx.namespace}:...) can be rolled`);
    else if (ctx.assets?.lootTables === undefined) warnF(s, `${at}.lootTable`, "loot_table_unchecked", `${d.lootTable} is not checked against the project's data pack here; if it is missing it rolls nothing (logged)`);
    else if (!ctx.assets.lootTables.includes(d.lootTable)) failF(s, `${at}.lootTable`, "loot_table_not_in_project", `${d.lootTable} is not a loot table of this project's data pack (make it with the data pack studio first)`);
  }
  if (d.minDamageShare !== undefined && d.mode === "ground") warnF(s, `${at}.minDamageShare`, "share_ground", "minDamageShare only matters for participants drops");
  if (!(d.items ?? []).length && !d.lootTable && !d.xp) warnF(s, at, "empty_drops", "drops with no items, loot table or XP give nothing");
}
function checkActions(s: Sink, at: string, list: BossAction[], ctx: BossContext, b: BossDesign, select: string | null) {
  walkBossActions(list, (a, p, depth) => {
    const ap = `${at}.${p}`;
    if (a.type === "delayed" && depth + 1 > BOSS_LIMITS.maxDelayDepth) failF(s, ap, "too_deep", `delayed steps nest at most ${BOSS_LIMITS.maxDelayDepth} deep`);
    if (select === "self" && isPerTarget(a)) failF(s, ap, "no_target", `${a.type} needs targets, but this attack selects "self" (no targets)`);
    switch (a.type) {
      case "leap": if (select === "self") failF(s, ap, "no_target", "leap jumps toward the first target; this attack has none"); break;
      case "play_sound": checkSound(s, `${ap}.sound`, a.sound, ctx); break;
      case "summon":
        checkMob(s, `${ap}.entity`, a.entity, ctx, MINION_BASES, "a minion");
        if (!b.minions) failF(s, ap, "minions_undeclared", "summon needs minions.maxAlive (the cap of this boss's minions)");
        else if (a.count > b.minions.maxAlive) failF(s, `${ap}.count`, "minion_cap", `summons ${a.count} but minions.maxAlive is ${b.minions.maxAlive}`);
        break;
      case "self_effect":
        if ((HARMFUL_EFFECTS as readonly string[]).includes(a.effect)) failF(s, `${ap}.effect`, "harmful_self_effect", `${a.effect} is harmful: self_effect is for the boss's own buffs`);
        if (["instant_health", "instant_damage", "saturation", "invisibility"].includes(a.effect)) failF(s, `${ap}.effect`, "self_effect_banned", `${a.effect} cannot be a boss self effect (use heal_self; an invisible boss cannot be fought fairly)`);
        break;
      case "potion_effect": if (a.effect === "invisibility") warnF(s, `${ap}.effect`, "odd_effect", "giving players invisibility is unusual for a boss attack"); break;
      default: break;
    }
  });
}

/** Validate one boss (references resolved against the mod's items). */
export function validateBoss(input: unknown, ctx: BossContext): BossValidation<BossDesign> {
  const id = (input as { id?: string })?.id ?? "?";
  const s: Sink = { errors: [], warnings: [], file: id };
  const budgets: AttackBudget[] = [];
  if (sizeOf(input) > BOSS_LIMITS.maxSpecBytes) { failF(s, "(root)", "spec_size", `the boss is larger than ${BOSS_LIMITS.maxSpecBytes} bytes`); return { ok: false, ...s, budgets }; }
  const p = BossDesignSchema.safeParse(input);
  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) failF(s, issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors: s.errors, warnings: s.warnings, budgets }; }
  const b = p.data;
  checkMob(s, "entity", b.entity, ctx, BOSS_BASES, "a boss");
  if ((NEUTRAL_BASES as readonly string[]).includes(b.entity.replace(/^minecraft:/, ""))) warnF(s, "entity", "neutral_base", `${b.entity} is neutral: it fights only its current target, which the boss sets to the nearest participant every half second`);
  for (const slot of EQUIP_SLOTS) { const ref = b.equipment?.[slot]; if (ref) checkItemRef(s, `equipment.${slot}`, ref, ctx, "boss equipment", true); }
  // phases: first at 1, strictly decreasing, unique ids, known attacks
  const attackIds = new Map<string, Attack>();
  b.attacks.forEach((a, i) => { if (attackIds.has(a.id)) failF(s, `attacks[${i}].id`, "duplicate_id", `attack ${a.id} is defined twice`); attackIds.set(a.id, a); });
  const phaseIds = new Set<string>();
  const used = new Set<string>();
  b.phases.forEach((ph, i) => {
    const at = `phases[${i}]`;
    if (phaseIds.has(ph.id)) failF(s, `${at}.id`, "duplicate_id", `phase ${ph.id} is defined twice`);
    phaseIds.add(ph.id);
    if (i === 0 && ph.below !== 1) failF(s, `${at}.below`, "first_phase", "the first phase starts at full health: below must be 1");
    if (i > 0 && ph.below >= b.phases[i - 1].below) failF(s, `${at}.below`, "phase_order", `phase thresholds must go down: ${ph.below} is not below ${b.phases[i - 1].below}`);
    const seen = new Set<string>();
    ph.attacks.forEach((r, j) => {
      if (!attackIds.has(r.attack)) failF(s, `${at}.attacks[${j}].attack`, "unresolved_ref", `no attack "${r.attack}" on this boss`);
      if (seen.has(r.attack)) failF(s, `${at}.attacks[${j}].attack`, "duplicate_id", `attack ${r.attack} is listed twice in this phase`);
      seen.add(r.attack); used.add(r.attack);
    });
    if (ph.onEnter) checkActions(s, `${at}.onEnter`, ph.onEnter, ctx, b, "all");
    const fx = new Set<string>();
    (ph.selfEffects ?? []).forEach((e, j) => {
      if ((HARMFUL_EFFECTS as readonly string[]).includes(e.effect) || ["instant_health", "instant_damage", "saturation", "invisibility"].includes(e.effect)) failF(s, `${at}.selfEffects[${j}].effect`, "harmful_self_effect", `${e.effect} cannot be a lasting boss effect`);
      if (fx.has(e.effect)) failF(s, `${at}.selfEffects[${j}]`, "duplicate_id", `${e.effect} is listed twice`);
      fx.add(e.effect);
    });
    if (ph.onEnter) { const bb = bossBudgetOf(ph.onEnter, BOSS_LIMITS.liveBosses * 0 + 8); checkBudget(s, `${at}.onEnter`, bb); }
  });
  b.attacks.forEach((a, i) => {
    const at = `attacks[${i}]`;
    if (!used.has(a.id)) warnF(s, at, "unused_attack", `attack ${a.id} is in no phase, so it never runs`);
    if (a.targets.range > b.arena.radius + DEFAULT_TARGET_RANGE_SLACK) failF(s, `${at}.targets.range`, "range_outside_arena", `range ${a.targets.range} is larger than the arena radius ${b.arena.radius}: only participants (inside the arena) are ever targets`);
    if (a.targets.select === "self" && a.targets.max !== 1) warnF(s, `${at}.targets.max`, "self_max", "select self has no targets; max is ignored");
    checkActions(s, `${at}.actions`, a.actions, ctx, b, a.targets.select);
    if (a.telegraph?.sound) checkSound(s, `${at}.telegraph.sound`, a.telegraph.sound, ctx);
    if (a.telegraph && a.telegraph.ticks === 0 && (a.telegraph.particle || a.telegraph.sound || a.telegraph.text)) warnF(s, `${at}.telegraph.ticks`, "telegraph_zero", "a telegraph of 0 ticks shows at the same moment as the attack");
    const bb = bossBudgetOf(a.actions, a.targets.select === "self" ? 0 : a.targets.max);
    budgets.push({ attack: a.id, ...bb });
    checkBudget(s, `${at}.actions`, bb);
    if ((a.cooldownTicks ?? 0) > 0 && b.phases.some((ph) => ph.attacks.length === 1 && ph.attacks[0].attack === a.id && (a.cooldownTicks ?? 0) > ph.intervalTicks)) warnF(s, `${at}.cooldownTicks`, "cooldown_idle", `in a phase where ${a.id} is the only attack, its cooldown is longer than the interval, so the boss sometimes skips a turn`);
  });
  if (b.drops) checkDrops(s, "drops", b.drops, ctx, b.spawn?.item);
  if (b.spawn?.item) checkSpawnItem(s, "spawn.item", b.spawn.item, ctx);
  if (b.minions && !b.attacks.some((a) => JSON.stringify(a.actions).includes('"summon"')) && !b.phases.some((ph) => JSON.stringify(ph.onEnter ?? []).includes('"summon"'))) warnF(s, "minions", "no_summon", "minions are declared but no action summons them");
  const sc = b.scaling;
  if (sc && (sc.healthPerPlayer ?? 0) > 0) {
    const worst = b.stats.health * (1 + (sc.healthPerPlayer ?? 0) * ((sc.maxPlayers ?? 8) - 1));
    if (worst > BOSS_CAPS.health[1]) warnF(s, "scaling.healthPerPlayer", "health_clamped", `with ${(sc.maxPlayers ?? 8)} players the health would be ${Math.round(worst)}; it is clamped to ${BOSS_CAPS.health[1]}`);
  }
  if (b.arena.onTimeout && !b.arena.maxDurationSeconds) warnF(s, "arena.onTimeout", "no_timeout", "onTimeout needs maxDurationSeconds");
  if (b.messages?.enrage && b.arena.onTimeout !== "enrage") warnF(s, "messages.enrage", "no_enrage", "the enrage message is shown only with arena.onTimeout enrage");
  if (b.bossBar?.darkenSky) warnF(s, "bossBar.darkenSky", "darken_sky", "darkenSky darkens the sky for every participant while the bar is shown");
  return s.errors.length ? { ok: false, errors: s.errors, warnings: s.warnings, budgets } : { ok: true, design: b, errors: [], warnings: s.warnings, budgets };
}

function checkBudget(s: Sink, at: string, bb: Omit<AttackBudget, "attack">) {
  for (const k of ["actions", "entities", "tasks", "particles", "projectiles"] as const) if (bb[k] > BUDGET[k]) failF(s, at, `budget_${k}`, `worst case ${bb[k]} ${k} per attack; the limit is ${BUDGET[k]} (lower targets.max or the counts)`);
  if (bb.summons > SUMMON_BUDGET) failF(s, at, "budget_summons", `worst case ${bb.summons} summoned minions per attack; the limit is ${SUMMON_BUDGET}`);
}

/** Validate one encounter (bosses resolved by id; `bosses` = every parseable boss of the mod). */
export function validateEncounter(input: unknown, ctx: BossContext, bosses: Map<string, BossDesign>): BossValidation<EncounterDesign> {
  const id = (input as { id?: string })?.id ?? "?";
  const s: Sink = { errors: [], warnings: [], file: id };
  if (sizeOf(input) > BOSS_LIMITS.maxSpecBytes) { failF(s, "(root)", "spec_size", `the encounter is larger than ${BOSS_LIMITS.maxSpecBytes} bytes`); return { ok: false, ...s, budgets: [] }; }
  const p = EncounterDesignSchema.safeParse(input);
  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) failF(s, issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors: s.errors, warnings: s.warnings, budgets: [] }; }
  const e = p.data;
  e.waves.forEach((w, i) => {
    const at = `waves[${i}]`;
    let total = 0;
    w.spawns.forEach((sp, j) => {
      const sa = `${at}.spawns[${j}]`;
      if ((sp.entity === undefined) === (sp.boss === undefined)) { failF(s, sa, "spawn_source", "a wave spawn needs exactly one of entity (a vanilla mob) or boss (a boss of this mod)"); return; }
      if (sp.entity) checkMob(s, `${sa}.entity`, sp.entity, ctx, MINION_BASES, "an encounter mob");
      if (sp.boss) {
        const bd = bosses.get(sp.boss);
        if (!bd) failF(s, `${sa}.boss`, "unresolved_ref", `no boss "${sp.boss}" in this mod`);
        else if (bd.arena.radius > e.arena.radius) warnF(s, `${sa}.boss`, "boss_arena_larger", `${sp.boss}'s arena (${bd.arena.radius}) is larger than this encounter's (${e.arena.radius})`);
        if (sp.count !== 1) failF(s, `${sa}.count`, "boss_count", "a boss spawns once per wave entry (count 1)");
      }
      total += sp.count;
    });
    if (total > e.maxAlive) failF(s, `${at}.spawns`, "wave_over_cap", `this wave spawns ${total} mobs but maxAlive is ${e.maxAlive}`);
    if (total > BOSS_LIMITS.encounterMobs) failF(s, `${at}.spawns`, "wave_over_cap", `this wave spawns ${total} mobs; the plugin-wide limit per encounter is ${BOSS_LIMITS.encounterMobs}`);
    if (w.advance === "timer" && w.seconds === undefined) failF(s, `${at}.seconds`, "timer_seconds", "a timer wave needs seconds (when the next wave starts)");
    if (w.advance === "timer" && i === e.waves.length - 1) warnF(s, `${at}.advance`, "last_timer", "the last wave is a timer wave: the encounter completes when it is cleared anyway");
    const bossesHere = w.spawns.filter((x) => x.boss).length;
    if (bossesHere > BOSS_LIMITS.liveBosses) failF(s, `${at}.spawns`, "too_many_bosses", `at most ${BOSS_LIMITS.liveBosses} bosses can be alive`);
  });
  if (e.maxAlive > BOSS_LIMITS.encounterMobs) failF(s, "maxAlive", "wave_over_cap", `the plugin-wide limit per encounter is ${BOSS_LIMITS.encounterMobs}`);
  if (e.rewards) checkDrops(s, "rewards", e.rewards, ctx, e.start?.item);
  if (e.start?.item) checkSpawnItem(s, "start.item", e.start.item, ctx);
  const limit = e.failure.timeLimitSeconds;
  if (limit !== undefined) {
    const minTime = e.waves.reduce((n, w) => n + (w.delaySeconds ?? 0) + (w.advance === "timer" ? (w.seconds ?? 0) : 0), 0);
    if (minTime > limit) failF(s, "failure.timeLimitSeconds", "time_limit_too_short", `the waves need at least ${minTime} s but the time limit is ${limit} s: the encounter can never be completed`);
  }
  return s.errors.length ? { ok: false, errors: s.errors, warnings: s.warnings, budgets: [] } : { ok: true, design: e, errors: [], warnings: s.warnings, budgets: [] };
}

/** Per-attack budgets of a boss (for the README / build summary). */
export const attackBudgets = (b: BossDesign): AttackBudget[] => b.attacks.map((a) => ({ attack: a.id, ...bossBudgetOf(a.actions, a.targets.select === "self" ? 0 : a.targets.max) }));

/** Cross-file checks of bosses + encounters (called by validateGameplay with every valid boss / encounter). */
export function crossCheckBosses(bosses: BossDesign[], encounters: EncounterDesign[], extraOpeners: { item: string; by: string }[]): BossIssue[] {
  const out: BossIssue[] = [];
  const used = new Set<string>();
  for (const e of encounters) for (const w of e.waves) for (const sp of w.spawns) if (sp.boss) used.add(sp.boss);
  for (const b of bosses) if (b.spawn?.command === false && !b.spawn.item && !used.has(b.id)) out.push({ file: b.id, path: "spawn", code: "unreachable_boss", message: `boss ${b.id} can never spawn (no command, no summon item and no encounter wave)` });
  for (const e of encounters) if (e.start?.command === false && !e.start.item) out.push({ file: e.id, path: "start", code: "unreachable_encounter", message: `encounter ${e.id} can never start (no command and no start item)` });
  // one opener item per thing: a summon item may not also open a menu or summon another boss / encounter
  const openers = new Map<string, string>();
  for (const o of extraOpeners) openers.set(o.item, o.by);
  for (const x of [...bosses.map((b) => ({ id: b.id, item: b.spawn?.item })), ...encounters.map((e) => ({ id: e.id, item: e.start?.item }))]) {
    if (!x.item) continue;
    if (openers.has(x.item)) out.push({ file: x.id, path: x.id.length ? "spawn.item" : "", code: "opener_conflict", message: `${x.item} already opens or summons ${openers.get(x.item)}` });
    else openers.set(x.item, x.id);
  }
  // minion budget across the mod (static worst case; the runtime cap is 48 plugin-wide)
  const minions = bosses.reduce((n, b) => n + (b.minions?.maxAlive ?? 0) * (b.spawn?.maxAlive ?? 1), 0);
  if (minions > BOSS_LIMITS.liveMinions) out.push({ file: bosses.at(-1)?.id, path: "minions", code: "minion_cap_mod", message: `the bosses could keep ${minions} minions alive; the plugin-wide limit is ${BOSS_LIMITS.liveMinions} (summons above it are skipped)` });
  return out;
}

export const BOSS_CHECK_CODES = [
  "schema", "base_not_allowed", "first_phase", "phase_order", "unresolved_ref", "duplicate_id", "range_outside_arena", "no_target", "minions_undeclared", "minion_cap",
  "harmful_self_effect", "self_effect_banned", "too_deep", "budget_actions", "budget_entities", "budget_tasks", "budget_particles", "budget_projectiles", "budget_summons",
  "drop_loop", "opener_conflict", "foreign_namespace", "loot_table_not_in_project", "spawn_source", "boss_count", "wave_over_cap", "timer_seconds", "time_limit_too_short",
  "unreachable_boss", "unreachable_encounter", "too_many_bosses", "too_many_encounters", "banned_item", "unknown_vanilla_id",
] as const;

