public final class BossEffects {
    private static final double MAX_SPEED = 4.0;
    private final Bosses b;

    BossEffects(Bosses b) { this.b = b; }

    private static boolean alive(LivingEntity t) { return t != null && t.isValid() && !t.isDead(); }

    public Location at(BossCast c) { Mob m = c.boss(); return m.getLocation().add(0, m.getHeight() / 2.0, 0); }
    public Location at(LivingEntity t) { return t == null || !t.isValid() ? null : t.getLocation().add(0, t.getHeight() / 2.0, 0); }

