        if (!alive(t) || amount <= 0 || !c.budget().entity()) return;
        t.damage(amount * c.mult(), c.boss());
    }

    private void push(BossCast c, LivingEntity t, Vector dir, double strength, double vertical) {
        if (!alive(t) || !c.budget().entity()) return;
        Vector h = dir.clone().setY(0);
        Vector v = h.lengthSquared() < 1.0E-4 ? new Vector(0, 0, 0) : h.normalize().multiply(strength);
