/**
 * Component boss-drops v1: a drop table (vanilla items, this mod's design items, one loot table of the project's data
 * pack) rolled with the hub's seeded java.util.Random: one nextDouble per item entry per roll set, in design order (the
 * TS simulator draws the same sequence). Design items carry their identity (DesignItem.create()). Boss equipment and
 * minion / wave mob loot never drop (cleared by the hub).
 */
public final class DropTable {
    public enum Mode { PARTICIPANTS, GROUND }

    private record Entry(Material material, String design, int count, double chance) {}

    private final List<Entry> entries = new ArrayList<>();
    private Mode mode = Mode.PARTICIPANTS;
    private double minShare;
    private int xp;
    private NamespacedKey lootTable;

    public void clear() { entries.clear(); lootTable = null; xp = 0; minShare = 0; mode = Mode.PARTICIPANTS; }
    public void mode(Mode m) { mode = m; }
    public void minShare(double s) { minShare = s; }
    public void xp(int n) { xp = n; }
    public void item(Material m, int count, double chance) { entries.add(new Entry(m, null, count, chance)); }
    public void design(String id, int count, double chance) { entries.add(new Entry(null, id, count, chance)); }
    public void lootTable(String namespace, String path) { lootTable = new NamespacedKey(namespace, path); }

    public Mode mode() { return mode; }
    public double minShare() { return minShare; }
    public int xp() { return xp; }
    public int size() { return entries.size(); }
    public boolean empty() { return entries.isEmpty() && lootTable == null && xp == 0; }

    /** Counts of one roll set (no item stacks): used by /<mod> boss check against the TS twin. */
    public int[] rollCounts(Random r) {
        int[] out = new int[entries.size()];
        for (int i = 0; i < entries.size(); i++) out[i] = r.nextDouble() < entries.get(i).chance() ? entries.get(i).count() : 0;
        return out;
    }

    /** One roll set as item stacks (+ the loot table, rolled at the location; a missing table logs a note and adds nothing). */
    public List<ItemStack> roll(Random r, Designer d, Location at, List<String> notes) {
        List<ItemStack> out = new ArrayList<>();
        for (Entry e : entries) {
            if (!(r.nextDouble() < e.chance())) continue;
            if (e.material() != null) out.add(new ItemStack(e.material(), Math.max(1, Math.min(64, e.count()))));
            else {
                DesignItem di = d.item(e.design());
                if (di == null) continue;
                ItemStack s = di.create();
                s.setAmount(Math.max(1, Math.min(s.getMaxStackSize(), e.count())));
                out.add(s);
            }
        }
        if (lootTable != null) {
            LootTable t = Bukkit.getLootTable(lootTable);
            if (t == null) notes.add("loot table " + lootTable + " is not loaded (is the data pack enabled?)");
            else {
                try {
                    Collection<ItemStack> got = t.populateLoot(r, new LootContext.Builder(at).build());
                    int n = 0;
                    for (ItemStack s : got) { if (s != null && !s.getType().isAir() && n < 27) { out.add(s); n++; } }
                } catch (RuntimeException ex) {
                    notes.add("loot table " + lootTable + " could not be rolled here: " + ex.getClass().getSimpleName());
                }
            }
        }
        return out;
    }
}
