    /** Wire the hub: definitions, leftovers sweep, config, listener, the boss / encounter subcommands (wrapping the existing executor). */
    public void enable(PluginCommand command, List<BossDef> bossList, List<EncounterDef> encounterList, boolean others) {
        for (BossDef b : bossList) defs.put(b.id(), b);
        encounters.register(encounterList);
        List<String> out = new ArrayList<>();
        load(startVersion, out);
        if (!registered) { plugin.getServer().getPluginManager().registerEvents(this, plugin); registered = true; }
        int swept = 0;
        for (World w : Bukkit.getWorlds()) for (LivingEntity e : w.getLivingEntities()) if (ours(e)) { e.remove(); swept++; }
        if (swept > 0) plugin.getLogger().info("removed " + swept + " leftover boss / minion / wave mobs from an earlier run");
        if (command != null) {
            BossCommand c = new BossCommand(this, command.getName(), command.getExecutor(), command.getTabCompleter(), others);
            command.setExecutor(c);
            command.setTabCompleter(c);
        }
    }

    /** Called after the Designer (and Gameplay) reloaded: bosses.* / encounters.* migration, parameters, the AI timer. */
    void load(int before, List<String> out) {
        FileConfiguration cfg = plugin.getConfig();
        Configuration defaults = cfg.getDefaults();
        int jar = defaults == null ? 1 : defaults.getInt("config_version", 1);
        if (before >= 0 && before < jar && defaults != null) {
            int n = 0;
            for (String key : defaults.getKeys(true)) {
                if (!(key.startsWith("bosses.") || key.startsWith("encounters.")) || defaults.isConfigurationSection(key)) continue;
                cfg.set(key, defaults.get(key));
                n++;
            }
            plugin.saveConfig();
            String m = "config.yml: " + n + " boss and encounter values updated to version " + jar;
            out.add(m);
            plugin.getLogger().info(m);
        }
        config.load();
        random = new Random(config.seed() + 7L);
        List<String> notes = new ArrayList<>();
        for (BossDef b : defs.values()) { b.load(config); b.normalize(notes); }
        encounters.load(config);
        for (String s : config.notes()) { out.add(s); plugin.getLogger().warning("config: " + s); }
        for (String s : notes) { out.add(s); plugin.getLogger().warning("config: " + s); }
        d.tasks().timer(AI_PERIOD, this::tick);
    }

    int fileVersion() {
        File f = new File(plugin.getDataFolder(), "config.yml");
        if (!f.isFile()) return -1;
        Object raw = YamlConfiguration.loadConfiguration(f).get("config_version");
        return raw instanceof Number n ? n.intValue() : 0;
    }

    // ---------------------------------------------------------------------------------------------- identity
    boolean ours(Entity e) {
        return e != null && (e.getPersistentDataContainer().has(bossKey, PersistentDataType.STRING) || e.getPersistentDataContainer().has(minionKey, PersistentDataType.STRING) || e.getPersistentDataContainer().has(encKey, PersistentDataType.STRING));
    }
    private boolean ourSource(Entity damager) {
        if (damager instanceof Projectile p) {
            if (p.getPersistentDataContainer().has(projectileKey, PersistentDataType.STRING)) return true;
            ProjectileSource s = p.getShooter();
            return s instanceof Entity e && ours(e);
        }
        return ours(damager);
    }
    boolean alive(BossInstance i) { return live.contains(i); }
    BossInstance instanceOf(Entity e) { return e == null ? null : byEntity.get(e.getUniqueId()); }

    // ---------------------------------------------------------------------------------------------- arena
    boolean inArena(BossInstance i, Location l) {
        if (l == null || l.getWorld() == null || !l.getWorld().equals(i.home.getWorld())) return false;
        return l.distanceSquared(i.home) <= i.def.radius * i.def.radius;
    }

    public List<Player> participants(BossInstance i) { return playersNear(i.home, i.def.radius); }

    List<Player> playersNear(Location home, double radius) {
        List<Player> out = new ArrayList<>();
        World w = home.getWorld();
        if (w == null) return out;
        double r2 = radius * radius;
        for (Player p : w.getPlayers()) {
            if (!p.isOnline() || p.isDead() || !p.isValid()) continue;
            if (p.getGameMode() != GameMode.SURVIVAL && p.getGameMode() != GameMode.ADVENTURE) continue;
            if (p.getLocation().distanceSquared(home) <= r2) out.add(p);
        }
        out.sort(Comparator.comparing(Player::getUniqueId));
        return out;
    }

    /** Targets of an attack: participants within range of the boss, ordered by the attack's mode, at most max. */
    List<LivingEntity> targets(BossInstance i, BossDef.Attack a, List<Player> ps) {
        List<LivingEntity> out = new ArrayList<>();
        if (a.select == BossDef.Select.SELF) return out;
        Location at = i.mob.getLocation();
        double r2 = a.range * a.range;
        for (Player p : ps) if (p.getWorld().equals(at.getWorld()) && p.getLocation().distanceSquared(at) <= r2) out.add(p);
        order(out, at, a.select);
        return out.size() > a.max ? new ArrayList<>(out.subList(0, a.max)) : out;
    }

    void order(List<LivingEntity> out, Location at, BossDef.Select select) {
        out.sort(Comparator.comparingDouble((LivingEntity e) -> e.getLocation().distanceSquared(at)).thenComparing(Entity::getUniqueId));
        if (select == BossDef.Select.FARTHEST) Collections.reverse(out);
        else if (select == BossDef.Select.RANDOM) Collections.shuffle(out, random);
    }

    Location spotNear(Location c, double r, int k, int n) {
        double ang = (Math.PI * 2.0 * k) / Math.max(1, n);
        Location p = c.clone().add(Math.cos(ang) * r, 0, Math.sin(ang) * r);
        Location safe = Effects.safeAt(p);
        if (safe != null) return safe;
        return Effects.safeAt(c.clone());
    }

    // ---------------------------------------------------------------------------------------------- spawning
    /** Spawn a boss; returns null on success (the instance is live) or the reason it did not spawn. */
    public String spawn(BossDef def, Location at, String encounter) {
        if (at == null || at.getWorld() == null) return "no location";
        World w = at.getWorld();
        if (w.getDifficulty() == Difficulty.PEACEFUL) return "the world is on peaceful difficulty (the game removes hostile mobs)";
        if (!w.isChunkLoaded(at.getBlockX() >> 4, at.getBlockZ() >> 4)) return "that spot is not loaded";
        if (live.size() >= MAX_LIVE) return "already " + MAX_LIVE + " bosses alive (the limit)";
        int same = 0;
        for (BossInstance i : live) if (i.def == def) same++;
        if (same >= def.maxAlive) return def.id() + " is already alive (" + same + "/" + def.maxAlive + ")";
        long now = d.now();
        Long last = lastSpawn.get(def.id());
        if (encounter == null && last != null && def.spawnCooldownTicks > 0 && now - last < def.spawnCooldownTicks) return def.id() + " can spawn again in " + ((def.spawnCooldownTicks - (now - last)) / 20) + " s";
        int players = Math.max(1, playersNear(at, def.radius).size());
        int number = counter.merge(def.id(), 1, Integer::sum);
        double max = def.scaledHealth(players);
        Consumer<Mob> init = m -> dressBoss(m, def, number, max, players);
        Mob mob = def.spawnBase(at, init);
        if (mob == null || !mob.isValid()) return "the spawn was blocked (another plugin or the world's rules)";
        clearRiders(mob);
        BossBar bar = BossBar.bossBar(Component.text(def.name, def.nameColor), 1f, def.barColor, def.barOverlay);
        if (def.darkenSky) bar.addFlag(BossBar.Flag.DARKEN_SCREEN);
        BossInstance i = new BossInstance(def, number, mob, at, now, bar, players, encounter);
        i.nextAttack = now + def.phases.get(0).interval;
        live.add(i);
        byEntity.put(mob.getUniqueId(), i);
        lastSpawn.put(def.id(), now);
        applySelfEffects(i, now);
        updateBar(i, participants(i));
        if (!def.msgSpawn.isEmpty()) for (Player p : participants(i)) p.sendMessage(Component.text(def.msgSpawn.replace("{boss}", def.name), NamedTextColor.GOLD));
        event("boss " + i.key() + " spawned at " + w.getName() + " " + at.getBlockX() + " " + at.getBlockY() + " " + at.getBlockZ() + ": health " + BossDef.fmt(max) + " (" + players + " player" + (players == 1 ? "" : "s") + ")");
        return null;
    }

    private void dressBoss(Mob m, BossDef def, int number, double max, int players) {
        m.setPersistent(false);
        m.setRemoveWhenFarAway(false);
        m.setCanPickupItems(false);
        m.getPersistentDataContainer().set(bossKey, PersistentDataType.STRING, def.id() + "#" + number);
        m.addScoreboardTag(d.namespace() + ".boss");
        m.addScoreboardTag(d.namespace() + ".boss." + def.id());
        m.customName(Component.text(def.name, def.nameColor));
        m.setCustomNameVisible(true);
        common(m);
        EntityEquipment eq = m.getEquipment();
        if (eq != null) eq.clear();
        def.equip(m);
        noDrops(m);
        attr(m, BossCompat.MAX_HEALTH, max);
        m.setHealth(max);
        if (def.armor >= 0) attr(m, BossCompat.ARMOR, def.armor);
        if (def.attackDamage >= 0) attr(m, BossCompat.ATTACK_DAMAGE, def.attackDamage * (1.0 + def.damagePerPlayer * (Math.max(1, Math.min(def.maxPlayers, players)) - 1)));
        if (def.speed >= 0) attr(m, BossCompat.MOVEMENT_SPEED, def.speed);
        if (def.knockbackResistance >= 0) attr(m, BossCompat.KNOCKBACK_RESISTANCE, def.knockbackResistance);
        if (def.followRange >= 0) attr(m, BossCompat.FOLLOW_RANGE, def.followRange);
    }

    void dressMinion(Mob m, BossInstance owner, Material weapon, double health) {
        m.setPersistent(false);
        m.setRemoveWhenFarAway(false);
        m.setCanPickupItems(false);
        m.getPersistentDataContainer().set(minionKey, PersistentDataType.STRING, owner == null ? "-" : owner.key());
        m.addScoreboardTag(d.namespace() + ".minion");
        common(m);
        EntityEquipment eq = m.getEquipment();
        if (eq != null) { eq.clear(); if (weapon != null) eq.setItemInMainHand(new ItemStack(weapon)); }
        noDrops(m);
        if (health > 0) { attr(m, BossCompat.MAX_HEALTH, health); m.setHealth(health); }
    }

    void dressWaveMob(Mob m, String runKey, Material weapon) {
        m.setPersistent(false);
        m.setRemoveWhenFarAway(false);
        m.setCanPickupItems(false);
        m.getPersistentDataContainer().set(encKey, PersistentDataType.STRING, runKey);
        m.addScoreboardTag(d.namespace() + ".enc");
        common(m);
        EntityEquipment eq = m.getEquipment();
        if (eq != null) { eq.clear(); if (weapon != null) eq.setItemInMainHand(new ItemStack(weapon)); }
        noDrops(m);
    }

    private static void common(Mob m) {
        if (m instanceof Ageable a) a.setAdult();
        if (m instanceof PiglinAbstract pa) pa.setImmuneToZombification(true);
        if (m instanceof Hoglin h) h.setImmuneToZombification(true);
    }

    private static void noDrops(Mob m) {
        EntityEquipment eq = m.getEquipment();
        if (eq == null) return;
        for (EquipmentSlot s : new EquipmentSlot[] {EquipmentSlot.HAND, EquipmentSlot.OFF_HAND, EquipmentSlot.HEAD, EquipmentSlot.CHEST, EquipmentSlot.LEGS, EquipmentSlot.FEET}) eq.setDropChance(s, 0f);
    }

    private static void attr(LivingEntity m, Attribute a, double v) {
        AttributeInstance ai = m.getAttribute(a);
        if (ai != null) ai.setBaseValue(v);
    }

    static void clearRiders(Mob m) {
        Entity v = m.getVehicle();
        if (v != null) { v.removePassenger(m); v.remove(); }
        for (Entity p : new ArrayList<>(m.getPassengers())) { m.removePassenger(p); p.remove(); }
    }

    boolean minionRoom(BossInstance i) {
        i.minions.removeIf(u -> { Entity e = Bukkit.getEntity(u); return e == null || !e.isValid() || e.isDead(); });
        return i.minions.size() < i.def.minionsMax && minionOwner.size() < MAX_MINIONS;
    }

    void addMinion(BossInstance i, Mob m) {
        clearRiders(m);
        i.minions.add(m.getUniqueId());
        minionOwner.put(m.getUniqueId(), i);
    }

    // ---------------------------------------------------------------------------------------------- the AI timer
    private void tick() {
        long now = d.now();
        for (BossInstance i : new ArrayList<>(live)) {
            Mob m = i.mob;
            if (!m.isValid()) { if (!m.isDead()) despawn(i, "its chunk unloaded"); continue; }
            BossDef def = i.def;
            if (!inArena(i, m.getLocation())) { m.teleport(i.home); i.leashes++; }
            List<Player> ps = participants(i);
            updateBar(i, ps);
            if (ps.isEmpty()) {
                if (i.emptySince < 0) i.emptySince = now;
                else if (now - i.emptySince >= def.emptyTicks) { despawn(i, "no players for " + (def.emptyTicks / 20) + " s"); continue; }
            } else i.emptySince = -1;
            if (!ps.isEmpty()) {
                LivingEntity t = m.getTarget();
                if (!(t instanceof Player tp) || !ps.contains(tp)) m.setTarget(nearest(ps, m.getLocation()));
            }
            checkPhase(i);
            if (def.maxTicks > 0 && !i.enraged && now - i.started >= def.maxTicks) {
                if (def.enrageOnTimeout) {
                    i.enraged = true;
                    if (!def.msgEnrage.isEmpty()) for (Player p : ps) p.sendMessage(Component.text(def.msgEnrage.replace("{boss}", def.name), NamedTextColor.RED));
                    event("boss " + i.key() + " enraged (time out)");
                } else { despawn(i, "time out"); continue; }
            }
            if (now - i.lastEffects >= 40) applySelfEffects(i, now);
            if (!ps.isEmpty() && !i.casting && now >= i.nextAttack) choose(i, ps, now);
        }
        encounters.tick(now);
    }

    private static Player nearest(List<Player> ps, Location at) {
        Player best = null;
        double bd = Double.MAX_VALUE;
        for (Player p : ps) { double x = p.getLocation().distanceSquared(at); if (x < bd) { bd = x; best = p; } }
        return best;
    }

    private void applySelfEffects(BossInstance i, long now) {
        i.lastEffects = now;
        BossDef.Phase ph = i.def.phases.get(i.phase);
        for (int k = 0; k < ph.effects.size(); k++) i.mob.addPotionEffect(new PotionEffect(ph.effects.get(k), 80, ph.amplifiers.get(k), true, false));
    }

    /** Enter every phase whose threshold the health fraction is below (one way: healing never goes back). */
    void checkPhase(BossInstance i) {
        if (!i.mob.isValid()) return;
        double f = Checks.healthFraction(i.mob);
        while (i.phase + 1 < i.def.phases.size() && f < i.def.phases.get(i.phase + 1).below) {
            i.phase++;
            BossDef.Phase ph = i.def.phases.get(i.phase);
            List<Player> ps = participants(i);
            List<LivingEntity> ts = new ArrayList<>(ps);
            order(ts, i.mob.getLocation(), BossDef.Select.NEAREST);
            if (ts.size() > ENTER_TARGETS) ts = new ArrayList<>(ts.subList(0, ENTER_TARGETS));
            BossCast c = BossCast.of(this, i, ts, i.def.damageMultiplier(i.mob.getWorld().getDifficulty(), ps.size(), i.enraged));
            i.def.enter(i.phase, c);
            applySelfEffects(i, d.now());
            i.nextAttack = Math.min(i.nextAttack, d.now() + ph.interval);
            updateBar(i, ps);
            event("boss " + i.key() + " entered phase " + ph.id + " at " + Math.round(f * 100) + "%");
        }
    }

    /** Weighted pick (seeded Random.nextInt over the summed weights) among attacks off cooldown that have a target. */
    private void choose(BossInstance i, List<Player> ps, long now) {
        BossDef.Phase ph = i.def.phases.get(i.phase);
        List<BossDef.Attack> ok = new ArrayList<>();
        List<Integer> w = new ArrayList<>();
        List<List<LivingEntity>> ts = new ArrayList<>();
        int total = 0;
        for (int k = 0; k < ph.attacks.size(); k++) {
            BossDef.Attack a = i.def.attack(ph.attacks.get(k));
            if (a == null) continue;
            Long r = i.ready.get(a.id);
            if (r != null && now < r) continue;
            List<LivingEntity> t = targets(i, a, ps);
            if (a.select != BossDef.Select.SELF && t.isEmpty()) continue;
            ok.add(a); w.add(ph.weights.get(k)); ts.add(t); total += ph.weights.get(k);
        }
        long interval = i.enraged ? Math.max(10L, ph.interval / 2) : ph.interval;
        if (ok.isEmpty() || total <= 0) { i.nextAttack = now + AI_PERIOD; return; }
        int roll = random.nextInt(total);
        int pick = 0;
        for (int k = 0; k < ok.size(); k++) { roll -= w.get(k); if (roll < 0) { pick = k; break; } }
        cast(i, ok.get(pick), ts.get(pick), now, true);
        i.nextAttack = now + ok.get(pick).telegraph + interval;
    }

    /** Telegraph (particle / sound / text at the boss), then the attack's generated actions with a fresh budget. */
    int cast(BossInstance i, BossDef.Attack a, List<LivingEntity> targets, long now, boolean telegraph) {
        i.ready.put(a.id, now + a.cooldown);
        if (telegraph && a.telegraph > 0) {
            Location at = i.mob.getLocation().add(0, i.mob.getHeight() + 0.3, 0);
            if (a.telegraphParticle != null && at.getWorld() != null) at.getWorld().spawnParticle(a.telegraphParticle, at, 24, 0.6, 0.4, 0.6, 0.02);
            if (a.telegraphSound != null && !a.telegraphSound.isEmpty() && at.getWorld() != null) at.getWorld().playSound(at, a.telegraphSound, org.bukkit.SoundCategory.HOSTILE, 1f, 1f);
            if (a.telegraphText != null && !a.telegraphText.isEmpty()) for (Player p : participants(i)) p.sendActionBar(Component.text(a.telegraphText.replace("{boss}", i.def.name), NamedTextColor.RED));
            i.casting = true;
            boolean ok = d.tasks().later(a.telegraph, () -> { i.casting = false; if (alive(i) && i.mob.isValid()) run(i, a, targets); });
            if (!ok) i.casting = false;
            return targets.size();
        }
        return run(i, a, targets);
    }

    private int run(BossInstance i, BossDef.Attack a, List<LivingEntity> targets) {
        int n = participants(i).size();
        BossCast c = BossCast.of(this, i, targets, i.def.damageMultiplier(i.mob.getWorld().getDifficulty(), n, i.enraged));
        i.def.attack(a.index, c);
        return c.targets().size();
    }

    void updateBar(BossInstance i, List<Player> ps) {
        BossDef.Phase ph = i.def.phases.get(i.phase);
        String title = i.def.name + (i.def.showPhase && !ph.name.isEmpty() ? " - " + ph.name : "") + (i.enraged ? " (enraged)" : "");
        i.bar.name(Component.text(title, i.def.nameColor));
        i.bar.progress((float) Math.max(0.0, Math.min(1.0, i.mob.isValid() ? Checks.healthFraction(i.mob) : 0.0)));
        List<UUID> keep = new ArrayList<>();
        for (Player p : ps) { keep.add(p.getUniqueId()); if (i.viewers.add(p.getUniqueId())) p.showBossBar(i.bar); }
        for (Iterator<UUID> it = i.viewers.iterator(); it.hasNext();) {
            UUID u = it.next();
            if (keep.contains(u)) continue;
            Player p = Bukkit.getPlayer(u);
            if (p != null) p.hideBossBar(i.bar);
            it.remove();
        }
    }

    String barTitle(BossInstance i) {
        BossDef.Phase ph = i.def.phases.get(i.phase);
        return i.def.name + (i.def.showPhase && !ph.name.isEmpty() ? " - " + ph.name : "") + (i.enraged ? " (enraged)" : "");
    }

    private void hideBar(BossInstance i) {
        for (UUID u : i.viewers) { Player p = Bukkit.getPlayer(u); if (p != null) p.hideBossBar(i.bar); }
        i.viewers.clear();
    }

    private int removeMinions(BossInstance i) {
        int n = 0;
        for (UUID u : i.minions) { Entity e = Bukkit.getEntity(u); if (e != null && e.isValid()) { e.remove(); n++; } minionOwner.remove(u); }
        i.minions.clear();
        return n;
    }

    /** Remove a boss without drops (empty arena, time out, unloaded chunk, command, disable). */
    public void despawn(BossInstance i, String why) {
        if (!live.remove(i)) return;
        byEntity.remove(i.mob.getUniqueId());
        hideBar(i);
        if (!i.def.msgDespawn.isEmpty()) for (Player p : participants(i)) p.sendMessage(Component.text(i.def.msgDespawn.replace("{boss}", i.def.name), NamedTextColor.GRAY));
        if (i.mob.isValid()) i.mob.remove();
        int n = removeMinions(i);
        event("boss " + i.key() + " despawned (" + why + "): minions removed " + n);
        encounters.bossGone(i, false);
    }

    // ---------------------------------------------------------------------------------------------- events
    @EventHandler(priority = EventPriority.NORMAL)
    public void onDeath(EntityDeathEvent e) {
        LivingEntity dead = e.getEntity();
        BossInstance i = byEntity.get(dead.getUniqueId());
        if (i != null) { e.getDrops().clear(); e.setDroppedExp(0); defeated(i, e); return; }
        if (!ours(dead)) return;
        e.getDrops().clear();
        e.setDroppedExp(0);
        BossInstance owner = minionOwner.remove(dead.getUniqueId());
        if (owner != null) owner.minions.remove(dead.getUniqueId());
        encounters.mobDied(dead);
    }

    private void defeated(BossInstance i, EntityDeathEvent e) {
        live.remove(i);
        byEntity.remove(i.mob.getUniqueId());
        Location at = i.mob.getLocation();
        List<String> notes = new ArrayList<>();
        List<Player> ps = participants(i);
        String who;
        int stacks = 0;
        DropTable t = i.def.drops;
        if (t.mode() == DropTable.Mode.GROUND) {
            for (ItemStack s : t.roll(random, d, at, notes)) { at.getWorld().dropItemNaturally(at, s); stacks++; }
            e.setDroppedExp(t.xp());
            who = "the ground";
        } else {
            List<Player> got = qualifying(i.damage, ps, t.minShare());
            for (Player p : got) {
                for (ItemStack s : t.roll(random, d, at, notes)) { for (ItemStack left : p.getInventory().addItem(s).values()) p.getWorld().dropItemNaturally(p.getLocation(), left); stacks++; }
                if (t.xp() > 0) p.giveExp(t.xp());
            }
            who = got.isEmpty() ? "nobody (no participant did " + Math.round(t.minShare() * 100) + "% of the damage)" : got.size() + " player" + (got.size() == 1 ? "" : "s");
        }
        hideBar(i);
        if (!i.def.msgDefeat.isEmpty()) for (Player p : ps) p.sendMessage(Component.text(i.def.msgDefeat.replace("{boss}", i.def.name), NamedTextColor.GOLD));
        int n = removeMinions(i);
        for (String s : notes) plugin.getLogger().warning(s);
        event("boss " + i.key() + " defeated: " + stacks + " drop stack" + (stacks == 1 ? "" : "s") + " to " + who + ", minions removed " + n);
        encounters.bossGone(i, true);
    }

    /** Players (participants or anyone who hit it) with at least minShare of the damage, by UUID (deterministic order). */
    List<Player> qualifying(Map<UUID, Double> damage, List<Player> ps, double minShare) {
        double total = 0;
        for (double v : damage.values()) total += v;
        List<Player> out = new ArrayList<>();
        if (total <= 0) return out;
        List<UUID> ids = new ArrayList<>(damage.keySet());
        Collections.sort(ids);
        for (UUID u : ids) {
            Player p = Bukkit.getPlayer(u);
            if (p == null || !p.isOnline()) continue;
            if (damage.get(u) / total + 1.0E-9 >= minShare) out.add(p);
        }
        return out;
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onDamage(EntityDamageEvent e) {
        Entity victim = e.getEntity();
        if (!ours(victim)) return;
        if (e instanceof EntityDamageByEntityEvent be && ourSource(be.getDamager())) { e.setCancelled(true); return; }
        BossInstance i = byEntity.get(victim.getUniqueId());
        if (i != null && i.def.immune.contains(e.getCause())) e.setCancelled(true);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onHit(EntityDamageByEntityEvent e) {
        Entity src = e.getDamager();
        if (src instanceof Projectile pr && pr.getShooter() instanceof Player sp) src = sp;
        if (!(src instanceof Player p)) return;
        BossInstance i = byEntity.get(e.getEntity().getUniqueId());
        if (i != null) i.damage.merge(p.getUniqueId(), e.getFinalDamage(), Double::sum);
        encounters.credit(e.getEntity(), p, e.getFinalDamage());
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onProjectile(ProjectileHitEvent e) {
        Projectile pr = e.getEntity();
        String tag = pr.getPersistentDataContainer().get(projectileKey, PersistentDataType.STRING);
        if (tag == null) return;
        Entity hit = e.getHitEntity();
        if (hit instanceof LivingEntity le && !ours(le) && le.isValid() && !le.isDead()) {
            int bar = tag.lastIndexOf('|');
            double dmg = 0;
            try { dmg = Double.parseDouble(tag.substring(bar + 1)); } catch (NumberFormatException ex) { dmg = 0; }
            ProjectileSource s = pr.getShooter();
            if (dmg > 0) { if (s instanceof Entity se) le.damage(Math.min(40.0 * 3, dmg), se); else le.damage(Math.min(40.0 * 3, dmg)); }
        }
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onCombust(EntityCombustEvent e) {
        if (e instanceof EntityCombustByEntityEvent || e instanceof EntityCombustByBlockEvent) return;
        if (ours(e.getEntity())) e.setCancelled(true); // daylight
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onChangeBlock(EntityChangeBlockEvent e) { if (ours(e.getEntity())) e.setCancelled(true); }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onTarget(EntityTargetLivingEntityEvent e) { if (ours(e.getEntity()) && e.getTarget() != null && ours(e.getTarget())) e.setCancelled(true); }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onTransform(EntityTransformEvent e) { if (ours(e.getEntity())) e.setCancelled(true); }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onEntitiesLoad(EntitiesLoadEvent e) {
        for (Entity x : e.getEntities()) if (ours(x) && !byEntity.containsKey(x.getUniqueId()) && !minionOwner.containsKey(x.getUniqueId()) && !encounters.tracks(x)) x.remove();
    }

    /** Summon items: right-click with a boss's / encounter's design item (consumed; <ns>.boss.summon). */
    @EventHandler(priority = EventPriority.HIGH)
    public void onInteract(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        if (e.getAction() != Action.RIGHT_CLICK_AIR && e.getAction() != Action.RIGHT_CLICK_BLOCK) return;
        if (e.useItemInHand() == Event.Result.DENY) return;
        Player p = e.getPlayer();
        ItemStack hand = p.getInventory().getItemInMainHand();
        String id = d.identity().idOf(hand);
        if (id == null) return;
        BossDef def = null;
        for (BossDef b : defs.values()) if (id.equals(b.summonItem)) def = b;
        EncounterDef enc = encounters.byItem(id);
        if (def == null && enc == null) return;
        e.setCancelled(true);
        if (!p.hasPermission(d.namespace() + ".boss.summon")) { p.sendMessage(Component.text("You don't have permission to summon that.", NamedTextColor.RED)); return; }
        String err = def != null ? spawn(def, p.getLocation(), null) : encounters.start(enc, p.getLocation());
        if (err != null) { p.sendMessage(Component.text("Nothing happens: " + err + ".", NamedTextColor.RED)); return; }
        hand.setAmount(hand.getAmount() - 1);
    }

    public void disable() {
        int bosses = live.size(), minions = 0;
        for (BossInstance i : new ArrayList<>(live)) { hideBar(i); if (i.mob.isValid()) i.mob.remove(); minions += removeMinions(i); }
        live.clear();
        byEntity.clear();
        minionOwner.clear();
        int mobs = encounters.stopAll("the plugin was disabled");
        plugin.getLogger().info("cleanup: removed " + bosses + " bosses, " + minions + " minions and " + mobs + " encounter mobs");
    }

    void event(String s) {
        plugin.getLogger().info(s);
        lastEvents.add(s);
        if (lastEvents.size() > 8) lastEvents.remove(0);
    }

    // ---------------------------------------------------------------------------------------------- accessors
    public Designer designer() { return d; }
    public JavaPlugin plugin() { return plugin; }
    public BossEffects effects() { return effects; }
    public Encounters encounters() { return encounters; }
    public Map<String, BossDef> defs() { return defs; }
    public BossDef def(String id) { return defs.get(id); }
    public List<BossInstance> live() { return live; }
    public List<String> lastEvents() { return lastEvents; }
    NamespacedKey projectileKey() { return projectileKey; }
    NamespacedKey encKey() { return encKey; }
    Random random() { return random; }
    public String namespace() { return d.namespace(); }
    public String statusLine(BossInstance i) {
        checkPhase(i);
        BossDef.Phase ph = i.def.phases.get(i.phase);
        AttributeInstance max = i.mob.getAttribute(BossCompat.MAX_HEALTH);
        double dist = i.mob.getWorld().equals(i.home.getWorld()) ? i.mob.getLocation().distance(i.home) : -1;
        i.minions.removeIf(u -> { Entity e = Bukkit.getEntity(u); return e == null || !e.isValid() || e.isDead(); });
        return i.key() + ": phase " + (i.phase + 1) + "/" + i.def.phases.size() + " " + ph.id + " health " + BossDef.fmt(i.mob.getHealth()) + "/" + BossDef.fmt(max == null ? 0 : max.getValue())
            + " participants " + participants(i).size() + " minions " + i.minions.size() + " bar \"" + barTitle(i) + "\" " + String.format(Locale.ROOT, "%.2f", (double) i.bar.progress())
            + " enraged " + i.enraged + " leashed " + i.leashes + " dist " + BossDef.fmt(dist);
    }
}
`;

export const ENCOUNTERDEF_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.bossbar.BossBar;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.entity.Mob;

/**
 * Component encounter-def v1: the base of every generated encounter. Structure (waves, their spawns: mob class literals
 * or boss ids, advance rules) in the generated constructor / spawnWave(); numbers and texts in load() (config.yml
 * encounters.<id>.*).
 */
public abstract class EncounterDef {
    public static final class Wave {
        public final boolean cleared;
        public long delayTicks;
        public long ticks;
        public String message = "";
        public int size;
        Wave(boolean cleared) { this.cleared = cleared; }
    }

    /** What a wave's generated code spawns through (the hub caps and tags every mob). */
    public interface Spawner {
        <T extends Mob> void mob(Class<T> type, Material weapon, int count);
        void boss(String id);
    }

    protected final Bosses b;
    private final String id;
    public final List<Wave> waves = new ArrayList<>();
    public final DropTable rewards = new DropTable();
    public BossBar.Color barColor = BossBar.Color.PURPLE;
    public BossBar.Overlay barOverlay = BossBar.Overlay.PROGRESS;
    public boolean command = true;
    public String startItem;
    public String title = "";
    public double radius = 24;
    public long cooldownTicks;
    public int maxAlive = 12;
    public long emptyTicks = 1200;
    public long timeLimitTicks;
    public String msgStart = "";
    public String msgComplete = "";
    public String msgFail = "";

    protected EncounterDef(Bosses b, String id) { this.b = b; this.id = id; }

    public final String id() { return id; }
    protected final Wave wave(boolean cleared) { Wave w = new Wave(cleared); waves.add(w); return w; }
    public abstract void load(DesignConfig c);
    public abstract void spawnWave(int index, Spawner s);
    public void describe(List<String> out) {}

    public final String describeDef() {
        StringBuilder s = new StringBuilder(id).append(": waves=").append(waves.size()).append(" sizes=");
        for (int i = 0; i < waves.size(); i++) s.append(i == 0 ? "" : ",").append(waves.get(i).size).append(waves.get(i).cleared ? "c" : "t");
        s.append(" max_alive=").append(maxAlive).append(" arena=").append(BossDef.fmt(radius)).append(" start=").append(command ? "command" : "-").append(startItem == null ? "" : ",item:" + startItem);
        s.append(" rewards=").append(rewards.mode().name().toLowerCase(java.util.Locale.ROOT)).append('/').append(rewards.size());
        return s.toString();
    }
}
`;

export const ENCOUNTERS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.function.Consumer;
import net.kyori.adventure.bossbar.BossBar;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Difficulty;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Mob;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;

/**
 * Component encounter-runtime v1: waves of capped, tagged mobs (and this mod's bosses) in an arena. At most 2 running
 * encounters, 24 mobs each. A wave starts after its delay; "cleared" waves advance when every mob of the wave is dead
 * (bosses: defeated), "timer" waves after their seconds; the last wave cleared = complete: rewards to the players who did
 * at least the reward table's minDamageShare of the damage to this encounter's mobs (participants mode), or on the
 * ground. Fails (no rewards, every mob removed) when the arena is empty for failure.emptySeconds, at the time limit, or
 * when a "cleared" wave runs past its seconds. Wave mobs drop nothing.
 */
public final class Encounters {
    public static final int MAX_LIVE = 2;
    public static final int MAX_MOBS = 24;
    private final Bosses b;
    private final Map<String, EncounterDef> defs = new LinkedHashMap<>();
    private final List<Run> runs = new ArrayList<>();
    private final Map<String, Long> lastStart = new HashMap<>();
    private final Map<String, Integer> counter = new HashMap<>();

    final class Run {
        final EncounterDef def;
        final int number;
        final Location home;
        final long started;
        final BossBar bar;
        int wave = -1;
        long waveAt;
        long waveStarted;
        long emptySince = -1;
        boolean spawned;
        final Set<UUID> mobs = new LinkedHashSet<>();
        final Set<BossInstance> bosses = new HashSet<>();
        int spawnedThisWave;
        final Map<UUID, Double> damage = new HashMap<>();
        final Set<UUID> viewers = new HashSet<>();
        Run(EncounterDef def, int number, Location home, long started, BossBar bar) { this.def = def; this.number = number; this.home = home.clone(); this.started = started; this.bar = bar; }
        String key() { return def.id() + "#" + number; }
    }

    Encounters(Bosses b) { this.b = b; }

    void register(List<EncounterDef> list) { for (EncounterDef e : list) defs.put(e.id(), e); }
    void load(DesignConfig c) { for (EncounterDef e : defs.values()) e.load(c); }
    public Map<String, EncounterDef> defs() { return defs; }
    public EncounterDef def(String id) { return defs.get(id); }
    EncounterDef byItem(String item) { for (EncounterDef e : defs.values()) if (item.equals(e.startItem)) return e; return null; }
    boolean tracks(Entity e) { for (Run r : runs) if (r.mobs.contains(e.getUniqueId())) return true; return false; }
    public int running() { return runs.size(); }

    /** Start an encounter at a location: null on success, else the reason. */
    public String start(EncounterDef def, Location at) {
        if (at == null || at.getWorld() == null) return "no location";
        if (at.getWorld().getDifficulty() == Difficulty.PEACEFUL) return "the world is on peaceful difficulty (the game removes hostile mobs)";
        if (!at.getWorld().isChunkLoaded(at.getBlockX() >> 4, at.getBlockZ() >> 4)) return "that spot is not loaded";
        if (runs.size() >= MAX_LIVE) return "already " + MAX_LIVE + " encounters running (the limit)";
        for (Run r : runs) if (r.def == def) return def.id() + " is already running";
        long now = b.designer().now();
        Long last = lastStart.get(def.id());
        if (last != null && def.cooldownTicks > 0 && now - last < def.cooldownTicks) return def.id() + " can start again in " + ((def.cooldownTicks - (now - last)) / 20) + " s";
        int n = counter.merge(def.id(), 1, Integer::sum);
        BossBar bar = BossBar.bossBar(Component.text(def.title, NamedTextColor.LIGHT_PURPLE), 1f, def.barColor, def.barOverlay);
        Run r = new Run(def, n, at, now, bar);
        r.waveAt = now + def.waves.get(0).delayTicks;
        r.wave = 0;
        runs.add(r);
        lastStart.put(def.id(), now);
        if (!def.msgStart.isEmpty()) for (Player p : b.playersNear(r.home, def.radius)) p.sendMessage(Component.text(def.msgStart, NamedTextColor.GOLD));
        b.event("encounter " + r.key() + " started at " + at.getWorld().getName() + " " + at.getBlockX() + " " + at.getBlockY() + " " + at.getBlockZ());
        if (def.waves.get(0).delayTicks <= 0) spawnWave(r, now);
        return null;
    }

    private void spawnWave(Run r, long now) {
        r.spawned = true;
        r.waveStarted = now;
        r.spawnedThisWave = 0;
        EncounterDef.Wave w = r.def.waves.get(r.wave);
        final int[] k = {0};
        r.def.spawnWave(r.wave, new EncounterDef.Spawner() {
            @Override
            public <T extends Mob> void mob(Class<T> type, Material weapon, int count) {
                for (int i = 0; i < count; i++) {
                    if (r.mobs.size() >= Math.min(MAX_MOBS, r.def.maxAlive)) return;
                    Location spot = b.spotNear(r.home, Math.min(6.0, Math.max(2.0, r.def.radius / 3.0)), k[0]++, Math.max(1, w.size));
                    if (spot == null) continue;
                    Consumer<T> init = m -> b.dressWaveMob(m, r.key(), weapon);
                    T m = spot.getWorld().spawn(spot, type, false, init);
                    if (m.isValid()) { Bosses.clearRiders(m); r.mobs.add(m.getUniqueId()); r.spawnedThisWave++; }
                }
            }

            @Override
            public void boss(String id) {
                BossDef def = b.def(id);
                if (def == null) return;
                Location spot = b.spotNear(r.home, 3.0, k[0]++, Math.max(1, w.size));
                String err = b.spawn(def, spot == null ? r.home : spot, r.key());
                if (err != null) { b.event("encounter " + r.key() + ": boss " + id + " did not spawn (" + err + ")"); return; }
                for (BossInstance i : b.live()) if (i.def == def && r.key().equals(i.encounter)) r.bosses.add(i);
                r.spawnedThisWave++;
            }
        });
        if (!w.message.isEmpty()) for (Player p : b.playersNear(r.home, r.def.radius)) p.sendMessage(Component.text(w.message, NamedTextColor.YELLOW));
        b.event("encounter " + r.key() + " wave " + (r.wave + 1) + "/" + r.def.waves.size() + ": " + r.spawnedThisWave + " spawned");
    }

    private int alive(Run r) {
        r.mobs.removeIf(u -> { Entity e = Bukkit.getEntity(u); return e == null || !e.isValid() || e.isDead(); });
        r.bosses.removeIf(i -> !b.alive(i));
        return r.mobs.size() + r.bosses.size();
    }

    void tick(long now) {
        for (Run r : new ArrayList<>(runs)) {
            EncounterDef def = r.def;
            List<Player> ps = b.playersNear(r.home, def.radius);
            int left = alive(r);
            updateBar(r, ps, left);
            if (ps.isEmpty()) {
                if (r.emptySince < 0) r.emptySince = now;
                else if (now - r.emptySince >= def.emptyTicks) { fail(r, "no players for " + (def.emptyTicks / 20) + " s"); continue; }
            } else r.emptySince = -1;
            if (def.timeLimitTicks > 0 && now - r.started >= def.timeLimitTicks) { fail(r, "time limit"); continue; }
            EncounterDef.Wave w = def.waves.get(r.wave);
            if (!r.spawned) { if (now >= r.waveAt) spawnWave(r, now); continue; }
            boolean last = r.wave == def.waves.size() - 1;
            if (w.cleared || last) {
                if (left == 0) { if (last) complete(r); else next(r, now); continue; }
                if (w.cleared && w.ticks > 0 && now - r.waveStarted >= w.ticks) { fail(r, "wave " + (r.wave + 1) + " was not cleared in time"); continue; }
            } else if (now - r.waveStarted >= w.ticks) next(r, now);
        }
    }

    private void next(Run r, long now) {
        r.wave++;
        r.spawned = false;
        r.waveAt = now + r.def.waves.get(r.wave).delayTicks;
        if (r.def.waves.get(r.wave).delayTicks <= 0) spawnWave(r, now);
    }

    private void updateBar(Run r, List<Player> ps, int left) {
        String t = r.def.title + " - wave " + (r.wave + 1) + "/" + r.def.waves.size() + (r.spawned ? " (" + left + " left)" : "");
        r.bar.name(Component.text(t, NamedTextColor.LIGHT_PURPLE));
        int size = Math.max(1, r.spawnedThisWave);
        r.bar.progress((float) Math.max(0.0, Math.min(1.0, r.spawned ? left / (double) size : 1.0)));
        Set<UUID> keep = new HashSet<>();
        for (Player p : ps) { keep.add(p.getUniqueId()); if (r.viewers.add(p.getUniqueId())) p.showBossBar(r.bar); }
        r.viewers.removeIf(u -> { if (keep.contains(u)) return false; Player p = Bukkit.getPlayer(u); if (p != null) p.hideBossBar(r.bar); return true; });
    }

    private int cleanup(Run r) {
        runs.remove(r);
        int n = 0;
        for (UUID u : r.mobs) { Entity e = Bukkit.getEntity(u); if (e != null && e.isValid()) { e.remove(); n++; } }
        r.mobs.clear();
        for (BossInstance i : new ArrayList<>(r.bosses)) if (b.alive(i)) { b.despawn(i, "encounter " + r.key() + " ended"); n++; }
        r.bosses.clear();
        for (UUID u : r.viewers) { Player p = Bukkit.getPlayer(u); if (p != null) p.hideBossBar(r.bar); }
        r.viewers.clear();
        return n;
    }

    private void fail(Run r, String why) {
        List<Player> ps = b.playersNear(r.home, r.def.radius);
        int n = cleanup(r);
        if (!r.def.msgFail.isEmpty()) for (Player p : ps) p.sendMessage(Component.text(r.def.msgFail, NamedTextColor.RED));
        b.event("encounter " + r.key() + " failed (" + why + "): mobs removed " + n);
    }

    private void complete(Run r) {
        List<Player> ps = b.playersNear(r.home, r.def.radius);
        cleanup(r);
        List<String> notes = new ArrayList<>();
        DropTable t = r.def.rewards;
        int stacks = 0;
        String who;
        if (t.mode() == DropTable.Mode.GROUND) {
            for (ItemStack s : t.roll(b.random(), b.designer(), r.home, notes)) { r.home.getWorld().dropItemNaturally(r.home, s); stacks++; }
            if (t.xp() > 0) for (Player p : ps) p.giveExp(t.xp());
            who = "the ground";
        } else {
            List<Player> got = b.qualifying(r.damage, ps, t.minShare());
            for (Player p : got) {
                for (ItemStack s : t.roll(b.random(), b.designer(), r.home, notes)) { for (ItemStack left : p.getInventory().addItem(s).values()) p.getWorld().dropItemNaturally(p.getLocation(), left); stacks++; }
                if (t.xp() > 0) p.giveExp(t.xp());
            }
            who = got.isEmpty() ? "nobody (no player did enough of the damage)" : got.size() + " player" + (got.size() == 1 ? "" : "s");
        }
        for (String s : notes) b.plugin().getLogger().warning(s);
        if (!r.def.msgComplete.isEmpty()) for (Player p : ps) p.sendMessage(Component.text(r.def.msgComplete, NamedTextColor.GOLD));
        b.event("encounter " + r.key() + " complete: " + stacks + " reward stack" + (stacks == 1 ? "" : "s") + " to " + who);
    }

    void mobDied(LivingEntity e) { for (Run r : runs) r.mobs.remove(e.getUniqueId()); }

    void bossGone(BossInstance i, boolean defeated) { for (Run r : runs) r.bosses.remove(i); }

    void credit(Entity victim, Player p, double dmg) {
        String k = victim.getPersistentDataContainer().get(b.encKey(), PersistentDataType.STRING);
        BossInstance bi = b.instanceOf(victim);
        for (Run r : runs) if ((k != null && k.equals(r.key())) || (bi != null && r.bosses.contains(bi))) r.damage.merge(p.getUniqueId(), dmg, Double::sum);
    }

    /** /<mod> encounter stop: removes every mob, no rewards. Returns how many were removed. */
    public int stop(String id, String why) {
        int n = 0;
        for (Run r : new ArrayList<>(runs)) if (id == null || r.def.id().equals(id)) { n += cleanup(r); b.event("encounter " + r.key() + " stopped (" + why + ")"); }
        return n;
    }

    int stopAll(String why) { int n = 0; for (Run r : new ArrayList<>(runs)) n += cleanup(r); return n; }

    public List<String> status() {
        List<String> out = new ArrayList<>();
        long now = b.designer().now();
        for (Run r : runs) out.add("encounter " + r.key() + ": wave " + (r.wave + 1) + "/" + r.def.waves.size() + (r.spawned ? "" : " (starting)") + " alive " + alive(r) + " participants " + b.playersNear(r.home, r.def.radius).size() + " elapsed " + ((now - r.started) / 20) + "s");
        return out;
    }
}
`;

export const BOSSCOMMAND_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Random;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.World;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;

/**
 * Component boss-command v1: adds the boss and encounter subcommands to the mod command and hands everything else to the
 * command it wraps (the items' DesignCommand or the menus/quests GameplayCommand):
 *   /<mod> boss list | status | check                          (<ns>.boss.admin, operators)
 *   /<mod> boss spawn <id> [<world> <x> <y> <z> | spawn]       (<ns>.boss.admin; players default to where they stand)
 *   /<mod> boss despawn <id|all> | cast <id> <attack>          (<ns>.boss.admin; cast = one attack now, no telegraph:
 *                                                               participants, or the nearest other mob for testing)
 *   /<mod> encounter list | status | start <id> [...] | stop <id|all>   (<ns>.boss.admin)
 *   /<mod> reload and params include bosses + encounters.
 */
public final class BossCommand implements CommandExecutor, TabCompleter {
    private static final List<String> SUBS = List.of("boss", "encounter");
    private static final List<String> BSUBS = List.of("list", "status", "check", "spawn", "despawn", "cast");
    private static final List<String> ESUBS = List.of("list", "status", "start", "stop");
    private final Bosses b;
    private final String label;
    private final CommandExecutor next;
    private final TabCompleter nextTab;
    private final boolean others;

    BossCommand(Bosses b, String label, CommandExecutor next, TabCompleter nextTab, boolean others) { this.b = b; this.label = label; this.next = next; this.nextTab = nextTab; this.others = others; }

    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }

    private boolean allowed(CommandSender s, String node) {
        if (s.hasPermission(b.namespace() + "." + node)) return true;
        say(s, "You don't have permission for that.", NamedTextColor.RED);
        return false;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String used, String[] args) {
        String sub = args.length == 0 ? "" : args[0].toLowerCase(Locale.ROOT);
        switch (sub) {
            case "boss", "bosses" -> { boss(sender, args); return true; }
            case "encounter", "encounters" -> { encounter(sender, args); return true; }
            case "reload" -> {
                if (!sender.hasPermission(b.namespace() + ".reload")) { say(sender, "You don't have permission for that.", NamedTextColor.RED); return true; }
                int before = b.fileVersion();
                if (next != null && others) next.onCommand(sender, command, used, args);
                else b.designer().reload();
                List<String> notes = new ArrayList<>();
                b.load(before, notes);
                say(sender, b.plugin().getName() + " bosses and encounters reloaded" + (notes.isEmpty() ? "" : " (" + notes.size() + " note" + (notes.size() == 1 ? "" : "s") + ")"), NamedTextColor.GREEN);
                for (String n : notes) say(sender, "- " + n, NamedTextColor.YELLOW);
                return true;
            }
            case "params" -> {
                if (!allowed(sender, "command")) return true;
                String want = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : null;
                boolean mine = want != null && (b.def(want) != null || b.encounters().def(want) != null);
                if (others && next != null && !mine) next.onCommand(sender, command, used, args);
                List<String> out = new ArrayList<>();
                for (BossDef d : b.defs().values()) if (want == null || d.id().equals(want)) d.describe(out);
                for (EncounterDef e : b.encounters().defs().values()) if (want == null || e.id().equals(want)) e.describe(out);
                if (out.isEmpty() && (!others || mine)) say(sender, "No parameters.", NamedTextColor.GRAY);
                for (String line : out) say(sender, line, NamedTextColor.AQUA);
                return true;
            }
            case "" -> {
                if (others && next != null) next.onCommand(sender, command, used, args);
                say(sender, b.plugin().getName() + ": bosses " + (b.defs().isEmpty() ? "-" : String.join(", ", b.defs().keySet())) + "; encounters " + (b.encounters().defs().isEmpty() ? "-" : String.join(", ", b.encounters().defs().keySet())) + ". Use /" + label + " boss list, /" + label + " encounter list", NamedTextColor.GOLD);
                return true;
            }
            default -> {
                if (next != null) return next.onCommand(sender, command, used, args);
                say(sender, "Unknown subcommand. Use /" + label + " boss, encounter, params or reload.", NamedTextColor.RED);
                return true;
            }
        }
    }

    private Location where(CommandSender sender, String[] args, int at) {
        if (args.length > at && args[at].equalsIgnoreCase("spawn")) { World w = Bukkit.getWorlds().get(0); return w.getSpawnLocation(); }
        if (args.length >= at + 4) {
            World w = Bukkit.getWorld(args[at]);
            if (w == null) return null;
            try { return new Location(w, Double.parseDouble(args[at + 1]), Double.parseDouble(args[at + 2]), Double.parseDouble(args[at + 3])); }
            catch (NumberFormatException e) { return null; }
        }
        return sender instanceof Player p ? p.getLocation() : null;
    }

    private void boss(CommandSender sender, String[] args) {
        if (!allowed(sender, "boss.admin")) return;
        String a = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "";
        switch (a) {
            case "list" -> { for (BossDef d : b.defs().values()) say(sender, d.describeDef(), NamedTextColor.AQUA); if (b.defs().isEmpty()) say(sender, "No bosses.", NamedTextColor.GRAY); }
            case "status" -> {
                if (b.live().isEmpty()) say(sender, "No bosses alive.", NamedTextColor.GRAY);
                for (BossInstance i : new ArrayList<>(b.live())) say(sender, b.statusLine(i), NamedTextColor.AQUA);
                for (String s : b.lastEvents()) say(sender, "last: " + s, NamedTextColor.GRAY);
            }
            case "check" -> { for (String line : check()) say(sender, line, line.contains("FAIL") ? NamedTextColor.RED : NamedTextColor.AQUA); }
            case "spawn" -> {
                BossDef d = args.length >= 3 ? b.def(args[2].toLowerCase(Locale.ROOT)) : null;
                if (d == null) { say(sender, "Usage: /" + label + " boss spawn <id> [<world> <x> <y> <z> | spawn]", NamedTextColor.RED); return; }
                if (!d.command) { say(sender, d.id() + " is not spawned by command (it has a summon item or comes in an encounter).", NamedTextColor.RED); return; }
                Location at = where(sender, args, 3);
                if (at == null) { say(sender, "Usage from the console: /" + label + " boss spawn <id> <world> <x> <y> <z> | spawn", NamedTextColor.RED); return; }
                String err = b.spawn(d, at, null);
                if (err != null) say(sender, "Not spawned: " + err + ".", NamedTextColor.RED);
                else say(sender, "Spawned " + b.live().get(b.live().size() - 1).key() + " (" + d.entity() + ") at " + at.getWorld().getName() + " " + at.getBlockX() + " " + at.getBlockY() + " " + at.getBlockZ() + ": health " + BossDef.fmt(b.live().get(b.live().size() - 1).mob.getHealth()) + ", phase " + d.phases.get(0).id + ", arena " + BossDef.fmt(d.radius) + " blocks", NamedTextColor.GREEN);
            }
            case "despawn" -> {
                String id = args.length >= 3 ? args[2].toLowerCase(Locale.ROOT) : null;
                if (id == null) { say(sender, "Usage: /" + label + " boss despawn <id|all>", NamedTextColor.RED); return; }
                int n = 0;
                for (BossInstance i : new ArrayList<>(b.live())) if (id.equals("all") || i.def.id().equals(id)) { b.despawn(i, "command"); n++; }
                say(sender, "Despawned " + n + " boss" + (n == 1 ? "" : "es") + ".", NamedTextColor.GREEN);
            }
            case "cast" -> {
                BossInstance i = null;
                if (args.length >= 4) for (BossInstance x : b.live()) if (x.def.id().equals(args[2].toLowerCase(Locale.ROOT))) i = x;
                BossDef.Attack at = i == null ? null : i.def.attack(args[3].toLowerCase(Locale.ROOT));
                if (i == null || at == null) { say(sender, "Usage: /" + label + " boss cast <alive boss id> <attack id>", NamedTextColor.RED); return; }
                List<LivingEntity> ts = b.targets(i, at, b.participants(i));
                boolean test = false;
                if (ts.isEmpty() && at.select != BossDef.Select.SELF) {
                    test = true;
                    for (Entity e : i.mob.getNearbyEntities(at.range, at.range, at.range)) if (e instanceof LivingEntity le && !(e instanceof Player) && !b.ours(e) && le.isValid() && !le.isDead() && !(e instanceof org.bukkit.entity.ArmorStand)) ts.add(le);
                    b.order(ts, i.mob.getLocation(), BossDef.Select.NEAREST);
                    if (ts.size() > at.max) ts = new ArrayList<>(ts.subList(0, at.max));
                }
                int n = b.cast(i, at, ts, b.designer().now(), false);
                say(sender, "Cast " + at.id + " of " + i.key() + " on " + n + " target" + (n == 1 ? "" : "s") + (test ? " (test targets: no participant in range)" : "") + " (telegraph skipped)", NamedTextColor.GREEN);
            }
            default -> say(sender, "Usage: /" + label + " boss list | status | check | spawn <id> [...] | despawn <id|all> | cast <id> <attack>", NamedTextColor.RED);
        }
    }

    private void encounter(CommandSender sender, String[] args) {
        if (!allowed(sender, "boss.admin")) return;
        String a = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "";
        switch (a) {
            case "list" -> { for (EncounterDef e : b.encounters().defs().values()) say(sender, e.describeDef(), NamedTextColor.AQUA); if (b.encounters().defs().isEmpty()) say(sender, "No encounters.", NamedTextColor.GRAY); }
            case "status" -> {
                List<String> s = b.encounters().status();
                if (s.isEmpty()) say(sender, "No encounters running.", NamedTextColor.GRAY);
                for (String line : s) say(sender, line, NamedTextColor.AQUA);
                for (String line : b.lastEvents()) say(sender, "last: " + line, NamedTextColor.GRAY);
            }
            case "start" -> {
                EncounterDef e = args.length >= 3 ? b.encounters().def(args[2].toLowerCase(Locale.ROOT)) : null;
                if (e == null) { say(sender, "Usage: /" + label + " encounter start <id> [<world> <x> <y> <z> | spawn]", NamedTextColor.RED); return; }
                if (!e.command) { say(sender, e.id() + " is not started by command (it has a start item).", NamedTextColor.RED); return; }
                Location at = where(sender, args, 3);
                if (at == null) { say(sender, "Usage from the console: /" + label + " encounter start <id> <world> <x> <y> <z> | spawn", NamedTextColor.RED); return; }
                String err = b.encounters().start(e, at);
                say(sender, err == null ? "Started " + e.id() + " (" + e.waves.size() + " waves)." : "Not started: " + err + ".", err == null ? NamedTextColor.GREEN : NamedTextColor.RED);
            }
            case "stop" -> {
                String id = args.length >= 3 ? args[2].toLowerCase(Locale.ROOT) : null;
                if (id == null) { say(sender, "Usage: /" + label + " encounter stop <id|all>", NamedTextColor.RED); return; }
                int n = b.encounters().stop(id.equals("all") ? null : id, "command");
                say(sender, "Stopped; " + n + " mobs removed.", NamedTextColor.GREEN);
            }
            default -> say(sender, "Usage: /" + label + " encounter list | status | start <id> [...] | stop <id|all>", NamedTextColor.RED);
        }
    }

    /** Definitions + the random / scaling math on this server's JVM (the TS simulator prints the same samples). */
    private List<String> check() {
        List<String> out = new ArrayList<>();
        out.add("boss index: bosses=" + b.defs().size() + " encounters=" + b.encounters().defs().size() + " ai_period=" + Bosses.AI_PERIOD + " max_bosses=" + Bosses.MAX_LIVE + " max_minions=" + Bosses.MAX_MINIONS + " max_encounters=" + Encounters.MAX_LIVE + " max_encounter_mobs=" + Encounters.MAX_MOBS + " budget=" + Budget.ACTIONS + "/" + Budget.ENTITIES + "/" + Budget.PARTICLES + "/" + Budget.PROJECTILES + "/" + Budget.TASKS);
        for (BossDef d : b.defs().values()) {
            out.add("scale " + d.id() + ": health n1=" + BossDef.fmt(d.scaledHealth(1)) + " n4=" + BossDef.fmt(d.scaledHealth(4)) + " n8=" + BossDef.fmt(d.scaledHealth(8)) + " damage easy=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.EASY, 1, false)) + " normal=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.NORMAL, 1, false)) + " hard=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.HARD, 1, false)) + " normal_x4=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.NORMAL, 4, false)) + " enraged=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.NORMAL, 1, true)));
            Random r = new Random(1234L);
            StringBuilder s = new StringBuilder("drops " + d.id() + ":");
            for (int k = 0; k < 5; k++) { int[] c = d.drops.rollCounts(r); s.append(k == 0 ? " " : " | "); for (int j = 0; j < c.length; j++) s.append(j == 0 ? "" : ",").append(c[j]); }
            out.add(s.toString());
            for (BossDef.Phase ph : d.phases) {
                Random w = new Random(7L);
                int total = 0;
                for (int x : ph.weights) total += x;
                StringBuilder p = new StringBuilder("picks " + d.id() + "." + ph.id + ":");
                for (int k = 0; k < 12 && total > 0; k++) { int roll = w.nextInt(total); int pick = 0; for (int j = 0; j < ph.weights.size(); j++) { roll -= ph.weights.get(j); if (roll < 0) { pick = j; break; } } p.append(' ').append(pick); }
                out.add(p.toString());
            }
        }
        List<Integer> order = new ArrayList<>(List.of(0, 1, 2, 3, 4, 5));
        Collections.shuffle(order, new Random(42L));
        out.add("random target order (seed 42): " + order);
        return out;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String used, String[] args) {
        List<String> out = new ArrayList<>();
        String last = args.length == 0 ? "" : args[args.length - 1].toLowerCase(Locale.ROOT);
        if (args.length <= 1) {
            for (String s : SUBS) if (s.startsWith(last)) out.add(s);
            if (nextTab != null) for (String s : nextTab.onTabComplete(sender, command, used, args)) if (!out.contains(s)) out.add(s);
            return out;
        }
        String sub = args[0].toLowerCase(Locale.ROOT);
        if (sub.startsWith("boss") && args.length == 2) { for (String s : BSUBS) if (s.startsWith(last)) out.add(s); return out; }
        if (sub.startsWith("boss") && args.length == 3) { for (String s : b.defs().keySet()) if (s.startsWith(last)) out.add(s); return out; }
        if (sub.startsWith("encounter") && args.length == 2) { for (String s : ESUBS) if (s.startsWith(last)) out.add(s); return out; }
        if (sub.startsWith("encounter") && args.length == 3) { for (String s : b.encounters().defs().keySet()) if (s.startsWith(last)) out.add(s); return out; }
        return nextTab == null ? out : nextTab.onTabComplete(sender, command, used, args);
    }
}
`;

