// Cyrus R3 gameplay designers, part 3: the BOSS + ENCOUNTER component sources. Fixed code like the item and gameplay
// libraries (../components/java.ts, ../gameplay/java.ts): reviewed once, compiled with javac against the real Paper
// classpaths (1.21.11 / JDK 21, 26.2 / JDK 25), strict-scanned and booted in Test Flight; generated boss / encounter
// classes only call them. `__PKG__` is replaced by the mod's package. BossCompat is the only per-version file
// (./components.ts renders it). Reused from the item library: Budget (the per-attack budget), Tasks (Paper main-thread
// scheduler only), DesignConfig (clamping config loader), Checks (health fraction), Effects.safeAt (safe spawn spots),
// ItemIdentity (summon items, design-item drops). No reflection, no threads, no network, no command dispatch.
/* eslint-disable no-useless-escape */

export const BOSSDEF_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Consumer;
import net.kyori.adventure.bossbar.BossBar;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextColor;
import org.bukkit.Difficulty;
import org.bukkit.Location;
import org.bukkit.Particle;
import org.bukkit.entity.Mob;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.potion.PotionEffectType;

/**
 * Component boss-def v1: the base of every generated boss. The generated subclass sets the STRUCTURE in its constructor
 * (phase ids, attack ids and target modes, immunities, bar style) and the PARAMETERS in load() (every number and text
 * of the design, read through the clamping DesignConfig: config.yml bosses.<id>.*). attack() / enter() are straight-line
 * calls into BossEffects. The scaling math here is mirrored by the TS simulator (boss check prints a sample of both).
 */
public abstract class BossDef {
    public enum Select { NEAREST, RANDOM, FARTHEST, ALL, SELF }

    public static final class Attack {
        public final String id;
        public final Select select;
        public final int index;
        public String name = "";
        public long cooldown;
        public long telegraph;
        public int max = 1;
        public double range = 8;
        public Particle telegraphParticle;
        public String telegraphSound;
        public String telegraphText;
        Attack(String id, Select select, int index) { this.id = id; this.select = select; this.index = index; }
    }

    public static final class Phase {
        public final String id;
        public final int index;
        public String name = "";
        public double below = 1.0;
        public long interval = 60;
        public final List<String> attacks = new ArrayList<>();
        public final List<Integer> weights = new ArrayList<>();
        public final List<PotionEffectType> effects = new ArrayList<>();
        public final List<Integer> amplifiers = new ArrayList<>();
        Phase(String id, int index) { this.id = id; this.index = index; }
    }

    protected final Bosses b;
    private final String id;
    private final String entity;
    public final List<Phase> phases = new ArrayList<>();
    public final List<Attack> attacks = new ArrayList<>();
    public final Set<EntityDamageEvent.DamageCause> immune = EnumSet.noneOf(EntityDamageEvent.DamageCause.class);
    public final DropTable drops = new DropTable();
    public BossBar.Color barColor = BossBar.Color.RED;
    public BossBar.Overlay barOverlay = BossBar.Overlay.PROGRESS;
    public boolean showPhase;
    public boolean darkenSky;
    public boolean command = true;
    public String summonItem;
    public boolean enrageOnTimeout;
    // parameters (generated load())
    public String name = "";
    public TextColor nameColor = NamedTextColor.RED;
    public double health = 100;
    public double armor = -1;
    public double attackDamage = -1;
    public double speed = -1;
    public double knockbackResistance = -1;
    public double followRange = -1;
    public double radius = 16;
    public long emptyTicks = 1200;
    public long maxTicks;
    public long spawnCooldownTicks;
    public int maxAlive = 1;
    public int minionsMax;
    public double healthPerPlayer;
    public double damagePerPlayer;
    public int maxPlayers = 8;
    public double difficultyEasy = 1.0;
    public double difficultyNormal = 1.0;
    public double difficultyHard = 1.0;
    public String msgSpawn = "";
    public String msgDefeat = "";
    public String msgDespawn = "";
    public String msgEnrage = "";

    protected BossDef(Bosses b, String id, String entity) { this.b = b; this.id = id; this.entity = entity; }

    public final String id() { return id; }
    public final String entity() { return entity; }
    protected final Attack attack(String attackId, Select select) { Attack a = new Attack(attackId, select, attacks.size()); attacks.add(a); return a; }
    protected final Phase phase(String phaseId) { Phase p = new Phase(phaseId, phases.size()); phases.add(p); return p; }
    public final Attack attack(String attackId) { for (Attack a : attacks) if (a.id.equals(attackId)) return a; return null; }

    /** Spawn the base mob (generated: the class literal of the base, randomizeData false = no random gear / babies / jockeys). */
    public abstract Mob spawnBase(Location at, Consumer<Mob> init);
    /** Display equipment (generated); drop chances are set to 0 by the hub. */
    public void equip(Mob m) {}
    public abstract void load(DesignConfig c);
    /** Run attack number index (generated straight-line actions). */
    public abstract void attack(int index, BossCast c);
    /** Run phase number index's onEnter actions (generated). */
    public void enter(int index, BossCast c) {}
    public void describe(List<String> out) {}

    /** After load(): thresholds forced to go down (a hand-edited config cannot reorder phases); the first phase is at 1. */
    final void normalize(List<String> notes) {
        for (int i = 0; i < phases.size(); i++) {
            Phase p = phases.get(i);
            if (i == 0) { p.below = 1.0; continue; }
            double prev = phases.get(i - 1).below;
            if (p.below > prev) { notes.add("bosses." + id + ".phases." + p.id + ".below " + p.below + " is above the previous phase; using " + prev); p.below = prev; }
        }
        if (maxPlayers < 1) maxPlayers = 1;
    }

    /** Max health for this many participants at spawn (counted 1..maxPlayers), clamped to 1..1024. */
    public final double scaledHealth(int players) {
        int n = Math.max(1, Math.min(maxPlayers, players));
        return Math.max(1.0, Math.min(1024.0, health * (1.0 + healthPerPlayer * (n - 1))));
    }

    /** Attack damage multiplier: world difficulty x (1 + damagePerPlayer per extra participant) x 1.5 when enraged. */
    public final double damageMultiplier(Difficulty d, int players, boolean enraged) {
        double base = d == Difficulty.HARD ? difficultyHard : d == Difficulty.NORMAL ? difficultyNormal : difficultyEasy;
        int n = Math.max(1, Math.min(maxPlayers, players));
        return base * (1.0 + damagePerPlayer * (n - 1)) * (enraged ? 1.5 : 1.0);
    }

    public final String describeDef() {
        StringBuilder s = new StringBuilder(id).append(": entity=").append(entity).append(" health=").append(fmt(health)).append(" phases=");
        for (int i = 0; i < phases.size(); i++) s.append(i == 0 ? "" : ">").append(phases.get(i).id).append('@').append(fmt(phases.get(i).below));
        s.append(" attacks=").append(attacks.size()).append(" arena=").append(fmt(radius)).append(" bar=").append(barColor.name().toLowerCase(Locale.ROOT)).append('/').append(barOverlay.name().toLowerCase(Locale.ROOT));
        s.append(" spawn=").append(command ? "command" : "-").append(summonItem == null ? "" : ",item:" + summonItem).append(" max_alive=").append(maxAlive).append(" minions=").append(minionsMax);
        return s.toString();
    }

    public static String fmt(double v) { return String.format(Locale.ROOT, "%.2f", v); }
}
`;

export const BOSSCAST_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Mob;

/** Component boss-cast v1: one attack (or phase start) of one boss: the boss, its targets, the damage multiplier and the shared Budget. */
public final class BossCast {
    private final Bosses b;
    private final BossInstance inst;
    private final List<LivingEntity> targets;
    private final LivingEntity target;
    private final double mult;
    private final Budget budget;

    private BossCast(Bosses b, BossInstance inst, List<LivingEntity> targets, LivingEntity target, double mult, Budget budget) {
        this.b = b; this.inst = inst; this.targets = targets; this.target = target; this.mult = mult; this.budget = budget;
    }

    static BossCast of(Bosses b, BossInstance inst, List<LivingEntity> targets, double mult) { return new BossCast(b, inst, new ArrayList<>(targets), null, mult, new Budget()); }

    /** The same cast (same budget) aimed at one target: the per-target actions. */
    public BossCast at(LivingEntity t) { return new BossCast(b, inst, targets, t, mult, budget); }

    /** Targets still alive and inside the arena (re-checked for delayed steps). */
    public List<LivingEntity> targets() {
        List<LivingEntity> out = new ArrayList<>();
        for (LivingEntity t : targets) if (t.isValid() && !t.isDead() && b.inArena(inst, t.getLocation())) out.add(t);
        return out;
    }

    public LivingEntity first() { List<LivingEntity> t = targets(); return t.isEmpty() ? null : t.get(0); }
    public LivingEntity target() { return target; }
    public Mob boss() { return inst.mob; }
    public BossInstance instance() { return inst; }
    public Bosses bosses() { return b; }
    public double mult() { return mult; }
    public Budget budget() { return budget; }
    public boolean valid() { return inst.mob.isValid() && !inst.mob.isDead() && b.alive(inst); }

    /** Run a step later (one task from the budget; skipped when the boss is gone). */
    public void later(long delay, Runnable step) {
        if (!budget.task()) return;
        b.designer().tasks().later(delay, () -> { if (valid()) step.run(); });
    }
}
`;

export const BOSSEFFECTS_JAVA = String.raw`package __PKG__.designer;

import java.time.Duration;
import java.util.function.Consumer;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextColor;
import net.kyori.adventure.title.Title;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.Particle;
import org.bukkit.SoundCategory;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.entity.AbstractArrow;
import org.bukkit.entity.Arrow;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Mob;
import org.bukkit.entity.Player;
import org.bukkit.entity.Projectile;
import org.bukkit.entity.SmallFireball;
import org.bukkit.entity.Snowball;
import org.bukkit.entity.WindCharge;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.util.Vector;

/**
 * Component boss-effects v1: every boss action. The same rules as the item Effects: each checks the cast's Budget, skips a
 * missing / dead subject, clamps velocities (4 blocks/tick), damage goes through Bukkit's damage events with the BOSS as
 * the source (armor, protection plugins and PvP rules apply), projectiles are removed after 5 s, fireballs set no fires
 * and break no blocks, sounds by namespaced key only. Minions go through the hub (capped, tagged, never dropping loot).
 */
public final class BossEffects {
    private static final double MAX_SPEED = 4.0;
    private final Bosses b;

    BossEffects(Bosses b) { this.b = b; }

    private static boolean alive(LivingEntity t) { return t != null && t.isValid() && !t.isDead(); }

    public Location at(BossCast c) { Mob m = c.boss(); return m.getLocation().add(0, m.getHeight() / 2.0, 0); }
    public Location at(LivingEntity t) { return t == null || !t.isValid() ? null : t.getLocation().add(0, t.getHeight() / 2.0, 0); }

    public void damage(BossCast c, LivingEntity t, double amount) {
        if (!alive(t) || amount <= 0 || !c.budget().entity()) return;
        t.damage(amount * c.mult(), c.boss());
    }

    private void push(BossCast c, LivingEntity t, Vector dir, double strength, double vertical) {
        if (!alive(t) || !c.budget().entity()) return;
        Vector h = dir.clone().setY(0);
        Vector v = h.lengthSquared() < 1.0E-4 ? new Vector(0, 0, 0) : h.normalize().multiply(strength);
        v.setY(vertical);
        if (v.length() > MAX_SPEED) v.normalize().multiply(MAX_SPEED);
        t.setVelocity(v);
    }

    /** Away from the boss. */
    public void knockback(BossCast c, LivingEntity t, double strength, double vertical) {
        if (t == null || !t.getWorld().equals(c.boss().getWorld())) return;
        push(c, t, t.getLocation().toVector().subtract(c.boss().getLocation().toVector()), strength, vertical);
    }

    /** Toward the boss (no effect closer than one block). */
    public void pull(BossCast c, LivingEntity t, double strength, double vertical) {
        if (t == null || !t.getWorld().equals(c.boss().getWorld())) return;
        Vector dir = c.boss().getLocation().toVector().subtract(t.getLocation().toVector());
        if (dir.length() < 1.0) return;
        push(c, t, dir, strength, vertical);
    }

    public void potion(BossCast c, LivingEntity t, PotionEffectType type, int ticks, int amplifier) {
        if (!alive(t) || type == null || !c.budget().entity()) return;
        t.addPotionEffect(new PotionEffect(type, ticks, amplifier));
    }

    /** One projectile from the boss's eyes at t; the extra damage rides on it (scaled now) and is dealt on hit by the hub. */
    public void launch(BossCast c, LivingEntity t, String kind, double speed, double damage) {
        if (!alive(t) || !c.budget().projectile()) return;
        Mob m = c.boss();
        Vector dir = at(t).toVector().subtract(m.getEyeLocation().toVector());
        if (dir.lengthSquared() < 1.0E-4) return;
        Vector vel = dir.normalize().multiply(speed);
        Projectile pr;
        if ("arrow".equals(kind)) { Arrow ar = m.launchProjectile(Arrow.class, vel); ar.setPickupStatus(AbstractArrow.PickupStatus.DISALLOWED); ar.setDamage(0.0); pr = ar; }
        else if ("small_fireball".equals(kind)) { SmallFireball f = m.launchProjectile(SmallFireball.class, vel); f.setIsIncendiary(false); f.setYield(0f); pr = f; }
        else if ("wind_charge".equals(kind)) pr = m.launchProjectile(WindCharge.class, vel);
        else pr = m.launchProjectile(Snowball.class, vel);
        pr.getPersistentDataContainer().set(b.projectileKey(), PersistentDataType.STRING, c.instance().key() + "|" + (damage * c.mult()));
        final Projectile launched = pr;
        if (c.budget().task()) b.designer().tasks().later(100L, () -> { if (launched.isValid()) launched.remove(); });
    }

    public void particles(BossCast c, Location at, Particle type, int count, double spread, double speed) {
        if (at == null || at.getWorld() == null) return;
        int n = c.budget().particles(count);
        if (n > 0) at.getWorld().spawnParticle(type, at, n, spread, spread, spread, speed);
    }

    public void sound(BossCast c, Location at, String key, float volume, float pitch) {
        if (at == null || at.getWorld() == null || key == null || key.isEmpty()) return;
        at.getWorld().playSound(at, key, SoundCategory.HOSTILE, volume, pitch);
    }

    private String fill(BossCast c, LivingEntity to, String s) {
        return s.replace("{player}", to == null ? "" : to.getName()).replace("{boss}", c.instance().def.name);
    }

    public void message(BossCast c, LivingEntity to, String text, TextColor color) {
        if (to instanceof Player p && p.isOnline()) p.sendMessage(Component.text(fill(c, to, text), color));
    }

    public void actionbar(BossCast c, LivingEntity to, String text, TextColor color) {
        if (to instanceof Player p && p.isOnline()) p.sendActionBar(Component.text(fill(c, to, text), color));
    }

    public void title(BossCast c, LivingEntity to, String title, String subtitle, TextColor color) {
        if (!(to instanceof Player p) || !p.isOnline()) return;
        p.showTitle(Title.title(Component.text(fill(c, to, title), color), Component.text(subtitle == null ? "" : fill(c, to, subtitle)),
            Title.Times.times(Duration.ofMillis(250), Duration.ofMillis(2000), Duration.ofMillis(500))));
    }

    /** Text to every participant (to: arena). */
    public void arenaMessage(BossCast c, String text, TextColor color) { for (Player p : b.participants(c.instance())) message(c, p, text, color); }
    public void arenaActionbar(BossCast c, String text, TextColor color) { for (Player p : b.participants(c.instance())) actionbar(c, p, text, color); }
    public void arenaTitle(BossCast c, String title, String subtitle, TextColor color) { for (Player p : b.participants(c.instance())) title(c, p, title, subtitle, color); }

    /** The boss jumps toward its first target. */
    public void leap(BossCast c, double strength, double vertical) {
        LivingEntity t = c.first();
        if (t == null || !c.budget().entity()) return;
        Mob m = c.boss();
        Vector h = t.getLocation().toVector().subtract(m.getLocation().toVector()).setY(0);
        Vector v = h.lengthSquared() < 1.0E-4 ? new Vector(0, 0, 0) : h.normalize().multiply(strength);
        v.setY(vertical);
        if (v.length() > MAX_SPEED) v.normalize().multiply(MAX_SPEED);
        m.setVelocity(v);
    }

    /** Minions next to the boss: capped per boss (minions.maxAlive) and plugin-wide (48); returns how many spawned. */
    public <T extends Mob> int summon(BossCast c, Class<T> type, Material weapon, int count, double health) {
        int n = 0;
        for (int i = 0; i < count; i++) {
            if (!b.minionRoom(c.instance())) break;
            Location spot = b.spotNear(c.boss().getLocation(), 2.5, i, count);
            if (spot == null) continue;
            Consumer<T> init = m -> b.dressMinion(m, c.instance(), weapon, health);
            T m = spot.getWorld().spawn(spot, type, false, init);
            if (m.isValid()) { b.addMinion(c.instance(), m); n++; }
        }
        return n;
    }

    public void healSelf(BossCast c, double amount) {
        Mob m = c.boss();
        if (amount <= 0 || !c.budget().entity()) return;
        AttributeInstance max = m.getAttribute(BossCompat.MAX_HEALTH);
        m.setHealth(Math.min(max == null ? m.getHealth() : max.getValue(), m.getHealth() + amount));
    }

    public void selfEffect(BossCast c, PotionEffectType type, int ticks, int amplifier) {
        if (type == null || !c.budget().entity()) return;
        c.boss().addPotionEffect(new PotionEffect(type, ticks, amplifier, false, true));
    }
}
