/**
 * Component boss-runtime v1 (the bosses + encounters hub, next to the item Designer). Owns every live boss, minion and
 * encounter and drops all of it on disable. ONE shared AI timer (every 10 ticks) runs every boss: leash to the arena,
 * participants (players in survival / adventure inside the arena), boss bar viewers, target, phase (one way, by health
 * fraction), time out / enrage, empty-arena despawn and the next attack (weighted pick with the seeded Random among the
 * phase's attacks that are off cooldown and have a target; telegraph, then the generated actions with a fresh Budget).
 * Caps: 4 live bosses, 48 minions, 2 encounters (24 mobs each) plugin-wide; per boss its maxAlive / minions.maxAlive.
 * Cleanup: bosses, minions and wave mobs are NOT persistent (never saved with a chunk: an unloaded fight ends), carry
 * <ns>:boss / <ns>:minion / <ns>:enc tags (+ scoreboard tags <ns>.boss etc.), and leftovers (a crash) are removed when
 * their chunk loads and on enable. Loot is only what the design drops: base-mob drops, equipment and minion / wave-mob
 * drops are cleared. Our mobs never hurt, target or burn each other, never break blocks, never convert (drowned /
 * zombified) and never burn in daylight. Config: bosses.* and encounters.* reset on a config_version bump (like
 * items.* / menus.* / quests.*); general.* is never touched.
 */
public final class Bosses implements Listener {
    public static final int MAX_LIVE = 4;
    public static final int MAX_MINIONS = 48;
    public static final int AI_PERIOD = 10;
    public static final int ENTER_TARGETS = 8;
    private final Designer d;
    private final JavaPlugin plugin;
    private final DesignConfig config;
    private final BossEffects effects;
    private final Encounters encounters;
    private final Map<String, BossDef> defs = new LinkedHashMap<>();
    private final List<BossInstance> live = new ArrayList<>();
    private final Map<UUID, BossInstance> byEntity = new HashMap<>();
    private final Map<UUID, BossInstance> minionOwner = new HashMap<>();
    private final Map<String, Long> lastSpawn = new HashMap<>();
    private final Map<String, Integer> counter = new HashMap<>();
    private final NamespacedKey bossKey;
    private final NamespacedKey minionKey;
    private final NamespacedKey projectileKey;
    private final NamespacedKey encKey;
    private final List<String> lastEvents = new ArrayList<>();
    private final int startVersion;
    private Random random = new Random(0L);
    private boolean registered;

    public Bosses(Designer d) {
        this.d = d;
        this.plugin = d.plugin();
        this.config = new DesignConfig(plugin);
        this.effects = new BossEffects(this);
        this.encounters = new Encounters(this);
        this.bossKey = new NamespacedKey(d.namespace(), "boss");
        this.minionKey = new NamespacedKey(d.namespace(), "minion");
        this.projectileKey = new NamespacedKey(d.namespace(), "boss_projectile");
        this.encKey = new NamespacedKey(d.namespace(), "enc");
        this.startVersion = fileVersion();
    }

    /** Wire the hub: definitions, leftovers sweep, config, listener, the boss / encounter subcommands (wrapping the existing executor). */
    public void enable(PluginCommand command, List<BossDef> bossList, List<EncounterDef> encounterList, boolean others) {
        for (BossDef b : bossList) defs.put(b.id(), b);
        encounters.register(encounterList);
        List<String> out = new ArrayList<>();
        load(startVersion, out);
        if (!registered) { plugin.getServer().getPluginManager().registerEvents(this, plugin); registered = true; }
        int swept = 0;
        for (World w : Bukkit.getWorlds()) for (LivingEntity e : w.getLivingEntities()) if (ours(e)) { e.remove(); swept++; }
        if (swept > 0) plugin.getLogger().info("removed " + swept + " leftover boss / minion / wave mobs from an earlier run");
        if (command != null) {
            BossCommand c = new BossCommand(this, command.getName(), command.getExecutor(), command.getTabCompleter(), others);
            command.setExecutor(c);
            command.setTabCompleter(c);
        }
    }

    /** Called after the Designer (and Gameplay) reloaded: bosses.* / encounters.* migration, parameters, the AI timer. */
    void load(int before, List<String> out) {
        FileConfiguration cfg = plugin.getConfig();
        Configuration defaults = cfg.getDefaults();
        int jar = defaults == null ? 1 : defaults.getInt("config_version", 1);
        if (before >= 0 && before < jar && defaults != null) {
            int n = 0;
            for (String key : defaults.getKeys(true)) {
                if (!(key.startsWith("bosses.") || key.startsWith("encounters.")) || defaults.isConfigurationSection(key)) continue;
                cfg.set(key, defaults.get(key));
                n++;
            }
            plugin.saveConfig();
            String m = "config.yml: " + n + " boss and encounter values updated to version " + jar;
            out.add(m);
            plugin.getLogger().info(m);
