        config.load();
        random = new Random(config.seed() + 7L);
        List<String> notes = new ArrayList<>();
        for (BossDef b : defs.values()) { b.load(config); b.normalize(notes); }
        encounters.load(config);
        for (String s : config.notes()) { out.add(s); plugin.getLogger().warning("config: " + s); }
        for (String s : notes) { out.add(s); plugin.getLogger().warning("config: " + s); }
