    boolean alive(BossInstance i) { return live.contains(i); }
    BossInstance instanceOf(Entity e) { return e == null ? null : byEntity.get(e.getUniqueId()); }

    // ---------------------------------------------------------------------------------------------- arena
    boolean inArena(BossInstance i, Location l) {
        if (l == null || l.getWorld() == null || !l.getWorld().equals(i.home.getWorld())) return false;
        return l.distanceSquared(i.home) <= i.def.radius * i.def.radius;
    }

    public List<Player> participants(BossInstance i) { return playersNear(i.home, i.def.radius); }

    List<Player> playersNear(Location home, double radius) {
        List<Player> out = new ArrayList<>();
        World w = home.getWorld();
        if (w == null) return out;
        double r2 = radius * radius;
        for (Player p : w.getPlayers()) {
            if (!p.isOnline() || p.isDead() || !p.isValid()) continue;
            if (p.getGameMode() != GameMode.SURVIVAL && p.getGameMode() != GameMode.ADVENTURE) continue;
            if (p.getLocation().distanceSquared(home) <= r2) out.add(p);
        }
        out.sort(Comparator.comparing(Player::getUniqueId));
        return out;
    }

    /** Targets of an attack: participants within range of the boss, ordered by the attack's mode, at most max. */
    List<LivingEntity> targets(BossInstance i, BossDef.Attack a, List<Player> ps) {
        List<LivingEntity> out = new ArrayList<>();
        if (a.select == BossDef.Select.SELF) return out;
        Location at = i.mob.getLocation();
        double r2 = a.range * a.range;
        for (Player p : ps) if (p.getWorld().equals(at.getWorld()) && p.getLocation().distanceSquared(at) <= r2) out.add(p);
        order(out, at, a.select);
        return out.size() > a.max ? new ArrayList<>(out.subList(0, a.max)) : out;
    }

    void order(List<LivingEntity> out, Location at, BossDef.Select select) {
        out.sort(Comparator.comparingDouble((LivingEntity e) -> e.getLocation().distanceSquared(at)).thenComparing(Entity::getUniqueId));
        if (select == BossDef.Select.FARTHEST) Collections.reverse(out);
        else if (select == BossDef.Select.RANDOM) Collections.shuffle(out, random);
