    }

    private void complete(Run r) {
        List<Player> ps = b.playersNear(r.home, r.def.radius);
        cleanup(r);
        List<String> notes = new ArrayList<>();
        DropTable t = r.def.rewards;
        int stacks = 0;
        String who;
        if (t.mode() == DropTable.Mode.GROUND) {
            for (ItemStack s : t.roll(b.random(), b.designer(), r.home, notes)) { r.home.getWorld().dropItemNaturally(r.home, s); stacks++; }
            if (t.xp() > 0) for (Player p : ps) p.giveExp(t.xp());
            who = "the ground";
        } else {
            List<Player> got = b.qualifying(r.damage, ps, t.minShare());
            for (Player p : got) {
                for (ItemStack s : t.roll(b.random(), b.designer(), r.home, notes)) { for (ItemStack left : p.getInventory().addItem(s).values()) p.getWorld().dropItemNaturally(p.getLocation(), left); stacks++; }
