        List<String> out = new ArrayList<>();
        long now = b.designer().now();
        for (Run r : runs) out.add("encounter " + r.key() + ": wave " + (r.wave + 1) + "/" + r.def.waves.size() + (r.spawned ? "" : " (starting)") + " alive " + alive(r) + " participants " + b.playersNear(r.home, r.def.radius).size() + " elapsed " + ((now - r.started) / 20) + "s");
        return out;
    }
}
