export const BOSSCOMMAND_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Random;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.World;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;

/**
 * Component boss-command v1: adds the boss and encounter subcommands to the mod command and hands everything else to the
 * command it wraps (the items' DesignCommand or the menus/quests GameplayCommand):
 *   /<mod> boss list | status | check                          (<ns>.boss.admin, operators)
 *   /<mod> boss spawn <id> [<world> <x> <y> <z> | spawn]       (<ns>.boss.admin; players default to where they stand)
 *   /<mod> boss despawn <id|all> | cast <id> <attack>          (<ns>.boss.admin; cast = one attack now, no telegraph:
 *                                                               participants, or the nearest other mob for testing)
 *   /<mod> encounter list | status | start <id> [...] | stop <id|all>   (<ns>.boss.admin)
 *   /<mod> reload and params include bosses + encounters.
 */
public final class BossCommand implements CommandExecutor, TabCompleter {
    private static final List<String> SUBS = List.of("boss", "encounter");
    private static final List<String> BSUBS = List.of("list", "status", "check", "spawn", "despawn", "cast");
    private static final List<String> ESUBS = List.of("list", "status", "start", "stop");
    private final Bosses b;
    private final String label;
    private final CommandExecutor next;
    private final TabCompleter nextTab;
    private final boolean others;

    BossCommand(Bosses b, String label, CommandExecutor next, TabCompleter nextTab, boolean others) { this.b = b; this.label = label; this.next = next; this.nextTab = nextTab; this.others = others; }

    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }

    private boolean allowed(CommandSender s, String node) {
        if (s.hasPermission(b.namespace() + "." + node)) return true;
        say(s, "You don't have permission for that.", NamedTextColor.RED);
        return false;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String used, String[] args) {
        String sub = args.length == 0 ? "" : args[0].toLowerCase(Locale.ROOT);
        switch (sub) {
            case "boss", "bosses" -> { boss(sender, args); return true; }
            case "encounter", "encounters" -> { encounter(sender, args); return true; }
            case "reload" -> {
                if (!sender.hasPermission(b.namespace() + ".reload")) { say(sender, "You don't have permission for that.", NamedTextColor.RED); return true; }
                int before = b.fileVersion();
                if (next != null && others) next.onCommand(sender, command, used, args);
                else b.designer().reload();
                List<String> notes = new ArrayList<>();
                b.load(before, notes);
                say(sender, b.plugin().getName() + " bosses and encounters reloaded" + (notes.isEmpty() ? "" : " (" + notes.size() + " note" + (notes.size() == 1 ? "" : "s") + ")"), NamedTextColor.GREEN);
                for (String n : notes) say(sender, "- " + n, NamedTextColor.YELLOW);
                return true;
            }
            case "params" -> {
                if (!allowed(sender, "command")) return true;
                String want = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : null;
                boolean mine = want != null && (b.def(want) != null || b.encounters().def(want) != null);
                if (others && next != null && !mine) next.onCommand(sender, command, used, args);
                List<String> out = new ArrayList<>();
                for (BossDef d : b.defs().values()) if (want == null || d.id().equals(want)) d.describe(out);
                for (EncounterDef e : b.encounters().defs().values()) if (want == null || e.id().equals(want)) e.describe(out);
                if (out.isEmpty() && (!others || mine)) say(sender, "No parameters.", NamedTextColor.GRAY);
                for (String line : out) say(sender, line, NamedTextColor.AQUA);
                return true;
            }
            case "" -> {
                if (others && next != null) next.onCommand(sender, command, used, args);
                say(sender, b.plugin().getName() + ": bosses " + (b.defs().isEmpty() ? "-" : String.join(", ", b.defs().keySet())) + "; encounters " + (b.encounters().defs().isEmpty() ? "-" : String.join(", ", b.encounters().defs().keySet())) + ". Use /" + label + " boss list, /" + label + " encounter list", NamedTextColor.GOLD);
                return true;
            }
            default -> {
                if (next != null) return next.onCommand(sender, command, used, args);
                say(sender, "Unknown subcommand. Use /" + label + " boss, encounter, params or reload.", NamedTextColor.RED);
                return true;
            }
        }
    }

    private Location where(CommandSender sender, String[] args, int at) {
        if (args.length > at && args[at].equalsIgnoreCase("spawn")) { World w = Bukkit.getWorlds().get(0); return w.getSpawnLocation(); }
        if (args.length >= at + 4) {
            World w = Bukkit.getWorld(args[at]);
            if (w == null) return null;
            try { return new Location(w, Double.parseDouble(args[at + 1]), Double.parseDouble(args[at + 2]), Double.parseDouble(args[at + 3])); }
            catch (NumberFormatException e) { return null; }
        }
        return sender instanceof Player p ? p.getLocation() : null;
