    private void boss(CommandSender sender, String[] args) {
        if (!allowed(sender, "boss.admin")) return;
        String a = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "";
        switch (a) {
            case "list" -> { for (BossDef d : b.defs().values()) say(sender, d.describeDef(), NamedTextColor.AQUA); if (b.defs().isEmpty()) say(sender, "No bosses.", NamedTextColor.GRAY); }
            case "status" -> {
                if (b.live().isEmpty()) say(sender, "No bosses alive.", NamedTextColor.GRAY);
                for (BossInstance i : new ArrayList<>(b.live())) say(sender, b.statusLine(i), NamedTextColor.AQUA);
                for (String s : b.lastEvents()) say(sender, "last: " + s, NamedTextColor.GRAY);
            }
            case "check" -> { for (String line : check()) say(sender, line, line.contains("FAIL") ? NamedTextColor.RED : NamedTextColor.AQUA); }
            case "spawn" -> {
                BossDef d = args.length >= 3 ? b.def(args[2].toLowerCase(Locale.ROOT)) : null;
                if (d == null) { say(sender, "Usage: /" + label + " boss spawn <id> [<world> <x> <y> <z> | spawn]", NamedTextColor.RED); return; }
                if (!d.command) { say(sender, d.id() + " is not spawned by command (it has a summon item or comes in an encounter).", NamedTextColor.RED); return; }
                Location at = where(sender, args, 3);
                if (at == null) { say(sender, "Usage from the console: /" + label + " boss spawn <id> <world> <x> <y> <z> | spawn", NamedTextColor.RED); return; }
                String err = b.spawn(d, at, null);
                if (err != null) say(sender, "Not spawned: " + err + ".", NamedTextColor.RED);
                else say(sender, "Spawned " + b.live().get(b.live().size() - 1).key() + " (" + d.entity() + ") at " + at.getWorld().getName() + " " + at.getBlockX() + " " + at.getBlockY() + " " + at.getBlockZ() + ": health " + BossDef.fmt(b.live().get(b.live().size() - 1).mob.getHealth()) + ", phase " + d.phases.get(0).id + ", arena " + BossDef.fmt(d.radius) + " blocks", NamedTextColor.GREEN);
            }
            case "despawn" -> {
                String id = args.length >= 3 ? args[2].toLowerCase(Locale.ROOT) : null;
                if (id == null) { say(sender, "Usage: /" + label + " boss despawn <id|all>", NamedTextColor.RED); return; }
                int n = 0;
                for (BossInstance i : new ArrayList<>(b.live())) if (id.equals("all") || i.def.id().equals(id)) { b.despawn(i, "command"); n++; }
                say(sender, "Despawned " + n + " boss" + (n == 1 ? "" : "es") + ".", NamedTextColor.GREEN);
            }
            case "cast" -> {
                BossInstance i = null;
                if (args.length >= 4) for (BossInstance x : b.live()) if (x.def.id().equals(args[2].toLowerCase(Locale.ROOT))) i = x;
                BossDef.Attack at = i == null ? null : i.def.attack(args[3].toLowerCase(Locale.ROOT));
                if (i == null || at == null) { say(sender, "Usage: /" + label + " boss cast <alive boss id> <attack id>", NamedTextColor.RED); return; }
                List<LivingEntity> ts = b.targets(i, at, b.participants(i));
                boolean test = false;
                if (ts.isEmpty() && at.select != BossDef.Select.SELF) {
                    test = true;
