                say(sender, "Cast " + at.id + " of " + i.key() + " on " + n + " target" + (n == 1 ? "" : "s") + (test ? " (test targets: no participant in range)" : "") + " (telegraph skipped)", NamedTextColor.GREEN);
            }
            default -> say(sender, "Usage: /" + label + " boss list | status | check | spawn <id> [...] | despawn <id|all> | cast <id> <attack>", NamedTextColor.RED);
        }
    }

    private void encounter(CommandSender sender, String[] args) {
        if (!allowed(sender, "boss.admin")) return;
        String a = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "";
        switch (a) {
            case "list" -> { for (EncounterDef e : b.encounters().defs().values()) say(sender, e.describeDef(), NamedTextColor.AQUA); if (b.encounters().defs().isEmpty()) say(sender, "No encounters.", NamedTextColor.GRAY); }
            case "status" -> {
                List<String> s = b.encounters().status();
                if (s.isEmpty()) say(sender, "No encounters running.", NamedTextColor.GRAY);
                for (String line : s) say(sender, line, NamedTextColor.AQUA);
                for (String line : b.lastEvents()) say(sender, "last: " + line, NamedTextColor.GRAY);
            }
            case "start" -> {
                EncounterDef e = args.length >= 3 ? b.encounters().def(args[2].toLowerCase(Locale.ROOT)) : null;
                if (e == null) { say(sender, "Usage: /" + label + " encounter start <id> [<world> <x> <y> <z> | spawn]", NamedTextColor.RED); return; }
                if (!e.command) { say(sender, e.id() + " is not started by command (it has a start item).", NamedTextColor.RED); return; }
                Location at = where(sender, args, 3);
                if (at == null) { say(sender, "Usage from the console: /" + label + " encounter start <id> <world> <x> <y> <z> | spawn", NamedTextColor.RED); return; }
                String err = b.encounters().start(e, at);
                say(sender, err == null ? "Started " + e.id() + " (" + e.waves.size() + " waves)." : "Not started: " + err + ".", err == null ? NamedTextColor.GREEN : NamedTextColor.RED);
            }
            case "stop" -> {
                String id = args.length >= 3 ? args[2].toLowerCase(Locale.ROOT) : null;
                if (id == null) { say(sender, "Usage: /" + label + " encounter stop <id|all>", NamedTextColor.RED); return; }
                int n = b.encounters().stop(id.equals("all") ? null : id, "command");
                say(sender, "Stopped; " + n + " mobs removed.", NamedTextColor.GREEN);
            }
            default -> say(sender, "Usage: /" + label + " encounter list | status | start <id> [...] | stop <id|all>", NamedTextColor.RED);
        }
    }

    /** Definitions + the random / scaling math on this server's JVM (the TS simulator prints the same samples). */
    private List<String> check() {
        List<String> out = new ArrayList<>();
        out.add("boss index: bosses=" + b.defs().size() + " encounters=" + b.encounters().defs().size() + " ai_period=" + Bosses.AI_PERIOD + " max_bosses=" + Bosses.MAX_LIVE + " max_minions=" + Bosses.MAX_MINIONS + " max_encounters=" + Encounters.MAX_LIVE + " max_encounter_mobs=" + Encounters.MAX_MOBS + " budget=" + Budget.ACTIONS + "/" + Budget.ENTITIES + "/" + Budget.PARTICLES + "/" + Budget.PROJECTILES + "/" + Budget.TASKS);
        for (BossDef d : b.defs().values()) {
            out.add("scale " + d.id() + ": health n1=" + BossDef.fmt(d.scaledHealth(1)) + " n4=" + BossDef.fmt(d.scaledHealth(4)) + " n8=" + BossDef.fmt(d.scaledHealth(8)) + " damage easy=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.EASY, 1, false)) + " normal=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.NORMAL, 1, false)) + " hard=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.HARD, 1, false)) + " normal_x4=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.NORMAL, 4, false)) + " enraged=" + BossDef.fmt(d.damageMultiplier(org.bukkit.Difficulty.NORMAL, 1, true)));
            Random r = new Random(1234L);
            StringBuilder s = new StringBuilder("drops " + d.id() + ":");
            for (int k = 0; k < 5; k++) { int[] c = d.drops.rollCounts(r); s.append(k == 0 ? " " : " | "); for (int j = 0; j < c.length; j++) s.append(j == 0 ? "" : ",").append(c[j]); }
            out.add(s.toString());
            for (BossDef.Phase ph : d.phases) {
                Random w = new Random(7L);
                int total = 0;
                for (int x : ph.weights) total += x;
                StringBuilder p = new StringBuilder("picks " + d.id() + "." + ph.id + ":");
                for (int k = 0; k < 12 && total > 0; k++) { int roll = w.nextInt(total); int pick = 0; for (int j = 0; j < ph.weights.size(); j++) { roll -= ph.weights.get(j); if (roll < 0) { pick = j; break; } } p.append(' ').append(pick); }
                out.add(p.toString());
            }
        }
        List<Integer> order = new ArrayList<>(List.of(0, 1, 2, 3, 4, 5));
        Collections.shuffle(order, new Random(42L));
        out.add("random target order (seed 42): " + order);
        return out;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String used, String[] args) {
        List<String> out = new ArrayList<>();
        String last = args.length == 0 ? "" : args[args.length - 1].toLowerCase(Locale.ROOT);
        if (args.length <= 1) {
            for (String s : SUBS) if (s.startsWith(last)) out.add(s);
            if (nextTab != null) for (String s : nextTab.onTabComplete(sender, command, used, args)) if (!out.contains(s)) out.add(s);
            return out;
        }
        String sub = args[0].toLowerCase(Locale.ROOT);
        if (sub.startsWith("boss") && args.length == 2) { for (String s : BSUBS) if (s.startsWith(last)) out.add(s); return out; }
        if (sub.startsWith("boss") && args.length == 3) { for (String s : b.defs().keySet()) if (s.startsWith(last)) out.add(s); return out; }
        if (sub.startsWith("encounter") && args.length == 2) { for (String s : ESUBS) if (s.startsWith(last)) out.add(s); return out; }
        if (sub.startsWith("encounter") && args.length == 3) { for (String s : b.encounters().defs().keySet()) if (s.startsWith(last)) out.add(s); return out; }
        return nextTab == null ? out : nextTab.onTabComplete(sender, command, used, args);
    }
}
`;

