// Cyrus R3 gameplay designers, part 3: the BOSS + ENCOUNTER code generator, used by the mod compiler
// (../gameplay/compile.ts compileMod) when a mod has boss or encounter designs. Every number and text of a boss /
// encounter (health, armor, thresholds, intervals, weights, cooldowns, telegraphs, ranges, damage, counts, chances,
// messages...) is a config.yml PARAMETER under bosses.<id>. / encounters.<id>. (each Param carries `ptr`, its place in
// the design, so ./params.ts edits the design without regenerating code); STRUCTURE (the base mob, which actions, target
// modes, immunities, particles, bar style, wave entries) is Java. Deterministic: same designs = same bytes.
import { addParam, colorExpr, jstr, loadLine, MATERIAL, bare, camel, JTYPE, type Param, type ParamKind, type ParamSink } from "../compile";
import { ENTITY_CLASS, isPerTarget, type BossAction, type BossCapName, type BossDesign, type Drops, type EncounterDesign, BOSS_CAPS } from "./spec";

export const BOSS_COMPILER_VERSION = "cyrus-boss-compile-1";
/** Optional-field defaults (docs "Cyrus boss and encounter designer"). */
export const BOSS_DEFAULTS = {
  knockbackVertical: 0.35, pullVertical: 0.25, leapVertical: 0.5, spread: 0.3, particleSpeed: 0.02, volume: 1, pitch: 1, amplifier: 0, projectileDamage: 0,
  cooldownTicks: 0, spawnCooldownSeconds: 0, maxAlive: 1, minionsMax: 0, healthPerPlayer: 0, damagePerPlayer: 0, maxPlayers: 8,
  difficultyEasy: 0.75, difficultyNormal: 1, difficultyHard: 1.25, minDamageShare: 0.1, xp: 0, weight: 1, waveDelaySeconds: 0,
} as const;
/** Base mobs that carry a weapon in vanilla (the vanilla random equipment is off: randomizeData false). */
export const DEFAULT_WEAPON: Record<string, string> = { skeleton: "bow", stray: "bow", bogged: "bow", pillager: "crossbow", vindicator: "iron_axe", piglin_brute: "golden_axe", wither_skeleton: "stone_sword" };
export const IMMUNE_CAUSES: Record<string, string[]> = {
  fire: ["FIRE", "FIRE_TICK", "LAVA", "HOT_FLOOR"], fall: ["FALL"], drowning: ["DROWNING"], projectile: ["PROJECTILE"], explosion: ["BLOCK_EXPLOSION", "ENTITY_EXPLOSION"],
  suffocation: ["SUFFOCATION", "CRAMMING"], freeze: ["FREEZE"], lightning: ["LIGHTNING"],
};
const SLOT_SETTER: Record<string, string> = { mainHand: "setItemInMainHand", offHand: "setItemInOffHand", helmet: "setHelmet", chestplate: "setChestplate", leggings: "setLeggings", boots: "setBoots" };

export type BossParam = Param & { ptr: (string | number)[] };
type Sink = ParamSink & { params: BossParam[] };
const cap = (c: BossCapName): [number, number] => [BOSS_CAPS[c][0], BOSS_CAPS[c][1]];
/** Add a parameter that lives at `ptr` in the design. */
function P(s: Sink, rel: string, kind: ParamKind, c: BossCapName | [number, number], value: number | string, label: string, role: string, ptr: (string | number)[]): BossParam {
  const p = addParam(s, rel, kind, Array.isArray(c) ? c : cap(c), value, label, role) as BossParam;
  p.ptr = ptr;
  return p;
}

// --------------------------------------------------------------------------------------------------- parameters
function actionParams(s: Sink, rel: string, list: BossAction[], what: string, ptr: (string | number)[]) {
  list.forEach((a, k) => {
    const r = `${rel}.a${k}`, at = [...ptr, k];
    switch (a.type) {
      case "damage": P(s, `${r}.amount`, "num", "damage", a.amount, `${what} damage (health points, before scaling)`, "damage", [...at, "amount"]); break;
      case "knockback": case "pull": case "leap": {
        const dv = a.type === "knockback" ? BOSS_DEFAULTS.knockbackVertical : a.type === "pull" ? BOSS_DEFAULTS.pullVertical : BOSS_DEFAULTS.leapVertical;
        P(s, `${r}.strength`, "num", "strength", a.strength, `${what} ${a.type} strength`, "strength", [...at, "strength"]);
        P(s, `${r}.vertical`, "num", "vertical", a.vertical ?? dv, `${what} ${a.type} lift`, "lift", [...at, "vertical"]); break;
      }
      case "potion_effect": case "self_effect":
        P(s, `${r}.duration_ticks`, "ticks", "potionTicks", a.durationTicks, `${what} ${a.effect} duration (ticks)`, "duration", [...at, "durationTicks"]);
        P(s, `${r}.amplifier`, "int", a.type === "self_effect" ? "selfAmplifier" : "amplifier", a.amplifier ?? BOSS_DEFAULTS.amplifier, `${what} ${a.effect} level - 1`, "level", [...at, "amplifier"]); break;
      case "launch_projectile":
        P(s, `${r}.speed`, "num", "projectileSpeed", a.speed, `${what} ${a.kind} speed`, "speed", [...at, "speed"]);
        P(s, `${r}.damage`, "num", "projectileDamage", a.damage ?? BOSS_DEFAULTS.projectileDamage, `${what} ${a.kind} extra damage on hit`, "damage", [...at, "damage"]); break;
      case "spawn_particles":
        P(s, `${r}.count`, "int", "particleCount", a.count, `${what} ${a.particle} particles`, "count", [...at, "count"]);
        P(s, `${r}.spread`, "num", "particleSpread", a.spread ?? BOSS_DEFAULTS.spread, `${what} ${a.particle} spread`, "other", [...at, "spread"]);
        P(s, `${r}.speed`, "num", "particleSpeed", a.speed ?? BOSS_DEFAULTS.particleSpeed, `${what} ${a.particle} speed`, "other", [...at, "speed"]); break;
      case "play_sound":
        P(s, `${r}.sound`, "sound", [0, 100], a.sound, `${what} sound key`, "sound", [...at, "sound"]);
        P(s, `${r}.volume`, "num", "volume", a.volume ?? BOSS_DEFAULTS.volume, `${what} sound volume`, "other", [...at, "volume"]);
        P(s, `${r}.pitch`, "num", "pitch", a.pitch ?? BOSS_DEFAULTS.pitch, `${what} sound pitch`, "other", [...at, "pitch"]); break;
      case "send_message": case "actionbar": P(s, `${r}.text`, "text", [0, 120], a.text, `${what} ${a.type === "actionbar" ? "actionbar" : "message"} text`, "text", [...at, "text"]); break;
      case "title":
        P(s, `${r}.title`, "text", [0, 40], a.title, `${what} title text`, "text", [...at, "title"]);
        if (a.subtitle !== undefined) P(s, `${r}.subtitle`, "text", [0, 60], a.subtitle, `${what} subtitle text`, "text", [...at, "subtitle"]); break;
      case "summon":
        P(s, `${r}.count`, "int", "summonCount", a.count, `${what} ${bare(a.entity)} minions`, "count", [...at, "count"]);
        if (a.health !== undefined) P(s, `${r}.health`, "num", "minionHealth", a.health, `${what} minion health`, "other", [...at, "health"]); break;
      case "heal_self": P(s, `${r}.amount`, "num", "heal", a.amount, `${what} self heal (health points)`, "heal", [...at, "amount"]); break;
      case "delayed":
        P(s, `${r}.delay_ticks`, "ticks", "delayTicks", a.delayTicks, `${what} delay (ticks)`, "duration", [...at, "delayTicks"]);
        actionParams(s, `${r}.n`, a.actions, what, [...at, "actions"]).length; break;
    }
  });
  return s.params;
}
function dropParams(s: Sink, rel: string, d: Drops | undefined, what: string, ptr: (string | number)[]) {
  if (!d) return;
  if (d.mode === "participants") P(s, `${rel}.min_damage_share`, "num", "damageShare", d.minDamageShare ?? BOSS_DEFAULTS.minDamageShare, `${what}: share of the damage a player needs for loot (0-0.5)`, "chance", [...ptr, "minDamageShare"]);
  P(s, `${rel}.xp`, "int", "xp", d.xp ?? BOSS_DEFAULTS.xp, `${what}: XP points`, "count", [...ptr, "xp"]);
  (d.items ?? []).forEach((x, i) => {
    P(s, `${rel}.d${i}.count`, "int", "dropCount", x.count, `${what}: ${bare(x.item)} count`, "count", [...ptr, "items", i, "count"]);
    P(s, `${rel}.d${i}.chance`, "num", "dropChance", x.chance, `${what}: ${bare(x.item)} chance (0-1)`, "chance", [...ptr, "items", i, "chance"]);
  });
}

export function bossParams(b: BossDesign): BossParam[] {
  const s: Sink = { params: [], base: `bosses.${b.id}.`, item: b.id };
  P(s, "name", "text", [0, 60], b.name.text, "boss name (name tag + boss bar)", "text", ["name", "text"]);
  P(s, "stats.health", "num", "health", b.stats.health, "max health (before player scaling)", "other", ["stats", "health"]);
  const st = b.stats;
  if (st.armor !== undefined) P(s, "stats.armor", "num", "armor", st.armor, "armor points", "other", ["stats", "armor"]);
  if (st.attackDamage !== undefined) P(s, "stats.attack_damage", "num", "attackDamage", st.attackDamage, "melee attack damage", "damage", ["stats", "attackDamage"]);
  if (st.speed !== undefined) P(s, "stats.speed", "num", "speed", st.speed, "movement speed", "speed", ["stats", "speed"]);
  if (st.knockbackResistance !== undefined) P(s, "stats.knockback_resistance", "num", "knockbackResistance", st.knockbackResistance, "knockback resistance (0-1)", "other", ["stats", "knockbackResistance"]);
  if (st.followRange !== undefined) P(s, "stats.follow_range", "num", "followRange", st.followRange, "follow range (blocks)", "range", ["stats", "followRange"]);
  P(s, "arena.radius", "num", "arenaRadius", b.arena.radius, "arena radius (blocks around the spawn point)", "range", ["arena", "radius"]);
  P(s, "arena.empty_despawn_seconds", "int", "emptyDespawnSeconds", b.arena.emptyDespawnSeconds, "despawn after the arena is empty this long (seconds)", "duration", ["arena", "emptyDespawnSeconds"]);
  if (b.arena.maxDurationSeconds !== undefined) P(s, "arena.max_duration_seconds", "int", "maxDurationSeconds", b.arena.maxDurationSeconds, `fight time limit (seconds, then ${b.arena.onTimeout ?? "despawn"})`, "duration", ["arena", "maxDurationSeconds"]);
  P(s, "spawn.cooldown_seconds", "int", "spawnCooldownSeconds", b.spawn?.cooldownSeconds ?? BOSS_DEFAULTS.spawnCooldownSeconds, "seconds between two spawns", "cooldown", ["spawn", "cooldownSeconds"]);
  P(s, "spawn.max_alive", "int", "maxAlive", b.spawn?.maxAlive ?? BOSS_DEFAULTS.maxAlive, "alive at once", "count", ["spawn", "maxAlive"]);
  b.phases.forEach((ph, i) => {
    const r = `phases.${ph.id}`, at = ["phases", i];
    if (ph.name !== undefined) P(s, `${r}.name`, "text", [0, 24], ph.name, `phase ${ph.id} name (boss bar)`, "text", [...at, "name"]);
    if (i > 0) P(s, `${r}.below`, "num", "below", ph.below, `phase ${ph.id} starts below this health fraction`, "other", [...at, "below"]);
    P(s, `${r}.interval_ticks`, "ticks", "intervalTicks", ph.intervalTicks, `phase ${ph.id} ticks between attacks`, "cooldown", [...at, "intervalTicks"]);
    ph.attacks.forEach((x, j) => P(s, `${r}.weights.${x.attack}`, "int", "weight", x.weight ?? BOSS_DEFAULTS.weight, `phase ${ph.id} weight of ${x.attack}`, "other", [...at, "attacks", j, "weight"]));
    (ph.selfEffects ?? []).forEach((e, j) => P(s, `${r}.effects.${e.effect}`, "int", "selfAmplifier", e.amplifier ?? BOSS_DEFAULTS.amplifier, `phase ${ph.id} ${e.effect} level - 1`, "level", [...at, "selfEffects", j, "amplifier"]));
    if (ph.onEnter) actionParams(s, `${r}.enter`, ph.onEnter, `phase ${ph.id} start:`, [...at, "onEnter"]);
  });
  b.attacks.forEach((a, i) => {
    const r = `attacks.${a.id}`, at = ["attacks", i];
    if (a.name !== undefined) P(s, `${r}.name`, "text", [0, 32], a.name, `attack ${a.id} name`, "text", [...at, "name"]);
    P(s, `${r}.cooldown_ticks`, "ticks", "cooldownTicks", a.cooldownTicks ?? BOSS_DEFAULTS.cooldownTicks, `attack ${a.id} cooldown (ticks)`, "cooldown", [...at, "cooldownTicks"]);
    if (a.telegraph) {
      P(s, `${r}.telegraph.ticks`, "ticks", "telegraphTicks", a.telegraph.ticks, `attack ${a.id} warning time (ticks)`, "duration", [...at, "telegraph", "ticks"]);
      if (a.telegraph.text !== undefined) P(s, `${r}.telegraph.text`, "text", [0, 60], a.telegraph.text, `attack ${a.id} warning text`, "text", [...at, "telegraph", "text"]);
      if (a.telegraph.sound !== undefined) P(s, `${r}.telegraph.sound`, "sound", [0, 100], a.telegraph.sound, `attack ${a.id} warning sound`, "sound", [...at, "telegraph", "sound"]);
    }
    if (a.targets.select !== "self") {
      P(s, `${r}.targets.max`, "int", "targetMax", a.targets.max, `attack ${a.id} max targets`, "count", [...at, "targets", "max"]);
      P(s, `${r}.targets.range`, "num", "targetRange", a.targets.range, `attack ${a.id} range (blocks from the boss)`, "range", [...at, "targets", "range"]);
    }
    actionParams(s, r, a.actions, `attack ${a.id}`, [...at, "actions"]);
  });
  if (b.minions) P(s, "minions.max_alive", "int", "minionsMax", b.minions.maxAlive, "minions alive at once", "count", ["minions", "maxAlive"]);
  P(s, "scaling.health_per_player", "num", "healthPerPlayer", b.scaling?.healthPerPlayer ?? BOSS_DEFAULTS.healthPerPlayer, "extra health per extra player at spawn (fraction)", "other", ["scaling", "healthPerPlayer"]);
  P(s, "scaling.damage_per_player", "num", "damagePerPlayer", b.scaling?.damagePerPlayer ?? BOSS_DEFAULTS.damagePerPlayer, "extra attack damage per extra player (fraction)", "damage", ["scaling", "damagePerPlayer"]);
  P(s, "scaling.max_players", "int", "maxPlayers", b.scaling?.maxPlayers ?? BOSS_DEFAULTS.maxPlayers, "players counted for scaling", "count", ["scaling", "maxPlayers"]);
  P(s, "difficulty.easy", "num", "difficulty", b.difficulty?.easy ?? BOSS_DEFAULTS.difficultyEasy, "attack damage x on easy", "damage", ["difficulty", "easy"]);
  P(s, "difficulty.normal", "num", "difficulty", b.difficulty?.normal ?? BOSS_DEFAULTS.difficultyNormal, "attack damage x on normal", "damage", ["difficulty", "normal"]);
  P(s, "difficulty.hard", "num", "difficulty", b.difficulty?.hard ?? BOSS_DEFAULTS.difficultyHard, "attack damage x on hard", "damage", ["difficulty", "hard"]);
  dropParams(s, "drops", b.drops, "drops", ["drops"]);
  for (const k of ["spawn", "defeat", "despawn", "enrage"] as const) if (b.messages?.[k] !== undefined) P(s, `messages.${k}`, "text", [0, 120], b.messages[k]!, `${k} message`, "text", ["messages", k]);
  return s.params.map((p) => ({ ...p, owner: "boss" as never }));
}

export function encounterParams(e: EncounterDesign): BossParam[] {
  const s: Sink = { params: [], base: `encounters.${e.id}.`, item: e.id };
  P(s, "title", "text", [0, 40], e.title, "encounter title (boss bar)", "text", ["title"]);
  P(s, "arena.radius", "num", "arenaRadius", e.arena.radius, "arena radius (blocks)", "range", ["arena", "radius"]);
  P(s, "start.cooldown_seconds", "int", "spawnCooldownSeconds", e.start?.cooldownSeconds ?? BOSS_DEFAULTS.spawnCooldownSeconds, "seconds between two starts", "cooldown", ["start", "cooldownSeconds"]);
  P(s, "max_alive", "int", "encounterMaxAlive", e.maxAlive, "mobs alive at once", "count", ["maxAlive"]);
  P(s, "failure.empty_seconds", "int", "emptyDespawnSeconds", e.failure.emptySeconds, "fails after the arena is empty this long (seconds)", "duration", ["failure", "emptySeconds"]);
  if (e.failure.timeLimitSeconds !== undefined) P(s, "failure.time_limit_seconds", "int", "encounterTimeLimit", e.failure.timeLimitSeconds, "time limit (seconds)", "duration", ["failure", "timeLimitSeconds"]);
  e.waves.forEach((w, i) => {
    const r = `waves.w${i}`, at = ["waves", i];
    P(s, `${r}.delay_seconds`, "int", "waveDelaySeconds", w.delaySeconds ?? BOSS_DEFAULTS.waveDelaySeconds, `wave ${i + 1} delay before it starts (seconds)`, "duration", [...at, "delaySeconds"]);
    if (w.seconds !== undefined) P(s, `${r}.seconds`, "int", "waveSeconds", w.seconds, w.advance === "timer" ? `wave ${i + 1} seconds until the next wave` : `wave ${i + 1} time limit (seconds)`, "duration", [...at, "seconds"]);
    if (w.message !== undefined) P(s, `${r}.message`, "text", [0, 120], w.message, `wave ${i + 1} message`, "text", [...at, "message"]);
    w.spawns.forEach((sp, j) => { if (sp.entity) P(s, `${r}.s${j}.count`, "int", "waveCount", sp.count, `wave ${i + 1} ${bare(sp.entity)} count`, "count", [...at, "spawns", j, "count"]); });
  });
  dropParams(s, "rewards", e.rewards, "rewards", ["rewards"]);
  for (const k of ["start", "complete", "fail"] as const) if (e.messages?.[k] !== undefined) P(s, `messages.${k}`, "text", [0, 120], e.messages[k]!, `${k} message`, "text", ["messages", k]);
  return s.params.map((p) => ({ ...p, owner: "encounter" as never }));
}

// ---------------------------------------------------------------------------------------------------- Java codegen
type Gen = { params: Map<string, BossParam>; ns: string; out: string[] };
const F = (g: Gen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
const has = (g: Gen, rel: string) => g.params.has(rel);
const ind = (n: number) => "    ".repeat(n);
const DEFAULT_TEXT_COLOR = "NamedTextColor.YELLOW";

function emitActions(g: Gen, list: BossAction[], rel: string, depth: number): void {
  const o = g.out, I = ind(depth);
  list.forEach((a, k) => {
    const r = `${rel}.a${k}`;
    const p = (f: string) => F(g, `${r}.${f}`);
    o.push(`${I}// ${r.replace(/^.*?\.(a\d)/, "$1")}: ${a.type}`);
    const per = isPerTarget(a);
    const color = "color" in a && a.color ? colorExpr(a.color) : DEFAULT_TEXT_COLOR;
    let call: string;
    switch (a.type) {
      case "damage": call = `fx.damage(c.at(t), t, ${p("amount")});`; break;
      case "knockback": call = `fx.knockback(c.at(t), t, ${p("strength")}, ${p("vertical")});`; break;
      case "pull": call = `fx.pull(c.at(t), t, ${p("strength")}, ${p("vertical")});`; break;
      case "potion_effect": call = `fx.potion(c.at(t), t, PotionEffectType.${a.effect.toUpperCase()}, (int) ${p("duration_ticks")}, ${p("amplifier")});`; break;
      case "launch_projectile": call = `fx.launch(c.at(t), t, ${jstr(a.kind)}, ${p("speed")}, ${p("damage")});`; break;
      case "spawn_particles": call = `fx.particles(c, ${per ? "fx.at(t)" : "fx.at(c)"}, Particle.${a.particle.toUpperCase()}, ${p("count")}, ${p("spread")}, ${p("speed")});`; break;
      case "play_sound": call = `fx.sound(c, ${per ? "fx.at(t)" : "fx.at(c)"}, ${p("sound")}, (float) ${p("volume")}, (float) ${p("pitch")});`; break;
      case "send_message": call = per ? `fx.message(c, t, ${p("text")}, ${color});` : `fx.arenaMessage(c, ${p("text")}, ${color});`; break;
      case "actionbar": call = per ? `fx.actionbar(c, t, ${p("text")}, ${color});` : `fx.arenaActionbar(c, ${p("text")}, ${color});`; break;
      case "title": { const sub = has(g, `${r}.subtitle`) ? p("subtitle") : "null"; call = per ? `fx.title(c, t, ${p("title")}, ${sub}, ${color});` : `fx.arenaTitle(c, ${p("title")}, ${sub}, ${color});`; break; }
      case "leap": call = `fx.leap(c, ${p("strength")}, ${p("vertical")});`; break;
      case "summon": { const cls = ENTITY_CLASS[bare(a.entity)]; const w = DEFAULT_WEAPON[bare(a.entity)]; call = `fx.summon(c, ${cls}.class, ${w ? MATERIAL(w) : "null"}, ${p("count")}, ${has(g, `${r}.health`) ? p("health") : "-1.0"});`; break; }
      case "heal_self": call = `fx.healSelf(c, ${p("amount")});`; break;
      case "self_effect": call = `fx.selfEffect(c, PotionEffectType.${a.effect.toUpperCase()}, (int) ${p("duration_ticks")}, ${p("amplifier")});`; break;
      case "delayed":
        o.push(`${I}if (!c.budget().action()) return;`);
        o.push(`${I}c.later(${p("delay_ticks")}, () -> {`);
        emitActions(g, a.actions, `${r}.n`, depth + 1);
        o.push(`${I}});`);
        return;
    }
    if (per) o.push(`${I}for (LivingEntity t : c.targets()) { if (!c.budget().action()) return; ${call} }`);
    else o.push(`${I}if (!c.budget().action()) return;`, `${I}${call}`);
  });
}

const header = (pkg: string, sub: string, extra: string[]) => [
  `package ${pkg}.${sub};`, ``,
  `import java.util.List;`, `import java.util.function.Consumer;`,
  `import net.kyori.adventure.bossbar.BossBar;`, `import net.kyori.adventure.text.format.NamedTextColor;`, `import net.kyori.adventure.text.format.TextColor;`,
  `import org.bukkit.Location;`, `import org.bukkit.Material;`, `import org.bukkit.Particle;`, `import org.bukkit.entity.*;`, `import org.bukkit.event.entity.EntityDamageEvent;`,
  `import org.bukkit.inventory.EntityEquipment;`, `import org.bukkit.potion.PotionEffectType;`,
  ...extra.map((e) => `import ${pkg}.designer.${e};`), ``,
];

function dropLines(g: Gen, rel: string, d: Drops | undefined, table: string, ns: string): string[] {
  const out = [`${table}.clear();`];
  if (!d) return out;
  out.push(`${table}.mode(DropTable.Mode.${d.mode === "ground" ? "GROUND" : "PARTICIPANTS"});`);
  if (has(g, `${rel}.min_damage_share`)) out.push(`${table}.minShare(${F(g, `${rel}.min_damage_share`)});`);
  out.push(`${table}.xp(${F(g, `${rel}.xp`)});`);
  (d.items ?? []).forEach((x, i) => out.push(x.item.startsWith("minecraft:") ? `${table}.item(${MATERIAL(x.item)}, ${F(g, `${rel}.d${i}.count`)}, ${F(g, `${rel}.d${i}.chance`)});` : `${table}.design(${jstr(x.item)}, ${F(g, `${rel}.d${i}.count`)}, ${F(g, `${rel}.d${i}.chance`)});`));
  if (d.lootTable) { const [lns, path] = d.lootTable.split(":"); void ns; out.push(`${table}.lootTable(${jstr(lns)}, ${jstr(path)});`); }
  return out;
}

export function bossClass(pkg: string, b: BossDesign, cls: string, ns: string): { source: string; params: BossParam[] } {
  const params = bossParams(b);
  const base = `bosses.${b.id}.`;
  const g: Gen = { params: new Map(params.map((p) => [p.path.slice(base.length), p])), ns, out: [] };
  const entity = bare(b.entity);
  const ecls = ENTITY_CLASS[entity];
  const bar = b.bossBar ?? {};
  const ctor: string[] = [
    `super(b, ${jstr(b.id)}, ${jstr(entity)});`,
    `command = ${b.spawn?.command !== false};`,
    ...(b.spawn?.item ? [`summonItem = ${jstr(b.spawn.item)};`] : []),
    ...(b.arena.onTimeout === "enrage" ? [`enrageOnTimeout = true;`] : []),
    `barColor = BossBar.Color.${(bar.color ?? "red").toUpperCase()};`,
    `barOverlay = BossBar.Overlay.${(bar.overlay ?? "progress").toUpperCase()};`,
    ...(bar.showPhase ? [`showPhase = true;`] : []),
    ...(bar.darkenSky ? [`darkenSky = true;`] : []),
    ...(b.name.color ? [`nameColor = ${colorExpr(b.name.color)};`] : []),
    ...[...new Set((b.immune ?? []).flatMap((x) => IMMUNE_CAUSES[x]))].sort().map((c) => `immune.add(EntityDamageEvent.DamageCause.${c});`),
  ];
  b.attacks.forEach((a, i) => {
    ctor.push(`Attack a${i} = attack(${jstr(a.id)}, Select.${a.targets.select.toUpperCase()});`);
    if (a.telegraph?.particle) ctor.push(`a${i}.telegraphParticle = Particle.${a.telegraph.particle.toUpperCase()};`);
  });
  b.phases.forEach((ph, i) => {
    ctor.push(`Phase p${i} = phase(${jstr(ph.id)});`);
    for (const x of ph.attacks) ctor.push(`p${i}.attacks.add(${jstr(x.attack)});`);
    for (const e of ph.selfEffects ?? []) ctor.push(`p${i}.effects.add(PotionEffectType.${e.effect.toUpperCase()});`);
  });
  const load: string[] = params.map((p) => loadLine(p, p.path.slice(base.length)));
  const st = b.stats;
  load.push(`name = p_name;`, `health = p_stats_health;`);
  if (st.armor !== undefined) load.push(`armor = p_stats_armor;`);
  if (st.attackDamage !== undefined) load.push(`attackDamage = p_stats_attack_damage;`);
  if (st.speed !== undefined) load.push(`speed = p_stats_speed;`);
  if (st.knockbackResistance !== undefined) load.push(`knockbackResistance = p_stats_knockback_resistance;`);
  if (st.followRange !== undefined) load.push(`followRange = p_stats_follow_range;`);
  load.push(`radius = p_arena_radius;`, `emptyTicks = p_arena_empty_despawn_seconds * 20L;`);
  if (b.arena.maxDurationSeconds !== undefined) load.push(`maxTicks = p_arena_max_duration_seconds * 20L;`);
  load.push(`spawnCooldownTicks = p_spawn_cooldown_seconds * 20L;`, `maxAlive = p_spawn_max_alive;`);
  if (b.minions) load.push(`minionsMax = p_minions_max_alive;`);
  load.push(`healthPerPlayer = p_scaling_health_per_player;`, `damagePerPlayer = p_scaling_damage_per_player;`, `maxPlayers = p_scaling_max_players;`);
  load.push(`difficultyEasy = p_difficulty_easy;`, `difficultyNormal = p_difficulty_normal;`, `difficultyHard = p_difficulty_hard;`);
  b.attacks.forEach((a, i) => {
    const r = `attacks.${a.id}`;
    load.push(`attacks.get(${i}).cooldown = ${F(g, `${r}.cooldown_ticks`)};`);
    if (has(g, `${r}.name`)) load.push(`attacks.get(${i}).name = ${F(g, `${r}.name`)};`);
    if (a.telegraph) load.push(`attacks.get(${i}).telegraph = ${F(g, `${r}.telegraph.ticks`)};`);
    if (has(g, `${r}.telegraph.text`)) load.push(`attacks.get(${i}).telegraphText = ${F(g, `${r}.telegraph.text`)};`);
    if (has(g, `${r}.telegraph.sound`)) load.push(`attacks.get(${i}).telegraphSound = ${F(g, `${r}.telegraph.sound`)};`);
    if (a.targets.select !== "self") load.push(`attacks.get(${i}).max = ${F(g, `${r}.targets.max`)};`, `attacks.get(${i}).range = ${F(g, `${r}.targets.range`)};`);
  });
  b.phases.forEach((ph, i) => {
    const r = `phases.${ph.id}`;
    load.push(`phases.get(${i}).interval = ${F(g, `${r}.interval_ticks`)};`);
    if (i > 0) load.push(`phases.get(${i}).below = ${F(g, `${r}.below`)};`);
    if (has(g, `${r}.name`)) load.push(`phases.get(${i}).name = ${F(g, `${r}.name`)};`);
    load.push(`phases.get(${i}).weights.clear();`, ...ph.attacks.map((x) => `phases.get(${i}).weights.add(${F(g, `${r}.weights.${x.attack}`)});`));
    if (ph.selfEffects?.length) load.push(`phases.get(${i}).amplifiers.clear();`, ...ph.selfEffects.map((e) => `phases.get(${i}).amplifiers.add(${F(g, `${r}.effects.${e.effect}`)});`));
  });
  load.push(...dropLines(g, "drops", b.drops, "drops", ns));
  for (const k of ["spawn", "defeat", "despawn", "enrage"] as const) if (has(g, `messages.${k}`)) load.push(`msg${k[0].toUpperCase()}${k.slice(1)} = ${F(g, `messages.${k}`)};`);
  const equip: string[] = [];
  const weapon = DEFAULT_WEAPON[entity];
  const eq = b.equipment ?? {};
  for (const slot of Object.keys(SLOT_SETTER)) {
    const ref = (eq as Record<string, string | undefined>)[slot] ?? (slot === "mainHand" && weapon ? `minecraft:${weapon}` : undefined);
    if (!ref) continue;
    equip.push(`eq.${SLOT_SETTER[slot]}(${ref.startsWith("minecraft:") ? `display(${MATERIAL(ref)})` : `display(${jstr(ref)})`});`);
  }
  // attacks + phase starts
  const bodies: string[] = [];
  b.attacks.forEach((a, i) => {
    g.out = [];
    emitActions(g, a.actions, `attacks.${a.id}`, 2);
    bodies.push(``, `    /** Attack ${a.id} (${a.targets.select}${a.targets.select === "self" ? "" : `, at most ${a.targets.max}`}). */`, `    private void attack${i}(BossCast c, BossEffects fx) {`, ...g.out, `    }`);
  });
  const enters: number[] = [];
  b.phases.forEach((ph, i) => {
    if (!ph.onEnter?.length) return;
    enters.push(i);
    g.out = [];
    emitActions(g, ph.onEnter, `phases.${ph.id}.enter`, 2);
    bodies.push(``, `    /** Phase ${ph.id} starts (targets: every participant, nearest first, at most 8). */`, `    private void enter${i}(BossCast c, BossEffects fx) {`, ...g.out, `    }`);
  });
  const src = [
    ...header(pkg, "bosses", ["BossCast", "BossDef", "BossEffects", "Bosses", "DesignConfig", "DropTable"]),
    `/** Boss "${b.name.text.replace(/\*\//g, "")}" (${ns}:${b.id}, ${entity}). Generated by Cyrus from assets/designs/${b.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
    `public final class ${cls} extends BossDef {`,
    `    private static final String B = ${jstr(base)};`,
    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
    ``,
    `    public ${cls}(Bosses b) {`,
    ...ctor.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    public Mob spawnBase(Location at, Consumer<Mob> init) {`,
    `        Consumer<${ecls}> c = init::accept;`,
    `        return at.getWorld().spawn(at, ${ecls}.class, false, c);`,
    `    }`,
    ``,
    `    @Override`,
    `    public void equip(Mob m) {`,
    ...(equip.length ? [`        EntityEquipment eq = m.getEquipment();`, `        if (eq == null) return;`, ...equip.map((l) => `        ${l}`)] : []),
    `    }`,
    ``,
    `    @Override`,
    `    public void load(DesignConfig c) {`,
    ...load.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    public void attack(int index, BossCast c) {`,
    `        BossEffects fx = c.bosses().effects();`,
    `        switch (index) {`,
    ...b.attacks.map((_, i) => `            case ${i} -> attack${i}(c, fx);`),
    `            default -> { }`,
    `        }`,
    `    }`,
    ``,
    `    @Override`,
    `    public void enter(int index, BossCast c) {`,
    ...(enters.length ? [`        BossEffects fx = c.bosses().effects();`, `        switch (index) {`, ...enters.map((i) => `            case ${i} -> enter${i}(c, fx);`), `            default -> { }`, `        }`] : []),
    `    }`,
    ...bodies,
    ``,
    `    @Override`,
    `    public void describe(List<String> out) {`,
    ...params.map((p) => `        out.add(B + ${jstr(p.path.slice(base.length))} + "=" + ${p.field});`),
    `    }`,
    `}`,
    ``,
  ];
  return { source: src.join("\n"), params };
}

export function encounterClass(pkg: string, e: EncounterDesign, cls: string, ns: string): { source: string; params: BossParam[] } {
  const params = encounterParams(e);
  const base = `encounters.${e.id}.`;
  const g: Gen = { params: new Map(params.map((p) => [p.path.slice(base.length), p])), ns, out: [] };
  const bar = e.bossBar ?? {};
  const ctor = [
    `super(b, ${jstr(e.id)});`,
    `command = ${e.start?.command !== false};`,
    ...(e.start?.item ? [`startItem = ${jstr(e.start.item)};`] : []),
    `barColor = BossBar.Color.${(bar.color ?? "purple").toUpperCase()};`,
    `barOverlay = BossBar.Overlay.${(bar.overlay ?? "progress").toUpperCase()};`,
    ...e.waves.map((w) => `wave(${w.advance === "cleared"});`),
  ];
  const load: string[] = params.map((p) => loadLine(p, p.path.slice(base.length)));
  load.push(`title = p_title;`, `radius = p_arena_radius;`, `cooldownTicks = p_start_cooldown_seconds * 20L;`, `maxAlive = p_max_alive;`, `emptyTicks = p_failure_empty_seconds * 20L;`);
  if (has(g, "failure.time_limit_seconds")) load.push(`timeLimitTicks = p_failure_time_limit_seconds * 20L;`);
  e.waves.forEach((w, i) => {
    const r = `waves.w${i}`;
    load.push(`waves.get(${i}).delayTicks = ${F(g, `${r}.delay_seconds`)} * 20L;`);
    if (has(g, `${r}.seconds`)) load.push(`waves.get(${i}).ticks = ${F(g, `${r}.seconds`)} * 20L;`);
    if (has(g, `${r}.message`)) load.push(`waves.get(${i}).message = ${F(g, `${r}.message`)};`);
    const size = w.spawns.map((sp, j) => (sp.entity ? F(g, `${r}.s${j}.count`) : "1")).join(" + ");
    load.push(`waves.get(${i}).size = ${size};`);
  });
  load.push(...dropLines(g, "rewards", e.rewards, "rewards", ns));
  for (const k of ["start", "complete", "fail"] as const) if (has(g, `messages.${k}`)) load.push(`msg${k[0].toUpperCase()}${k.slice(1)} = ${F(g, `messages.${k}`)};`);
  const waves: string[] = [];
  e.waves.forEach((w, i) => {
    const lines = w.spawns.map((sp, j) => {
      if (sp.boss) return `s.boss(${jstr(sp.boss)});`;
      const ent = bare(sp.entity!);
      const wpn = DEFAULT_WEAPON[ent];
      return `s.mob(${ENTITY_CLASS[ent]}.class, ${wpn ? MATERIAL(wpn) : "null"}, ${F(g, `waves.w${i}.s${j}.count`)});`;
    });
    waves.push(`            case ${i} -> {`, ...lines.map((l) => `                ${l}`), `            }`);
  });
  const src = [
    ...header(pkg, "encounters", ["Bosses", "DesignConfig", "DropTable", "EncounterDef"]),
    `/** Encounter "${e.title.replace(/\*\//g, "")}" (${ns}:${e.id}, ${e.waves.length} waves). Generated by Cyrus from assets/designs/${e.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
    `public final class ${cls} extends EncounterDef {`,
    `    private static final String B = ${jstr(base)};`,
    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
    ``,
    `    public ${cls}(Bosses b) {`,
    ...ctor.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    public void load(DesignConfig c) {`,
    ...load.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    public void spawnWave(int index, Spawner s) {`,
    `        switch (index) {`,
    ...waves,
    `            default -> { }`,
    `        }`,
    `    }`,
    ``,
    `    @Override`,
    `    public void describe(List<String> out) {`,
    ...params.map((p) => `        out.add(B + ${jstr(p.path.slice(base.length))} + "=" + ${p.field});`),
    `    }`,
    `}`,
