    ...(hooks ? [`        ${pkg}.custom.CustomHooks.disable();`] : []),
    ...(ms ? [`        if (modelStates != null) modelStates.stop();`, `        modelStates = null;`] : []),
    `        if (bosses != null) bosses.disable();`,
    ...(gp ? [`        if (gameplay != null) gameplay.disable();`] : []),
    `        if (designer != null) designer.disable();`,
    `        bosses = null;`,
    ...(gp ? [`        gameplay = null;`] : []),
    `        designer = null;`,
    `    }`,
    `}`,
    ``,
  ].join("\\n");
}

function bossNotes(bosses: BossDesign[], encounters: EncounterDesign[], ns: string): string[] {
  const out: string[] = [];
  if (bosses.length) out.push(`Bosses fight players in survival or adventure inside their arena; the boss bar shows to them only. A boss leaves (no loot) when its arena is empty for a while, and is pulled back when it walks out of the arena. Operators can select bosses with the tag ${ns}.boss (e.g. /kill @e[tag=${ns}.boss]).`);
  if (bosses.length || encounters.length) out.push("Bosses, minions and wave mobs are never saved with the world: when their chunk unloads or the server stops, the fight ends and they are removed. They drop only what the design says (no vanilla loot, no equipment), never break blocks and never burn in daylight.");
  if (bosses.some((b) => b.drops?.mode === "participants") || encounters.some((e) => e.rewards?.mode === "participants")) out.push("Loot goes straight into the inventory of every player who did enough of the damage (overflow drops at their feet); killing a boss with commands drops nothing.");
  if (bosses.some((b) => b.scaling && ((b.scaling.healthPerPlayer ?? 0) > 0 || (b.scaling.damagePerPlayer ?? 0) > 0))) out.push("Player scaling counts the players in the arena: health when the boss spawns, attack damage at every attack.");
  if (bosses.some((b) => ["iron_golem", "polar_bear", "hoglin"].includes(b.entity.replace(/^minecraft:/, "")))) out.push("Neutral base mobs (iron golem, polar bear, hoglin) attack only the target the boss gives them (the nearest participant).");
  out.push("Peaceful difficulty removes hostile mobs, so bosses and encounters do not start on peaceful.");
  return out;
}

// --------------------------------------------------------------------------------------------- resources + README''')
open(p,'w').write(s)
EOF

