// Prints the golden compile record of the menu/quest showcase mod (test/fixtures/cyrus-gameplay) for every registry version
// the designer supports: `npx tsx scripts/cyrus/gameplay-golden.ts > test/fixtures/cyrus-gameplay/golden.json`
// (review the diff: a changed hash means changed generated code). `--errors` prints the compile errors instead.
import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { compileMod } from "../../lib/cyrus/designer/gameplay/compile";
import { designFeatures } from "../../lib/cyrus/designer/spec";
import { VERSIONS } from "../../lib/cyrus/versions/registry";

const FX = path.join(__dirname, "../../test/fixtures/cyrus-gameplay");
export const GAMEPLAY_FIXTURES = ["guild_badge", "guild_charm", "shop", "elder", "trial_one", "trial_two", "trial_three", "daily_bread"];
export const loadGameplayFixtures = () => GAMEPLAY_FIXTURES.map((n) => JSON.parse(readFileSync(path.join(FX, `${n}.json`), "utf8")));
export const GP_NS = "nx_r11guild";
export const GP_PLUGIN = "GuildQuests";

if (require.main === module && process.argv.includes("--print")) {
  // review aid: print generated files (by path suffix) or README of the 1.21.11 compile
  const r = compileMod(loadGameplayFixtures(), { version: "1.21.11", namespace: GP_NS, pluginName: GP_PLUGIN });
  if (!r.ok) { console.error(r.errors); process.exit(1); }
  for (const want of process.argv.slice(process.argv.indexOf("--print") + 1)) console.log(`===== ${want}\n${want === "README" ? r.readme : r.files.find((x) => x.path.endsWith(want))?.content}`);
} else if (require.main === module) {
  void readdirSync;
  const out: Record<string, unknown> = {};
  for (const v of VERSIONS.map((x) => x.id).filter((x) => designFeatures(x).ok)) {
    const r = compileMod(loadGameplayFixtures(), { version: v, namespace: GP_NS, pluginName: GP_PLUGIN });
    if (!r.ok) { console.error(v, JSON.stringify(r.errors, null, 1)); process.exit(1); }
    if (process.argv.includes("--warnings")) console.error(v, r.warnings.map((w) => `${w.code} ${w.path}`).join("\n"));
    out[v] = { hash: r.hash, readme: r.readmeSha256, files: Object.fromEntries(r.files.map((f) => [f.path.replace(/^src\/main\/java\/dev\/nxeon\/plugins\/guildquests\//, ""), f.sha256])) };
  }
  console.log(JSON.stringify(out, null, 1));
}

