// Cyrus R3 gameplay designers, part 3: the TS REFERENCE SIMULATOR of the boss + encounter runtime (./java.ts). It runs
// a boss against scripted participants and damage on the same AI clock (every 10 ticks) with the same rules as the Java
// hub: participants = players inside the arena, empty-arena despawn, time out / enrage, one-way phases by health
// fraction, the weighted attack pick (java.util.Random nextInt over the summed weights, among attacks off cooldown with a
// target), target ordering (nearest / farthest / random = Collections.shuffle), the per-attack Budget, minion caps and
// the drop rolls (one nextDouble per entry). Also the twin of `/<mod> boss check` (bossCheckLines) that the real-server
// flight compares line by line. A reference model, not the game: movement, vanilla AI melee, collisions, armor and
// protection plugins are not simulated (damage is logged as dealt before armor).
import { BUDGET } from "../spec";
import { randomSeedFor } from "../compile";
import { BOSS_DEFAULTS } from "./compile";
import { BOSS_LIMITS, isPerTarget, type Attack, type BossAction, type BossDesign, type Drops, type EncounterDesign } from "./spec";

// ---------------------------------------------------------------------------------------- java.util.Random port
const MASK = (1n << 48n) - 1n;
export class JRandom {
  private seed: bigint;
  constructor(seed: number | bigint) { this.seed = (BigInt(seed) ^ 0x5deece66dn) & MASK; }
  private next(bits: number): number {
    this.seed = (this.seed * 0x5deece66dn + 0xbn) & MASK;
    const r = Number(this.seed >> BigInt(48 - bits));
    return bits === 32 ? r | 0 : r;
  }
  nextDouble(): number { return (this.next(26) * 2 ** 27 + this.next(27)) * 2 ** -53; }
  /** java.util.Random.nextInt(bound) (the legacy algorithm, unchanged since Java 1.2). */
  nextInt(bound: number): number {
    if (!(bound > 0)) throw new Error("bound must be positive");
    let r = this.next(31);
    const m = bound - 1;
    if ((bound & m) === 0) return Number((BigInt(bound) * BigInt(r)) >> 31n);
    for (let u = r; u - (r = u % bound) + m > 0x7fffffff || (u - r + m) | 0) {
      // Java: for (int u = r; u - (r = u % bound) + m < 0; u = next(31)); (int overflow test)
      if (((u - r + m) | 0) >= 0) break;
      u = this.next(31);
    }
    return r;
  }
}
/** Collections.shuffle(list, rnd) for a RandomAccess list. */
export function javaShuffle<T>(list: T[], rnd: JRandom): T[] {
  for (let i = list.length; i > 1; i--) { const j = rnd.nextInt(i); const t = list[i - 1]; list[i - 1] = list[j]; list[j] = t; }
  return list;
}
const fmt = (v: number) => (Math.round(v * 100) / 100).toFixed(2);

// ---------------------------------------------------------------------------------------------- shared math
export type Difficulty = "easy" | "normal" | "hard";
export function scaledHealth(b: BossDesign, players: number): number {
  const maxP = b.scaling?.maxPlayers ?? BOSS_DEFAULTS.maxPlayers;
  const n = Math.max(1, Math.min(maxP, players));
  return Math.max(1, Math.min(1024, b.stats.health * (1 + (b.scaling?.healthPerPlayer ?? BOSS_DEFAULTS.healthPerPlayer) * (n - 1))));
}
export function damageMultiplier(b: BossDesign, d: Difficulty, players: number, enraged: boolean): number {
  const base = d === "hard" ? b.difficulty?.hard ?? BOSS_DEFAULTS.difficultyHard : d === "normal" ? b.difficulty?.normal ?? BOSS_DEFAULTS.difficultyNormal : b.difficulty?.easy ?? BOSS_DEFAULTS.difficultyEasy;
  const n = Math.max(1, Math.min(b.scaling?.maxPlayers ?? BOSS_DEFAULTS.maxPlayers, players));
  return base * (1 + (b.scaling?.damagePerPlayer ?? BOSS_DEFAULTS.damagePerPlayer) * (n - 1)) * (enraged ? 1.5 : 1);
}
/** One roll set of a drop table (counts per item entry, in design order). */
export function rollCounts(d: Drops | undefined, r: JRandom): number[] { return (d?.items ?? []).map((x) => (r.nextDouble() < x.chance ? x.count : 0)); }
export function weightedPick(weights: number[], r: JRandom): number {
  const total = weights.reduce((a, b) => a + b, 0);
  let roll = r.nextInt(total);
  for (let j = 0; j < weights.length; j++) { roll -= weights[j]; if (roll < 0) return j; }
  return 0;
}

/** The exact lines `/<mod> boss check` prints on the server (Java BossCommand.check), from the designs. */
export function bossCheckLines(bosses: BossDesign[], encounters: EncounterDesign[]): string[] {
  const out = [`boss index: bosses=${bosses.length} encounters=${encounters.length} ai_period=${BOSS_LIMITS.aiPeriodTicks} max_bosses=${BOSS_LIMITS.liveBosses} max_minions=${BOSS_LIMITS.liveMinions} max_encounters=${BOSS_LIMITS.liveEncounters} max_encounter_mobs=${BOSS_LIMITS.encounterMobs} budget=${BUDGET.actions}/${BUDGET.entities}/${BUDGET.particles}/${BUDGET.projectiles}/${BUDGET.tasks}`];
  for (const b of [...bosses].sort((x, y) => (x.id < y.id ? -1 : 1))) {
    out.push(`scale ${b.id}: health n1=${fmt(scaledHealth(b, 1))} n4=${fmt(scaledHealth(b, 4))} n8=${fmt(scaledHealth(b, 8))} damage easy=${fmt(damageMultiplier(b, "easy", 1, false))} normal=${fmt(damageMultiplier(b, "normal", 1, false))} hard=${fmt(damageMultiplier(b, "hard", 1, false))} normal_x4=${fmt(damageMultiplier(b, "normal", 4, false))} enraged=${fmt(damageMultiplier(b, "normal", 1, true))}`);
    const r = new JRandom(1234);
    out.push(`drops ${b.id}: ${Array.from({ length: 5 }, () => rollCounts(b.drops, r).join(",")).join(" | ")}`);
    for (const ph of b.phases) {
      const w = new JRandom(7);
      const weights = ph.attacks.map((x) => x.weight ?? BOSS_DEFAULTS.weight);
      out.push(`picks ${b.id}.${ph.id}: ${Array.from({ length: 12 }, () => weightedPick(weights, w)).join(" ")}`);
    }
  }
  out.push(`random target order (seed 42): [${javaShuffle([0, 1, 2, 3, 4, 5], new JRandom(42)).join(", ")}]`);
  return out;
}

// ---------------------------------------------------------------------------------------------- the fight model
export type SimPlayer = { id: string; pos: [number, number, number]; health: number; online?: boolean; mode?: "survival" | "adventure" | "creative" | "spectator"; world?: string };
export type FightEvent =
  | { t: number; kind: "damage"; by?: string; amount: number }
  | { t: number; kind: "move"; player: string; pos: [number, number, number] }
  | { t: number; kind: "join" | "leave"; player: string }
  | { t: number; kind: "heal"; amount: number };
export type FightLog = { t: number; kind: string; detail: string };
export type FightOptions = { seed?: number; namespace?: string; difficulty?: Difficulty; home?: [number, number, number]; telegraph?: boolean };

const dist2 = (a: [number, number, number], b: [number, number, number]) => (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2;

/** One boss fight on the 10-tick AI clock (the Java Bosses.tick order: validity, participants, empty, phase, time out, attack). */
export class BossFight {
  readonly log: FightLog[] = [];
  readonly players = new Map<string, SimPlayer>();
  readonly damageBy = new Map<string, number>();
  readonly minions: number[] = [];
  readonly drops: { player: string; counts: number[] }[] = [];
  t = 0;
  health: number;
  readonly max: number;
  phase = 0;
  enraged = false;
  alive = true;
  ended: "defeated" | "despawned" | null = null;
  private nextAttack: number;
  private emptySince = -1;
  private readonly ready = new Map<string, number>();
  private readonly random: JRandom;
  private readonly pending: { at: number; run: () => void }[] = [];
  readonly home: [number, number, number];
  readonly boss: [number, number, number];

  constructor(readonly b: BossDesign, players: SimPlayer[], readonly opts: FightOptions = {}) {
    for (const p of players) this.players.set(p.id, { online: true, mode: "survival", world: "world", ...p });
    this.home = opts.home ?? [0, 64, 0];
    this.boss = [...this.home];
    this.random = new JRandom((opts.seed ?? randomSeedFor(opts.namespace ?? "nx_00000000")) + 7);
    this.max = scaledHealth(b, Math.max(1, this.participants().length));
    this.health = this.max;
    this.nextAttack = b.phases[0].intervalTicks;
    this.note("spawn", `health ${fmt(this.max)} players ${Math.max(1, this.participants().length)}`);
  }

  private note(kind: string, detail: string) { this.log.push({ t: this.t, kind, detail }); }

  participants(): SimPlayer[] {
    const r2 = this.b.arena.radius ** 2;
    return [...this.players.values()].filter((p) => p.online && p.health > 0 && (p.mode === "survival" || p.mode === "adventure") && (p.world ?? "world") === "world" && dist2(p.pos, this.home) <= r2).sort((a, b) => (a.id < b.id ? -1 : 1));
  }

  targets(a: Attack, ps = this.participants()): SimPlayer[] {
    if (a.targets.select === "self") return [];
    const r2 = a.targets.range ** 2;
    const out = ps.filter((p) => dist2(p.pos, this.boss) <= r2).sort((x, y) => dist2(x.pos, this.boss) - dist2(y.pos, this.boss) || (x.id < y.id ? -1 : 1));
    if (a.targets.select === "farthest") out.reverse();
    else if (a.targets.select === "random") javaShuffle(out, this.random);
    return out.slice(0, a.targets.max);
  }

  /** Run the clock to tick `until`, applying the scripted events in order. */
  run(events: FightEvent[], until: number): this {
    const evs = [...events].sort((a, b) => a.t - b.t);
    let e = 0;
    for (let t = this.t; t <= until && !this.ended; t++) {
      this.t = t;
      while (e < evs.length && evs[e].t <= t) this.apply(evs[e++]);
      for (const p of this.pending.filter((x) => x.at === t)) p.run();
      this.pending.splice(0, this.pending.length, ...this.pending.filter((x) => x.at > t));
      if (t > 0 && t % BOSS_LIMITS.aiPeriodTicks === 0) this.tick();
    }
    return this;
  }

  private apply(ev: FightEvent) {
    if (ev.kind === "damage") {
      if (!this.alive) return;
      this.health = Math.max(0, this.health - ev.amount);
      if (ev.by) this.damageBy.set(ev.by, (this.damageBy.get(ev.by) ?? 0) + ev.amount);
      if (this.health <= 0) this.defeat();
    } else if (ev.kind === "heal") this.health = Math.min(this.max, this.health + ev.amount);
    else if (ev.kind === "move") { const p = this.players.get(ev.player); if (p) p.pos = ev.pos; }
    else { const p = this.players.get(ev.player); if (p) p.online = ev.kind === "join"; }
  }

  private tick() {
    if (!this.alive) return;
    const ps = this.participants();
    if (!ps.length) {
      if (this.emptySince < 0) this.emptySince = this.t;
      else if (this.t - this.emptySince >= this.b.arena.emptyDespawnSeconds * 20) { this.end("despawned", `no players for ${this.b.arena.emptyDespawnSeconds} s`); return; }
    } else this.emptySince = -1;
    this.checkPhase();
    const maxT = (this.b.arena.maxDurationSeconds ?? 0) * 20;
    if (maxT > 0 && !this.enraged && this.t >= maxT) {
      if (this.b.arena.onTimeout === "enrage") { this.enraged = true; this.note("enrage", "time out"); }
      else { this.end("despawned", "time out"); return; }
    }
    if (ps.length && this.t >= this.nextAttack) this.choose(ps);
  }

  checkPhase() {
    const f = this.health / this.max;
    while (this.phase + 1 < this.b.phases.length && f < this.b.phases[this.phase + 1].below) {
      this.phase++;
      const ph = this.b.phases[this.phase];
      this.note("phase", `${ph.id} at ${Math.round(f * 100)}%`);
      if (ph.onEnter) this.execute(ph.onEnter, this.participants().slice(0, BOSS_LIMITS.enterTargets), `enter ${ph.id}`);
      this.nextAttack = Math.min(this.nextAttack, this.t + ph.intervalTicks);
    }
  }

  private choose(ps: SimPlayer[]) {
    const ph = this.b.phases[this.phase];
    const ok: { a: Attack; w: number; ts: SimPlayer[] }[] = [];
    for (const ref of ph.attacks) {
      const a = this.b.attacks.find((x) => x.id === ref.attack);
      if (!a) continue;
      if ((this.ready.get(a.id) ?? -1) > this.t) continue;
      const ts = this.targets(a, ps);
      if (a.targets.select !== "self" && !ts.length) continue;
      ok.push({ a, w: ref.weight ?? BOSS_DEFAULTS.weight, ts });
    }
    const interval = this.enraged ? Math.max(10, Math.floor(ph.intervalTicks / 2)) : ph.intervalTicks;
    if (!ok.length) { this.nextAttack = this.t + BOSS_LIMITS.aiPeriodTicks; return; }
    const pick = ok[weightedPick(ok.map((x) => x.w), this.random)];
    this.ready.set(pick.a.id, this.t + (pick.a.cooldownTicks ?? 0));
    const tele = this.opts.telegraph === false ? 0 : pick.a.telegraph?.ticks ?? 0;
    this.note("attack", `${pick.a.id} -> ${pick.ts.map((p) => p.id).join(",") || "self"}${tele ? ` (telegraph ${tele})` : ""}`);
    const go = () => { if (this.alive) this.execute(pick.a.actions, pick.ts, pick.a.id); };
    if (tele > 0) this.pending.push({ at: this.t + tele, run: go }); else go();
    this.nextAttack = this.t + tele + interval;
  }

  /** Execute actions with a fresh budget (per-target actions once per target; delayed re-checks the targets). */
  execute(list: BossAction[], targets: SimPlayer[], what: string, budget = { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0 }): typeof budget {
    const mult = damageMultiplier(this.b, this.opts.difficulty ?? "easy", this.participants().length, this.enraged);
    const live = () => targets.filter((p) => p.online && p.health > 0 && dist2(p.pos, this.home) <= this.b.arena.radius ** 2);
    for (const a of list) {
      const per = isPerTarget(a);
      const ts = per ? live() : [null];
      for (const p of ts) {
        if (budget.actions >= BUDGET.actions) { this.note("budget", `${what}: actions exhausted`); return budget; }
        budget.actions++;
        switch (a.type) {
          case "damage": if (p && budget.entities < BUDGET.entities) { budget.entities++; p.health = Math.max(0, p.health - a.amount * mult); this.note("damage", `${what}: ${p.id} -${fmt(a.amount * mult)}`); } break;
          case "launch_projectile": if (p && budget.projectiles < BUDGET.projectiles) { budget.projectiles++; budget.tasks++; this.note("projectile", `${what}: ${a.kind} -> ${p.id} (+${fmt((a.damage ?? 0) * mult)} on hit)`); } break;
          case "spawn_particles": budget.particles += Math.min(a.count, BUDGET.particles - budget.particles); break;
          case "summon": {
            let n = 0;
            for (let i = 0; i < a.count; i++) { const live2 = this.minions.length; if (live2 >= (this.b.minions?.maxAlive ?? 0) || budget.entities >= BUDGET.entities) break; budget.entities++; this.minions.push(this.t); n++; }
            this.note("summon", `${what}: ${n} ${a.entity.replace(/^minecraft:/, "")}`); break;
          }
          case "heal_self": budget.entities++; this.health = Math.min(this.max, this.health + a.amount); this.note("heal", `${what}: +${fmt(a.amount)}`); break;
          case "delayed": if (budget.tasks < BUDGET.tasks) { budget.tasks++; const at = this.t + a.delayTicks; this.pending.push({ at, run: () => { if (this.alive) this.execute(a.actions, targets, `${what} (delayed)`, budget); } }); } break;
          default: if (p && ["knockback", "pull", "potion_effect"].includes(a.type)) { budget.entities++; this.note(a.type, `${what}: ${p.id}`); } else if (["leap", "self_effect"].includes(a.type)) budget.entities++; break;
        }
      }
    }
    return budget;
  }

  private defeat() {
    const d = this.b.drops;
    const total = [...this.damageBy.values()].reduce((a, b) => a + b, 0);
    const share = d?.minDamageShare ?? BOSS_DEFAULTS.minDamageShare;
    if (d?.mode === "ground") this.drops.push({ player: "(ground)", counts: rollCounts(d, this.random) });
    else if (d) for (const [id, v] of [...this.damageBy].sort((a, b) => (a[0] < b[0] ? -1 : 1))) if (total > 0 && this.players.get(id)?.online && v / total + 1e-9 >= share) this.drops.push({ player: id, counts: rollCounts(d, this.random) });
    this.end("defeated", `${this.drops.length} roll set(s)`);
  }

  private end(how: "defeated" | "despawned", why: string) {
    this.alive = false;
    this.ended = how;
    this.note(how, `${why}; minions removed ${this.minions.length}`);
    this.minions.length = 0;
  }
}

// ---------------------------------------------------------------------------------------------- encounter model
/** Wave progression of an encounter: kills arrive as events; returns the log (waves started, complete / failed). */
export function simulateEncounter(e: EncounterDesign, script: { t: number; kill: number }[], until: number, playersPresent: (t: number) => boolean = () => true): FightLog[] {
  const log: FightLog[] = [];
  let wave = 0, spawned = false, waveAt = (e.waves[0].delaySeconds ?? 0) * 20, waveStarted = 0, alive = 0, emptySince = -1;
  const sizeOf = (i: number) => Math.min(e.maxAlive, BOSS_LIMITS.encounterMobs, e.waves[i].spawns.reduce((n, s) => n + s.count, 0));
  const spawn = (t: number) => { spawned = true; waveStarted = t; alive = sizeOf(wave); log.push({ t, kind: "wave", detail: `${wave + 1}/${e.waves.length}: ${alive} spawned` }); };
  if (waveAt <= 0) spawn(0);
  const kills = [...script].sort((a, b) => a.t - b.t);
  let k = 0;
  for (let t = 0; t <= until; t++) {
    while (k < kills.length && kills[k].t <= t) { alive = Math.max(0, alive - kills[k].kill); k++; }
    if (t === 0 || t % BOSS_LIMITS.aiPeriodTicks !== 0) continue;
    if (!playersPresent(t)) { if (emptySince < 0) emptySince = t; else if (t - emptySince >= e.failure.emptySeconds * 20) { log.push({ t, kind: "failed", detail: "empty" }); return log; } } else emptySince = -1;
    if (e.failure.timeLimitSeconds && t >= e.failure.timeLimitSeconds * 20) { log.push({ t, kind: "failed", detail: "time limit" }); return log; }
    const w = e.waves[wave];
    if (!spawned) { if (t >= waveAt) spawn(t); continue; }
    const last = wave === e.waves.length - 1;
    if (w.advance === "cleared" || last) {
      if (alive === 0) { if (last) { log.push({ t, kind: "complete", detail: `${(e.rewards?.items ?? []).length} reward entries` }); return log; } wave++; spawned = false; waveAt = t + (e.waves[wave].delaySeconds ?? 0) * 20; if (waveAt <= t) spawn(t); continue; }
      if (w.advance === "cleared" && w.seconds && t - waveStarted >= w.seconds * 20) { log.push({ t, kind: "failed", detail: `wave ${wave + 1} not cleared in time` }); return log; }
    } else if (t - waveStarted >= (w.seconds ?? 0) * 20) { wave++; spawned = false; waveAt = t + (e.waves[wave].delaySeconds ?? 0) * 20; if (waveAt <= t) spawn(t); }
  }
  return log;
}

