      { id: "encounter-wave2", waitMs: 4500, command: `${CMD} encounter status`, expect: ["encounter ash_trial#1: wave 2/3 alive 4", "last: encounter ash_trial#1 wave 2/3: 4 spawned"] },
      { id: "encounter-kill2", command: `kill @e[tag=${ETAG}]`, expect: ["Killed"] },
      { id: "encounter-wave3", waitMs: 23500, command: `${CMD} encounter status`, expect: ["encounter ash_trial#1: wave 3/3 alive 1"] },
      { id: "encounter-boss", command: `execute if entity @e[tag=${NS}.boss.grave_lord]`, expect: ["Test passed, count: 1"] },
      { id: "encounter-kill-boss", command: `kill @e[tag=${NS}.boss.grave_lord]`, expect: ["Killed"] },
      { id: "encounter-complete", waitMs: 1200, command: `${CMD} encounter status`, expect: ["No encounters running.", "last: encounter ash_trial#1 complete: 1 reward stack to the ground"] },
      { id: "config-clamped-on-reload", writeFile: { path: `plugins/${PLUGIN}/config.yml`, content: clampCfg }, command: `${CMD} reload`, expect: ["bosses and encounters reloaded", "clamped bosses.ember_warden.stats.health 99999.0 -> 1024.0", "bosses.ember_warden.phases.p3.below 0.9 is above the previous phase; using 0.6"], expectNot: ["internal error", "Exception"] },
      { id: "list-after-clamp", command: `${CMD} boss list`, expect: ["ember_warden: entity=wither_skeleton health=1024.00 phases=p1@1.00>p2@0.60>p3@0.60"] },
