    console.log(`flight ${lane.version}: ${describeSummary(f.summary)}`);
    for (const x of f.report.checks) if (x.status !== "pass") console.log(`  ${x.id}: ${x.status}\n    ${x.evidence.slice(0, 24).join("\n    ")}`);
    console.log(`  log: cleanup=${JSON.stringify((disk as { cleanupLine?: string }).cleanupLine)} pluginErrors=${JSON.stringify((disk as { pluginErrorLines?: string[] }).pluginErrorLines)}`);

    // parameter edit: health, slam damage, phase threshold -> only config.yml changes; the edited jar migrates an existing config
    const edits = [{ path: "bosses.ember_warden.stats.health", value: 450 }, { path: "bosses.ember_warden.attacks.slam.a0.amount", value: 9 }, { path: "bosses.ember_warden.phases.p2.below", value: 0.7 }, { path: "encounters.ash_trial.waves.w1.s0.count", value: 6 }];
    const e = recompileModWithEdits(c, edits, { version: lane.version, namespace: NS, pluginName: PLUGIN });
    if (!e.ok) { L.edit = { ok: false, errors: e.errors }; console.log(e.errors); continue; }
    const b2 = build(e.result, lane, "edit");
    const za = indexZip(readFileSync(b.jarPath)), zb = indexZip(readFileSync(b2.jarPath));
