        { id: "plugins", command: "plugins", expect: [PLUGIN] },
        { id: "params-after-update", command: `${CMD} params`, expect: ["bosses.ember_warden.stats.health=450.0", "bosses.ember_warden.attacks.slam.a0.amount=9.0", "bosses.ember_warden.phases.p2.below=0.7", "encounters.ash_trial.waves.w1.s0.count=6"] },
        { id: "list-after-update", command: `${CMD} boss list`, expect: ["ember_warden: entity=wither_skeleton health=450.00 phases=p1@1.00>p2@0.70>p3@0.25"] },
        { id: "encounter-after-update", command: `${CMD} encounter list`, expect: ["ash_trial: waves=3 sizes=5c,6t,1c"] },
        { id: "spawn-after-update", command: `${CMD} boss spawn ember_warden spawn`, expect: ["health 450.00"] },
      ],
    }, `edit flight ${lane.version}`);
    (L.edit as Record<string, unknown>).flight = { status: f2.report.status, overall: f2.summary.overall, success: f2.summary.success, line: describeSummary(f2.summary), checks: f2.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 12) })), disk: harvest(f2.report.runId ?? null) };
    console.log(`edit flight ${lane.version}: ${describeSummary(f2.summary)}; jar entries that differ: ${differ.join(", ")}`);
    for (const x of f2.report.checks) if (x.status !== "pass") console.log(`  ${x.id}: ${x.status}\n    ${x.evidence.slice(0, 12).join("\n    ")}`);
  }
  res.leftovers = { runsDir: existsSync(path.join(TF, "runs")) ? readdirSync(path.join(TF, "runs")).length : 0 };
  const out = arg("--out");
  if (out) { mkdirSync(path.dirname(out), { recursive: true }); writeFileSync(out, JSON.stringify(res, null, 1)); }
  console.log(JSON.stringify(res, null, 1).slice(0, 2000));
  rmSync(RUN, { recursive: true, force: true });
}

main().catch((e) => { console.error(e); process.exit(1); });

