// Cyrus R3 gameplay designers, part 3 (pure): the BOSS and ENCOUNTER designers. The IR (kind discriminator on the
// existing design files; item / menu / quest designs unchanged), caps, the adversarial corpus (forbidden bases, phase
// order, unreachable bosses / encounters, budget overruns, drop loops, summon-item conflicts, wave caps), the component
// library (present, documented, version-independent except BossCompat, strict-scan + precheck clean, the hardening in
// the code), the compiler (golden hashes per version, order independence, config.yml / plugin.yml / main class), edit
// without regenerating, the TS simulator (phases, weighted picks, cooldowns, despawn, enrage, minion caps, budget, drops,
// encounter waves) incl. the java.util.Random twin checked against the REAL server's `boss check` output, TS == the
// generated service JS, the prompt part, routing, the build request, the service workspace and the portal sync.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { BOSS_CAPS, BOSS_LIMITS, BOSS_BASES, MINION_BASES, ENTITY_CLASS, bossBudgetOf, bossJsonSchema, validateBoss, type BossDesign, type EncounterDesign } from "../lib/cyrus/designer/boss/spec";
import { BOSS_COMPONENTS, BOSS_COMPAT_META, bossCompatSource } from "../lib/cyrus/designer/boss/components";
import { BOSS_DEFAULTS, bossParams } from "../lib/cyrus/designer/boss/compile";
import { BossFight, JRandom, bossCheckLines, damageMultiplier, javaShuffle, scaledHealth, simulateEncounter, weightedPick } from "../lib/cyrus/designer/boss/simulate";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { applyGameplayEdits, recompileModWithEdits } from "../lib/cyrus/designer/gameplay/params";
import { designKind, validateGameplay } from "../lib/cyrus/designer/gameplay/spec";
import { COMPONENTS } from "../lib/cyrus/designer/components";
import { GAMEPLAY_COMPONENTS } from "../lib/cyrus/designer/gameplay/components";
import { designFeatures } from "../lib/cyrus/designer/spec";
import { decideDesignerRoute, hasBossDesigns, matchBossWords } from "../lib/cyrus/designer/route";
import { checkReturnedDesigns, DESIGN_KIND_MIME } from "../lib/cyrus/designer/sync";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { assetLines } from "../lib/cyrus-mods/doc";
import { readCyrusMeta } from "../lib/cyrus/meta";
import { VERSIONS } from "../lib/cyrus/versions/registry";
import { BOSS_NS as NS, BOSS_PLUGIN, loadBossFixtures, loadBrokenBoss } from "../scripts/cyrus/boss-golden";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-boss");
const ALL = () => loadBossFixtures();
const byId = (id: string) => ALL().find((d: { id: string }) => d.id === id);
const clone = <T,>(x: T): T => structuredClone(x);
const SUPPORTED = VERSIONS.map((v) => v.id).filter((v) => designFeatures(v).ok);
const ctx = (version = "1.21.11") => ({ version, namespace: NS, pluginName: BOSS_PLUGIN });
const compileOk = (d: unknown[], c = ctx()): ModCompileOk => { const r = compileMod(d, c); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const errorsOf = (inputs: unknown[], file?: string) => { const v = validateGameplay(inputs, { version: "1.21.11", namespace: NS }); return (file ? v.files.find((f) => f.id === file)?.errors ?? [] : v.errors).map((e) => e.code); };
const items = () => ALL().filter((d: { kind?: string }) => !d.kind);
const warden = (): BossDesign => clone(byId("ember_warden"));
const grave = (): BossDesign => clone(byId("grave_lord"));
const trial = (): EncounterDesign => clone(byId("ash_trial"));
/** A mod = the showcase items + one changed boss / encounter. */
const withBoss = (b: unknown) => [...items(), b];
const bossCodes = (b: unknown) => errorsOf(withBoss(b), (b as { id: string }).id);

describe("boss IR: the showcase mod", () => {
  it("is valid on every supported version; the kind discriminator; item / menu / quest kinds unchanged", () => {
    for (const v of SUPPORTED) { const r = validateGameplay(ALL(), { version: v, namespace: NS }); assert.ok(r.ok, `${v}: ${JSON.stringify(r.errors.slice(0, 3))}`); assert.deepEqual([r.bosses.length, r.encounters.length], [2, 1]); }
    assert.equal(validateGameplay(ALL(), { version: "26.3", namespace: NS }).ok, false, "26.3 fails closed");
    assert.equal(designKind({ kind: "boss" }), "boss"); assert.equal(designKind({ kind: "encounter" }), "encounter"); assert.equal(designKind({}), "item"); assert.equal(designKind({ kind: "dragon" }), null);
    assert.ok(errorsOf([{ ...warden(), kind: "dragon" }], undefined).includes("unknown_kind"));
  });
  it("the JSON Schema file is current and carries the caps", () => {
    const file = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/designer/boss.v1.schema.json"), "utf8"));
    assert.deepEqual(file, JSON.parse(JSON.stringify(bossJsonSchema())));
    const txt = JSON.stringify(file);
    assert.match(txt, /"maximum":1024/); assert.match(txt, /"wither_skeleton"|"enum"/);
  });
  it("closed base lists: every allowed base has a Bukkit class literal; minions are a subset", () => {
    for (const b of BOSS_BASES) assert.ok(ENTITY_CLASS[b], b);
    for (const m of MINION_BASES) assert.ok((BOSS_BASES as readonly string[]).includes(m), m);
    for (const bad of ["creeper", "ghast", "enderman", "wither", "ender_dragon", "warden", "slime", "silverfish", "phantom"]) assert.ok(!(BOSS_BASES as readonly string[]).includes(bad), bad);
  });
});

describe("boss IR: caps (min/max accepted, just outside refused)", () => {
  type Setter = (b: BossDesign, v: number) => void;
  const BOSS_SET: Partial<Record<keyof typeof BOSS_CAPS, Setter>> = {
    health: (b, v) => { b.stats.health = v; }, armor: (b, v) => { b.stats.armor = v; }, attackDamage: (b, v) => { b.stats.attackDamage = v; }, speed: (b, v) => { b.stats.speed = v; },
    knockbackResistance: (b, v) => { b.stats.knockbackResistance = v; }, followRange: (b, v) => { b.stats.followRange = v; },
    arenaRadius: (b, v) => { b.arena.radius = v; for (const a of b.attacks) a.targets.range = Math.min(a.targets.range, v); }, emptyDespawnSeconds: (b, v) => { b.arena.emptyDespawnSeconds = v; }, maxDurationSeconds: (b, v) => { b.arena.maxDurationSeconds = v; },
    spawnCooldownSeconds: (b, v) => { b.spawn!.cooldownSeconds = v; }, maxAlive: (b, v) => { b.spawn!.maxAlive = v; }, intervalTicks: (b, v) => { b.phases[0].intervalTicks = v; }, weight: (b, v) => { b.phases[0].attacks[0].weight = v; },
    cooldownTicks: (b, v) => { b.attacks[0].cooldownTicks = v; }, telegraphTicks: (b, v) => { b.attacks[0].telegraph!.ticks = v; }, targetMax: (b, v) => { b.attacks[1].targets.max = v; if (v > 3) b.attacks[1].actions = b.attacks[1].actions.filter((a) => a.type !== "launch_projectile"); },
    targetRange: (b, v) => { b.arena.radius = 64; b.attacks[0].targets.range = v; }, damage: (b, v) => { (b.attacks[0].actions[0] as { amount: number }).amount = v; }, strength: (b, v) => { (b.attacks[0].actions[1] as { strength: number }).strength = v; },
    vertical: (b, v) => { (b.attacks[0].actions[1] as { vertical: number }).vertical = v; }, projectileSpeed: (b, v) => { (b.attacks[1].actions[0] as { speed: number }).speed = v; }, projectileDamage: (b, v) => { (b.attacks[1].actions[0] as { damage: number }).damage = v; },
    particleCount: (b, v) => { (b.attacks[0].actions[2] as { count: number }).count = v; }, summonCount: (b, v) => { b.minions!.maxAlive = 16; (b.attacks[2].actions[0] as { count: number }).count = v; }, minionHealth: (b, v) => { (b.attacks[2].actions[0] as { health: number }).health = v; },
    minionsMax: (b, v) => { b.minions!.maxAlive = v; (b.attacks[2].actions[0] as { count: number }).count = 1; }, delayTicks: (b, v) => { (b.attacks[3].actions[1] as { delayTicks: number }).delayTicks = v; },
    healthPerPlayer: (b, v) => { b.scaling!.healthPerPlayer = v; }, damagePerPlayer: (b, v) => { b.scaling!.damagePerPlayer = v; }, maxPlayers: (b, v) => { b.scaling!.maxPlayers = v; }, difficulty: (b, v) => { b.difficulty!.hard = v; },
    dropCount: (b, v) => { b.drops!.items![0].count = v; }, dropChance: (b, v) => { b.drops!.items![0].chance = v; }, damageShare: (b, v) => { b.drops!.minDamageShare = v; }, xp: (b, v) => { b.drops!.xp = v; },
    below: (b, v) => { b.phases[2].below = v; if (v >= 0.6) b.phases[2].below = 0.59; },
  };
  for (const [cap, set] of Object.entries(BOSS_SET) as [keyof typeof BOSS_CAPS, Setter][]) {
    const [lo, hi] = BOSS_CAPS[cap];
    it(`${cap} ${lo}..${hi}`, () => {
      for (const v of [lo, hi]) { const b = warden(); set(b, v); const c = bossCodes(b); assert.ok(!c.includes("schema"), `${cap}=${v}: ${c}`); }
      const step = Number.isInteger(lo) && Number.isInteger(hi) && hi - lo >= 1 ? 1 : 0.001;
      for (const v of [lo - step, hi + step]) { if (cap === "below" && v > 1) continue; const b = warden(); set(b, v); assert.ok(bossCodes(b).includes("schema"), `${cap}=${v} must be refused`); }
    });
  }
  it("encounter caps: wave counts, waves, maxAlive, time limits", () => {
    const e = trial(); e.waves[0].spawns[0].count = 13; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e], "ash_trial").includes("schema"));
    const e2 = trial(); e2.maxAlive = 25; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e2], "ash_trial").includes("schema"));
    const e3 = trial(); e3.waves = Array.from({ length: 9 }, () => clone(trial().waves[0])); assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e3], "ash_trial").includes("schema"));
  });
});

describe("boss IR: adversarial corpus", () => {
  it("the deliberately broken boss is rejected with every semantic code (and compileMod refuses the mod)", () => {
    const codes = errorsOf([...ALL(), loadBrokenBoss()], "broken_boss").sort();
    for (const c of ["base_not_allowed", "first_phase", "phase_order", "unresolved_ref", "range_outside_arena", "no_target", "minions_undeclared", "self_effect_banned", "budget_projectiles", "drop_loop"]) assert.ok(codes.includes(c), `${c} in ${codes}`);
    assert.equal(compileMod([...ALL(), loadBrokenBoss()], ctx()).ok, false);
  });
  it("refuses code and commands in any form (closed action set, unknown keys)", () => {
    for (const bad of [{ type: "run_command", command: "op @a" }, { type: "damage", amount: 5, script: "x" }, { type: "explode", power: 4 }, { type: "set_block", block: "minecraft:tnt" }]) {
      const b = warden(); (b.attacks[0].actions as unknown[]).push(bad); assert.ok(bossCodes(b).includes("schema"), JSON.stringify(bad));
    }
    const b = warden(); (b as unknown as Record<string, unknown>).onDeath = "op @a"; assert.ok(bossCodes(b).includes("schema"));
  });
  it("budgets: particles at every target, projectiles, nested delays, summons", () => {
    const p = warden(); p.attacks[0].actions.push({ type: "spawn_particles", particle: "flame", count: 64, at: "target" }, { type: "spawn_particles", particle: "soul", count: 64, at: "target" }); assert.ok(bossCodes(p).includes("budget_particles"));
    const pr = warden(); pr.attacks[1].targets.max = 4; assert.ok(bossCodes(pr).includes("budget_projectiles"));
    const d = warden(); d.attacks[3].actions.push({ type: "delayed", delayTicks: 5, actions: [{ type: "delayed", delayTicks: 5, actions: [{ type: "delayed", delayTicks: 5, actions: [{ type: "heal_self", amount: 1 }] }] }] }); assert.ok(bossCodes(d).includes("too_deep"));
    const s = warden(); s.minions!.maxAlive = 16; s.attacks[2].actions.push({ type: "summon", entity: "minecraft:zombie", count: 3 }); assert.ok(bossCodes(s).includes("budget_summons"));
    assert.deepEqual(bossBudgetOf(warden().attacks[0].actions, 6), { actions: 14, entities: 12, tasks: 0, particles: 4, projectiles: 0, summons: 0, depth: 0 });
  });
  it("forbidden bases, minions, harmful self effects, invisibility", () => {
    const b = warden(); b.entity = "minecraft:ghast"; assert.ok(bossCodes(b).includes("base_not_allowed"));
    const m = warden(); (m.attacks[2].actions[0] as { entity: string }).entity = "minecraft:ravager"; assert.ok(bossCodes(m).includes("base_not_allowed"), "ravager is not a minion");
    const h = warden(); h.phases[1].selfEffects = [{ effect: "poison" }]; assert.ok(bossCodes(h).includes("harmful_self_effect"));
    const inv = warden(); inv.phases[1].selfEffects = [{ effect: "invisibility" }]; assert.ok(bossCodes(inv).includes("harmful_self_effect"));
  });
  it("reachability, summon-item conflicts, drop loops", () => {
    const g = grave(); g.spawn = { command: false };
    const noWave = trial(); noWave.waves = noWave.waves.filter((w) => !w.spawns.some((s) => s.boss));
    const mod = [...ALL().filter((d: { id: string }) => d.id !== "grave_lord" && d.id !== "ash_trial"), g, noWave];
    assert.ok(errorsOf(mod, "grave_lord").includes("unreachable_boss"));
    assert.ok(!errorsOf([...ALL().filter((d: { id: string }) => d.id !== "grave_lord"), g], "grave_lord").includes("unreachable_boss"), "an encounter wave spawns it");
    const e = trial(); e.start = { command: false }; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e], "ash_trial").includes("unreachable_encounter"));
    const twice = trial(); twice.start!.item = "ember_core"; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), twice], "ash_trial").includes("opener_conflict"));
    const menu = { schemaVersion: 1, kind: "menu", style: "chest", id: "core_menu", title: "Core", rows: 1, buttons: [{ slot: 0, icon: { material: "minecraft:stone" }, actions: [{ type: "close" }] }], openWith: { item: "ember_core" } };
    assert.ok(errorsOf([...ALL(), menu], "ember_warden").includes("opener_conflict"), "a menu opener cannot also summon");
    const clicky = { ...byId("ember_core"), abilities: [{ id: "zap", name: "Zap", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }] }] };
    assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ember_core"), clicky], "ember_warden").includes("opener_conflict"));
    const loop = warden(); loop.drops!.items!.push({ item: "ember_core", count: 1, chance: 0.1 }); assert.ok(bossCodes(loop).includes("drop_loop"));
    const lt = warden(); lt.drops!.lootTable = "minecraft:chests/simple_dungeon"; assert.ok(bossCodes(lt).includes("foreign_namespace"));
    const lt2 = warden(); lt2.drops!.lootTable = `${NS}:boss/ember`;
    assert.ok(validateGameplay(withBoss(lt2), { version: "1.21.11", namespace: NS, assets: { lootTables: [] } }).files.find((f) => f.id === "ember_warden")!.errors.some((x) => x.code === "loot_table_not_in_project"));
    assert.ok(validateGameplay(withBoss(lt2), { version: "1.21.11", namespace: NS, assets: { lootTables: [`${NS}:boss/ember`] } }).files.find((f) => f.id === "ember_warden")!.ok);
  });
  it("encounters: wave caps, sources, boss counts, timer seconds, impossible time limits, too many bosses", () => {
    const rest = ALL().filter((d: { id: string }) => d.id !== "ash_trial");
    const over = trial(); over.waves[1].spawns[0].count = 9; assert.ok(errorsOf([...rest, over], "ash_trial").includes("wave_over_cap"));
    const both = trial(); (both.waves[0].spawns[0] as Record<string, unknown>).boss = "grave_lord"; assert.ok(errorsOf([...rest, both], "ash_trial").includes("spawn_source"));
    const two = trial(); two.waves[2].spawns[0].count = 2; assert.ok(errorsOf([...rest, two], "ash_trial").includes("boss_count"));
    const tm = trial(); delete tm.waves[1].seconds; assert.ok(errorsOf([...rest, tm], "ash_trial").includes("timer_seconds"));
    const tl = trial(); tl.failure.timeLimitSeconds = 60; tl.waves[1].seconds = 100; assert.ok(errorsOf([...rest, tl], "ash_trial").includes("time_limit_too_short"));
    const five = [...ALL(), ...["b_one", "b_two", "b_three"].map((id) => ({ ...grave(), id }))];
    assert.ok(errorsOf(five).includes("too_many_bosses"));
    const wm = trial(); wm.waves[0].spawns[0].entity = "minecraft:iron_golem"; assert.ok(errorsOf([...rest, wm], "ash_trial").includes("base_not_allowed"));
  });
});

describe("boss component library + compiler", () => {
  const c = compileOk(ALL());
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-boss-"));
  for (const f of c.files) { const abs = path.join(tmp, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); }
  const java = c.files.filter((f) => f.path.endsWith(".java"));
  it("every component (item + boss; no menu/quest library in a boss-only mod) is in the tree, documented", () => {
    for (const comp of [...COMPONENTS, ...BOSS_COMPONENTS]) {
      assert.ok(c.files.some((f) => f.path.endsWith(comp.file)), comp.id);
      assert.ok(comp.purpose.length > 10 && comp.tests.length >= 2 && comp.families.length === 2, comp.id);
    }
    assert.ok(c.files.some((f) => f.path.endsWith(BOSS_COMPAT_META.file)));
    for (const g of GAMEPLAY_COMPONENTS) assert.ok(!c.files.some((f) => f.path.endsWith(g.file)), `${g.id} not needed`);
