describe("TS reference simulator", () => {
  it("java.util.Random twin == the REAL server's /<mod> boss check (recorded on node-2 Paper 1.21.11 + 26.2)", () => {
    const jvm = JSON.parse(fs.readFileSync(path.join(FX, "jvm-check.json"), "utf8"));
    const c = compileOk(ALL());
    assert.deepEqual(bossCheckLines(c.bosses, c.encounters), jvm.lines);
  });
  it("Random primitives: nextInt power-of-two and general bounds, shuffle, weighted pick", () => {
    const r = new JRandom(42);
    const ints = Array.from({ length: 6 }, () => r.nextInt(10));
    assert.ok(ints.every((x) => x >= 0 && x < 10));
    const p2 = new JRandom(5); assert.ok(Array.from({ length: 50 }, () => p2.nextInt(8)).every((x) => x >= 0 && x < 8));
    assert.deepEqual(javaShuffle([0, 1, 2, 3, 4, 5], new JRandom(42)).sort(), [0, 1, 2, 3, 4, 5]);
    const w = new JRandom(7); const picks = Array.from({ length: 300 }, () => weightedPick([3, 1], w));
    assert.ok(picks.filter((x) => x === 0).length > 180, "weight 3 is picked about 3x as often");
  });
  it("scaling: health per player (clamped 1024), damage by difficulty / players / enrage", () => {
    const b = warden();
    assert.equal(scaledHealth(b, 1), 300); assert.equal(scaledHealth(b, 4), 615); assert.equal(scaledHealth(b, 50), 825, "maxPlayers 6");
    const big = warden(); big.stats.health = 1000; assert.equal(scaledHealth(big, 6), 1024);
    assert.equal(damageMultiplier(b, "easy", 1, false), 0.75); assert.equal(damageMultiplier(b, "hard", 1, false), 1.3); assert.ok(Math.abs(damageMultiplier(b, "normal", 4, true) - 1.45 * 1.5) < 1e-9);
  });
  it("a fight: one-way phases, onEnter, weighted attacks with cooldowns, telegraph, drops by damage share", () => {
    const players = [{ id: "alice", pos: [3, 64, 0] as [number, number, number], health: 20 }, { id: "bob", pos: [0, 64, 4] as [number, number, number], health: 20 }];
    const f = new BossFight(warden(), players, { seed: 99 });
    assert.equal(f.max, 405, "2 players: 300 x (1 + 0.35)");
    f.run([{ t: 100, kind: "damage", by: "alice", amount: 200 }, { t: 140, kind: "heal", amount: 300 }, { t: 200, kind: "damage", by: "bob", amount: 10 }], 300);
    const phases = f.log.filter((l) => l.kind === "phase").map((l) => l.detail);
    assert.deepEqual(phases, ["p2 at 51%"], "healing never goes back a phase");
    assert.equal(f.phase, 1);
    const attacks = f.log.filter((l) => l.kind === "attack");
    assert.ok(attacks.length >= 3);
    for (const a of attacks.filter((x) => x.detail.startsWith("slam"))) assert.match(a.detail, /\(telegraph 20\)/);
    const slams = attacks.filter((x) => x.detail.startsWith("slam")).map((x) => x.t);
    for (let i = 1; i < slams.length; i++) assert.ok(slams[i] - slams[i - 1] >= 80, "slam cooldown 80 ticks");
    f.run([{ t: 310, kind: "damage", by: "alice", amount: 1000 }], 320);
    assert.equal(f.ended, "defeated");
    assert.deepEqual(f.drops.map((d) => d.player), ["alice"], "bob did under 10% of the damage");
    assert.equal(f.drops[0].counts.length, 3);
  });
  it("empty arena despawn, time out enrage, minion cap, players outside the arena are not participants", () => {
    const away = new BossFight(grave(), [{ id: "carl", pos: [100, 64, 0], health: 20 }]);
    away.run([], 400);
    assert.equal(away.ended, "despawned"); assert.match(away.log.at(-1)!.detail, /no players for 10 s/);
    const e = warden(); e.arena.maxDurationSeconds = 60;
    const f = new BossFight(e, [{ id: "dana", pos: [2, 64, 2], health: 1000 }], { seed: 3 });
    f.run([], 1300);
    assert.ok(f.enraged && f.log.some((l) => l.kind === "enrage"));
    const m = new BossFight(warden(), [{ id: "eve", pos: [1, 64, 1], health: 1000 }]);
    const cinders = warden().attacks.find((a) => a.id === "cinders")!;
    for (let i = 0; i < 3; i++) m.execute(cinders.actions, [], "cinders");
    assert.equal(m.minions.length, 4, "minions.maxAlive 4");
  });
  it("the per-attack budget stops a hand-edited flood (the same 64-action Budget as the item graph)", () => {
    const b = warden(); b.attacks[0].actions = Array.from({ length: 12 }, () => ({ type: "damage", amount: 1 }));
    const f = new BossFight(b, Array.from({ length: 8 }, (_, i) => ({ id: `p${i}`, pos: [1, 64, i % 3] as [number, number, number], health: 1000 })));
    const used = f.execute(b.attacks[0].actions, [...f.participants()], "flood");
    assert.equal(used.actions, 64); assert.ok(f.log.some((l) => l.kind === "budget"));
  });
  it("encounter waves: cleared -> delay -> timer -> boss -> complete; empty arena fails", () => {
    const log = simulateEncounter(trial(), [{ t: 100, kill: 5 }, { t: 300, kill: 4 }, { t: 800, kill: 1 }], 2000);
    assert.deepEqual(log.map((l) => l.kind), ["wave", "wave", "wave", "complete"]);
    assert.deepEqual(log.filter((l) => l.kind === "wave").map((l) => l.detail), ["1/3: 5 spawned", "2/3: 4 spawned", "3/3: 1 spawned"]);
    const failed = simulateEncounter(trial(), [], 3000, () => false);
    assert.equal(failed.at(-1)!.kind, "failed");
  });
});

