    const t = checkReturnedDesigns(list.map((x) => (x.name === "ember_warden" ? { ...x, spec: bad } : x)), { namespace: NS, mcVersion: "1.21.11", pluginName: BOSS_PLUGIN, compile: { hash: svc.hash } });
    assert.ok(t.dropped.map((d) => d.name).includes("ember_warden")); assert.equal(t.serviceAgreed, false);
    assert.match(t.notices[0], /^Boss design "ember_warden" was left out/);
    assert.equal(DESIGN_KIND_MIME.boss, "application/vnd.nxeon.boss-design+json"); assert.equal(DESIGN_KIND_MIME.encounter, "application/vnd.nxeon.encounter-design+json");
  });
  it("mod page lines: 'Includes N bosses and M encounters'", () => {
    const row = { version: "1.21.11", specSha256: "x", compileHash: "y", serviceAgreed: true, configVersion: 1, settings: 3, abilities: 0 };
    const a = { status: "none" as const, namespace: NS, projectId: "p", revisionId: "r", textures: [], dropped: [], pack: null, loader: null, notices: [],
      designs: [{ ...row, name: "ember_warden", kind: "boss" as const }, { ...row, name: "grave_lord", kind: "boss" as const }, { ...row, name: "ash_trial", kind: "encounter" as const }] };
    assert.ok(assetLines(a).some((l) => /^Includes 2 bosses and 1 encounter;/.test(l)), JSON.stringify(assetLines(a)));
  });
  it("defaults documented in BOSS_DEFAULTS are the ones the compiler writes", () => {
    const cfg = compileOk(ALL()).files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, new RegExp(`difficulty:\\n(?:.*\\n){2}      normal: ${BOSS_DEFAULTS.difficultyNormal.toFixed(1)}`));
    assert.equal(validateBoss(grave(), { version: "1.21.11", namespace: NS, features: (designFeatures("1.21.11") as { features: never }).features, items: new Map() }).ok, true);
  });
});

toolu_016E9613gVgMB8Wz3bHL7eUE.content:
// Cyrus R3 gameplay designers, part 3 (pure): the BOSS and ENCOUNTER designers. The IR (kind discriminator on the
// existing design files; item / menu / quest designs unchanged), caps, the adversarial corpus (forbidden bases, phase
// order, unreachable bosses / encounters, budget overruns, drop loops, summon-item conflicts, wave caps), the component
// library (present, documented, version-independent except BossCompat, strict-scan + precheck clean, the hardening in
// the code), the compiler (golden hashes per version, order independence, config.yml / plugin.yml / main class), edit
// without regenerating, the TS simulator (phases, weighted picks, cooldowns, despawn, enrage, minion caps, budget, drops,
// encounter waves) incl. the java.util.Random twin checked against the REAL server's `boss check` output, TS == the
// generated service JS, the prompt part, routing, the build request, the service workspace and the portal sync.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { BOSS_CAPS, BOSS_LIMITS, BOSS_BASES, MINION_BASES, ENTITY_CLASS, bossBudgetOf, bossJsonSchema, validateBoss, type BossDesign, type EncounterDesign } from "../lib/cyrus/designer/boss/spec";
import { BOSS_COMPONENTS, BOSS_COMPAT_META, bossCompatSource } from "../lib/cyrus/designer/boss/components";
import { BOSS_DEFAULTS, bossParams } from "../lib/cyrus/designer/boss/compile";
import { BossFight, JRandom, bossCheckLines, damageMultiplier, javaShuffle, scaledHealth, simulateEncounter, weightedPick } from "../lib/cyrus/designer/boss/simulate";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { applyGameplayEdits, recompileModWithEdits } from "../lib/cyrus/designer/gameplay/params";
import { designKind, validateGameplay } from "../lib/cyrus/designer/gameplay/spec";
import { COMPONENTS } from "../lib/cyrus/designer/components";
import { GAMEPLAY_COMPONENTS } from "../lib/cyrus/designer/gameplay/components";
import { designFeatures } from "../lib/cyrus/designer/spec";
import { decideDesignerRoute, hasBossDesigns, matchBossWords } from "../lib/cyrus/designer/route";
import { checkReturnedDesigns, DESIGN_KIND_MIME } from "../lib/cyrus/designer/sync";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { assetLines } from "../lib/cyrus-mods/doc";
import { readCyrusMeta } from "../lib/cyrus/meta";
import { VERSIONS } from "../lib/cyrus/versions/registry";
import { BOSS_NS as NS, BOSS_PLUGIN, loadBossFixtures, loadBrokenBoss } from "../scripts/cyrus/boss-golden";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-boss");
const ALL = () => loadBossFixtures();
const byId = (id: string) => ALL().find((d: { id: string }) => d.id === id);
const clone = <T,>(x: T): T => structuredClone(x);
const SUPPORTED = VERSIONS.map((v) => v.id).filter((v) => designFeatures(v).ok);
const ctx = (version = "1.21.11") => ({ version, namespace: NS, pluginName: BOSS_PLUGIN });
const compileOk = (d: unknown[], c = ctx()): ModCompileOk => { const r = compileMod(d, c); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const errorsOf = (inputs: unknown[], file?: string) => { const v = validateGameplay(inputs, { version: "1.21.11", namespace: NS }); return (file ? v.files.find((f) => f.id === file)?.errors ?? [] : v.errors).map((e) => e.code); };
const items = () => ALL().filter((d: { kind?: string }) => !d.kind);
const warden = (): BossDesign => clone(byId("ember_warden"));
const grave = (): BossDesign => clone(byId("grave_lord"));
const trial = (): EncounterDesign => clone(byId("ash_trial"));
/** A mod = the showcase items + one changed boss / encounter. */
const withBoss = (b: unknown) => [...items(), b];
const bossCodes = (b: unknown) => errorsOf(withBoss(b), (b as { id: string }).id);

describe("boss IR: the showcase mod", () => {
  it("is valid on every supported version; the kind discriminator; item / menu / quest kinds unchanged", () => {
    for (const v of SUPPORTED) { const r = validateGameplay(ALL(), { version: v, namespace: NS }); assert.ok(r.ok, `${v}: ${JSON.stringify(r.errors.slice(0, 3))}`); assert.deepEqual([r.bosses.length, r.encounters.length], [2, 1]); }
    assert.equal(validateGameplay(ALL(), { version: "26.3", namespace: NS }).ok, false, "26.3 fails closed");
    assert.equal(designKind({ kind: "boss" }), "boss"); assert.equal(designKind({ kind: "encounter" }), "encounter"); assert.equal(designKind({}), "item"); assert.equal(designKind({ kind: "dragon" }), null);
    assert.ok(errorsOf([{ ...warden(), kind: "dragon" }], undefined).includes("unknown_kind"));
  });
  it("the JSON Schema file is current and carries the caps", () => {
    const file = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/designer/boss.v1.schema.json"), "utf8"));
    assert.deepEqual(file, JSON.parse(JSON.stringify(bossJsonSchema())));
    const txt = JSON.stringify(file);
    assert.match(txt, /"maximum":1024/); assert.match(txt, /"wither_skeleton"|"enum"/);
  });
  it("closed base lists: every allowed base has a Bukkit class literal; minions are a subset", () => {
    for (const b of BOSS_BASES) assert.ok(ENTITY_CLASS[b], b);
    for (const m of MINION_BASES) assert.ok((BOSS_BASES as readonly string[]).includes(m), m);
    for (const bad of ["creeper", "ghast", "enderman", "wither", "ender_dragon", "warden", "slime", "silverfish", "phantom"]) assert.ok(!(BOSS_BASES as readonly string[]).includes(bad), bad);
  });
});

describe("boss IR: caps (min/max accepted, just outside refused)", () => {
  type Setter = (b: BossDesign, v: number) => void;
  const BOSS_SET: Partial<Record<keyof typeof BOSS_CAPS, Setter>> = {
    health: (b, v) => { b.stats.health = v; }, armor: (b, v) => { b.stats.armor = v; }, attackDamage: (b, v) => { b.stats.attackDamage = v; }, speed: (b, v) => { b.stats.speed = v; },
    knockbackResistance: (b, v) => { b.stats.knockbackResistance = v; }, followRange: (b, v) => { b.stats.followRange = v; },
    arenaRadius: (b, v) => { b.arena.radius = v; for (const a of b.attacks) a.targets.range = Math.min(a.targets.range, v); }, emptyDespawnSeconds: (b, v) => { b.arena.emptyDespawnSeconds = v; }, maxDurationSeconds: (b, v) => { b.arena.maxDurationSeconds = v; },
    spawnCooldownSeconds: (b, v) => { b.spawn!.cooldownSeconds = v; }, maxAlive: (b, v) => { b.spawn!.maxAlive = v; }, intervalTicks: (b, v) => { b.phases[0].intervalTicks = v; }, weight: (b, v) => { b.phases[0].attacks[0].weight = v; },
    cooldownTicks: (b, v) => { b.attacks[0].cooldownTicks = v; }, telegraphTicks: (b, v) => { b.attacks[0].telegraph!.ticks = v; }, targetMax: (b, v) => { b.attacks[1].targets.max = v; if (v > 3) b.attacks[1].actions = b.attacks[1].actions.filter((a) => a.type !== "launch_projectile"); },
    targetRange: (b, v) => { b.arena.radius = 64; b.attacks[0].targets.range = v; }, damage: (b, v) => { (b.attacks[0].actions[0] as { amount: number }).amount = v; }, strength: (b, v) => { (b.attacks[0].actions[1] as { strength: number }).strength = v; },
    vertical: (b, v) => { (b.attacks[0].actions[1] as { vertical: number }).vertical = v; }, projectileSpeed: (b, v) => { (b.attacks[1].actions[0] as { speed: number }).speed = v; }, projectileDamage: (b, v) => { (b.attacks[1].actions[0] as { damage: number }).damage = v; },
    particleCount: (b, v) => { (b.attacks[0].actions[2] as { count: number }).count = v; }, summonCount: (b, v) => { b.minions!.maxAlive = 16; (b.attacks[2].actions[0] as { count: number }).count = v; }, minionHealth: (b, v) => { (b.attacks[2].actions[0] as { health: number }).health = v; },
    minionsMax: (b, v) => { b.minions!.maxAlive = v; (b.attacks[2].actions[0] as { count: number }).count = 1; }, delayTicks: (b, v) => { (b.attacks[3].actions[1] as { delayTicks: number }).delayTicks = v; },
    healthPerPlayer: (b, v) => { b.scaling!.healthPerPlayer = v; }, damagePerPlayer: (b, v) => { b.scaling!.damagePerPlayer = v; }, maxPlayers: (b, v) => { b.scaling!.maxPlayers = v; }, difficulty: (b, v) => { b.difficulty!.hard = v; },
    dropCount: (b, v) => { b.drops!.items![0].count = v; }, dropChance: (b, v) => { b.drops!.items![0].chance = v; }, damageShare: (b, v) => { b.drops!.minDamageShare = v; }, xp: (b, v) => { b.drops!.xp = v; },
    below: (b, v) => { b.phases[2].below = v; if (v >= 0.6) b.phases[2].below = 0.59; },
  };
  for (const [cap, set] of Object.entries(BOSS_SET) as [keyof typeof BOSS_CAPS, Setter][]) {
    const [lo, hi] = BOSS_CAPS[cap];
    it(`${cap} ${lo}..${hi}`, () => {
      for (const v of [lo, hi]) { const b = warden(); set(b, v); const c = bossCodes(b); assert.ok(!c.includes("schema"), `${cap}=${v}: ${c}`); }
      const step = Number.isInteger(lo) && Number.isInteger(hi) && hi - lo >= 1 ? 1 : 0.001;
      for (const v of [lo - step, hi + step]) { if (cap === "below" && v > 1) continue; const b = warden(); set(b, v); assert.ok(bossCodes(b).includes("schema"), `${cap}=${v} must be refused`); }
    });
  }
  it("encounter caps: wave counts, waves, maxAlive, time limits", () => {
    const e = trial(); e.waves[0].spawns[0].count = 13; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e], "ash_trial").includes("schema"));
    const e2 = trial(); e2.maxAlive = 25; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e2], "ash_trial").includes("schema"));
    const e3 = trial(); e3.waves = Array.from({ length: 9 }, () => clone(trial().waves[0])); assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e3], "ash_trial").includes("schema"));
  });
});

describe("boss IR: adversarial corpus", () => {
  it("the deliberately broken boss is rejected with every semantic code (and compileMod refuses the mod)", () => {
    const codes = errorsOf([...ALL(), loadBrokenBoss()], "broken_boss").sort();
    for (const c of ["base_not_allowed", "first_phase", "phase_order", "unresolved_ref", "range_outside_arena", "no_target", "minions_undeclared", "self_effect_banned", "budget_projectiles", "drop_loop"]) assert.ok(codes.includes(c), `${c} in ${codes}`);
    assert.equal(compileMod([...ALL(), loadBrokenBoss()], ctx()).ok, false);
  });
  it("refuses code and commands in any form (closed action set, unknown keys)", () => {
    for (const bad of [{ type: "run_command", command: "op @a" }, { type: "damage", amount: 5, script: "x" }, { type: "explode", power: 4 }, { type: "set_block", block: "minecraft:tnt" }]) {
      const b = warden(); (b.attacks[0].actions as unknown[]).push(bad); assert.ok(bossCodes(b).includes("schema"), JSON.stringify(bad));
    }
    const b = warden(); (b as unknown as Record<string, unknown>).onDeath = "op @a"; assert.ok(bossCodes(b).includes("schema"));
  });
  it("budgets: particles at every target, projectiles, nested delays, summons", () => {
    const p = warden(); p.attacks[0].actions.push({ type: "spawn_particles", particle: "flame", count: 64, at: "target" }, { type: "spawn_particles", particle: "soul", count: 64, at: "target" }); assert.ok(bossCodes(p).includes("budget_particles"));
    const pr = warden(); pr.attacks[1].targets.max = 4; assert.ok(bossCodes(pr).includes("budget_projectiles"));
    const d = warden(); d.attacks[3].actions.push({ type: "delayed", delayTicks: 5, actions: [{ type: "delayed", delayTicks: 5, actions: [{ type: "delayed", delayTicks: 5, actions: [{ type: "heal_self", amount: 1 }] }] }] }); assert.ok(bossCodes(d).includes("too_deep"));
    const s = warden(); s.minions!.maxAlive = 16; s.attacks[2].actions.push({ type: "summon", entity: "minecraft:zombie", count: 3 }); assert.ok(bossCodes(s).includes("budget_summons"));
    assert.deepEqual(bossBudgetOf(warden().attacks[0].actions, 6), { actions: 14, entities: 12, tasks: 0, particles: 4, projectiles: 0, summons: 0, depth: 0 });
  });
  it("forbidden bases, minions, harmful self effects, invisibility", () => {
    const b = warden(); b.entity = "minecraft:ghast"; assert.ok(bossCodes(b).includes("base_not_allowed"));
    const m = warden(); (m.attacks[2].actions[0] as { entity: string }).entity = "minecraft:ravager"; assert.ok(bossCodes(m).includes("base_not_allowed"), "ravager is not a minion");
    const h = warden(); h.phases[1].selfEffects = [{ effect: "poison" }]; assert.ok(bossCodes(h).includes("harmful_self_effect"));
    const inv = warden(); inv.phases[1].selfEffects = [{ effect: "invisibility" }]; assert.ok(bossCodes(inv).includes("harmful_self_effect"));
  });
  it("reachability, summon-item conflicts, drop loops", () => {
    const g = grave(); g.spawn = { command: false };
    const noWave = trial(); noWave.waves = noWave.waves.filter((w) => !w.spawns.some((s) => s.boss));
    const mod = [...ALL().filter((d: { id: string }) => d.id !== "grave_lord" && d.id !== "ash_trial"), g, noWave];
    assert.ok(errorsOf(mod, "grave_lord").includes("unreachable_boss"));
    assert.ok(!errorsOf([...ALL().filter((d: { id: string }) => d.id !== "grave_lord"), g], "grave_lord").includes("unreachable_boss"), "an encounter wave spawns it");
    const e = trial(); e.start = { command: false }; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), e], "ash_trial").includes("unreachable_encounter"));
    const twice = trial(); twice.start!.item = "ember_core"; assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ash_trial"), twice], "ash_trial").includes("opener_conflict"));
    const menu = { schemaVersion: 1, kind: "menu", style: "chest", id: "core_menu", title: "Core", rows: 1, buttons: [{ slot: 0, icon: { material: "minecraft:stone" }, actions: [{ type: "close" }] }], openWith: { item: "ember_core" } };
    assert.ok(errorsOf([...ALL(), menu], "ember_warden").includes("opener_conflict"), "a menu opener cannot also summon");
    const clicky = { ...byId("ember_core"), abilities: [{ id: "zap", name: "Zap", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }] }] };
    assert.ok(errorsOf([...ALL().filter((d: { id: string }) => d.id !== "ember_core"), clicky], "ember_warden").includes("opener_conflict"));
    const loop = warden(); loop.drops!.items!.push({ item: "ember_core", count: 1, chance: 0.1 }); assert.ok(bossCodes(loop).includes("drop_loop"));
    const lt = warden(); lt.drops!.lootTable = "minecraft:chests/simple_dungeon"; assert.ok(bossCodes(lt).includes("foreign_namespace"));
    const lt2 = warden(); lt2.drops!.lootTable = `${NS}:boss/ember`;
    assert.ok(validateGameplay(withBoss(lt2), { version: "1.21.11", namespace: NS, assets: { lootTables: [] } }).files.find((f) => f.id === "ember_warden")!.errors.some((x) => x.code === "loot_table_not_in_project"));
    assert.ok(validateGameplay(withBoss(lt2), { version: "1.21.11", namespace: NS, assets: { lootTables: [`${NS}:boss/ember`] } }).files.find((f) => f.id === "ember_warden")!.ok);
  });
  it("encounters: wave caps, sources, boss counts, timer seconds, impossible time limits, too many bosses", () => {
    const rest = ALL().filter((d: { id: string }) => d.id !== "ash_trial");
    const over = trial(); over.waves[1].spawns[0].count = 9; assert.ok(errorsOf([...rest, over], "ash_trial").includes("wave_over_cap"));
    const both = trial(); (both.waves[0].spawns[0] as Record<string, unknown>).boss = "grave_lord"; assert.ok(errorsOf([...rest, both], "ash_trial").includes("spawn_source"));
    const two = trial(); two.waves[2].spawns[0].count = 2; assert.ok(errorsOf([...rest, two], "ash_trial").includes("boss_count"));
    const tm = trial(); delete tm.waves[1].seconds; assert.ok(errorsOf([...rest, tm], "ash_trial").includes("timer_seconds"));
    const tl = trial(); tl.failure.timeLimitSeconds = 60; tl.waves[1].seconds = 100; assert.ok(errorsOf([...rest, tl], "ash_trial").includes("time_limit_too_short"));
    const five = [...ALL(), ...["b_one", "b_two", "b_three"].map((id) => ({ ...grave(), id }))];
    assert.ok(errorsOf(five).includes("too_many_bosses"));
    const wm = trial(); wm.waves[0].spawns[0].entity = "minecraft:iron_golem"; assert.ok(errorsOf([...rest, wm], "ash_trial").includes("base_not_allowed"));
  });
});

describe("boss component library + compiler", () => {
  const c = compileOk(ALL());
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-boss-"));
  for (const f of c.files) { const abs = path.join(tmp, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); }
  const java = c.files.filter((f) => f.path.endsWith(".java"));
  it("every component (item + boss; no menu/quest library in a boss-only mod) is in the tree, documented", () => {
    for (const comp of [...COMPONENTS, ...BOSS_COMPONENTS]) {
      assert.ok(c.files.some((f) => f.path.endsWith(comp.file)), comp.id);
      assert.ok(comp.purpose.length > 10 && comp.tests.length >= 2 && comp.families.length === 2, comp.id);
    }
    assert.ok(c.files.some((f) => f.path.endsWith(BOSS_COMPAT_META.file)));
    for (const g of GAMEPLAY_COMPONENTS) assert.ok(!c.files.some((f) => f.path.endsWith(g.file)), `${g.id} not needed`);
    assert.ok(java.some((f) => f.path.endsWith("bosses/EmberWardenBoss.java")) && java.some((f) => f.path.endsWith("encounters/AshTrialEncounter.java")));
  });
  it("is deterministic and matches the golden hashes on every version (order independent)", () => {
    const golden = JSON.parse(fs.readFileSync(path.join(FX, "golden.json"), "utf8"));
    for (const v of SUPPORTED) {
      const r = compileOk(ALL(), ctx(v));
      assert.equal(r.hash, golden[v]?.hash, `${v} golden hash (regenerate: npx tsx scripts/cyrus/boss-golden.ts > test/fixtures/cyrus-boss/golden.json)`);
      assert.equal(compileOk([...ALL()].reverse(), ctx(v)).hash, r.hash, `${v} order`);
    }
  });
  it("only Compat + BossCompat vary per version (GENERIC_ attributes on 1.21.1)", () => {
    const a = compileOk(ALL(), ctx("1.21.1")), b = compileOk(ALL(), ctx("26.2"));
    const diff = a.files.filter((f) => b.files.find((x) => x.path === f.path)?.sha256 !== f.sha256).map((f) => f.path.split("/").pop());
    for (const d of diff) assert.ok(["Compat.java", "BossCompat.java", "plugin.yml"].includes(d!) || /Item\.java$/.test(d!), d);
    assert.match(bossCompatSource(designFeatures("1.21.1").ok ? (designFeatures("1.21.1") as { features: never }).features : ({} as never)), /Attribute\.GENERIC_MAX_HEALTH/);
    assert.match(bossCompatSource((designFeatures("26.2") as { features: never }).features), /Attribute\.MAX_HEALTH;/);
  });
  it("generated code: no reflection, threads, network, commands; strict source rules + precheck clean on every version", () => {
    const banned = /\b(Runtime|ProcessBuilder|java\.lang\.reflect|Class\.forName|getDeclared|MethodHandles|dispatchCommand|performCommand|new Thread|Executors|java\.net|HttpClient|System\.exit|setOp|getenv|ClassLoader|ObjectInputStream|Unsafe|ScriptEngine|runTaskAsynchronously|getRegionScheduler|getAsyncScheduler|setType|breakNaturally|createExplosion)\b/;
    for (const f of java) assert.doesNotMatch(f.content, banned, f.path);
    const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
    assert.deepEqual(S.scanSource(java.map((f) => ({ abs: path.join(tmp, f.path), rel: f.path }))), [], "strict source rules");
    const pre = require(path.join(ROOT, "services/modbuilder/precheck.js"));
    for (const v of SUPPORTED) {
      const r = compileOk(ALL(), ctx(v));
      const d = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-boss-pre-"));
      const files = r.files.filter((f) => f.path.endsWith(".java")).map((f) => { const abs = path.join(d, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); return { abs, rel: f.path }; });
      assert.deepEqual(pre.precheck(files, v), [], v);
    }
  });
  it("hardening is in the component code: not persistent, tagged, no vanilla loot, no griefing / burning / converting / friendly fire, caps = the IR limits", () => {
    const hub = c.files.find((f) => f.path.endsWith("designer/Bosses.java"))!.content;
    for (const must of ["m.setPersistent(false)", "e.getDrops().clear()", "e.setDroppedExp(0)", "onCombust", "onChangeBlock", "onTransform", "onEntitiesLoad", "Difficulty.PEACEFUL", "ourSource(be.getDamager())", "setImmuneToZombification(true)", "spawn(at, ", "MAX_LIVE = 4", "MAX_MINIONS = 48", "AI_PERIOD = 10", "ENTER_TARGETS = 8", "eq.setItemInMainHandDropChance(0f)", "cleanup: removed"]) assert.ok(hub.includes(must) || c.files.some((f) => f.content.includes(must)), must);
    const enc = c.files.find((f) => f.path.endsWith("designer/Encounters.java"))!.content;
    assert.match(enc, /MAX_LIVE = 2;/); assert.match(enc, /MAX_MOBS = 24;/);
    assert.equal(BOSS_LIMITS.liveBosses, 4); assert.equal(BOSS_LIMITS.liveMinions, 48); assert.equal(BOSS_LIMITS.encounterMobs, 24); assert.equal(BOSS_LIMITS.aiPeriodTicks, 10);
    const boss = c.files.find((f) => f.path.endsWith("bosses/EmberWardenBoss.java"))!.content;
    assert.match(boss, /at\.getWorld\(\)\.spawn\(at, WitherSkeleton\.class, false, c\)/);
    assert.match(boss, /fx\.summon\(c, Blaze\.class, null, p_attacks_cinders_a0_count, p_attacks_cinders_a0_health\)/);
    assert.match(boss, /eq\.setItemInMainHand\(display\("cinder_blade"\)\)/, "a design item is display gear without identity");
    assert.match(boss, /immune\.add\(EntityDamageEvent\.DamageCause\.FIRE_TICK\)/);
    assert.match(boss, /for \(LivingEntity t : c\.targets\(\)\) \{ if \(!c\.budget\(\)\.action\(\)\) return; fx\.damage\(c\.at\(t\), t, p_attacks_slam_a0_amount\); \}/);
    assert.ok(!/\b\d+\.\d+\b/.test(boss.split("public void load")[1].split("public void attack")[0].replace(/c\.(num|ticks|integer)\(B \+ "[^"]+", [^)]+\)/g, "").replace(/\* 20L/g, "")), "load() reads every number from config");
  });
  it("config.yml (general, items, bosses, encounters) and plugin.yml (boss nodes, no menu/quest nodes in a boss-only mod), main class", () => {
    const cfg = c.files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, /^bosses:\n  ember_warden:\n/m); assert.match(cfg, /^encounters:\n  ash_trial:\n/m); assert.match(cfg, /# max health \(before player scaling\) \(20\.0 to 1024\.0\)\n      health: 300\.0/);
    assert.doesNotMatch(cfg, /max_active_quests/);
    const yml = c.files.find((f) => f.path.endsWith("plugin.yml"))!.content;
    assert.match(yml, new RegExp(`${NS}\\.boss\\.admin:\\n    description: .*\\n    default: op`)); assert.match(yml, new RegExp(`${NS}\\.boss\\.summon:\\n    description: .*\\n    default: true`));
    assert.doesNotMatch(yml, /\.quests\.admin|\.menu\.others/);
    const main = c.files.find((f) => f.path.endsWith("BossTrials.java"))!.content;
    assert.match(main, /bosses = new Bosses\(designer\);\n        designer\.enable\(getCommand\("bosstrials"\)/); assert.match(main, /bosses\.enable\(getCommand\("bosstrials"\), List\.of\(new EmberWardenBoss\(bosses\), new GraveLordBoss\(bosses\)\), List\.of\(new AshTrialEncounter\(bosses\)\), true, false\);/);
    assert.match(main, /if \(bosses != null\) bosses\.disable\(\);\n        if \(designer != null\) designer\.disable\(\);/);
    assert.match(c.readme, /## Bosses/); assert.match(c.readme, /## Encounters/); assert.match(c.readme, /boss spawn <id>/);
  });
  it("a boss inside a menu/quest mod wires all three hubs (Gameplay keeps the command, Bosses wraps it)", () => {
    const menu = { schemaVersion: 1, kind: "menu", style: "chest", id: "boss_menu", title: "Bosses", rows: 1, buttons: [{ slot: 0, icon: { material: "minecraft:stone" }, actions: [{ type: "close" }] }] };
    const r = compileOk([...ALL(), menu]);
    const main = r.files.find((f) => f.path.endsWith("BossTrials.java"))!.content;
    assert.match(main, /gameplay = new Gameplay\(designer\);\n        bosses = new Bosses\(designer\);\n        designer\.enable\(null,/);
    assert.match(main, /, true, true\);/);
    assert.ok(r.files.some((f) => f.path.endsWith("designer/GameplayCommand.java")));
    assert.match(r.files.find((f) => f.path.endsWith("plugin.yml"))!.content, /quests\.admin/);
  });
});

describe("edit without regenerating: bosses and encounters", () => {
  const base = compileOk(ALL());
  it("health / damage / threshold / weight / wave count / drop edits change ONLY config.yml (+ README); config_version goes up", () => {
    const e = recompileModWithEdits(base, [
      { path: "bosses.ember_warden.stats.health", value: 450 }, { path: "bosses.ember_warden.attacks.slam.a0.amount", value: 9 }, { path: "bosses.ember_warden.phases.p2.below", value: 0.7 },
      { path: "bosses.ember_warden.phases.p1.weights.volley", value: 5 }, { path: "encounters.ash_trial.waves.w1.s0.count", value: 6 }, { path: "bosses.ember_warden.drops.d0.chance", value: 0.9 },
      { path: "bosses.ember_warden.attacks.leap.a1.n0.amount", value: 12 }, { path: "bosses.grave_lord.messages.defeat", value: "The Grave Lord falls." },
    ], ctx());
    assert.ok(e.ok, JSON.stringify(!e.ok && e.errors));
    if (!e.ok) return;
    assert.equal(e.diff.javaChanged, false);
    assert.deepEqual(e.diff.changed.map((x) => x.path), ["src/main/resources/config.yml"]);
    assert.equal(e.result.configVersion, 2);
    assert.equal(e.result.bosses.find((b) => b.id === "grave_lord")!.messages!.defeat, "The Grave Lord falls.", "a missing object on the way is created");
  });
  it("a structural change (another action) changes that boss's Java file (+ config)", () => {
    const b = warden(); b.attacks[0].actions.push({ type: "heal_self", amount: 5 });
    const r = compileOk([...ALL().filter((d: { id: string }) => d.id !== "ember_warden"), b]);
    const changed = r.files.filter((f) => base.files.find((x) => x.path === f.path)?.sha256 !== f.sha256).map((f) => f.path.split("/").pop());
    assert.deepEqual(changed.sort(), ["EmberWardenBoss.java", "config.yml"]);
  });
  it("refuses out-of-range values, wrong types and non-parameters", () => {
    const m = { items: base.designs, menus: [], quests: [], bosses: base.bosses, encounters: base.encounters };
    assert.equal(applyGameplayEdits(m, [{ path: "bosses.ember_warden.stats.health", value: 5000 }]).ok, false);
    assert.equal(applyGameplayEdits(m, [{ path: "bosses.ember_warden.stats.health", value: "lots" }]).ok, false);
    assert.equal(applyGameplayEdits(m, [{ path: "bosses.ember_warden.entity", value: "minecraft:warden" }]).ok, false);
    const params = bossParams(warden());
    assert.ok(params.every((p) => Array.isArray(p.ptr) && p.ptr.length > 0 && p.owner === "boss"));
    assert.ok(params.length > 60);
  });
});

describe("TS reference simulator", () => {
  it("java.util.Random twin == the REAL server's /<mod> boss check (recorded on node-2 Paper 1.21.11 + 26.2)", () => {
    const jvm = JSON.parse(fs.readFileSync(path.join(FX, "jvm-check.json"), "utf8"));
    const c = compileOk(ALL());
    assert.deepEqual(bossCheckLines(c.bosses, c.encounters), jvm.lines);
  });
  it("Random primitives: nextInt power-of-two and general bounds, shuffle, weighted pick", () => {
    const r = new JRandom(42);
    const ints = Array.from({ length: 6 }, () => r.nextInt(10));
    assert.ok(ints.every((x) => x >= 0 && x < 10));
    const p2 = new JRandom(5); assert.ok(Array.from({ length: 50 }, () => p2.nextInt(8)).every((x) => x >= 0 && x < 8));
    assert.deepEqual(javaShuffle([0, 1, 2, 3, 4, 5], new JRandom(42)).sort(), [0, 1, 2, 3, 4, 5]);
    const w = new JRandom(7); const picks = Array.from({ length: 300 }, () => weightedPick([3, 1], w));
    assert.ok(picks.filter((x) => x === 0).length > 180, "weight 3 is picked about 3x as often");
  });
  it("scaling: health per player (clamped 1024), damage by difficulty / players / enrage", () => {
    const b = warden();
    assert.equal(scaledHealth(b, 1), 300); assert.equal(scaledHealth(b, 4), 615); assert.equal(scaledHealth(b, 50), 825, "maxPlayers 6");
    const big = warden(); big.stats.health = 1000; assert.equal(scaledHealth(big, 6), 1024);
    assert.equal(damageMultiplier(b, "easy", 1, false), 0.75); assert.equal(damageMultiplier(b, "hard", 1, false), 1.3); assert.ok(Math.abs(damageMultiplier(b, "normal", 4, true) - 1.45 * 1.5) < 1e-9);
  });
  it("a fight: one-way phases, onEnter, weighted attacks with cooldowns, telegraph, drops by damage share", () => {
    const players = [{ id: "alice", pos: [3, 64, 0] as [number, number, number], health: 20 }, { id: "bob", pos: [0, 64, 4] as [number, number, number], health: 20 }];
    const f = new BossFight(warden(), players, { seed: 99 });
    assert.equal(f.max, 405, "2 players: 300 x (1 + 0.35)");
    f.run([{ t: 100, kind: "damage", by: "alice", amount: 200 }, { t: 140, kind: "heal", amount: 300 }, { t: 200, kind: "damage", by: "bob", amount: 10 }], 300);
    const phases = f.log.filter((l) => l.kind === "phase").map((l) => l.detail);
    assert.deepEqual(phases, ["p2 at 51%"], "healing never goes back a phase");
    assert.equal(f.phase, 1);
    const attacks = f.log.filter((l) => l.kind === "attack");
    assert.ok(attacks.length >= 3);
    for (const a of attacks.filter((x) => x.detail.startsWith("slam"))) assert.match(a.detail, /\(telegraph 20\)/);
    const slams = attacks.filter((x) => x.detail.startsWith("slam")).map((x) => x.t);
    for (let i = 1; i < slams.length; i++) assert.ok(slams[i] - slams[i - 1] >= 80, "slam cooldown 80 ticks");
    f.run([{ t: 310, kind: "damage", by: "alice", amount: 1000 }], 320);
    assert.equal(f.ended, "defeated");
    assert.deepEqual(f.drops.map((d) => d.player), ["alice"], "bob did under 10% of the damage");
    assert.equal(f.drops[0].counts.length, 3);
  });
  it("empty arena despawn, time out enrage, minion cap, players outside the arena are not participants", () => {
    const away = new BossFight(grave(), [{ id: "carl", pos: [100, 64, 0], health: 20 }]);
    away.run([], 400);
    assert.equal(away.ended, "despawned"); assert.match(away.log.at(-1)!.detail, /no players for 10 s/);
    const e = warden(); e.arena.maxDurationSeconds = 60;
    const f = new BossFight(e, [{ id: "dana", pos: [2, 64, 2], health: 1000 }], { seed: 3 });
    f.run([], 1300);
    assert.ok(f.enraged && f.log.some((l) => l.kind === "enrage"));
    const m = new BossFight(warden(), [{ id: "eve", pos: [1, 64, 1], health: 1000 }]);
    const cinders = warden().attacks.find((a) => a.id === "cinders")!;
    for (let i = 0; i < 3; i++) m.execute(cinders.actions, [], "cinders");
    assert.equal(m.minions.length, 4, "minions.maxAlive 4");
  });
  it("the per-attack budget stops a hand-edited flood (the same 64-action Budget as the item graph)", () => {
    const b = warden(); b.attacks[0].actions = Array.from({ length: 12 }, () => ({ type: "damage", amount: 1 }));
    const f = new BossFight(b, Array.from({ length: 8 }, (_, i) => ({ id: `p${i}`, pos: [1, 64, i % 3] as [number, number, number], health: 1000 })));
    const used = f.execute(b.attacks[0].actions, [...f.participants()], "flood");
    assert.equal(used.actions, 64); assert.ok(f.log.some((l) => l.kind === "budget"));
  });
  it("encounter waves: cleared -> delay -> timer -> boss -> complete; empty arena fails", () => {
    const log = simulateEncounter(trial(), [{ t: 100, kill: 5 }, { t: 300, kill: 4 }, { t: 800, kill: 1 }], 2000);
    assert.deepEqual(log.map((l) => l.kind), ["wave", "wave", "wave", "complete"]);
    assert.deepEqual(log.filter((l) => l.kind === "wave").map((l) => l.detail), ["1/3: 5 spawned", "2/3: 4 spawned", "3/3: 1 spawned"]);
    const failed = simulateEncounter(trial(), [], 3000, () => false);
    assert.equal(failed.at(-1)!.kind, "failed");
  });
});

describe("service copy, prompt, routing, request, sync, mod page", () => {
  const DZ = require(path.join(ROOT, "services/modbuilder/designer-spec.js"));
  it("TS == generated JS: validation codes and compile hashes on the showcase and the broken boss", () => {
    for (const v of ["1.21.1", "1.21.11", "26.2"]) {
      for (const corpus of [ALL(), [...ALL(), loadBrokenBoss()]]) assert.deepEqual(DZ.validateGameplay(corpus, { version: v, namespace: NS }).errors.map((e: { code: string }) => e.code), validateGameplay(corpus, { version: v, namespace: NS }).errors.map((e) => e.code));
      assert.equal(DZ.compileMod(ALL(), ctx(v)).hash, compileOk(ALL(), ctx(v)).hash, v);
    }
    assert.deepEqual(DZ.BOSS_LIMITS, BOSS_LIMITS);
  });
  it("prompt: the BOSSES AND ENCOUNTERS part only with design + bosses; the example validates; Dockerfile copies it", () => {
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    const d = P.systemPrompt("1.21.11", { design: true });
    assert.doesNotMatch(d, /BOSSES AND ENCOUNTERS/);
    assert.equal(P.systemPrompt("1.21.11", { bosses: true }), P.systemPrompt("1.21.11", {}), "bosses alone adds nothing");
    const b = P.systemPrompt("1.21.11", { design: true, bosses: true });
    assert.ok(b.startsWith(d) && /BOSSES AND ENCOUNTERS \(this build uses them\)/.test(b));
    assert.deepEqual(P.BOSS_MAX, { bosses: BOSS_LIMITS.maxBosses, encounters: BOSS_LIMITS.maxEncounters });
    for (const base of BOSS_BASES) assert.ok(P.BOSS_SECTION.includes(base), `prompt lists ${base}`);
    const ex = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/designer-boss-example.json"), "utf8"));
    const r = validateGameplay(Object.values(ex), { version: "1.21.11", namespace: "nx_abcd1234" });
    assert.ok(r.ok, JSON.stringify(r.errors));
    assert.match(P.assetsBlock({ texture: false, sound: false, design: true, bosses: true, namespace: NS }), new RegExp(`${NS}\\.boss`));
    assert.match(fs.readFileSync(path.join(ROOT, "services/modbuilder/Dockerfile"), "utf8"), /designer-boss-example\.json/);
  });
  it("routing: boss words, 'boss bar' alone is not a boss, honest exclusions, flag off, existing bosses keep the part", () => {
    const base = { mcVersion: "1.21.11", on: true };
    assert.deepEqual(matchBossWords("a boss fight with three phases"), ["boss:boss fight"]);
    assert.deepEqual(matchBossWords("waves of zombies in an arena"), ["boss:waves of zombies"]);
    assert.deepEqual(matchBossWords("show my mana on the boss bar"), []);
    assert.deepEqual(matchBossWords("a custom boss model with animations"), []);
    assert.deepEqual(matchBossWords("an ender dragon boss rework"), []);
    assert.deepEqual(matchBossWords("a dungeon with a boss"), []);
    const r = decideDesignerRoute({ ...base, text: "make a fire boss with phases and minions" });
    assert.equal(r.route, true); assert.equal(r.bosses, true); assert.ok(r.limits.some((l) => /No custom boss models/.test(l) && l.length <= 300));
    assert.deepEqual(decideDesignerRoute({ ...base, text: "a boss", on: false }), { route: false, matched: [], notices: [], limits: [] });
    assert.equal(decideDesignerRoute({ ...base, text: "a sword with a cooldown" }).bosses, undefined, "item builds are unchanged");
    assert.equal(decideDesignerRoute({ ...base, text: "make it harder", existingBosses: true }).bosses, true);
    assert.ok(hasBossDesigns({ assets: { designs: [{ kind: "boss" }] } }) && !hasBossDesigns({ assets: { designs: [{ kind: "quest" }] } }));
    const meta = readCyrusMeta({ assets: { requested: [], allowed: [], notices: [], designer: { route: true, matched: ["boss:boss fight"], limits: [], bosses: true } } });
    assert.equal(meta.assets?.designer?.bosses, true);
  });
  it("resolveBuildAssets: a boss request gets design + bosses; not plan-gated; byte-identical when off; parseAssetsRequest", async () => {
    let tierCalls = 0;
    const deps = { tierOf: async () => { tierCalls++; return "free"; }, projectForRootBuild: async () => ({ id: "cp1", namespace: NS }), createProject: async () => ({ id: "cpx", namespace: NS }) };
    const text = "a two-phase boss fight with a boss bar and minions";
    assert.deepEqual(await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => false }), { plan: null, service: null, meta: null });
    const on = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => true });
    assert.deepEqual(on.service, { texture: false, sound: false, namespace: NS, design: true, bosses: true });
    assert.equal(on.meta!.designer!.bosses, true);
    assert.equal(tierCalls, 0);
    const TX = require(path.join(ROOT, "services/modbuilder/textures.js"));
    const ok = () => true;
    assert.equal(TX.parseAssetsRequest({ namespace: NS, design: true, bosses: true }, "1.21.11", new Set(), ok, ok).bosses, true);
    assert.match(TX.parseAssetsRequest({ namespace: NS, bosses: true }, "1.21.11", new Set(), ok, ok).error, /needs assets\.design/);
    assert.match(TX.parseAssetsRequest({ namespace: NS, design: true, bosses: 1 }, "1.21.11", new Set(), ok, ok).error, /true or false/);
  });
  it("service workspace: kind caps, loot tables from the data pack spec, compile == TypeScript", () => {
    const DZS = require(path.join(ROOT, "services/modbuilder/designs.js"));
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-boss-ws-"));
    fs.mkdirSync(path.join(ws, "assets/designs"), { recursive: true });
    fs.mkdirSync(path.join(ws, "assets/datapack"), { recursive: true });
    fs.writeFileSync(path.join(ws, "assets/datapack/loot.json"), JSON.stringify({ resources: [{ type: "loot_table", id: "boss/ember" }] }));
    for (const d of ALL()) fs.writeFileSync(path.join(ws, `assets/designs/${d.id}.json`), JSON.stringify(d));
    fs.writeFileSync(path.join(ws, "assets/designs/broken_boss.json"), JSON.stringify(loadBrokenBoss()));
    assert.deepEqual(DZS.assetKeysOf(ws, NS, "1.21.11").lootTables, [`${NS}:boss/ember`]);
    const r = DZS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: "1.21.11" });
    assert.deepEqual(r.results.filter((x: { ok: boolean }) => !x.ok).map((x: { name: string }) => x.name), ["broken_boss"]);
    assert.deepEqual(r.results.filter((x: { ok: boolean }) => x.ok).map((x: { kind: string }) => x.kind).sort(), ["boss", "boss", "encounter", "item", "item", "item"]);
    fs.rmSync(path.join(ws, "assets/designs/broken_boss.json"));
    const ok = DZS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: "1.21.11" });
    const c = DZS.compileWorkspaceDesigns(ws, { pluginName: BOSS_PLUGIN, mcVersion: "1.21.11", assets: { namespace: NS } }, ok.results.map((x: { spec: unknown }) => x.spec));
    assert.ok(c.ok, JSON.stringify(c.errors)); assert.deepEqual(c.summary.counts, { items: 3, menus: 0, quests: 0, bosses: 2, encounters: 1 });
    assert.equal(c.summary.hash, compileOk(ALL()).hash, "service == TypeScript");
    assert.ok(fs.existsSync(path.join(ws, "src/main/java/dev/nxeon/plugins/bosstrials/bosses/EmberWardenBoss.java")));
  });
  it("portal sync: re-validates boss kinds, re-compiles (serviceAgreed), drops a tampered boss, mime per kind", () => {
    const svc = compileOk(ALL());
    const list = ALL().map((d: { id: string }) => ({ name: d.id, path: `assets/designs/${d.id}.json`, sha256: "x", spec: d }));
    const r = checkReturnedDesigns(list, { namespace: NS, mcVersion: "1.21.11", pluginName: BOSS_PLUGIN, compile: { hash: svc.hash, configVersion: 1 } });
    assert.equal(r.serviceAgreed, true);
    assert.deepEqual(r.ok.map((x) => x.kind).sort(), ["boss", "boss", "encounter", "item", "item", "item"]);
    const bad = warden(); bad.entity = "minecraft:wither";
    const t = checkReturnedDesigns(list.map((x) => (x.name === "ember_warden" ? { ...x, spec: bad } : x)), { namespace: NS, mcVersion: "1.21.11", pluginName: BOSS_PLUGIN, compile: { hash: svc.hash } });
    assert.ok(t.dropped.map((d) => d.name).includes("ember_warden")); assert.equal(t.serviceAgreed, false);
    assert.match(t.notices[0], /^Boss design "ember_warden" was left out/);
    assert.equal(DESIGN_KIND_MIME.boss, "application/vnd.nxeon.boss-design+json"); assert.equal(DESIGN_KIND_MIME.encounter, "application/vnd.nxeon.encounter-design+json");
  });
  it("mod page lines: 'Includes N bosses and M encounters'", () => {
    const row = { version: "1.21.11", specSha256: "x", compileHash: "y", serviceAgreed: true, configVersion: 1, settings: 3, abilities: 0 };
    const a = { status: "none" as const, namespace: NS, projectId: "p", revisionId: "r", textures: [], dropped: [], pack: null, loader: null, notices: [],
      designs: [{ ...row, name: "ember_warden", kind: "boss" as const }, { ...row, name: "grave_lord", kind: "boss" as const }, { ...row, name: "ash_trial", kind: "encounter" as const }] };
    assert.ok(assetLines(a).some((l) => /^Includes 2 bosses and 1 encounter;/.test(l)), JSON.stringify(assetLines(a)));
  });
  it("defaults documented in BOSS_DEFAULTS are the ones the compiler writes", () => {
    const cfg = compileOk(ALL()).files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, new RegExp(`difficulty:\\n(?:.*\\n){2}      normal: ${BOSS_DEFAULTS.difficultyNormal.toFixed(1)}`));
    assert.equal(validateBoss(grave(), { version: "1.21.11", namespace: NS, features: (designFeatures("1.21.11") as { features: never }).features, items: new Map() }).ok, true);
  });
});

