it("menu/quest designer build: MENUS AND QUESTS part, kind-aware checks, compiled with the gameplay library (service == TypeScript)", async () => {
  const before = log().length;
  await api("POST", "/builds", { id: "pipe-gp-ok-01", prompt: "Quest board GPBUILD", mcVersion: "1.21.11", assets: { design: true, gameplay: true, namespace: "nx_abcd1234" } });
  const r = await waitDone("pipe-gp-ok-01");
  assert.equal(r.status, "succeeded", JSON.stringify(ev(r)) + svcErr.slice(-2000));
  const call = log()[before];
  assert.equal(call.design, true); assert.equal(call.gameplay, true);
  const paths = r.files.map((f: { path: string }) => f.path);
  for (const p of ["designer/MenuManager.java", "designer/QuestStore.java", "menus/QuestBoardMenu.java", "menus/TraderMenu.java", "quests/FirstHuntQuest.java"]) assert.ok(paths.includes(`src/main/java/dev/nxeon/plugins/guildboard/${p}`), p);
  assert.ok(!paths.some((p: string) => p.endsWith("VaultMoney.java")));
  assert.deepEqual(r.assetResult.designs.map((d: { name: string; kind?: string }) => `${d.kind ?? "item"}:${d.name}`).sort(), ["menu:quest_board", "menu:trader", "quest:first_hunt"]);
  assert.deepEqual(r.assetResult.designCompile.counts, { items: 0, menus: 2, quests: 1 });
  assert.deepEqual(r.assetResult.designCompile.deps, []);
  assert.equal(r.assetResult.designPromptVersion, "mb-design-2026-10-10.1+mb-gameplay-2026-10-10.1");
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { compileMod } = require(path.join(ROOT, "lib/cyrus/designer/gameplay/compile")) as typeof import("../lib/cyrus/designer/gameplay/compile");
  const ex = JSON.parse(fs.readFileSync(path.join(SVC, "designer-gameplay-example.json"), "utf8"));
  const ts = compileMod(Object.values(ex), { version: "1.21.11", namespace: "nx_abcd1234", pluginName: "GuildBoard", assets: { models: [], sounds: [], advancements: [] } });
  assert.ok(ts.ok && r.assetResult.designCompile.hash === ts.hash, "service bundle == TypeScript compiler");
  assert.ok(r.config.some((c: { key: string }) => c.key === "quests.first_hunt.steps.hunt.o0.count"));
  assert.ok(r.events.some((e: { message: string }) => /Compiled 0 item, 2 menu and 1 quest designs into the plugin/.test(e.message)));
});

it("a money price puts the allowlisted Vault API on the javac classpath (not installed here: the build stops clearly); gameplay without design is a 400", async () => {
  await api("POST", "/builds", { id: "pipe-gp-money-02", prompt: "Quest board GPBUILD GPMONEY", mcVersion: "1.21.11", assets: { design: true, gameplay: true, namespace: "nx_abcd1234" } });
  const r = await waitDone("pipe-gp-money-02");
  assert.equal(r.status, "failed");
  assert.match(r.error, /dependency this plugin needs is not available/);
