// Cyrus R4 HUD and glyphs: the HUD design IR (`"kind":"hud"` files in assets/designs, same id space as the other
// designs). Honest limits, by construction: a vanilla client with a server-pushed resource pack can show TEXT in three
// places a server controls (the action bar line above the hotbar, boss bar titles, the scoreboard sidebar); a HUD here is
// glyph-based text in those three channels: small pixel-art glyphs in this mod's OWN font (`<ns>:hud`, a bitmap font +
// a space font for pixel offsets), bars made of glyph segments, values (health, food, XP, air, an ability's charges or
// cooldown, a boss's health) and plain text. NO core shaders, no free-form positioning, no widgets anywhere on screen
// (those need a client mod), no animation beyond the update rate. Glyph codepoints come from the project's glyph block
// (lib/cyrus/engine-core/identifiers.ts: the namespace's home block in the supplementary Private Use Area); since they
// live in the mod's own font they cannot clash with another pack's glyphs (the conflict engine still sees them).
import { z } from "zod";
import { buildIdentifier, glyphBlockStart, glyphHomeBlock, GLYPH_BLOCK, isGlyphCodepoint, type IdentRecord } from "../../engine-core/identifiers";
import { Color, Key, Text, type DzIssue, type ItemDesign } from "../spec";
import type { BossDesign } from "../boss/spec";

export const HUD_SPEC_VERSION = 1;
export const HUD_LIMITS = {
  maxHuds: 2, maxGlyphs: 24, maxGlyphsPerMod: 32, maxSpacesPerMod: 16, maxBars: 6, maxParts: 12, maxSidebarLines: 8, maxLineParts: 8, maxTitleParts: 4,
  maxGlyphPixels: 16, maxPaletteColors: 8, maxSpecBytes: 32 * 1024,
  /** An action bar line wider than this (estimated, at GUI scale 1 in font pixels) is warned about: it may not fit small windows. */
  actionbarWarnPx: 240,
} as const;
export const HUD_CAPS = {
  glyphHeight: [4, 32], ascent: [-32, 32], segments: [1, 20], spacePx: [-64, 64], updateTicks: [10, 40], textChars: [1, 40],
} as const satisfies Record<string, readonly [number, number]>;
export type HudCapName = keyof typeof HUD_CAPS;

/** Built-in pixel-art glyphs (Cyrus-authored, tinted by `color`): '#' main, '+' highlight, '-' shadow, 'o' outline, '.' clear. */
export const GLYPH_PRESETS: Record<string, string[]> = {
  heart: [".oo.oo.", "o++o#-o", "o+###-o", "o####-o", ".o##-o.", "..o-o..", "...o..."],
  heart_half: [".oo.oo.", "o++o..o", "o+#...o", "o##...o", ".o#..o.", "..o.o..", "...o..."],
  heart_empty: [".oo.oo.", "o..o..o", "o.....o", "o.....o", ".o...o.", "..o.o..", "...o..."],
  bar_full: ["ooooooooo", "o+++++++o", "o#######o", "o-------o", "ooooooooo"],
  bar_half: ["ooooooooo", "o++++...o", "o####...o", "o----...o", "ooooooooo"],
  bar_empty: ["ooooooooo", "o.......o", "o.......o", "o.......o", "ooooooooo"],
  drop: ["...o...", "..o+o..", ".o+##o.", "o+###-o", "o####-o", ".o#--o.", "..ooo.."],
  shield: ["ooooooo", "o++#--o", "o+##--o", "o###--o", ".o##-o.", "..o-o..", "...o..."],
  star: ["...o...", "..o+o..", "oo+##oo", "o+###-o", ".o##-o.", "o-o.o-o", "oo...oo"],
  coin: [".ooooo.", "o+++##o", "o+#o#-o", "o#oo#-o", "o##o#-o", "o##--oo", ".ooooo."],
  skull: [".ooooo.", "o+###-o", "o#o#o-o", "o#####o", ".o#-#o.", ".o#o#o.", "..ooo.."],
  sword: ["......o", ".....o+", "....o+o", "o..o+o.", ".oo+o..", "..oo...", ".o..o.."],
  bolt: ["...oo..", "..o+o..", ".o+o...", "o+###o.", "...o+o.", "..o+o..", "..oo..."],
  flame: ["...o...", "..o+o..", ".o+#o..", ".o##-o.", "o+##-o.", "o###-o.", ".oooo.."],
  dot: [".ooo.", "o+#-o", "o##-o", "o#--o", ".ooo."],
};
export const PRESET_NAMES = Object.keys(GLYPH_PRESETS) as [string, ...string[]];

export const GlyphSchema = z.strictObject({
  name: Key,
  /** A built-in glyph tinted with `color`, OR `pixels` (rows of palette characters, '.' = clear) with a `palette`. */
  preset: z.enum(PRESET_NAMES).optional(),
  color: z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),
  pixels: z.array(z.string().min(1).max(HUD_LIMITS.maxGlyphPixels).regex(/^[.a-zA-Z0-9#+*o-]+$/)).min(1).max(HUD_LIMITS.maxGlyphPixels).optional(),
  palette: z.record(z.string().regex(/^[a-zA-Z0-9#+*o-]$/), z.string().regex(/^#[0-9a-fA-F]{6}$/)).optional(),
  /** Shown height in font pixels (vanilla letters are 8; default: the art's size). */
  height: z.number().int().min(HUD_CAPS.glyphHeight[0]).max(HUD_CAPS.glyphHeight[1]).optional(),
  /** Pixels above the text baseline (default height - 1, like letters); must not exceed height. Negative moves it down. */
  ascent: z.number().int().min(HUD_CAPS.ascent[0]).max(HUD_CAPS.ascent[1]).optional(),
});
export type GlyphDef = z.infer<typeof GlyphSchema>;

export const SourceSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("health") }),
  z.strictObject({ type: z.literal("food") }),
  z.strictObject({ type: z.literal("xp_level") }),
  z.strictObject({ type: z.literal("air") }),
  /** Charges left of an ability of this mod's design item (a mana / ammo bar). */
  z.strictObject({ type: z.literal("ability_charges"), item: Key, ability: Key }),
  /** An ability's cooldown: full = ready. */
  z.strictObject({ type: z.literal("ability_cooldown"), item: Key, ability: Key }),
  /** The health of the nearest live boss of this mod whose arena the player is in (empty when there is none). */
  z.strictObject({ type: z.literal("boss_health"), boss: Key }),
]);
export type HudSource = z.infer<typeof SourceSchema>;
export const BarSchema = z.strictObject({ id: Key, source: SourceSchema, segments: z.number().int().min(HUD_CAPS.segments[0]).max(HUD_CAPS.segments[1]), full: Key, half: Key.optional(), empty: Key, gap: z.number().int().min(-8).max(8).optional() });
export type HudBar = z.infer<typeof BarSchema>;
export const PartSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("text"), text: Text(HUD_CAPS.textChars[1]), color: Color.optional() }),
  z.strictObject({ type: z.literal("glyph"), glyph: Key }),
  z.strictObject({ type: z.literal("bar"), bar: Key }),
  z.strictObject({ type: z.literal("value"), source: SourceSchema, format: z.enum(["int", "percent", "fraction"]).optional(), color: Color.optional() }),
  /** Move the next part by px font pixels (negative = left): the space font, the only positioning a server has. */
  z.strictObject({ type: z.literal("space"), px: z.number().int().min(HUD_CAPS.spacePx[0]).max(HUD_CAPS.spacePx[1]).refine((v) => v !== 0, "0 moves nothing") }),
]);
export type HudPart = z.infer<typeof PartSchema>;
export const ShowSchema = z.discriminatedUnion("when", [
  z.strictObject({ when: z.literal("always") }),
  z.strictObject({ when: z.literal("holding"), item: Key }),
  z.strictObject({ when: z.literal("in_boss_arena"), boss: Key }),
]);
export type HudShow = z.infer<typeof ShowSchema>;
const Parts = (max: number) => z.array(PartSchema).min(1).max(max);
export const HudDesignSchema = z.strictObject({
  schemaVersion: z.literal(HUD_SPEC_VERSION),
  kind: z.literal("hud"),
  id: Key,
  glyphs: z.array(GlyphSchema).max(HUD_LIMITS.maxGlyphs),
  bars: z.array(BarSchema).max(HUD_LIMITS.maxBars).optional(),
  /** Every channel is optional; at least one is needed. */
  actionbar: z.strictObject({ parts: Parts(HUD_LIMITS.maxParts), show: ShowSchema.optional() }).optional(),
  bossbar: z.strictObject({ parts: Parts(HUD_LIMITS.maxParts), progress: SourceSchema.optional(), color: z.enum(["pink", "blue", "red", "green", "yellow", "purple", "white"]).optional(), overlay: z.enum(["progress", "notched_6", "notched_10", "notched_12", "notched_20"]).optional(), show: ShowSchema.optional() }).optional(),
  sidebar: z.strictObject({ title: Parts(HUD_LIMITS.maxTitleParts), lines: z.array(Parts(HUD_LIMITS.maxLineParts)).min(1).max(HUD_LIMITS.maxSidebarLines), show: ShowSchema.optional() }).optional(),
  /** Ticks between updates (the action bar is re-sent each time; it fades after about 3 s without one). */
  updateTicks: z.number().int().min(HUD_CAPS.updateTicks[0]).max(HUD_CAPS.updateTicks[1]),
});
export type HudDesign = z.infer<typeof HudDesignSchema>;
export type HudChannel = "actionbar" | "bossbar" | "sidebar";
export const CHANNELS: HudChannel[] = ["actionbar", "bossbar", "sidebar"];

export function hudJsonSchema(): Record<string, unknown> {
  return { $schema: "https://json-schema.org/draft/2020-12/schema", title: "Cyrus HUD designs v1 (glyph HUD text in the action bar, boss bars and the sidebar)", ...z.toJSONSchema(HudDesignSchema, { io: "input", reused: "ref" }) };
}

// -------------------------------------------------------------------------------------------- glyph art + codepoints
export type GlyphArt = { width: number; height: number; px: (string | null)[][] };
const rgb = (hex: string) => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
const hex2 = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
const mix = (a: string, b: string, t: number) => { const x = rgb(a), y = rgb(b); return `#${hex2(x[0] + (y[0] - x[0]) * t)}${hex2(x[1] + (y[1] - x[1]) * t)}${hex2(x[2] + (y[2] - x[2]) * t)}`; };
export const PRESET_DEFAULT_COLORS: Record<string, string> = { heart: "#e03a3a", heart_half: "#e03a3a", heart_empty: "#e03a3a", bar_full: "#3b6be8", bar_half: "#3b6be8", bar_empty: "#3b6be8", drop: "#3b8be8", shield: "#9aa7b8", star: "#f2c230", coin: "#f2b630", skull: "#d8d2c4", sword: "#c8d0dc", bolt: "#f2d830", flame: "#f07a20", dot: "#ffffff" };
/** The pixel art of a glyph (rows top to bottom; null = transparent). Deterministic. */
export function glyphArt(g: GlyphDef): GlyphArt {
  const rows = g.preset ? GLYPH_PRESETS[g.preset] : g.pixels ?? [];
  const width = Math.max(...rows.map((r) => r.length));
  let pal: Record<string, string>;
  if (g.preset) {
    const c = (g.color ?? PRESET_DEFAULT_COLORS[g.preset] ?? "#ffffff").toLowerCase();
    pal = { "#": c, "+": mix(c, "#ffffff", 0.45), "-": mix(c, "#000000", 0.35), o: mix(c, "#000000", 0.72) };
  } else pal = Object.fromEntries(Object.entries(g.palette ?? {}).map(([k, v]) => [k, v.toLowerCase()]));
  return { width, height: rows.length, px: rows.map((r) => Array.from({ length: width }, (_, x) => (r[x] && r[x] !== "." ? pal[r[x]] ?? null : null))) };
}
/** Font metrics (bitmap provider): the PNG is a square cell of `size` pixels (art top-left, transparent padding is trimmed by the game). */
export function glyphMetrics(g: GlyphDef): { size: number; height: number; ascent: number } {
  const a = glyphArt(g);
  const size = Math.max(a.width, a.height);
  const height = g.height ?? size;
  return { size, height, ascent: g.ascent ?? height - 1 };
}

/** Every HUD glyph / space of a mod, sorted (HUD id, then design order), with its codepoint in the project's home glyph block. */
export type HudGlyphSlot = { hud: string; name: string; codepoint: number; kind: "glyph" | "space"; px?: number };
export function allocateHudGlyphs(huds: HudDesign[], namespace: string): HudGlyphSlot[] {
  const start = glyphBlockStart(glyphHomeBlock(namespace));
  const out: HudGlyphSlot[] = [];
  const sorted = [...huds].sort((a, b) => (a.id < b.id ? -1 : 1));
  for (const h of sorted) for (const g of h.glyphs) out.push({ hud: h.id, name: g.name, codepoint: start + out.length, kind: "glyph" });
  const spaces = [...new Set(sorted.flatMap((h) => spacesOf(h)))].sort((a, b) => a - b);
  for (const px of spaces) out.push({ hud: "*", name: `space_${px < 0 ? "m" : "p"}${Math.abs(px)}`, codepoint: start + out.length, kind: "space", px });
  return out;
}
/** Pixel offsets a HUD needs from the space font: its space parts and bar gaps. */
export function spacesOf(h: HudDesign): number[] {
  const parts = [...(h.actionbar?.parts ?? []), ...(h.bossbar?.parts ?? []), ...(h.sidebar ? [...h.sidebar.title, ...h.sidebar.lines.flat()] : [])];
  return [...new Set([...parts.filter((p) => p.type === "space").map((p) => (p as { px: number }).px), ...(h.bars ?? []).filter((b) => b.gap).map((b) => b.gap!)])];
}
/** Identifier-registry records of a mod's HUD glyphs (kind "glyph", `<ns>:<hud>_<glyph>` with its codepoint) for the conflict engine. */
export function hudIdentRecords(huds: HudDesign[], namespace: string, owner = namespace): IdentRecord[] {
  return allocateHudGlyphs(huds, namespace).filter((s) => s.kind === "glyph").map((s) => {
    const id = buildIdentifier(namespace, "glyph", `${s.hud}_${s.name}`);
    return { kind: "glyph" as const, id: id.ok ? id.id : `${namespace}:${s.hud}_${s.name}`, codepoint: s.codepoint, owner };
  });
}

// ------------------------------------------------------------------------------------------------------- validation
export type HudContext = { version: string; namespace: string; items: Map<string, ItemDesign>; bosses: Map<string, BossDesign> };
export type HudIssue = DzIssue & { file?: string };
export type HudValidation = { ok: true; design: HudDesign; errors: []; warnings: HudIssue[] } | { ok: false; errors: HudIssue[]; warnings: HudIssue[] };
const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");
/** Estimated width in font pixels at GUI scale 1 (vanilla letters ~6 px with spacing; glyphs: scaled art width + 1). */
export function partsWidth(h: HudDesign, parts: HudPart[], fraction = 1): number {
  const gw = (name: string) => { const g = h.glyphs.find((x) => x.name === name); if (!g) return 0; const m = glyphMetrics(g); return Math.ceil(glyphArt(g).width * (m.height / m.size)) + 1; };
  let w = 0;
  for (const p of parts) {
    if (p.type === "text") w += p.text.length * 6;
    else if (p.type === "glyph") w += gw(p.glyph);
    else if (p.type === "space") w += p.px;
    else if (p.type === "value") w += (p.format === "fraction" ? 7 : p.format === "percent" ? 4 : 3) * 6;
    else { const b = h.bars?.find((x) => x.id === p.bar); if (b) w += b.segments * (Math.max(gw(b.full), gw(b.empty)) + (b.gap ?? 0)); }
  }
  void fraction;
  return w;
}

export function validateHud(input: unknown, ctx: HudContext): HudValidation {
  const id = (input as { id?: string })?.id ?? "?";
  const errors: HudIssue[] = [], warnings: HudIssue[] = [];
  const fail = (path: string, code: string, message: string) => errors.push({ path, code, message, file: id });
  const warn = (path: string, code: string, message: string) => warnings.push({ path, code, message, file: id });
  try { if (new TextEncoder().encode(JSON.stringify(input)).length > HUD_LIMITS.maxSpecBytes) { fail("(root)", "spec_size", `the HUD is larger than ${HUD_LIMITS.maxSpecBytes} bytes`); return { ok: false, errors, warnings }; } } catch { fail("(root)", "spec_size", "not JSON"); return { ok: false, errors, warnings }; }
  const p = HudDesignSchema.safeParse(input);
  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) fail(issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors, warnings }; }
  const h = p.data;
  const glyphs = new Map<string, GlyphDef>();
  h.glyphs.forEach((g, i) => {
    const at = `glyphs[${i}]`;
    if (glyphs.has(g.name)) fail(`${at}.name`, "duplicate_id", `glyph ${g.name} is defined twice`);
    glyphs.set(g.name, g);
    if ((g.preset === undefined) === (g.pixels === undefined)) { fail(at, "glyph_source", "a glyph needs exactly one of preset (a built-in glyph) or pixels (+ palette)"); return; }
    if (g.pixels) {
      if (g.color) warn(`${at}.color`, "color_ignored", "color tints presets only; pixels use the palette");
      const w = g.pixels[0].length;
      if (g.pixels.some((r) => r.length !== w)) fail(`${at}.pixels`, "pixel_rows", "every pixels row must have the same length");
      const pal = g.palette ?? {};
      if (Object.keys(pal).length > HUD_LIMITS.maxPaletteColors) fail(`${at}.palette`, "palette_size", `at most ${HUD_LIMITS.maxPaletteColors} palette colors`);
      const used = new Set(g.pixels.join("").replace(/\./g, "").split(""));
      if (!used.size) fail(`${at}.pixels`, "empty_glyph", "the glyph has no visible pixel");
      for (const ch of used) if (!(ch in pal)) fail(`${at}.pixels`, "palette_key", `pixels use "${ch}" but palette has no "${ch}"`);
    } else if (g.palette) warn(`${at}.palette`, "palette_ignored", "presets use color, not a palette");
    const m = glyphMetrics(g);
    if (m.ascent > m.height) fail(`${at}.ascent`, "ascent_height", `ascent ${m.ascent} is higher than the height ${m.height} (the game refuses such a font)`);
  });
  const checkSource = (at: string, s: HudSource) => {
    if (s.type === "ability_charges" || s.type === "ability_cooldown") {
      const it = ctx.items.get(s.item);
      const ab = it?.abilities.find((a) => a.id === s.ability);
      if (!it) fail(`${at}.item`, "unresolved_ref", `no design item "${s.item}" in this mod`);
      else if (!ab) fail(`${at}.ability`, "unresolved_ref", `item ${s.item} has no ability "${s.ability}"`);
      else if (s.type === "ability_charges" && !ab.charges) fail(at, "no_charges", `ability ${s.item}.${s.ability} has no charges`);
      else if (s.type === "ability_cooldown" && !ab.cooldownTicks) fail(at, "no_cooldown", `ability ${s.item}.${s.ability} has no cooldownTicks`);
    }
    if (s.type === "boss_health" && !ctx.bosses.has(s.boss)) fail(`${at}.boss`, "unresolved_ref", `no boss "${s.boss}" in this mod`);
  };
  const bars = new Map<string, HudBar>();
  (h.bars ?? []).forEach((b, i) => {
    const at = `bars[${i}]`;
    if (bars.has(b.id)) fail(`${at}.id`, "duplicate_id", `bar ${b.id} is defined twice`);
    bars.set(b.id, b);
    for (const k of ["full", "half", "empty"] as const) { const g = b[k]; if (g && !glyphs.has(g)) fail(`${at}.${k}`, "unresolved_ref", `no glyph "${g}" in this HUD`); }
    checkSource(`${at}.source`, b.source);
  });
  const usedBars = new Set<string>(), usedGlyphs = new Set<string>([...bars.values()].flatMap((b) => [b.full, b.empty, ...(b.half ? [b.half] : [])]));
  const checkParts = (at: string, parts: HudPart[]) => parts.forEach((pt, i) => {
    const pa = `${at}[${i}]`;
    if (pt.type === "glyph") { usedGlyphs.add(pt.glyph); if (!glyphs.has(pt.glyph)) fail(`${pa}.glyph`, "unresolved_ref", `no glyph "${pt.glyph}" in this HUD`); }
    if (pt.type === "bar") { usedBars.add(pt.bar); if (!bars.has(pt.bar)) fail(`${pa}.bar`, "unresolved_ref", `no bar "${pt.bar}" in this HUD`); }
    if (pt.type === "value") checkSource(`${pa}.source`, pt.source);
  });
  const checkShow = (at: string, s?: HudShow) => {
    if (!s) return;
    if (s.when === "holding" && !ctx.items.has(s.item)) fail(`${at}.item`, "unresolved_ref", `no design item "${s.item}" in this mod`);
    if (s.when === "in_boss_arena" && !ctx.bosses.has(s.boss)) fail(`${at}.boss`, "unresolved_ref", `no boss "${s.boss}" in this mod`);
  };
  if (!h.actionbar && !h.bossbar && !h.sidebar) fail("(root)", "no_channel", "a HUD needs at least one of actionbar, bossbar or sidebar");
  if (h.actionbar) {
    checkParts("actionbar.parts", h.actionbar.parts); checkShow("actionbar.show", h.actionbar.show);
    const w = partsWidth(h, h.actionbar.parts);
    if (w > HUD_LIMITS.actionbarWarnPx) warn("actionbar.parts", "actionbar_wide", `the action bar line is about ${w} px wide; small windows may cut it`);
    warn("actionbar", "actionbar_shared", "the action bar is one line for everything: another plugin's (or an item ability's) message replaces the HUD until the next update");
  }
  if (h.bossbar) { checkParts("bossbar.parts", h.bossbar.parts); checkShow("bossbar.show", h.bossbar.show); if (h.bossbar.progress) checkSource("bossbar.progress", h.bossbar.progress); if (!h.bossbar.progress) warn("bossbar", "bossbar_full", "without progress the bar under the title is always full (a vanilla boss bar always draws its bar)"); }
  if (h.sidebar) {
    checkParts("sidebar.title", h.sidebar.title); h.sidebar.lines.forEach((l, i) => checkParts(`sidebar.lines[${i}]`, l)); checkShow("sidebar.show", h.sidebar.show);
    warn("sidebar", "sidebar_exclusive", "the sidebar uses a per-player scoreboard: it is skipped for players another plugin already gave a scoreboard (TAB, other sidebars)");
  }
  for (const g of glyphs.keys()) if (!usedGlyphs.has(g)) warn("glyphs", "unused_glyph", `glyph ${g} is not used`);
  for (const b of bars.keys()) if (!usedBars.has(b)) warn("bars", "unused_bar", `bar ${b} is not used`);
  return errors.length ? { ok: false, errors, warnings } : { ok: true, design: h, errors: [], warnings };
}

/** Cross-file checks of a mod's HUDs: one action bar and one sidebar HUD per mod, the glyph block budget. */
export function crossCheckHuds(huds: HudDesign[], namespace: string): HudIssue[] {
  const out: HudIssue[] = [];
  for (const ch of ["actionbar", "sidebar"] as const) {
    const users = huds.filter((h) => h[ch]).map((h) => h.id);
    if (users.length > 1) out.push({ file: users[1], path: ch, code: "channel_taken", message: `${ch} is already used by HUD ${users[0]} (one ${ch} line per player)` });
  }
  const slots = allocateHudGlyphs(huds, namespace);
  const g = slots.filter((s) => s.kind === "glyph").length, sp = slots.filter((s) => s.kind === "space").length;
  if (g > HUD_LIMITS.maxGlyphsPerMod) out.push({ file: huds.at(-1)?.id, path: "glyphs", code: "too_many_glyphs", message: `${g} glyphs; the limit is ${HUD_LIMITS.maxGlyphsPerMod} per mod` });
  if (sp > HUD_LIMITS.maxSpacesPerMod) out.push({ file: huds.at(-1)?.id, path: "(mod)", code: "too_many_spaces", message: `${sp} different space widths; the limit is ${HUD_LIMITS.maxSpacesPerMod}` });
  if (slots.length > GLYPH_BLOCK || slots.some((s) => !isGlyphCodepoint(s.codepoint))) out.push({ file: huds.at(-1)?.id, path: "(mod)", code: "glyph_block", message: "the HUD glyphs do not fit the project's glyph block" });
  return out;
}

export const HUD_CHECK_CODES = ["schema", "duplicate_id", "glyph_source", "pixel_rows", "palette_size", "empty_glyph", "palette_key", "ascent_height", "unresolved_ref", "no_charges", "no_cooldown", "no_channel", "channel_taken", "too_many_glyphs", "too_many_spaces", "too_many_huds"] as const;

toolu_01GTtJ4abstcrwHUyyYmvd2b.content:
// Cyrus R4 HUD and glyphs: the HUD design IR (`"kind":"hud"` files in assets/designs, same id space as the other
// designs). Honest limits, by construction: a vanilla client with a server-pushed resource pack can show TEXT in three
// places a server controls (the action bar line above the hotbar, boss bar titles, the scoreboard sidebar); a HUD here is
// glyph-based text in those three channels: small pixel-art glyphs in this mod's OWN font (`<ns>:hud`, a bitmap font +
// a space font for pixel offsets), bars made of glyph segments, values (health, food, XP, air, an ability's charges or
// cooldown, a boss's health) and plain text. NO core shaders, no free-form positioning, no widgets anywhere on screen
// (those need a client mod), no animation beyond the update rate. Glyph codepoints come from the project's glyph block
// (lib/cyrus/engine-core/identifiers.ts: the namespace's home block in the supplementary Private Use Area); since they
// live in the mod's own font they cannot clash with another pack's glyphs (the conflict engine still sees them).
import { z } from "zod";
import { buildIdentifier, glyphBlockStart, glyphHomeBlock, GLYPH_BLOCK, isGlyphCodepoint, type IdentRecord } from "../../engine-core/identifiers";
import { Color, Key, Text, type DzIssue, type ItemDesign } from "../spec";
import type { BossDesign } from "../boss/spec";

export const HUD_SPEC_VERSION = 1;
export const HUD_LIMITS = {
  maxHuds: 2, maxGlyphs: 24, maxGlyphsPerMod: 32, maxSpacesPerMod: 16, maxBars: 6, maxParts: 12, maxSidebarLines: 8, maxLineParts: 8, maxTitleParts: 4,
  maxGlyphPixels: 16, maxPaletteColors: 8, maxSpecBytes: 32 * 1024,
  /** An action bar line wider than this (estimated, at GUI scale 1 in font pixels) is warned about: it may not fit small windows. */
  actionbarWarnPx: 240,
} as const;
export const HUD_CAPS = {
  glyphHeight: [4, 32], ascent: [-32, 32], segments: [1, 20], spacePx: [-64, 64], updateTicks: [10, 40], textChars: [1, 40],
} as const satisfies Record<string, readonly [number, number]>;
export type HudCapName = keyof typeof HUD_CAPS;

/** Built-in pixel-art glyphs (Cyrus-authored, tinted by `color`): '#' main, '+' highlight, '-' shadow, 'o' outline, '.' clear. */
export const GLYPH_PRESETS: Record<string, string[]> = {
  heart: [".oo.oo.", "o++o#-o", "o+###-o", "o####-o", ".o##-o.", "..o-o..", "...o..."],
  heart_half: [".oo.oo.", "o++o..o", "o+#...o", "o##...o", ".o#..o.", "..o.o..", "...o..."],
  heart_empty: [".oo.oo.", "o..o..o", "o.....o", "o.....o", ".o...o.", "..o.o..", "...o..."],
  bar_full: ["ooooooooo", "o+++++++o", "o#######o", "o-------o", "ooooooooo"],
  bar_half: ["ooooooooo", "o++++...o", "o####...o", "o----...o", "ooooooooo"],
  bar_empty: ["ooooooooo", "o.......o", "o.......o", "o.......o", "ooooooooo"],
  drop: ["...o...", "..o+o..", ".o+##o.", "o+###-o", "o####-o", ".o#--o.", "..ooo.."],
  shield: ["ooooooo", "o++#--o", "o+##--o", "o###--o", ".o##-o.", "..o-o..", "...o..."],
  star: ["...o...", "..o+o..", "oo+##oo", "o+###-o", ".o##-o.", "o-o.o-o", "oo...oo"],
  coin: [".ooooo.", "o+++##o", "o+#o#-o", "o#oo#-o", "o##o#-o", "o##--oo", ".ooooo."],
  skull: [".ooooo.", "o+###-o", "o#o#o-o", "o#####o", ".o#-#o.", ".o#o#o.", "..ooo.."],
  sword: ["......o", ".....o+", "....o+o", "o..o+o.", ".oo+o..", "..oo...", ".o..o.."],
  bolt: ["...oo..", "..o+o..", ".o+o...", "o+###o.", "...o+o.", "..o+o..", "..oo..."],
  flame: ["...o...", "..o+o..", ".o+#o..", ".o##-o.", "o+##-o.", "o###-o.", ".oooo.."],
  dot: [".ooo.", "o+#-o", "o##-o", "o#--o", ".ooo."],
};
export const PRESET_NAMES = Object.keys(GLYPH_PRESETS) as [string, ...string[]];

export const GlyphSchema = z.strictObject({
  name: Key,
  /** A built-in glyph tinted with `color`, OR `pixels` (rows of palette characters, '.' = clear) with a `palette`. */
  preset: z.enum(PRESET_NAMES).optional(),
  color: z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),
  pixels: z.array(z.string().min(1).max(HUD_LIMITS.maxGlyphPixels).regex(/^[.a-zA-Z0-9#+*o-]+$/)).min(1).max(HUD_LIMITS.maxGlyphPixels).optional(),
  palette: z.record(z.string().regex(/^[a-zA-Z0-9#+*o-]$/), z.string().regex(/^#[0-9a-fA-F]{6}$/)).optional(),
  /** Shown height in font pixels (vanilla letters are 8; default: the art's size). */
  height: z.number().int().min(HUD_CAPS.glyphHeight[0]).max(HUD_CAPS.glyphHeight[1]).optional(),
  /** Pixels above the text baseline (default height - 1, like letters); must not exceed height. Negative moves it down. */
  ascent: z.number().int().min(HUD_CAPS.ascent[0]).max(HUD_CAPS.ascent[1]).optional(),
});
export type GlyphDef = z.infer<typeof GlyphSchema>;

export const SourceSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("health") }),
  z.strictObject({ type: z.literal("food") }),
  z.strictObject({ type: z.literal("xp_level") }),
  z.strictObject({ type: z.literal("air") }),
  /** Charges left of an ability of this mod's design item (a mana / ammo bar). */
  z.strictObject({ type: z.literal("ability_charges"), item: Key, ability: Key }),
  /** An ability's cooldown: full = ready. */
  z.strictObject({ type: z.literal("ability_cooldown"), item: Key, ability: Key }),
  /** The health of the nearest live boss of this mod whose arena the player is in (empty when there is none). */
  z.strictObject({ type: z.literal("boss_health"), boss: Key }),
]);
export type HudSource = z.infer<typeof SourceSchema>;
export const BarSchema = z.strictObject({ id: Key, source: SourceSchema, segments: z.number().int().min(HUD_CAPS.segments[0]).max(HUD_CAPS.segments[1]), full: Key, half: Key.optional(), empty: Key, gap: z.number().int().min(-8).max(8).optional() });
export type HudBar = z.infer<typeof BarSchema>;
export const PartSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("text"), text: Text(HUD_CAPS.textChars[1]), color: Color.optional() }),
  z.strictObject({ type: z.literal("glyph"), glyph: Key }),
  z.strictObject({ type: z.literal("bar"), bar: Key }),
  z.strictObject({ type: z.literal("value"), source: SourceSchema, format: z.enum(["int", "percent", "fraction"]).optional(), color: Color.optional() }),
  /** Move the next part by px font pixels (negative = left): the space font, the only positioning a server has. */
  z.strictObject({ type: z.literal("space"), px: z.number().int().min(HUD_CAPS.spacePx[0]).max(HUD_CAPS.spacePx[1]).refine((v) => v !== 0, "0 moves nothing") }),
]);
export type HudPart = z.infer<typeof PartSchema>;
export const ShowSchema = z.discriminatedUnion("when", [
  z.strictObject({ when: z.literal("always") }),
  z.strictObject({ when: z.literal("holding"), item: Key }),
  z.strictObject({ when: z.literal("in_boss_arena"), boss: Key }),
]);
export type HudShow = z.infer<typeof ShowSchema>;
const Parts = (max: number) => z.array(PartSchema).min(1).max(max);
export const HudDesignSchema = z.strictObject({
  schemaVersion: z.literal(HUD_SPEC_VERSION),
  kind: z.literal("hud"),
  id: Key,
  glyphs: z.array(GlyphSchema).max(HUD_LIMITS.maxGlyphs),
  bars: z.array(BarSchema).max(HUD_LIMITS.maxBars).optional(),
  /** Every channel is optional; at least one is needed. */
  actionbar: z.strictObject({ parts: Parts(HUD_LIMITS.maxParts), show: ShowSchema.optional() }).optional(),
  bossbar: z.strictObject({ parts: Parts(HUD_LIMITS.maxParts), progress: SourceSchema.optional(), color: z.enum(["pink", "blue", "red", "green", "yellow", "purple", "white"]).optional(), overlay: z.enum(["progress", "notched_6", "notched_10", "notched_12", "notched_20"]).optional(), show: ShowSchema.optional() }).optional(),
  sidebar: z.strictObject({ title: Parts(HUD_LIMITS.maxTitleParts), lines: z.array(Parts(HUD_LIMITS.maxLineParts)).min(1).max(HUD_LIMITS.maxSidebarLines), show: ShowSchema.optional() }).optional(),
  /** Ticks between updates (the action bar is re-sent each time; it fades after about 3 s without one). */
  updateTicks: z.number().int().min(HUD_CAPS.updateTicks[0]).max(HUD_CAPS.updateTicks[1]),
});
export type HudDesign = z.infer<typeof HudDesignSchema>;
export type HudChannel = "actionbar" | "bossbar" | "sidebar";
export const CHANNELS: HudChannel[] = ["actionbar", "bossbar", "sidebar"];

export function hudJsonSchema(): Record<string, unknown> {
  return { $schema: "https://json-schema.org/draft/2020-12/schema", title: "Cyrus HUD designs v1 (glyph HUD text in the action bar, boss bars and the sidebar)", ...z.toJSONSchema(HudDesignSchema, { io: "input", reused: "ref" }) };
}

// -------------------------------------------------------------------------------------------- glyph art + codepoints
export type GlyphArt = { width: number; height: number; px: (string | null)[][] };
const rgb = (hex: string) => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
const hex2 = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
const mix = (a: string, b: string, t: number) => { const x = rgb(a), y = rgb(b); return `#${hex2(x[0] + (y[0] - x[0]) * t)}${hex2(x[1] + (y[1] - x[1]) * t)}${hex2(x[2] + (y[2] - x[2]) * t)}`; };
export const PRESET_DEFAULT_COLORS: Record<string, string> = { heart: "#e03a3a", heart_half: "#e03a3a", heart_empty: "#e03a3a", bar_full: "#3b6be8", bar_half: "#3b6be8", bar_empty: "#3b6be8", drop: "#3b8be8", shield: "#9aa7b8", star: "#f2c230", coin: "#f2b630", skull: "#d8d2c4", sword: "#c8d0dc", bolt: "#f2d830", flame: "#f07a20", dot: "#ffffff" };
/** The pixel art of a glyph (rows top to bottom; null = transparent). Deterministic. */
export function glyphArt(g: GlyphDef): GlyphArt {
  const rows = g.preset ? GLYPH_PRESETS[g.preset] : g.pixels ?? [];
  const width = Math.max(...rows.map((r) => r.length));
  let pal: Record<string, string>;
  if (g.preset) {
    const c = (g.color ?? PRESET_DEFAULT_COLORS[g.preset] ?? "#ffffff").toLowerCase();
    pal = { "#": c, "+": mix(c, "#ffffff", 0.45), "-": mix(c, "#000000", 0.35), o: mix(c, "#000000", 0.72) };
  } else pal = Object.fromEntries(Object.entries(g.palette ?? {}).map(([k, v]) => [k, v.toLowerCase()]));
  return { width, height: rows.length, px: rows.map((r) => Array.from({ length: width }, (_, x) => (r[x] && r[x] !== "." ? pal[r[x]] ?? null : null))) };
}
/** Font metrics (bitmap provider): the PNG is a square cell of `size` pixels (art top-left, transparent padding is trimmed by the game). */
export function glyphMetrics(g: GlyphDef): { size: number; height: number; ascent: number } {
  const a = glyphArt(g);
  const size = Math.max(a.width, a.height);
  const height = g.height ?? size;
  return { size, height, ascent: g.ascent ?? height - 1 };
}

/** Every HUD glyph / space of a mod, sorted (HUD id, then design order), with its codepoint in the project's home glyph block. */
export type HudGlyphSlot = { hud: string; name: string; codepoint: number; kind: "glyph" | "space"; px?: number };
export function allocateHudGlyphs(huds: HudDesign[], namespace: string): HudGlyphSlot[] {
  const start = glyphBlockStart(glyphHomeBlock(namespace));
  const out: HudGlyphSlot[] = [];
  const sorted = [...huds].sort((a, b) => (a.id < b.id ? -1 : 1));
  for (const h of sorted) for (const g of h.glyphs) out.push({ hud: h.id, name: g.name, codepoint: start + out.length, kind: "glyph" });
  const spaces = [...new Set(sorted.flatMap((h) => spacesOf(h)))].sort((a, b) => a - b);
  for (const px of spaces) out.push({ hud: "*", name: `space_${px < 0 ? "m" : "p"}${Math.abs(px)}`, codepoint: start + out.length, kind: "space", px });
  return out;
}
/** Pixel offsets a HUD needs from the space font: its space parts and bar gaps. */
export function spacesOf(h: HudDesign): number[] {
  const parts = [...(h.actionbar?.parts ?? []), ...(h.bossbar?.parts ?? []), ...(h.sidebar ? [...h.sidebar.title, ...h.sidebar.lines.flat()] : [])];
  return [...new Set([...parts.filter((p) => p.type === "space").map((p) => (p as { px: number }).px), ...(h.bars ?? []).filter((b) => b.gap).map((b) => b.gap!)])];
}
/** Identifier-registry records of a mod's HUD glyphs (kind "glyph", `<ns>:<hud>_<glyph>` with its codepoint) for the conflict engine. */
export function hudIdentRecords(huds: HudDesign[], namespace: string, owner = namespace): IdentRecord[] {
  return allocateHudGlyphs(huds, namespace).filter((s) => s.kind === "glyph").map((s) => {
    const id = buildIdentifier(namespace, "glyph", `${s.hud}_${s.name}`);
    return { kind: "glyph" as const, id: id.ok ? id.id : `${namespace}:${s.hud}_${s.name}`, codepoint: s.codepoint, owner };
  });
}

// ------------------------------------------------------------------------------------------------------- validation
export type HudContext = { version: string; namespace: string; items: Map<string, ItemDesign>; bosses: Map<string, BossDesign> };
export type HudIssue = DzIssue & { file?: string };
export type HudValidation = { ok: true; design: HudDesign; errors: []; warnings: HudIssue[] } | { ok: false; errors: HudIssue[]; warnings: HudIssue[] };
const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");
/** Estimated width in font pixels at GUI scale 1 (vanilla letters ~6 px with spacing; glyphs: scaled art width + 1). */
export function partsWidth(h: HudDesign, parts: HudPart[], fraction = 1): number {
  const gw = (name: string) => { const g = h.glyphs.find((x) => x.name === name); if (!g) return 0; const m = glyphMetrics(g); return Math.ceil(glyphArt(g).width * (m.height / m.size)) + 1; };
  let w = 0;
  for (const p of parts) {
    if (p.type === "text") w += p.text.length * 6;
    else if (p.type === "glyph") w += gw(p.glyph);
    else if (p.type === "space") w += p.px;
    else if (p.type === "value") w += (p.format === "fraction" ? 7 : p.format === "percent" ? 4 : 3) * 6;
    else { const b = h.bars?.find((x) => x.id === p.bar); if (b) w += b.segments * (Math.max(gw(b.full), gw(b.empty)) + (b.gap ?? 0)); }
  }
  void fraction;
  return w;
}

export function validateHud(input: unknown, ctx: HudContext): HudValidation {
  const id = (input as { id?: string })?.id ?? "?";
  const errors: HudIssue[] = [], warnings: HudIssue[] = [];
  const fail = (path: string, code: string, message: string) => errors.push({ path, code, message, file: id });
  const warn = (path: string, code: string, message: string) => warnings.push({ path, code, message, file: id });
  try { if (new TextEncoder().encode(JSON.stringify(input)).length > HUD_LIMITS.maxSpecBytes) { fail("(root)", "spec_size", `the HUD is larger than ${HUD_LIMITS.maxSpecBytes} bytes`); return { ok: false, errors, warnings }; } } catch { fail("(root)", "spec_size", "not JSON"); return { ok: false, errors, warnings }; }
  const p = HudDesignSchema.safeParse(input);
  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) fail(issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors, warnings }; }
  const h = p.data;
  const glyphs = new Map<string, GlyphDef>();
  h.glyphs.forEach((g, i) => {
    const at = `glyphs[${i}]`;
    if (glyphs.has(g.name)) fail(`${at}.name`, "duplicate_id", `glyph ${g.name} is defined twice`);
    glyphs.set(g.name, g);
    if ((g.preset === undefined) === (g.pixels === undefined)) { fail(at, "glyph_source", "a glyph needs exactly one of preset (a built-in glyph) or pixels (+ palette)"); return; }
    if (g.pixels) {
      if (g.color) warn(`${at}.color`, "color_ignored", "color tints presets only; pixels use the palette");
      const w = g.pixels[0].length;
      if (g.pixels.some((r) => r.length !== w)) fail(`${at}.pixels`, "pixel_rows", "every pixels row must have the same length");
      const pal = g.palette ?? {};
      if (Object.keys(pal).length > HUD_LIMITS.maxPaletteColors) fail(`${at}.palette`, "palette_size", `at most ${HUD_LIMITS.maxPaletteColors} palette colors`);
      const used = new Set(g.pixels.join("").replace(/\./g, "").split(""));
      if (!used.size) fail(`${at}.pixels`, "empty_glyph", "the glyph has no visible pixel");
      for (const ch of used) if (!(ch in pal)) fail(`${at}.pixels`, "palette_key", `pixels use "${ch}" but palette has no "${ch}"`);
    } else if (g.palette) warn(`${at}.palette`, "palette_ignored", "presets use color, not a palette");
    const m = glyphMetrics(g);
    if (m.ascent > m.height) fail(`${at}.ascent`, "ascent_height", `ascent ${m.ascent} is higher than the height ${m.height} (the game refuses such a font)`);
  });
  const checkSource = (at: string, s: HudSource) => {
    if (s.type === "ability_charges" || s.type === "ability_cooldown") {
      const it = ctx.items.get(s.item);
      const ab = it?.abilities.find((a) => a.id === s.ability);
      if (!it) fail(`${at}.item`, "unresolved_ref", `no design item "${s.item}" in this mod`);
      else if (!ab) fail(`${at}.ability`, "unresolved_ref", `item ${s.item} has no ability "${s.ability}"`);
      else if (s.type === "ability_charges" && !ab.charges) fail(at, "no_charges", `ability ${s.item}.${s.ability} has no charges`);
      else if (s.type === "ability_cooldown" && !ab.cooldownTicks) fail(at, "no_cooldown", `ability ${s.item}.${s.ability} has no cooldownTicks`);
    }
    if (s.type === "boss_health" && !ctx.bosses.has(s.boss)) fail(`${at}.boss`, "unresolved_ref", `no boss "${s.boss}" in this mod`);
  };
  const bars = new Map<string, HudBar>();
  (h.bars ?? []).forEach((b, i) => {
    const at = `bars[${i}]`;
    if (bars.has(b.id)) fail(`${at}.id`, "duplicate_id", `bar ${b.id} is defined twice`);
    bars.set(b.id, b);
    for (const k of ["full", "half", "empty"] as const) { const g = b[k]; if (g && !glyphs.has(g)) fail(`${at}.${k}`, "unresolved_ref", `no glyph "${g}" in this HUD`); }
    checkSource(`${at}.source`, b.source);
  });
  const usedBars = new Set<string>(), usedGlyphs = new Set<string>([...bars.values()].flatMap((b) => [b.full, b.empty, ...(b.half ? [b.half] : [])]));
  const checkParts = (at: string, parts: HudPart[]) => parts.forEach((pt, i) => {
    const pa = `${at}[${i}]`;
    if (pt.type === "glyph") { usedGlyphs.add(pt.glyph); if (!glyphs.has(pt.glyph)) fail(`${pa}.glyph`, "unresolved_ref", `no glyph "${pt.glyph}" in this HUD`); }
    if (pt.type === "bar") { usedBars.add(pt.bar); if (!bars.has(pt.bar)) fail(`${pa}.bar`, "unresolved_ref", `no bar "${pt.bar}" in this HUD`); }
    if (pt.type === "value") checkSource(`${pa}.source`, pt.source);
  });
  const checkShow = (at: string, s?: HudShow) => {
    if (!s) return;
    if (s.when === "holding" && !ctx.items.has(s.item)) fail(`${at}.item`, "unresolved_ref", `no design item "${s.item}" in this mod`);
    if (s.when === "in_boss_arena" && !ctx.bosses.has(s.boss)) fail(`${at}.boss`, "unresolved_ref", `no boss "${s.boss}" in this mod`);
  };
  if (!h.actionbar && !h.bossbar && !h.sidebar) fail("(root)", "no_channel", "a HUD needs at least one of actionbar, bossbar or sidebar");
  if (h.actionbar) {
    checkParts("actionbar.parts", h.actionbar.parts); checkShow("actionbar.show", h.actionbar.show);
    const w = partsWidth(h, h.actionbar.parts);
    if (w > HUD_LIMITS.actionbarWarnPx) warn("actionbar.parts", "actionbar_wide", `the action bar line is about ${w} px wide; small windows may cut it`);
    warn("actionbar", "actionbar_shared", "the action bar is one line for everything: another plugin's (or an item ability's) message replaces the HUD until the next update");
  }
  if (h.bossbar) { checkParts("bossbar.parts", h.bossbar.parts); checkShow("bossbar.show", h.bossbar.show); if (h.bossbar.progress) checkSource("bossbar.progress", h.bossbar.progress); if (!h.bossbar.progress) warn("bossbar", "bossbar_full", "without progress the bar under the title is always full (a vanilla boss bar always draws its bar)"); }
  if (h.sidebar) {
    checkParts("sidebar.title", h.sidebar.title); h.sidebar.lines.forEach((l, i) => checkParts(`sidebar.lines[${i}]`, l)); checkShow("sidebar.show", h.sidebar.show);
    warn("sidebar", "sidebar_exclusive", "the sidebar uses a per-player scoreboard: it is skipped for players another plugin already gave a scoreboard (TAB, other sidebars)");
  }
  for (const g of glyphs.keys()) if (!usedGlyphs.has(g)) warn("glyphs", "unused_glyph", `glyph ${g} is not used`);
  for (const b of bars.keys()) if (!usedBars.has(b)) warn("bars", "unused_bar", `bar ${b} is not used`);
  return errors.length ? { ok: false, errors, warnings } : { ok: true, design: h, errors: [], warnings };
}

/** Cross-file checks of a mod's HUDs: one action bar and one sidebar HUD per mod, the glyph block budget. */
export function crossCheckHuds(huds: HudDesign[], namespace: string): HudIssue[] {
  const out: HudIssue[] = [];
  for (const ch of ["actionbar", "sidebar"] as const) {
    const users = huds.filter((h) => h[ch]).map((h) => h.id);
    if (users.length > 1) out.push({ file: users[1], path: ch, code: "channel_taken", message: `${ch} is already used by HUD ${users[0]} (one ${ch} line per player)` });
  }
  const slots = allocateHudGlyphs(huds, namespace);
  const g = slots.filter((s) => s.kind === "glyph").length, sp = slots.filter((s) => s.kind === "space").length;
  if (g > HUD_LIMITS.maxGlyphsPerMod) out.push({ file: huds.at(-1)?.id, path: "glyphs", code: "too_many_glyphs", message: `${g} glyphs; the limit is ${HUD_LIMITS.maxGlyphsPerMod} per mod` });
  if (sp > HUD_LIMITS.maxSpacesPerMod) out.push({ file: huds.at(-1)?.id, path: "(mod)", code: "too_many_spaces", message: `${sp} different space widths; the limit is ${HUD_LIMITS.maxSpacesPerMod}` });
  if (slots.length > GLYPH_BLOCK || slots.some((s) => !isGlyphCodepoint(s.codepoint))) out.push({ file: huds.at(-1)?.id, path: "(mod)", code: "glyph_block", message: "the HUD glyphs do not fit the project's glyph block" });
  return out;
}

export const HUD_CHECK_CODES = ["schema", "duplicate_id", "glyph_source", "pixel_rows", "palette_size", "empty_glyph", "palette_key", "ascent_height", "unresolved_ref", "no_charges", "no_cooldown", "no_channel", "channel_taken", "too_many_glyphs", "too_many_spaces", "too_many_huds"] as const;

