// Cyrus R4 HUD and glyphs: the RESOURCE PACK part of a HUD. Deterministic files the pack builder
// (lib/cyrus/textures/pack.ts buildPack `fonts`) adds to the mod's one pack:
//   assets/<ns>/textures/font/hud/<hud>_<glyph>.png   one square RGBA cell per glyph (art top-left; the game trims
//                                                      transparent columns, so the glyph is as wide as its art)
//   assets/<ns>/font/hud.json                          a `bitmap` provider per glyph (file, ascent, height, one char)
//                                                      + one `space` provider (advances for the pixel offsets)
// The codepoints are the ones the plugin uses (allocateHudGlyphs: the project's home glyph block); both sides compute
// them from the same designs, and `checkHudFont` re-checks the emitted font against the game's rules (ascent <= height,
// one char per bitmap, PNG dimensions, codepoints in the supplementary Private Use Area).
import { encodePng } from "../../textures/png";
import { isGlyphCodepoint } from "../../engine-core/identifiers";
import { allocateHudGlyphs, glyphArt, glyphMetrics, type HudDesign } from "./spec";

export const HUD_FONT = "hud";
export type HudFontFile = { path: string; data: Buffer };
export type HudFont = { font: string; files: HudFontFile[]; glyphs: { name: string; codepoint: number; file: string; height: number; ascent: number; size: number }[]; spaces: { px: number; codepoint: number }[] };

const rgba = (hex: string): [number, number, number] => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
const chr = (cp: number) => String.fromCodePoint(cp);

/** The font files of a mod's HUDs (empty when there are none). */
export function hudFont(huds: HudDesign[], namespace: string): HudFont {
  const slots = allocateHudGlyphs(huds, namespace);
  const providers: Record<string, unknown>[] = [];
  const files: HudFontFile[] = [];
  const glyphs: HudFont["glyphs"] = [];
  for (const s of slots.filter((x) => x.kind === "glyph")) {
    const h = huds.find((x) => x.id === s.hud)!;
    const g = h.glyphs.find((x) => x.name === s.name)!;
    const art = glyphArt(g);
    const m = glyphMetrics(g);
    const px = new Uint8ClampedArray(m.size * m.size * 4);
    art.px.forEach((row, y) => row.forEach((c, x) => { if (!c) return; const [r, gg, b] = rgba(c); const i = (y * m.size + x) * 4; px[i] = r; px[i + 1] = gg; px[i + 2] = b; px[i + 3] = 255; }));
    const file = `hud/${s.hud}_${s.name}`;
    files.push({ path: `assets/${namespace}/textures/font/${file}.png`, data: encodePng({ size: m.size, px }) });
    providers.push({ type: "bitmap", file: `${namespace}:font/${file}.png`, ascent: m.ascent, height: m.height, chars: [chr(s.codepoint)] });
    glyphs.push({ name: `${s.hud}.${s.name}`, codepoint: s.codepoint, file, height: m.height, ascent: m.ascent, size: m.size });
  }
  const spaces = slots.filter((x) => x.kind === "space").map((s) => ({ px: s.px!, codepoint: s.codepoint }));
  if (spaces.length) providers.push({ type: "space", advances: Object.fromEntries(spaces.map((s) => [chr(s.codepoint), s.px])) });
  if (providers.length) files.push({ path: `assets/${namespace}/font/${HUD_FONT}.json`, data: Buffer.from(JSON.stringify({ providers }, null, 2)) });
  return { font: `${namespace}:${HUD_FONT}`, files, glyphs, spaces };
}

/** Re-check an emitted font against the game's font loader rules. Returns problems (empty = ok). */
export function checkHudFont(f: HudFont, namespace: string): string[] {
  const out: string[] = [];
  const json = f.files.find((x) => x.path === `assets/${namespace}/font/${HUD_FONT}.json`);
  if (!json) return f.glyphs.length || f.spaces.length ? ["no font json"] : [];
  let doc: { providers?: { type: string; file?: string; ascent?: number; height?: number; chars?: string[]; advances?: Record<string, number> }[] };
  try { doc = JSON.parse(json.data.toString("utf8")); } catch { return ["font json does not parse"]; }
  const seen = new Set<number>();
  for (const p of doc.providers ?? []) {
    if (p.type === "bitmap") {
      if ((p.ascent ?? 0) > (p.height ?? 8)) out.push(`${p.file}: ascent ${p.ascent} > height ${p.height}`);
      if (!p.chars || p.chars.length !== 1 || [...p.chars[0]].length !== 1) out.push(`${p.file}: one char per bitmap expected`);
      const cp = p.chars?.[0]?.codePointAt(0) ?? -1;
      if (!isGlyphCodepoint(cp)) out.push(`${p.file}: U+${cp.toString(16)} is not in the glyph blocks`);
      if (seen.has(cp)) out.push(`${p.file}: codepoint used twice`); seen.add(cp);
      const png = f.files.find((x) => x.path === `assets/${namespace}/textures/${p.file!.split(":")[1]}`);
      if (!png) { out.push(`${p.file}: png missing`); continue; }
      const w = png.data.readUInt32BE(16), h = png.data.readUInt32BE(20);
      if (w !== h || w < 1 || w > 64) out.push(`${p.file}: ${w}x${h} (expected a square cell of 1-64 px)`);
    } else if (p.type === "space") {
      for (const [k, v] of Object.entries(p.advances ?? {})) { const cp = k.codePointAt(0)!; if (seen.has(cp)) out.push(`space U+${cp.toString(16)} used twice`); seen.add(cp); if (!Number.isInteger(v)) out.push(`space advance ${v}`); }
    } else out.push(`unexpected provider ${p.type}`);
  }
  return out;
}

