export const HUDRENDER_JAVA = String.raw`package __PKG__.designer;

import java.util.Locale;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.TextComponent;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextColor;
import org.bukkit.entity.Player;

/**
 * Component hud-render v1: builds one HUD line as an Adventure component (glyphs and spaces in the mod's font, text in
 * the default font) and, in parallel, a token string ([glyph] {px} 'text' <value>) that /<mod> hud preview prints and
 * the TS twin reproduces. Glyphs are drawn WHITE (the font's own colours; a text colour would tint them). In preview mode
 * every source reads the given fraction of 20.
 */
public final class HudRender {
    private final HudDef def;
    private final Player player;
    private final double preview;
    private final Key font;
    private final TextComponent.Builder b = Component.text();
    private final StringBuilder tokens = new StringBuilder();

    public HudRender(HudDef def, Player player, double preview, Key font) { this.def = def; this.player = player; this.preview = preview; this.font = font; }

    public double[] src(int k) {
        if (!Double.isNaN(preview)) { double f = Math.max(0.0, Math.min(1.0, preview)); return new double[] {f * 20.0, 20.0, f}; }
        return player == null ? null : def.source(k, player);
    }

    public double fraction(int k) { double[] v = src(k); return v == null ? 0.0 : Math.max(0.0, Math.min(1.0, v[2])); }

    public void glyph(String chars, String name) { b.append(Component.text(chars, NamedTextColor.WHITE).font(font)); tokens.append('[').append(name).append(']'); }

    public void space(String chars, int px) { b.append(Component.text(chars).font(font)); tokens.append('{').append(px).append('}'); }

    public void text(String s, TextColor c) { if (s == null || s.isEmpty()) return; b.append(Component.text(s, c == null ? NamedTextColor.WHITE : c)); tokens.append('\'').append(s).append('\''); }

    /** format 0 = int, 1 = percent, 2 = value/max. */
    public void value(int k, int format, TextColor c) {
        double[] v = src(k);
        String s = v == null ? "-" : format == 1 ? Math.round(Math.max(0.0, Math.min(1.0, v[2])) * 100) + "%" : format == 2 ? Math.round(v[0]) + "/" + Math.round(v[1]) : String.valueOf(Math.round(v[0]));
        b.append(Component.text(s, c == null ? NamedTextColor.WHITE : c));
        tokens.append('<').append(s).append('>');
    }

    /** segments glyphs: full ones, then one half glyph when the rest is at least half a segment, then empty ones. */
    public void bar(int k, int segments, String full, String fullName, String half, String halfName, String empty, String emptyName, String gap, int gapPx) {
        int n = Math.max(1, Math.min(20, segments));
        double units = fraction(k) * n;
        int whole = (int) Math.floor(units + 1.0E-9);
        boolean halfOne = half != null && whole < n && units - whole >= 0.5 - 1.0E-9;
        for (int i = 0; i < n; i++) {
            if (i > 0 && gap != null) space(gap, gapPx);
            if (i < whole) glyph(full, fullName);
            else if (i == whole && halfOne) glyph(half, halfName);
            else glyph(empty, emptyName);
        }
    }

    public Component component() { return b.build(); }
    public String tokens() { return tokens.toString(); }
    public static String fmt(double v) { return String.format(Locale.ROOT, "%.2f", v); }
}
`;

export const HUDSOURCES_JAVA = String.raw`package __PKG__.designer;

import org.bukkit.attribute.AttributeInstance;
import org.bukkit.entity.Player;

/** Component hud-sources v1: the values a HUD can show ({value, max, fraction}); a missing ability reads as empty. */
public final class HudSources {
    private HudSources() {}

    private static double[] of(double v, double max) { return new double[] {v, max, max <= 0 ? 0.0 : Math.max(0.0, Math.min(1.0, v / max))}; }

    public static double[] health(Player p) { AttributeInstance a = p.getAttribute(Compat.MAX_HEALTH); return of(p.getHealth(), a == null ? 20.0 : a.getValue()); }
    public static double[] food(Player p) { return of(p.getFoodLevel(), 20.0); }
    public static double[] xp(Player p) { return new double[] {p.getLevel(), Math.max(1, p.getLevel()), Math.max(0.0, Math.min(1.0, p.getExp()))}; }
    public static double[] air(Player p) { return of(Math.max(0, p.getRemainingAir()), Math.max(1, p.getMaximumAir())); }

    public static double[] charges(Designer d, Player p, String item, String ability) {
        Ability a = d.ability(item, ability);
        if (a == null || a.maxCharges <= 0) return of(0, 1);
        return of(a.chargesLeft(p), a.maxCharges);
    }

    /** value = seconds left, max = the cooldown in seconds, fraction = how ready (1 = ready). */
    public static double[] cooldown(Designer d, Player p, String item, String ability) {
        Ability a = d.ability(item, ability);
        if (a == null || a.cooldown() <= 0) return new double[] {0, 0, 1.0};
        double left = Math.max(0, d.cooldowns().remaining(p.getUniqueId(), a.key(), d.now()));
        return new double[] {left / 20.0, a.cooldown() / 20.0, 1.0 - Math.max(0.0, Math.min(1.0, left / a.cooldown()))};
    }

    public static boolean holding(Designer d, Player p, String item) { return d.identity().is(p.getInventory().getItemInMainHand(), item); }
}
`;

/** Only in mods with both HUDs and bosses: the boss_health source and the in_boss_arena condition. */
export const HUDBOSS_JAVA = String.raw`package __PKG__.designer;

import org.bukkit.attribute.AttributeInstance;
import org.bukkit.entity.Player;

/** Component hud-boss v1: the nearest live boss of an id whose arena the player is in (health {value, max, fraction}). */
public final class HudBossSource {
    private HudBossSource() {}

    private static BossInstance nearest(Bosses b, Player p, String id) {
        BossInstance best = null;
        double bd = Double.MAX_VALUE;
        for (BossInstance i : b.live()) {
            if (!i.def.id().equals(id) || !i.mob.isValid() || !b.inArena(i, p.getLocation())) continue;
            double x = i.mob.getLocation().distanceSquared(p.getLocation());
            if (x < bd) { bd = x; best = i; }
        }
        return best;
    }

    public static double[] health(Bosses b, Player p, String id) {
        BossInstance i = nearest(b, p, id);
        if (i == null) return null;
        AttributeInstance a = i.mob.getAttribute(BossCompat.MAX_HEALTH);
        double max = a == null ? 1 : a.getValue();
        return new double[] {i.mob.getHealth(), max, max <= 0 ? 0 : Math.max(0.0, Math.min(1.0, i.mob.getHealth() / max))};
    }

    public static boolean inArena(Bosses b, Player p, String id) { return nearest(b, p, id) != null; }
}
`;

export const HUDS_JAVA = String.raw`package __PKG__.designer;

import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import io.papermc.paper.scoreboard.numbers.NumberFormat;
import net.kyori.adventure.bossbar.BossBar;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.text.Component;
import org.bukkit.Bukkit;
import org.bukkit.NamespacedKey;
import org.bukkit.command.PluginCommand;
import org.bukkit.configuration.Configuration;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scoreboard.Criteria;
import org.bukkit.scoreboard.DisplaySlot;
import org.bukkit.scoreboard.Objective;
import org.bukkit.scoreboard.Score;
import org.bukkit.scoreboard.Scoreboard;

/**
 * Component hud-runtime v1 (the HUD hub). ONE timer (every 10 ticks) updates every online player's HUDs that are due
 * (each HUD's update rate, 10-40 ticks). Channels: the action bar (re-sent every update: it fades after about 3 s, and
 * any other action bar message replaces it until the next update), one Adventure boss bar per player per HUD (shown
 * while its condition holds), and a per-player scoreboard sidebar ONLY when the player still has the main scoreboard
 * (another plugin's board is never replaced; ours is swapped back to the main board when hidden). Players turn it off
 * with /<mod> hud toggle (stored in their PersistentDataContainer <ns>:hud_off). Everything is dropped on quit and
 * disable. Config: huds.* resets on a config_version bump (like the other designers).
 */
public final class Huds implements Listener {
    public static final int TIMER = 10;
    public static final int MAX_LINES = 8;
    private final Designer d;
    private final JavaPlugin plugin;
    private final DesignConfig config;
    private final Key font;
    private final NamespacedKey offKey;
    private final Map<String, HudDef> defs = new LinkedHashMap<>();
    private final Map<UUID, Map<String, BossBar>> bars = new HashMap<>();
    private final Map<UUID, Scoreboard> boards = new HashMap<>();
    private final Map<UUID, String> lastSidebar = new HashMap<>();
    private final int startVersion;
    private boolean registered;

    public Huds(Designer d) {
        this.d = d;
        this.plugin = d.plugin();
        this.config = new DesignConfig(plugin);
        this.font = Key.key(d.namespace(), "hud");
        this.offKey = new NamespacedKey(d.namespace(), "hud_off");
        this.startVersion = fileVersion();
    }

    public void enable(PluginCommand command, List<HudDef> list, boolean delegateParams) {
        for (HudDef h : list) defs.put(h.id(), h);
        load(startVersion, new ArrayList<>());
        if (!registered) { plugin.getServer().getPluginManager().registerEvents(this, plugin); registered = true; }
        if (command != null) {
            HudCommand c = new HudCommand(this, command.getName(), command.getExecutor(), command.getTabCompleter(), delegateParams);
            command.setExecutor(c);
            command.setTabCompleter(c);
        }
    }

    void load(int before, List<String> out) {
        FileConfiguration cfg = plugin.getConfig();
        Configuration defaults = cfg.getDefaults();
        int jar = defaults == null ? 1 : defaults.getInt("config_version", 1);
        if (before >= 0 && before < jar && defaults != null) {
            int n = 0;
            for (String key : defaults.getKeys(true)) {
                if (!key.startsWith("huds.") || defaults.isConfigurationSection(key)) continue;
                cfg.set(key, defaults.get(key));
                n++;
            }
            plugin.saveConfig();
            String m = "config.yml: " + n + " HUD values updated to version " + jar;
            out.add(m);
            plugin.getLogger().info(m);
        }
        config.load();
        for (HudDef h : defs.values()) h.load(config);
        for (String s : config.notes()) { out.add(s); plugin.getLogger().warning("config: " + s); }
        d.tasks().timer(TIMER, this::tick);
    }

    int fileVersion() {
        File f = new File(plugin.getDataFolder(), "config.yml");
        if (!f.isFile()) return -1;
        Object raw = YamlConfiguration.loadConfiguration(f).get("config_version");
        return raw instanceof Number n ? n.intValue() : 0;
    }

    public boolean off(Player p) { return p.getPersistentDataContainer().has(offKey, PersistentDataType.BYTE); }

    /** Flip a player's HUD on / off; returns true when it is now on. */
    public boolean toggle(Player p) {
        if (off(p)) { p.getPersistentDataContainer().remove(offKey); return true; }
        p.getPersistentDataContainer().set(offKey, PersistentDataType.BYTE, (byte) 1);
        clear(p);
        return false;
    }

    private void tick() {
        long now = d.now();
        for (HudDef h : defs.values()) {
            if (now - h.lastUpdate < h.updateTicks) continue;
            h.lastUpdate = now;
            for (Player p : Bukkit.getOnlinePlayers()) { if (!off(p)) deliver(h, p); }
        }
    }

    private void deliver(HudDef h, Player p) {
        if (h.actionbar && h.show("actionbar", p)) { HudRender r = new HudRender(h, p, Double.NaN, font); h.actionbar(r); p.sendActionBar(r.component()); }
        if (h.bossbar) {
            Map<String, BossBar> mine = bars.computeIfAbsent(p.getUniqueId(), u -> new HashMap<>());
            if (h.show("bossbar", p)) {
                HudRender r = new HudRender(h, p, Double.NaN, font);
                h.bossbar(r);
                BossBar bar = mine.get(h.id());
                if (bar == null) { bar = BossBar.bossBar(r.component(), 1f, h.barColor, h.barOverlay); mine.put(h.id(), bar); p.showBossBar(bar); }
                bar.name(r.component());
                bar.progress((float) Math.max(0.0, Math.min(1.0, h.bossbarProgress(r))));
            } else { BossBar bar = mine.remove(h.id()); if (bar != null) p.hideBossBar(bar); }
        }
        if (h.sidebar) {
            Scoreboard ours = boards.get(p.getUniqueId());
            boolean main = p.getScoreboard() == Bukkit.getScoreboardManager().getMainScoreboard();
            if (h.show("sidebar", p) && (main || p.getScoreboard() == ours)) sidebar(h, p);
            else if (ours != null && p.getScoreboard() == ours) { p.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard()); boards.remove(p.getUniqueId()); lastSidebar.remove(p.getUniqueId()); }
        }
    }

    private void sidebar(HudDef h, Player p) {
        HudRender title = new HudRender(h, p, Double.NaN, font);
        h.sidebarTitle(title);
        int n = Math.max(0, Math.min(MAX_LINES, h.sidebarLines()));
        List<HudRender> lines = new ArrayList<>();
        StringBuilder key = new StringBuilder(title.tokens());
        for (int i = 0; i < n; i++) { HudRender r = new HudRender(h, p, Double.NaN, font); h.sidebarLine(i, r); lines.add(r); key.append('\n').append(r.tokens()); }
        if (key.toString().equals(lastSidebar.get(p.getUniqueId())) && p.getScoreboard() == boards.get(p.getUniqueId())) return;
        lastSidebar.put(p.getUniqueId(), key.toString());
        Scoreboard sb = boards.get(p.getUniqueId());
        if (sb == null) { sb = Bukkit.getScoreboardManager().getNewScoreboard(); boards.put(p.getUniqueId(), sb); }
        Objective o = sb.getObjective("nx_hud");
        if (o == null) { o = sb.registerNewObjective("nx_hud", Criteria.DUMMY, title.component()); o.setDisplaySlot(DisplaySlot.SIDEBAR); o.numberFormat(NumberFormat.blank()); }
        o.displayName(title.component());
        for (int i = 0; i < MAX_LINES; i++) {
            String entry = "nxhud_l" + i;
            if (i < n) { Score s = o.getScore(entry); s.setScore(n - i); s.customName(lines.get(i).component()); }
            else sb.resetScores(entry);
        }
        if (p.getScoreboard() != sb) p.setScoreboard(sb);
    }

    private void clear(Player p) {
        Map<String, BossBar> mine = bars.remove(p.getUniqueId());
        if (mine != null) for (BossBar b : mine.values()) p.hideBossBar(b);
        Scoreboard ours = boards.remove(p.getUniqueId());
        if (ours != null && p.getScoreboard() == ours) p.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());
        lastSidebar.remove(p.getUniqueId());
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onQuit(PlayerQuitEvent e) {
        bars.remove(e.getPlayer().getUniqueId());
        boards.remove(e.getPlayer().getUniqueId());
        lastSidebar.remove(e.getPlayer().getUniqueId());
    }

    public void disable() {
        for (Player p : Bukkit.getOnlinePlayers()) clear(p);
        bars.clear();
        boards.clear();
        lastSidebar.clear();
    }

    /** Render one channel of a HUD with every source at the given fraction (no player needed). */
    public HudRender preview(HudDef h, String channel, double fraction, int line) {
        HudRender r = new HudRender(h, null, fraction, font);
        switch (channel) {
            case "actionbar" -> h.actionbar(r);
            case "bossbar" -> h.bossbar(r);
            case "title" -> h.sidebarTitle(r);
            default -> h.sidebarLine(line, r);
        }
        return r;
    }

    public Designer designer() { return d; }
    public JavaPlugin plugin() { return plugin; }
    public Map<String, HudDef> defs() { return defs; }
    public HudDef def(String id) { return defs.get(id); }
    public Key font() { return font; }
    public String namespace() { return d.namespace(); }
}
`;

export const HUDCOMMAND_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.serializer.gson.GsonComponentSerializer;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;

/**
 * Component hud-command v1: adds the hud subcommands to the mod command, everything else goes to the wrapped command:
 *   /<mod> hud toggle                                   (players, <ns>.hud.toggle: everyone)
 *   /<mod> hud list | check                             (<ns>.hud.admin, operators)
 *   /<mod> hud preview <id> <actionbar|bossbar|title|line<N>> <0-1>   (<ns>.hud.admin; the token line + the component JSON)
 *   /<mod> reload and params include the HUDs.
 */
public final class HudCommand implements CommandExecutor, TabCompleter {
    private static final List<String> HSUBS = List.of("toggle", "list", "check", "preview");
    private final Huds h;
    private final String label;
    private final CommandExecutor next;
    private final TabCompleter nextTab;
    private final boolean delegateParams;

    HudCommand(Huds h, String label, CommandExecutor next, TabCompleter nextTab, boolean delegateParams) { this.h = h; this.label = label; this.next = next; this.nextTab = nextTab; this.delegateParams = delegateParams; }

    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }

    private boolean allowed(CommandSender s, String node) {
        if (s.hasPermission(h.namespace() + "." + node)) return true;
        say(s, "You don't have permission for that.", NamedTextColor.RED);
        return false;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String used, String[] args) {
        String sub = args.length == 0 ? "" : args[0].toLowerCase(Locale.ROOT);
        switch (sub) {
            case "hud" -> { hud(sender, args); return true; }
            case "reload" -> {
                if (!sender.hasPermission(h.namespace() + ".reload")) { say(sender, "You don't have permission for that.", NamedTextColor.RED); return true; }
                int before = h.fileVersion();
                if (next != null) next.onCommand(sender, command, used, args); else h.designer().reload();
                List<String> notes = new ArrayList<>();
                h.load(before, notes);
                say(sender, h.plugin().getName() + " HUDs reloaded" + (notes.isEmpty() ? "" : " (" + notes.size() + " note" + (notes.size() == 1 ? "" : "s") + ")"), NamedTextColor.GREEN);
                for (String n : notes) say(sender, "- " + n, NamedTextColor.YELLOW);
                return true;
            }
            case "params" -> {
                if (!allowed(sender, "command")) return true;
                String want = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : null;
                boolean mine = want != null && h.def(want) != null;
                List<String> out = new ArrayList<>();
                if (!mine && delegateParams && next != null) next.onCommand(sender, command, used, args);
                else if (!mine) for (DesignItem i : h.designer().items()) if (want == null || i.id().equals(want)) i.describe(out);
                for (HudDef d : h.defs().values()) if (want == null || d.id().equals(want)) d.describe(out);
                if (out.isEmpty() && (mine || !delegateParams)) say(sender, "No parameters.", NamedTextColor.GRAY);
                for (String line : out) say(sender, line, NamedTextColor.AQUA);
                return true;
            }
            default -> {
                if (next != null) return next.onCommand(sender, command, used, args);
                say(sender, "Unknown subcommand. Use /" + label + " hud, params or reload.", NamedTextColor.RED);
                return true;
            }
        }
    }

    private void hud(CommandSender sender, String[] args) {
        String a = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "";
        switch (a) {
            case "toggle" -> {
                if (!(sender instanceof Player p)) { say(sender, "Only players can toggle their HUD.", NamedTextColor.RED); return; }
                if (!allowed(sender, "hud.toggle")) return;
                say(p, h.toggle(p) ? "HUD on." : "HUD off.", NamedTextColor.GREEN);
            }
            case "list" -> {
                if (!allowed(sender, "hud.admin")) return;
                for (HudDef d : h.defs().values()) {
                    List<String> ch = new ArrayList<>();
                    if (d.actionbar) ch.add("actionbar");
                    if (d.bossbar) ch.add("bossbar(" + d.barColor.name().toLowerCase(Locale.ROOT) + "/" + d.barOverlay.name().toLowerCase(Locale.ROOT) + ")");
                    if (d.sidebar) ch.add("sidebar(" + d.sidebarLines() + " lines)");
                    say(sender, d.id() + ": channels=" + String.join(",", ch) + " update=" + d.updateTicks + " ticks font=" + h.font().asString(), NamedTextColor.AQUA);
                }
                if (h.defs().isEmpty()) say(sender, "No HUDs.", NamedTextColor.GRAY);
            }
            case "check" -> {
                if (!allowed(sender, "hud.admin")) return;
                List<String> out = new ArrayList<>();
                out.add("hud index: huds=" + h.defs().size() + " timer=" + Huds.TIMER + " max_lines=" + Huds.MAX_LINES + " font=" + h.font().asString());
                for (HudDef d : h.defs().values()) d.glyphs(out);
                for (String s : out) say(sender, s, NamedTextColor.AQUA);
            }
            case "preview" -> {
                if (!allowed(sender, "hud.admin")) return;
                HudDef d = args.length >= 3 ? h.def(args[2].toLowerCase(Locale.ROOT)) : null;
                String ch = args.length >= 4 ? args[3].toLowerCase(Locale.ROOT) : "";
                double f;
                try { f = args.length >= 5 ? Double.parseDouble(args[4]) : 1.0; } catch (NumberFormatException e) { f = -1; }
                int line = ch.startsWith("line") ? parse(ch.substring(4)) : 0;
                boolean known = ch.equals("actionbar") || ch.equals("bossbar") || ch.equals("title") || (ch.startsWith("line") && line >= 0);
                if (d == null || !known || f < 0 || f > 1) { say(sender, "Usage: /" + label + " hud preview <id> <actionbar|bossbar|title|line<N>> <0-1>", NamedTextColor.RED); return; }
                HudRender r = h.preview(d, ch, f, line);
                say(sender, d.id() + " " + ch + " @" + HudRender.fmt(f) + ": " + r.tokens(), NamedTextColor.AQUA);
                if (ch.equals("bossbar")) say(sender, "progress " + HudRender.fmt(d.bossbarProgress(r)), NamedTextColor.AQUA);
                say(sender, "json " + GsonComponentSerializer.gson().serialize(r.component()), NamedTextColor.GRAY);
            }
            default -> say(sender, "Usage: /" + label + " hud toggle | list | check | preview <id> <channel> <0-1>", NamedTextColor.RED);
        }
    }

    private static int parse(String s) { try { return Integer.parseInt(s); } catch (NumberFormatException e) { return -1; } }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String used, String[] args) {
        List<String> out = new ArrayList<>();
        String last = args.length == 0 ? "" : args[args.length - 1].toLowerCase(Locale.ROOT);
        if (args.length <= 1) {
            if ("hud".startsWith(last)) out.add("hud");
            if (nextTab != null) for (String s : nextTab.onTabComplete(sender, command, used, args)) if (!out.contains(s)) out.add(s);
            return out;
        }
        if (args[0].equalsIgnoreCase("hud") && args.length == 2) { for (String s : HSUBS) if (s.startsWith(last)) out.add(s); return out; }
        if (args[0].equalsIgnoreCase("hud") && args.length == 3) { for (String s : h.defs().keySet()) if (s.startsWith(last)) out.add(s); return out; }
        return nextTab == null ? out : nextTab.onTabComplete(sender, command, used, args);
    }
}
`;

