// Cyrus R4 HUD and glyphs: metadata of the HUD components + the library hash. "Verified" as for the other designer
// libraries: javac against the real Paper classpaths of 1.21.11 (JDK 21) and 26.2 (JDK 25) with zero warnings, the strict
// safety scan, a Test Flight boot with RCON checks (test/cyrus-hud-real.ts). What a player SEES is not verified without a
// real client (fonts, glyph alignment, the sidebar, the action bar timing).
import { createHash } from "node:crypto";
import type { ComponentMeta } from "../components";
import { HUD_LIMITS } from "./spec";
import * as J from "./java";

export const HUD_LIBRARY_VERSION = "cyrus-hud-components-1";
const ALL: ("1.21" | "26")[] = ["1.21", "26"];
const UNIT = "test/cyrus-hud.test.ts (pure: present in every HUD compile, strict-scan text rules, precheck, golden hashes, TS render twin)";
const REAL = "test/cyrus-hud-real.ts (javac 1.21.11/JDK 21 + 26.2/JDK 25 with 0 warnings, strict scan, Test Flight boot + RCON)";

export const HUD_COMPONENTS: ComponentMeta[] = [
  { id: "hud-def", file: "designer/HudDef.java", purpose: "base of every generated HUD: channels, bar style, update rate, render hooks", families: ALL, limits: [`${HUD_LIMITS.maxParts} parts per line`, `${HUD_LIMITS.maxSidebarLines} sidebar lines`], tests: [UNIT, REAL], source: J.HUDDEF_JAVA },
  { id: "hud-render", file: "designer/HudRender.java", purpose: "builds one HUD line: glyphs + spaces in the mod's font, text in the default font, bars from glyph segments; the token string the TS twin reproduces", families: ALL, limits: ["glyphs drawn white (no tint)", "1-20 bar segments"], tests: [UNIT, REAL, "Test Flight: hud preview == TS tokens"], source: J.HUDRENDER_JAVA },
  { id: "hud-sources", file: "designer/HudSources.java", purpose: "values: health, food, XP, air, an ability's charges / cooldown, holding a design item", families: ALL, limits: ["read only"], tests: [UNIT, REAL], source: J.HUDSOURCES_JAVA },
  { id: "hud-runtime", file: "designer/Huds.java", purpose: "the HUD hub: one timer, action bar / per-player boss bars / per-player sidebar (never replacing another plugin's scoreboard), toggle, cleanup, huds.* migration", families: ALL, limits: ["one timer per mod (10 ticks)", "update 10-40 ticks per HUD", "the sidebar only for players on the main scoreboard"], tests: [UNIT, REAL, "Test Flight: hud list / check / preview, reload clamps"], source: J.HUDS_JAVA },
  { id: "hud-command", file: "designer/HudCommand.java", purpose: "hud subcommands (toggle, list, check, preview) wrapping the mod command; reload + params include HUDs", families: ALL, limits: ["toggle: players (<ns>.hud.toggle)", "list / check / preview: <ns>.hud.admin"], tests: [UNIT, REAL], source: J.HUDCOMMAND_JAVA },
];
/** Only in mods with HUDs AND bosses (the boss_health source / in_boss_arena condition). */
export const HUD_BOSS_COMPONENT: ComponentMeta = { id: "hud-boss", file: "designer/HudBossSource.java", purpose: "the nearest live boss of an id whose arena the player is in", families: ALL, limits: ["read only"], tests: [UNIT, REAL], source: J.HUDBOSS_JAVA };

export function hudLibraryHash(): string {
  const h = createHash("sha256");
  h.update(HUD_LIBRARY_VERSION);
  for (const c of [...HUD_COMPONENTS, HUD_BOSS_COMPONENT]) { h.update(c.id); h.update(c.source); }
  return h.digest("hex");
}

