// Cyrus R4 HUD and glyphs: the HUD code generator, used by the mod compiler (../gameplay/compile.ts compileMod) when a
// mod has HUD designs. Texts, bar segment counts and the update rate are config.yml parameters under huds.<id>. (each
// Param carries `ptr`, edits go through ../gameplay/params.ts); glyphs, sources, channels and bar style are Java.
// Glyph characters are constants built from the codepoints allocateHudGlyphs gives the project (the same numbers the
// resource pack font uses: ./font.ts).
import { addParam, colorExpr, jstr, loadLine, camel, JTYPE, type Param, type ParamSink } from "../compile";
import { allocateHudGlyphs, type HudDesign, type HudPart, type HudShow, type HudSource } from "./spec";

export const HUD_COMPILER_VERSION = "cyrus-hud-compile-1";
export type HudParam = Param & { ptr: (string | number)[] };
type Sink = ParamSink & { params: HudParam[] };
function P(s: Sink, rel: string, kind: "text" | "int", cap: [number, number], value: number | string, label: string, role: string, ptr: (string | number)[]) {
  const p = addParam(s, rel, kind, cap, value, label, role) as HudParam;
  p.ptr = ptr;
}

const partsParams = (s: Sink, rel: string, parts: HudPart[], what: string, ptr: (string | number)[]) =>
  parts.forEach((p, i) => { if (p.type === "text") P(s, `${rel}.p${i}.text`, "text", [0, 40], p.text, `${what} text ${i + 1}`, "text", [...ptr, i, "text"]); });

export function hudParams(h: HudDesign): HudParam[] {
  const s: Sink = { params: [], base: `huds.${h.id}.`, item: h.id };
  P(s, "update_ticks", "int", [10, 40], h.updateTicks, "ticks between HUD updates (20 = 1 s)", "cooldown", ["updateTicks"]);
  (h.bars ?? []).forEach((b, i) => P(s, `bars.${b.id}.segments`, "int", [1, 20], b.segments, `bar ${b.id} segments`, "count", ["bars", i, "segments"]));
  if (h.actionbar) partsParams(s, "actionbar", h.actionbar.parts, "action bar", ["actionbar", "parts"]);
  if (h.bossbar) partsParams(s, "bossbar", h.bossbar.parts, "boss bar", ["bossbar", "parts"]);
  if (h.sidebar) {
    partsParams(s, "sidebar.title", h.sidebar.title, "sidebar title", ["sidebar", "title"]);
    h.sidebar.lines.forEach((l, j) => partsParams(s, `sidebar.l${j}`, l, `sidebar line ${j + 1}`, ["sidebar", "lines", j]));
  }
  return s.params.map((p) => ({ ...p, owner: "hud" as const }));
}

/** Sources of a HUD in first-use order (bars, then channel parts, then the boss bar progress); deduplicated. */
export function hudSources(h: HudDesign): HudSource[] {
  const out: HudSource[] = [];
  const add = (x: HudSource) => { if (!out.some((y) => JSON.stringify(y) === JSON.stringify(x))) out.push(x); };
  for (const b of h.bars ?? []) add(b.source);
  for (const parts of [h.actionbar?.parts ?? [], h.bossbar?.parts ?? [], ...(h.sidebar ? [h.sidebar.title, ...h.sidebar.lines] : [])]) for (const p of parts) if (p.type === "value") add(p.source);
  if (h.bossbar?.progress) add(h.bossbar.progress);
  return out;
}
const srcIndex = (h: HudDesign, s: HudSource) => hudSources(h).findIndex((x) => JSON.stringify(x) === JSON.stringify(s));
export const needsBosses = (h: HudDesign) => hudSources(h).some((s) => s.type === "boss_health") || [h.actionbar?.show, h.bossbar?.show, h.sidebar?.show].some((x) => x?.when === "in_boss_arena");

function sourceExpr(s: HudSource): string {
  switch (s.type) {
    case "health": return "HudSources.health(p)";
    case "food": return "HudSources.food(p)";
    case "xp_level": return "HudSources.xp(p)";
    case "air": return "HudSources.air(p)";
    case "ability_charges": return `HudSources.charges(h.designer(), p, ${jstr(s.item)}, ${jstr(s.ability)})`;
    case "ability_cooldown": return `HudSources.cooldown(h.designer(), p, ${jstr(s.item)}, ${jstr(s.ability)})`;
    case "boss_health": return `HudBossSource.health(bosses, p, ${jstr(s.boss)})`;
  }
}
function showExpr(s: HudShow): string {
  switch (s.when) {
    case "always": return "true";
    case "holding": return `HudSources.holding(h.designer(), p, ${jstr(s.item)})`;
    case "in_boss_arena": return `HudBossSource.inArena(bosses, p, ${jstr(s.boss)})`;
  }
}

export function hudClass(pkg: string, h: HudDesign, cls: string, ns: string): { source: string; params: HudParam[] } {
  const params = hudParams(h);
  const base = `huds.${h.id}.`;
  const field = new Map(params.map((p) => [p.path.slice(base.length), p.field]));
  const slots = allocateHudGlyphs([h], ns); // codepoints are mod-wide: recomputed below with every HUD of the mod
  void slots;
  return { source: "", params };
}

