  const F = (rel: string) => { const p = params.find((x) => x.path === base + rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
  const gconst = new Map<string, string>(), sconst = new Map<number, string>();
  const consts: string[] = [];
  for (const g of h.glyphs) { const s = slotsOfMod.find((x) => x.kind === "glyph" && x.hud === h.id && x.name === g.name)!; const c = `G_${g.name.toUpperCase()}`; gconst.set(g.name, c); consts.push(`private static final String ${c} = new String(Character.toChars(0x${s.codepoint.toString(16).toUpperCase()}));`); }
  for (const s of slotsOfMod.filter((x) => x.kind === "space")) { const c = `S_${s.px! < 0 ? "M" : "P"}${Math.abs(s.px!)}`; sconst.set(s.px!, c); consts.push(`private static final String ${c} = new String(Character.toChars(0x${s.codepoint.toString(16).toUpperCase()}));`); }
  const lines = (rel: string, parts: HudPart[]) => parts.map((p, i) => {
    switch (p.type) {
      case "text": return `r.text(${F(`${rel}.p${i}.text`)}, ${p.color ? colorExpr(p.color) : "null"});`;
      case "glyph": return `r.glyph(${gconst.get(p.glyph)}, ${jstr(p.glyph)});`;
      case "space": return `r.space(${sconst.get(p.px)}, ${p.px});`;
      case "value": return `r.value(${srcIndex(h, p.source)}, ${p.format === "percent" ? 1 : p.format === "fraction" ? 2 : 0}, ${p.color ? colorExpr(p.color) : "null"});`;
      case "bar": {
        const b = h.bars!.find((x) => x.id === p.bar)!;
        return `r.bar(${srcIndex(h, b.source)}, ${F(`bars.${b.id}.segments`)}, ${gconst.get(b.full)}, ${jstr(b.full)}, ${b.half ? gconst.get(b.half) : "null"}, ${b.half ? jstr(b.half) : "null"}, ${gconst.get(b.empty)}, ${jstr(b.empty)}, ${b.gap ? sconst.get(b.gap) : "null"}, ${b.gap ?? 0});`;
      }
    }
  });
  const bosses = needsBosses(h);
  const ctor = [
    `super(h, ${jstr(h.id)});`,
    ...(bosses ? ["this.bosses = bosses;"] : []),
    ...(h.actionbar ? ["actionbar = true;"] : []),
    ...(h.bossbar ? ["bossbar = true;", `barColor = BossBar.Color.${(h.bossbar.color ?? "white").toUpperCase()};`, `barOverlay = BossBar.Overlay.${(h.bossbar.overlay ?? "progress").toUpperCase()};`] : []),
    ...(h.sidebar ? ["sidebar = true;"] : []),
  ];
  const srcs = hudSources(h);
  const shows = ([["actionbar", h.actionbar?.show], ["bossbar", h.bossbar?.show], ["sidebar", h.sidebar?.show]] as const).filter(([, s]) => s && s.when !== "always");
  const body: string[] = [];
  const method = (sig: string, inner: string[]) => body.push(``, `    @Override`, `    public ${sig} {`, ...inner.map((l) => `        ${l}`), `    }`);
  method("double[] source(int index, Player p)", srcs.length ? [`switch (index) {`, ...srcs.map((s, i) => `    case ${i}: return ${sourceExpr(s)};`), `    default: return null;`, `}`] : [`return null;`]);
  if (shows.length) method("boolean show(String channel, Player p)", [`switch (channel) {`, ...shows.map(([c, s]) => `    case ${jstr(c)}: return ${showExpr(s!)};`), `    default: return true;`, `}`]);
  if (h.actionbar) method("void actionbar(HudRender r)", lines("actionbar", h.actionbar.parts));
  if (h.bossbar) {
    method("void bossbar(HudRender r)", lines("bossbar", h.bossbar.parts));
    if (h.bossbar.progress) method("double bossbarProgress(HudRender r)", [`return r.fraction(${srcIndex(h, h.bossbar.progress)});`]);
  }
  if (h.sidebar) {
    method("void sidebarTitle(HudRender r)", lines("sidebar.title", h.sidebar.title));
    method("int sidebarLines()", [`return ${h.sidebar.lines.length};`]);
    method("void sidebarLine(int line, HudRender r)", [`switch (line) {`, ...h.sidebar.lines.flatMap((l, j) => [`    case ${j}: {`, ...lines(`sidebar.l${j}`, l).map((x) => `        ${x}`), `        return;`, `    }`]), `    default: return;`, `}`]);
  }
  const glyphLines = [
    ...h.glyphs.map((g) => `out.add("glyph " + id() + "." + ${jstr(g.name)} + " U+" + Integer.toHexString(${gconst.get(g.name)}.codePointAt(0)).toUpperCase(Locale.ROOT) + " chars=" + ${gconst.get(g.name)}.length());`),
    ...[...sconst].filter(([px]) => slotsOfMod.some((s) => s.kind === "space" && s.px === px)).map(([px, c]) => `out.add("space " + id() + " " + ${px} + " U+" + Integer.toHexString(${c}.codePointAt(0)).toUpperCase(Locale.ROOT));`),
  ];
  method("void glyphs(List<String> out)", glyphLines);
  const src = [
    `package ${pkg}.huds;`, ``,
    `import java.util.List;`, `import java.util.Locale;`,
    `import net.kyori.adventure.bossbar.BossBar;`, `import net.kyori.adventure.text.format.NamedTextColor;`, `import net.kyori.adventure.text.format.TextColor;`,
    `import org.bukkit.entity.Player;`,
    ...(bosses ? [`import ${pkg}.designer.Bosses;`, `import ${pkg}.designer.HudBossSource;`] : []),
    `import ${pkg}.designer.DesignConfig;`, `import ${pkg}.designer.HudDef;`, `import ${pkg}.designer.HudRender;`, `import ${pkg}.designer.HudSources;`, `import ${pkg}.designer.Huds;`, ``,
    `/** HUD ${h.id} (${ns}:hud font). Generated by Cyrus from assets/designs/${h.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
    `public final class ${cls} extends HudDef {`,
