    `    }`,
    ``,
    `    @Override`,
    `    public void load(DesignConfig c) {`,
    ...params.map((p) => `        ${loadLine(p, p.path.slice(base.length))}`),
    `        updateTicks = p_update_ticks;`,
    `    }`,
