// Cyrus R4 HUD and glyphs: the TS twin of HudRender (./java.ts): the token string of one HUD line, exactly as
// `/<mod> hud preview <id> <channel> <fraction>` prints it on the server ([glyph] {px} 'text' <value>), and the glyph
// codepoint lines of `/<mod> hud check`. The real-server flight compares both line by line. What the client draws (the
// font, alignment, shadows) is not modelled.
import { allocateHudGlyphs, type HudDesign, type HudPart } from "./spec";
import { HUD_LIMITS } from "./spec";

const fmt = (v: number) => (Math.round(v * 100) / 100).toFixed(2);
const jround = (x: number) => Math.floor(x + 0.5);

export type HudChannelRef = "actionbar" | "bossbar" | "title" | `line${number}`;

function partsOf(h: HudDesign, ch: HudChannelRef): HudPart[] {
  if (ch === "actionbar") return h.actionbar?.parts ?? [];
  if (ch === "bossbar") return h.bossbar?.parts ?? [];
  if (ch === "title") return h.sidebar?.title ?? [];
  return h.sidebar?.lines[Number(ch.slice(4))] ?? [];
}

/** Tokens of one channel with every source at `fraction` (the preview: value = fraction x 20). `segments` overrides bar sizes (config edits). */
export function previewTokens(h: HudDesign, ch: HudChannelRef, fraction: number, segments: Record<string, number> = {}): string {
  const f = Math.max(0, Math.min(1, fraction));
  let out = "";
  for (const p of partsOf(h, ch)) {
    switch (p.type) {
      case "text": if (p.text) out += `'${p.text}'`; break;
      case "glyph": out += `[${p.glyph}]`; break;
      case "space": out += `{${p.px}}`; break;
      case "value": out += `<${p.format === "percent" ? `${jround(f * 100)}%` : p.format === "fraction" ? `${jround(f * 20)}/20` : String(jround(f * 20))}>`; break;
      case "bar": {
        const b = h.bars!.find((x) => x.id === p.bar)!;
        const n = Math.max(1, Math.min(20, segments[b.id] ?? b.segments));
        const units = f * n;
        const whole = Math.floor(units + 1e-9);
        const half = !!b.half && whole < n && units - whole >= 0.5 - 1e-9;
        for (let i = 0; i < n; i++) {
          if (i > 0 && b.gap) out += `{${b.gap}}`;
          out += `[${i < whole ? b.full : i === whole && half ? b.half : b.empty}]`;
        }
        break;
      }
    }
  }
  return out;
}

/** The line `/<mod> hud preview` prints first: `<id> <channel> @<f>: <tokens>`. */
export const previewLine = (h: HudDesign, ch: HudChannelRef, fraction: number) => `${h.id} ${ch} @${fmt(fraction)}: ${previewTokens(h, ch, fraction)}`;

/** The lines of `/<mod> hud check` (index + per HUD its glyphs and spaces, in Java's order). */
export function hudCheckLines(huds: HudDesign[], namespace: string): string[] {
  const slots = allocateHudGlyphs(huds, namespace);
  const out = [`hud index: huds=${huds.length} timer=10 max_lines=${HUD_LIMITS.maxSidebarLines} font=${namespace}:hud`];
  for (const h of [...huds].sort((a, b) => (a.id < b.id ? -1 : 1))) {
    for (const g of h.glyphs) { const s = slots.find((x) => x.kind === "glyph" && x.hud === h.id && x.name === g.name)!; out.push(`glyph ${h.id}.${g.name} U+${s.codepoint.toString(16).toUpperCase()} chars=2`); }
    for (const s of slots.filter((x) => x.kind === "space")) out.push(`space ${h.id} ${s.px} U+${s.codepoint.toString(16).toUpperCase()}`);
  }
  return out;
}

