main=r'''async function main() {
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, bot: false, aiModel: "none (designs are fixtures; no model call)", lanes: [] as unknown[] };
  mkdirSync(RUN, { recursive: true });
  // the deliberately broken HUD: rejected by the validator (and compileMod refuses the mod)
  const broken = validateGameplay([...loadHudFixtures(), loadBrokenHud()], { version: "1.21.11", namespace: NS });
  const bf = broken.files.find((f) => f.id === "broken_hud")!;
  const bc = compileMod([...loadHudFixtures(), loadBrokenHud()], { version: "1.21.11", namespace: NS, pluginName: PLUGIN });
  res.brokenDesign = { rejected: !bf.ok && !bc.ok, codes: [...new Set(bf.errors.map((e) => e.code))].sort(), errors: bf.errors.length, compileRefused: !bc.ok };
  console.log(`broken HUD rejected=${(res.brokenDesign as { rejected: boolean }).rejected} codes=${(res.brokenDesign as { codes: string[] }).codes.join(",")}`);
  for (const lane of LANES) {
