    const huds = c.huds as HudDesign[];
    const font = hudFont(huds, NS);
    L.compile = { ok: true, hash: c.hash, files: c.files.length, params: c.params.length, configVersion: c.configVersion, counts: c.counts, warnings: [...new Set(c.warnings.map((w) => w.code))] };
    L.font = { files: font.files.map((f) => `${f.path} (${f.data.length} B)`), glyphs: font.glyphs.length, spaces: font.spaces.length, problems: checkHudFont(font, NS) };
    const b = build(c, lane, "base");
    L.javac = { ok: true, sources: b.sources, classFiles: b.classFiles, ms: b.javacMs, warnings: b.javacWarnings, output: b.javacOut };
    L.jar = { sha256: b.jarSha256, bytes: b.jarBytes, reproducible: b.reproducible };
    L.scan = scan(b, lane);
    console.log(`${lane.version}: javac ok (${b.sources} sources, ${b.javacWarnings} warnings), jar reproducible=${b.reproducible}, scan blocks=${(L.scan as { blocks: number }).blocks} warnings=${(L.scan as { warnings: number }).warnings}, font problems=${(L.font as { problems: string[] }).problems.length}`);
    if (b.javacWarnings) console.log(b.javacOut);
    if (process.argv.includes("--javac-only")) continue;
    const cfg = c.files.find((f) => f.path.endsWith("config.yml"))!.content;
    const mana = huds.find((h) => h.id === "mana_hud")!, stats = huds.find((h) => h.id === "stats_hud")!;
    const clampCfg = cfg.replace(/(\n  mana_hud:\n(?:.*\n)*?    update_ticks: )10\n/, "$15\n").replace(/(\n      mana:\n(?:.*\n)*?        segments: )5\n/, "$199\n");
    const oldCfg = cfg.replace("config_version: 1", "config_version: 0").replace(/(\n      mana:\n(?:.*\n)*?        segments: )5\n/, "$17\n");
    const font_ = `"font":"${NS}:hud"`;
    const rcon: RconCheck[] = [
      { id: "plugins", command: "plugins", expect: [PLUGIN] },
      { id: "help-command", command: `help ${CMD}`, expect: [`/${CMD}: ${PLUGIN}: bosses, encounters, HUDs and items`] },
      { id: "hud-list", command: `${CMD} hud list`, expect: [`mana_hud: channels=actionbar,bossbar(red/notched_10) update=10 ticks font=${NS}:hud`, `stats_hud: channels=sidebar(3 lines) update=20 ticks font=${NS}:hud`] },
      { id: "hud-check-twin", command: `${CMD} hud check`, expect: hudCheckLines(huds, NS), expectNot: ["chars=1 "] },
      { id: "preview-actionbar-50", command: `${CMD} hud preview mana_hud actionbar 0.5`, expect: [previewLine(mana, "actionbar", 0.5), font_] },
      { id: "preview-actionbar-100", command: `${CMD} hud preview mana_hud actionbar 1`, expect: [previewLine(mana, "actionbar", 1)] },
      { id: "preview-actionbar-0", command: `${CMD} hud preview mana_hud actionbar 0`, expect: [previewLine(mana, "actionbar", 0)] },
      { id: "preview-actionbar-37", command: `${CMD} hud preview mana_hud actionbar 0.37`, expect: [previewLine(mana, "actionbar", 0.37)] },
      { id: "preview-bossbar", command: `${CMD} hud preview mana_hud bossbar 0.42`, expect: [previewLine(mana, "bossbar", 0.42), "progress 0.42", font_] },
      { id: "preview-sidebar-title", command: `${CMD} hud preview stats_hud title 1`, expect: [previewLine(stats, "title", 1)] },
      { id: "preview-sidebar-line0", command: `${CMD} hud preview stats_hud line0 0.75`, expect: [previewLine(stats, "line0", 0.75)] },
      { id: "preview-sidebar-line2", command: `${CMD} hud preview stats_hud line2 0.33`, expect: [previewLine(stats, "line2", 0.33)] },
      { id: "preview-usage", command: `${CMD} hud preview stats_hud nowhere 0.5`, expect: ["Usage: /"] },
      { id: "toggle-console", command: `${CMD} hud toggle`, expect: ["Only players can toggle their HUD."] },
      { id: "params-hud", command: `${CMD} params mana_hud`, expect: ["huds.mana_hud.update_ticks=10", "huds.mana_hud.bars.mana.segments=5", "huds.mana_hud.actionbar.p5.text= Mana", "huds.mana_hud.bossbar.p2.text=Ember Warden "] },
      { id: "chain-boss", command: `${CMD} boss list`, expect: ["ember_warden: entity=wither_skeleton"] },
      { id: "chain-items", command: `${CMD} list`, expect: ["arc_staff: identity=ok material=blaze_rod abilities=1"] },
      { id: "summary", command: CMD, expect: ["bosses ember_warden, grave_lord; encounters ash_trial"] },
      { id: "config-clamped-on-reload", writeFile: { path: `plugins/${PLUGIN}/config.yml`, content: clampCfg }, command: `${CMD} reload`, expect: ["HUDs reloaded", "clamped huds.mana_hud.update_ticks 5.0 -> 10.0", "clamped huds.mana_hud.bars.mana.segments 99.0 -> 20.0"], expectNot: ["internal error", "Exception"] },
      { id: "preview-after-clamp", command: `${CMD} hud preview mana_hud actionbar 0.5`, expect: [`mana_hud actionbar @0.50: ${previewTokens(mana, "actionbar", 0.5, { mana: 20 })}`] },
      { id: "config-migrated-on-reload", writeFile: { path: `plugins/${PLUGIN}/config.yml`, content: oldCfg }, command: `${CMD} reload`, expect: ["config.yml migrated from version 0 to 1", "HUD values updated to version 1"] },
