// Prints the golden compile record of the HUD showcase mod (the boss showcase + test/fixtures/cyrus-hud) for every
// registry version the designer supports: `npx tsx scripts/cyrus/hud-golden.ts > test/fixtures/cyrus-hud/golden.json`
// (review the diff: a changed hash means changed generated code or a changed font). `--print <file suffix|README|font>`.
import { readFileSync } from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { compileMod } from "../../lib/cyrus/designer/gameplay/compile";
import { designFeatures } from "../../lib/cyrus/designer/spec";
import { hudFont } from "../../lib/cyrus/designer/hud/font";
import type { HudDesign } from "../../lib/cyrus/designer/hud/spec";
import { VERSIONS } from "../../lib/cyrus/versions/registry";
import { BOSS_FIXTURES } from "./boss-golden";

const BFX = path.join(__dirname, "../../test/fixtures/cyrus-boss");
const HFX = path.join(__dirname, "../../test/fixtures/cyrus-hud");
export const HUD_FIXTURES = ["arc_staff", "mana_hud", "stats_hud"];
export const loadHudFixtures = () => [...BOSS_FIXTURES.map((n) => JSON.parse(readFileSync(path.join(BFX, `${n}.json`), "utf8"))), ...HUD_FIXTURES.map((n) => JSON.parse(readFileSync(path.join(HFX, `${n}.json`), "utf8")))];
export const loadBrokenHud = () => JSON.parse(readFileSync(path.join(HFX, "broken_hud.json"), "utf8"));
export const HUD_NS = "nx_r20hud01";
export const HUD_PLUGIN = "HudTrials";
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");

if (require.main === module && process.argv.includes("--print")) {
  const r = compileMod(loadHudFixtures(), { version: "1.21.11", namespace: HUD_NS, pluginName: HUD_PLUGIN });
  if (!r.ok) { console.error(r.errors); process.exit(1); }
  for (const want of process.argv.slice(process.argv.indexOf("--print") + 1)) console.log(`===== ${want}\n${want === "README" ? r.readme : want === "font" ? hudFont(r.huds as HudDesign[], HUD_NS).files.find((f) => f.path.endsWith(".json"))?.data.toString() : r.files.find((x) => x.path.endsWith(want))?.content}`);
} else if (require.main === module) {
  const out: Record<string, unknown> = {};
  for (const v of VERSIONS.map((x) => x.id).filter((x) => designFeatures(x).ok)) {
    const r = compileMod(loadHudFixtures(), { version: v, namespace: HUD_NS, pluginName: HUD_PLUGIN });
    if (!r.ok) { console.error(v, JSON.stringify(r.errors, null, 1)); process.exit(1); }
    out[v] = { hash: r.hash, readme: r.readmeSha256, files: Object.fromEntries(r.files.map((f) => [f.path.replace(/^src\/main\/java\/dev\/nxeon\/plugins\/hudtrials\//, ""), f.sha256])) };
  }
  const font = hudFont((compileMod(loadHudFixtures(), { version: "1.21.11", namespace: HUD_NS, pluginName: HUD_PLUGIN }) as { huds: HudDesign[] }).huds, HUD_NS);
  out.font = Object.fromEntries(font.files.map((f) => [f.path, sha(f.data)]));
  console.log(JSON.stringify(out, null, 1));
}
