    for (const v of SUPPORTED) {
      const r = compileOk(ALL(), ctx(v));
      assert.equal(r.hash, golden[v]?.hash, `${v} golden hash (regenerate: npx tsx scripts/cyrus/hud-golden.ts > test/fixtures/cyrus-hud/golden.json)`);
      assert.equal(compileOk([...ALL()].reverse(), ctx(v)).hash, r.hash, `${v} order`);
    }
    const { createHash } = require("node:crypto");
    assert.deepEqual(Object.fromEntries(hudFont(c.huds, NS).files.map((f) => [f.path, createHash("sha256").update(f.data).digest("hex")])), golden.font);
    const boss = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-boss/golden.json"), "utf8"));
    const { loadBossFixtures, BOSS_NS, BOSS_PLUGIN } = require("../scripts/cyrus/boss-golden");
    assert.equal(compileOk(loadBossFixtures(), { version: "1.21.11", namespace: BOSS_NS, pluginName: BOSS_PLUGIN }).hash, boss["1.21.11"].hash, "boss mods without a HUD are unchanged");
  });
  it("generated code: glyph constants = the font's codepoints; no reflection, threads, network, commands; strict scan + precheck clean", () => {
    const h = c.files.find((f) => f.path.endsWith("huds/ManaHudHud.java"))!.content;
    for (const s of allocateHudGlyphs(c.huds, NS).filter((x) => x.kind === "glyph" && x.hud === "mana_hud")) assert.ok(h.includes(`Character.toChars(0x${s.codepoint.toString(16).toUpperCase()})`), s.name);
    assert.match(h, /case 0: return HudSources\.charges\(h\.designer\(\), p, "arc_staff", "bolt"\);/);
    assert.match(h, /case "bossbar": return HudBossSource\.inArena\(bosses, p, "ember_warden"\);/);
    const banned = /\b(Runtime|ProcessBuilder|java\.lang\.reflect|Class\.forName|getDeclared|MethodHandles|dispatchCommand|performCommand|new Thread|Executors|java\.net|HttpClient|System\.exit|setOp|getenv|ClassLoader|ObjectInputStream|Unsafe|ScriptEngine|runTaskAsynchronously|sendPacket|craftbukkit|net\.minecraft)\b/;
    for (const f of java) assert.doesNotMatch(f.content, banned, f.path);
    const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
    assert.deepEqual(S.scanSource(java.map((f) => ({ abs: path.join(tmp, f.path), rel: f.path }))), []);
    const pre = require(path.join(ROOT, "services/modbuilder/precheck.js"));
    for (const v of SUPPORTED) {
      const r = compileOk(ALL(), ctx(v));
      const d = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-hud-pre-"));
      const files = r.files.filter((f) => f.path.endsWith(".java")).map((f) => { const abs = path.join(d, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); return { abs, rel: f.path }; });
      assert.deepEqual(pre.precheck(files, v), [], v);
