  it("delivery rules are in the component code: main-scoreboard guard, re-sent action bar, cleanup, toggle in the PDC, the own font", () => {
    const hub = c.files.find((f) => f.path.endsWith("designer/Huds.java"))!.content;
    for (const must of ["p.getScoreboard() == Bukkit.getScoreboardManager().getMainScoreboard()", "p.sendActionBar(r.component())", "p.hideBossBar(", "NumberFormat.blank()", "hud_off", "Key.key(d.namespace(), \"hud\")", "public static final int TIMER = 10;", "huds."]) assert.ok(hub.includes(must), must);
    const render = c.files.find((f) => f.path.endsWith("designer/HudRender.java"))!.content;
    assert.match(render, /Component\.text\(chars, NamedTextColor\.WHITE\)\.font\(font\)/);
