  it("config.yml (huds section), plugin.yml (hud nodes), README", () => {
    const cfg = c.files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, /^huds:\n  mana_hud:\n/m); assert.match(cfg, /Values under "items", "bosses", "encounters" and "huds"/);
    const yml = c.files.find((f) => f.path.endsWith("plugin.yml"))!.content;
    assert.match(yml, new RegExp(`${NS}\\.hud\\.toggle:\\n    description: .*\\n    default: true`)); assert.match(yml, new RegExp(`${NS}\\.hud\\.admin:\\n    description: .*\\n    default: op`));
    assert.match(yml, /usage: '\/hudtrials <boss\|encounter\|hud\|give\|list\|params\|reload>'/);
