    const x = decideDesignerRoute({ ...base, text: "a HUD with a minimap in the corner" });
    assert.equal(x.route, false); assert.deepEqual(x.notices, [HUD_LIMIT_NOTICE]);
    assert.equal(decideDesignerRoute({ ...base, text: "a sword with a cooldown" }).hud, undefined);
