    assert.equal(on.service?.hud, true); assert.equal(on.service?.design, true); assert.equal(on.meta!.designer!.hud, true);
    const TX = require(path.join(ROOT, "services/modbuilder/textures.js"));
    const ok = () => true;
    assert.equal(TX.parseAssetsRequest({ namespace: NS, design: true, hud: true }, "1.21.11", new Set(), ok, ok).hud, true);
