toolu_01BHekctKtGo6XRm15pscPWg.content:
// Cyrus R4 HUD and glyphs (pure): the HUD design IR ("kind":"hud" on the existing design files), the honest limits
// (text channels only), caps and the corpus, glyph codepoints from the project's glyph block (identifier registry), the
// resource pack font (bitmap + space providers, PNG cells) and the pack builder, the HUD component library and compiler
// (golden hashes, strict scan, precheck, a HUD-only mod without the boss library), edit without regenerating, the TS
// render twin checked against the REAL server's `hud check` / `hud preview` output, TS == the service bundle, the prompt
// part, routing (incl. the client-only exclusions), the build request, the service workspace and the portal sync.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { GLYPH_PRESETS, HUD_CAPS, HUD_LIMITS, allocateHudGlyphs, glyphArt, glyphMetrics, hudIdentRecords, hudJsonSchema, partsWidth, type HudDesign } from "../lib/cyrus/designer/hud/spec";
import { checkHudFont, hudFont } from "../lib/cyrus/designer/hud/font";
import { HUD_BOSS_COMPONENT, HUD_COMPONENTS } from "../lib/cyrus/designer/hud/components";
import { hudParams, hudSources } from "../lib/cyrus/designer/hud/compile";
import { hudCheckLines, previewLine, previewTokens } from "../lib/cyrus/designer/hud/simulate";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { recompileModWithEdits } from "../lib/cyrus/designer/gameplay/params";
import { designKind, validateGameplay } from "../lib/cyrus/designer/gameplay/spec";
import { BOSS_COMPONENTS } from "../lib/cyrus/designer/boss/components";
import { designFeatures } from "../lib/cyrus/designer/spec";
import { decideDesignerRoute, hasHudDesigns, matchHudWords, HUD_LIMIT_NOTICE } from "../lib/cyrus/designer/route";
import { checkReturnedDesigns, DESIGN_KIND_MIME } from "../lib/cyrus/designer/sync";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { assetLines } from "../lib/cyrus-mods/doc";
import { buildPack } from "../lib/cyrus/textures/pack";
import { detectCollisions, glyphBlockStart, glyphHomeBlock, isGlyphCodepoint } from "../lib/cyrus/engine-core/identifiers";
import { VERSIONS } from "../lib/cyrus/versions/registry";
import { HUD_NS as NS, HUD_PLUGIN, loadBrokenHud, loadHudFixtures } from "../scripts/cyrus/hud-golden";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-hud");
const ALL = () => loadHudFixtures();
const byId = (id: string) => ALL().find((d: { id: string }) => d.id === id);
const clone = <T,>(x: T): T => structuredClone(x);
const SUPPORTED = VERSIONS.map((v) => v.id).filter((v) => designFeatures(v).ok);
const ctx = (version = "1.21.11") => ({ version, namespace: NS, pluginName: HUD_PLUGIN });
const compileOk = (d: unknown[], c = ctx()): ModCompileOk => { const r = compileMod(d, c); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const mana = (): HudDesign => clone(byId("mana_hud"));
const stats = (): HudDesign => clone(byId("stats_hud"));
const rest = (id: string) => ALL().filter((d: { id: string }) => d.id !== id);
const codesOf = (inputs: unknown[], file?: string) => { const v = validateGameplay(inputs, { version: "1.21.11", namespace: NS }); return (file ? v.files.find((f) => f.id === file)?.errors ?? [] : v.errors).map((e) => e.code); };
const hudCodes = (h: HudDesign) => codesOf([...rest(h.id), h], h.id);
/** A HUD-only mod: the staff (for its charges) and a health / food HUD, no bosses. */
const hudOnly = () => { const s = stats(); return [byId("arc_staff"), s]; };

describe("HUD IR: the showcase", () => {
  it("is valid on every supported version; the kind discriminator; text channels only", () => {
    for (const v of SUPPORTED) { const r = validateGameplay(ALL(), { version: v, namespace: NS }); assert.ok(r.ok, `${v}: ${JSON.stringify(r.errors.slice(0, 3))}`); assert.equal(r.huds.length, 2); }
    assert.equal(designKind({ kind: "hud" }), "hud");
    const keys = Object.keys((hudJsonSchema() as { properties: Record<string, unknown> }).properties);
    assert.deepEqual(keys.filter((k) => !["schemaVersion", "kind", "id", "glyphs", "bars", "updateTicks"].includes(k)).sort(), ["actionbar", "bossbar", "sidebar"], "no other place on screen");
  });
  it("the JSON Schema file is current", () => {
    assert.deepEqual(JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/designer/hud.v1.schema.json"), "utf8")), JSON.parse(JSON.stringify(hudJsonSchema())));
  });
  it("presets are rectangular-enough pixel art in 4 tones; custom pixels use their palette", () => {
    for (const [name, rows] of Object.entries(GLYPH_PRESETS)) { assert.ok(rows.length >= 3 && rows.length <= 16, name); assert.ok(rows.every((r) => /^[.#+o-]+$/.test(r)), name); }
    const a = glyphArt({ name: "c", pixels: ["ab", ".b"], palette: { a: "#112233", b: "#AABBCC" } });
    assert.deepEqual(a.px, [["#112233", "#aabbcc"], [null, "#aabbcc"]]);
    assert.deepEqual(glyphMetrics({ name: "h", preset: "heart" }), { size: 7, height: 7, ascent: 6 });
  });
});

describe("HUD IR: caps and corpus", () => {
  it("caps: glyph height / ascent, segments, space px, update ticks, text length, glyph and line counts", () => {
    const set = (f: (h: HudDesign) => void) => { const h = mana(); f(h); return hudCodes(h); };
    for (const [lo, hi] of [HUD_CAPS.glyphHeight]) { assert.ok(!set((h) => { h.glyphs[3].height = hi; h.glyphs[3].ascent = 1; }).length); assert.ok(set((h) => { h.glyphs[3].height = lo - 1; }).includes("schema")); assert.ok(set((h) => { h.glyphs[3].height = hi + 1; }).includes("schema")); }
    assert.ok(set((h) => { h.bars![0].segments = 21; }).includes("schema")); assert.ok(set((h) => { h.bars![0].segments = 0; }).includes("schema")); assert.deepEqual(set((h) => { h.bars![0].segments = 20; }), []);
    assert.ok(set((h) => { h.updateTicks = 9; }).includes("schema")); assert.ok(set((h) => { h.updateTicks = 41; }).includes("schema"));
    assert.ok(set((h) => { h.actionbar!.parts.push({ type: "space", px: 0 }); }).includes("schema"), "a 0 px space is refused");
    assert.ok(set((h) => { h.actionbar!.parts.push({ type: "space", px: 65 }); }).includes("schema"));
    assert.ok(set((h) => { h.actionbar!.parts.push({ type: "text", text: "x".repeat(41) }); }).includes("schema"));
    assert.ok(set((h) => { h.glyphs = Array.from({ length: 25 }, (_, i) => ({ name: `g${i}a`, preset: "dot" })); }).includes("schema"));
    const s = stats(); s.sidebar!.lines = Array.from({ length: 9 }, () => [{ type: "text", text: "x" }]); assert.ok(hudCodes(s).includes("schema"));
    assert.equal(HUD_LIMITS.maxHuds, 2);
  });
  it("the deliberately broken HUD is rejected with every code; compileMod refuses the mod", () => {
    const c = codesOf([...ALL(), loadBrokenHud()], "broken_hud").sort();
    for (const k of ["ascent_height", "glyph_source", "palette_key", "pixel_rows", "unresolved_ref"]) assert.ok(c.includes(k), `${k} in ${c}`);
    assert.equal(compileMod([...ALL(), loadBrokenHud()], ctx()).ok, false);
  });
  it("refuses code, free positioning and unknown channels; checks sources, conditions and channels across files", () => {
    for (const bad of [{ ...mana(), overlay: { x: 10, y: 20 } }, { ...mana(), shader: "rendertype_text" }, { ...mana(), actionbar: { parts: [{ type: "command", text: "op @a" }] } }]) assert.ok(hudCodes(bad as HudDesign).includes("schema"));
    const nc = mana(); nc.bars![0].source = { type: "ability_charges", item: "ember_core", ability: "x" }; assert.ok(hudCodes(nc).includes("unresolved_ref"));
    const nch = mana(); nch.bars![0].source = { type: "ability_cooldown", item: "arc_staff", ability: "bolt" }; assert.deepEqual(hudCodes(nch), [], "bolt has a cooldown");
