describe("glyph codepoints, the font and the pack", () => {
  const huds = () => [mana(), stats()];
  it("codepoints come from the project's home glyph block (identifier registry), deterministic, sorted, then spaces", () => {
    const slots = allocateHudGlyphs(huds(), NS);
