    assert.deepEqual(slots.map((s) => s.codepoint), slots.map((_, i) => start + i));
    assert.ok(slots.every((s) => isGlyphCodepoint(s.codepoint)));
    assert.deepEqual(slots.filter((s) => s.kind === "space").map((s) => s.px), [-1, 2, 3, 8]);
    assert.deepEqual(allocateHudGlyphs([stats(), mana()], NS), slots, "order independent");
    assert.deepEqual(detectCollisions(hudIdentRecords(huds(), NS)), [], "no clash inside the mod");
    assert.ok(hudIdentRecords(huds(), NS).every((r) => r.kind === "glyph" && r.id.startsWith(`${NS}:`)));
  });
  it("the font: one bitmap provider per glyph (square PNG cell, ascent <= height, one char) + one space provider; re-checked", () => {
    const f = hudFont(huds(), NS);
    assert.deepEqual(checkHudFont(f, NS), []);
    const doc = JSON.parse(f.files.find((x) => x.path === `assets/${NS}/font/hud.json`)!.data.toString());
    assert.equal(doc.providers.filter((p: { type: string }) => p.type === "bitmap").length, 9);
    const sp = doc.providers.find((p: { type: string }) => p.type === "space");
    assert.deepEqual(Object.values(sp.advances), [-1, 2, 3, 8]);
    const slots = allocateHudGlyphs(huds(), NS);
    for (const p of doc.providers.filter((x: { type: string }) => x.type === "bitmap")) { const cp = p.chars[0].codePointAt(0); assert.ok(slots.some((s) => s.codepoint === cp)); assert.ok(p.ascent <= p.height); }
    const coin = doc.providers.find((p: { file: string }) => p.file.endsWith("stats_hud_coin.png"));
    assert.deepEqual([coin.height, coin.ascent], [7, 6]);
    const png = f.files.find((x) => x.path.endsWith("mana_hud_mana_full.png"))!.data;
    assert.deepEqual([png.readUInt32BE(16), png.readUInt32BE(20)], [9, 9], "a 9x5 bar in a 9x9 cell");
    const broken = { ...f, files: f.files.map((x) => (x.path.endsWith(".json") ? { ...x, data: Buffer.from(x.data.toString().replace('"ascent": 6', '"ascent": 60')) } : x)) };
    assert.ok(checkHudFont(broken, NS).some((m) => /ascent/.test(m)), "the re-check catches a broken font");
    assert.deepEqual(hudFont([], NS).files, []);
  });
  it("the pack builder ships the font (alone or with textures); foreign paths and non-PNGs are refused", () => {
    const f = hudFont(huds(), NS);
    const only = buildPack({ namespace: NS, description: "hud", mcVersion: "1.21.11", textures: [], fonts: f.files });
    assert.ok(only.ok, !only.ok ? only.error : "");
    if (only.ok) { assert.ok(only.pack.files.includes(`assets/${NS}/font/hud.json`)); assert.equal(only.pack.fonts!.length, f.files.length); }
    const tex = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
    const both = buildPack({ namespace: NS, description: "hud", mcVersion: "1.21.11", textures: [tex], fonts: f.files });
    assert.ok(both.ok && both.pack.files.includes(`assets/${NS}/textures/item/${tex.name}.png`) && both.pack.files.includes(`assets/${NS}/font/hud.json`));
    assert.match((buildPack({ namespace: NS, description: "x", mcVersion: "1.21.11", textures: [], fonts: [{ path: "assets/minecraft/font/default.json", data: Buffer.from("{}") }] }) as { error: string }).error, /outside this mod's font folders/);
    assert.match((buildPack({ namespace: NS, description: "x", mcVersion: "1.21.11", textures: [], fonts: [{ path: `assets/${NS}/textures/font/hud/x.png`, data: Buffer.from("nope") }] }) as { error: string }).error, /not a PNG/);
    const none = buildPack({ namespace: NS, description: "x", mcVersion: "1.21.11", textures: [] });
