// REAL scripted-player flight for the boss + HUD designers on node-2 (not part of the unit suite): ONE Test Flight on
// Paper 1.21.11 (the only version the playtest bot is verified on) with the HudTrials jar (the boss showcase + the HUD
// showcase) and the Mineflayer bot (runner tf-lite-4, lib/cyrus/playtest), so the PLAYER side is exercised:
//   P-1 the summon item: the bot right-clicks Ember Core -> the boss spawns at it, the bot is a participant (spawn message
//       in its chat, `boss status` participants 1), the item is used up
//   P-2 a phase change by damage -> the arena title reaches the bot
//   P-3 a targeted attack on a real participant (not the test targets): slam hits the bot (knocked back)
//   P-4 the HUD: holding the Arc Staff shows the mana HUD in the bot's action bar
//   P-5 the bot does the killing blow (/damage ... by the bot) -> participants loot lands in its inventory
// Not covered even here: what the bot SEES (it does not load resource packs: glyphs are raw codepoints to it), the boss
// bar and the sidebar (no playtest step kind for them), the bot fighting by itself.
//   devhost run --lock -- npx tsx test/cyrus-designers2-playtest-real.ts --out /tank/nxeon-build/tmp/cyrus-r20-hud/playtest.json
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import { withPlaytest } from "../lib/cyrus/playtest/flight";
import { validatePlaytestPlan, type PlaytestPlan } from "../lib/cyrus/playtest/plan";
import { HUD_NS as NS, HUD_PLUGIN as PLUGIN, loadHudFixtures } from "../scripts/cyrus/hud-golden";

const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r20-hud/play-${Date.now().toString(36)}`;
const LANE = { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` };
const CMD = PLUGIN.toLowerCase();
