function iconParams(s: ParamSink, rel: string, ic: Icon, what: string) {
  if (ic.name) addParam(s, `${rel}.name`, "text", [0, 60], ic.name.text, `${what} name`, "text");
  (ic.lore ?? []).forEach((l, j) => addParam(s, `${rel}.lore${j}`, "text", [0, 60], l.text, `${what} lore line ${j + 1}`, "text"));
  if (menus.some((m) => m.openWith?.npc)) notes.push(`NPC menus open when a player right-clicks an entity tagged ${ctx.namespace}.npc.<menu id> (an operator adds the tag with /tag <entity> add ${ctx.namespace}.npc.<menu id>).`);
  if (quests.length) notes.push("Quest progress is stored on each player (no database) and survives restarts; when a quest's steps change in an update, players on a changed step restart that quest.");
  if (quests.some((q) => (q.repeat?.mode ?? "once") === "daily" || q.repeat?.mode === "weekly")) notes.push("Daily and weekly quests use a rolling cooldown from the last completion (24 h / 7 days), not a calendar reset.");
  if (menus.length) notes.push("Menu clicks are server-side only: shift-clicks, number keys, drags and drops in a menu do nothing; prices are taken before anything is given.");
  if (hasBoss) notes.push(...bossNotes(bosses, encounters, ctx.namespace));
  if (hasHud) notes.push(`The HUD draws glyphs from this mod's resource pack (font ${ctx.namespace}:hud): players who decline the pack see empty boxes instead of the glyphs. It uses text channels only (the action bar line, boss bars, the sidebar): no shaders, no free positioning; another plugin's action bar message replaces the HUD line until the next update, and the sidebar is skipped for players another plugin gave a scoreboard. Players turn it off with /${command} hud toggle.`);
  notes.push("Gameplay effects run on the server: protection plugins and PvP settings can block damage and teleports.");
  // the item part of the README = the item compiler's item sections (everything before its settings)
  const itemPart = (() => {
    if (!items.length) return "";
    const r = compileDesigns(items, { ...ctx, configVersion: 1 });
    if (!r.ok) return "";
    return r.readme.split("\n## Settings (config.yml)")[0].split("\n").slice(4).join("\n");
  })();
  const rd = readmeGp(itemPart, ordered, ctx.pluginName, command, ctx.namespace, ctx.version, menus, quests, notes, ext ? {
    sections: [...(hasBoss ? bossReadme(bosses, encounters, command, ctx.namespace) : []), ...hudReadme(huds, command, ctx.namespace)],
    commands: [
      ...(hasBoss ? [`- \`/${command} boss list|status|check\`, \`boss spawn <id> [<world> <x> <y> <z> | spawn]\`, \`boss despawn <id|all>\`, \`boss cast <id> <attack>\`, \`encounter list|status|start <id>|stop <id|all>\` (${ctx.namespace}.boss.admin, operators); summon items need ${ctx.namespace}.boss.summon (everyone)`] : []),
      ...(hasHud ? [`- \`/${command} hud toggle\` (${ctx.namespace}.hud.toggle: everyone), \`hud list|check|preview <id> <channel> <0-1>\` (${ctx.namespace}.hud.admin, operators)`] : []),
